        public static void VerifyInventoryIntegrityNotificationOnly()
        {
            string theme = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    SessionContext.Start("integrity-notification", "Manager", "fixture");
                    using (var form = new InventoryIntegrityForm(false))
                    {
                        typeof(InventoryIntegrityForm).GetMethod("ApplyPresentation", flags | System.Reflection.BindingFlags.Public).Invoke(form, new object[] { english });
                        Prepare(form, new Size(960, 640));
                        IntPtr handle = form.Handle;
                        var grid = Require<DataGridView>(form, "inventoryIntegrityGrid");
                        grid.DataSource = typeof(InventoryIntegrityForm).GetMethod("CreatePreviewIssues", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic).Invoke(null, null);
                        var cancellation = new System.Threading.CancellationTokenSource();
                        var token = cancellation.Token;
                        typeof(InventoryIntegrityForm).GetField("readCancellation", flags).SetValue(form, cancellation);
                        var session = new InventoryIntegrityReadSession(new InventoryIntegrityReadService(new InventoryIntegrityReadProbe(), actor => true), new OperationActor { UserName = "fixture", UserRole = "Manager" }, () => true);
                        typeof(InventoryIntegrityForm).GetField("readSession", flags).SetValue(form, session);
                        SessionContext.Start("integrity-notification", "Manager", "fixture");
                        if (!token.IsCancellationRequested || grid.DataSource != null || typeof(InventoryIntegrityForm).GetField("readSession", flags).GetValue(form) != null)
                            throw new Exception("Integrity notification retained results, read session or pending request.");
                        var closing = new System.Threading.CancellationTokenSource();
                        var closingToken = closing.Token;
                        typeof(InventoryIntegrityForm).GetField("readCancellation", flags).SetValue(form, closing);
                        form.Dispose();
                        if (!closingToken.IsCancellationRequested) throw new Exception("Integrity disposal retained pending request.");
                    }
                }
            }
            finally { SessionContext.Clear(); Properties.Setings.Default.ThemeMode = theme; }
            Console.WriteLine("PASS inventory integrity immediate session result clear/read cancellation/fresh session/disposal; both themes/directions; no SQL/native keys.");
        }
