        internal static void VerifyDashboardHistoryReadOnlyOnly()
        {
            string originalTheme=Properties.Setings.Default.ThemeMode;
            int cases=0,failures=0;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})
                foreach(bool english in new[]{false,true})
                {
                    Properties.Setings.Default.ThemeMode=theme;
                    using(var form=new DashboardPreview())
                    {
                        form.ApplyPresentation(english);
                        var grid=Require<DataGridView>(form,"CustomerGV");
                        var table=(DataTable)grid.DataSource;
                        object[][] expected=table.Rows.Cast<DataRow>().Select(row=>row.ItemArray).ToArray();
                        form.BindingContext=new BindingContext();grid.BindingContext=form.BindingContext;
                        IntPtr handle=grid.Handle;
                        if(form.Visible||expected.Length!=2||grid.Rows.Count!=2)
                            throw new InvalidOperationException("Hidden dashboard history fixture did not bind two invoices.");
                        grid.ClearSelection();grid.CurrentCell=grid.Rows[0].Cells[0];grid.Rows[0].Selected=true;
                        bool handled=(bool)typeof(DataGridView).GetMethod("ProcessDataGridViewKey",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)
                            .Invoke(grid,new object[]{new KeyEventArgs(Keys.Delete)});
                        Console.WriteLine("Dashboard history Delete: theme="+theme+"; english="+english+"; gridRows="+grid.Rows.Count+
                            "; sourceRows="+table.Rows.Count+"; allowDelete="+grid.AllowUserToDeleteRows+"; handled="+handled);
                        bool valid=grid.ReadOnly&&!grid.AllowUserToAddRows&&!grid.AllowUserToDeleteRows&&
                            table.Rows.Count==2&&grid.Rows.Count==2&&!form.Visible;
                        if(valid)
                            for(int row=0;row<2;row++)valid&=table.Rows[row].RowState!=DataRowState.Deleted&&table.Rows[row].ItemArray.SequenceEqual(expected[row]);
                        if(!valid)failures++;
                        cases++;
                    }
                }
                if(failures>0)throw new InvalidOperationException("Dashboard history Delete changed local invoice rows in "+failures+" of "+cases+" cases.");
                Console.WriteLine("PASS dashboard history row protection: "+cases+" theme/direction cases; every invoice value retained; hidden preview, no SQL or desktop input.");
            }
            finally
            {
                Properties.Setings.Default.ThemeMode=originalTheme;
                using(var refresh=new Form())UiTheme.Apply(refresh);
            }
        }

        internal static void VerifyDashboardOpeningOnly()
        {
            bool originalOpening = Properties.Setings.Default.OpenScreensMaximized;
            string originalTheme = Properties.Setings.Default.ThemeMode;
            int cases = 0;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool maximize in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    Properties.Setings.Default.OpenScreensMaximized = maximize;
                    using (var form = new DashboardPreview(maximize)
                    {
                        ShowInTaskbar = false, Opacity = 0
                    })
                    {
                        form.ApplyPresentation(english);
                        form.Show(); Application.DoEvents();
                        if (form.WindowState != (maximize ? FormWindowState.Maximized : FormWindowState.Normal))
                            throw new InvalidOperationException("Dashboard did not use its selected opening mode.");
                        form.WindowState = FormWindowState.Normal;
                        Application.DoEvents();
                        Console.WriteLine("Dashboard restore: theme=" + theme + "; english=" + english +
                            "; openingMaximized=" + maximize + "; actual=" + form.WindowState);
                        if (form.WindowState != FormWindowState.Normal)
                            throw new InvalidOperationException("Dashboard opening preference overrode the user's Restore action.");
                        Rectangle normal = form.Bounds;
                        form.ApplyPresentation(!english); Application.DoEvents();
                        UiTheme.Apply(form); Application.DoEvents();
                        Console.WriteLine("Dashboard refreshed: state=" + form.WindowState + "; bounds=" + form.Bounds + "; normal=" + normal);
                        if (form.WindowState != FormWindowState.Normal || form.Bounds != normal)
                            throw new InvalidOperationException("Dashboard language/theme layout changed the restored window geometry.");
                        form.WindowState = FormWindowState.Maximized; Application.DoEvents();
                        form.ApplyPresentation(english); Application.DoEvents();
                        if (form.WindowState != FormWindowState.Maximized)
                            throw new InvalidOperationException("Dashboard layout undid manual maximization.");
                        form.WindowState = FormWindowState.Minimized; Application.DoEvents();
                        if (form.WindowState != FormWindowState.Minimized)
                            throw new InvalidOperationException("Dashboard layout undid manual minimization.");
                        form.WindowState = FormWindowState.Normal; Application.DoEvents();
                        if (form.WindowState != FormWindowState.Normal || form.Bounds != normal)
                            throw new InvalidOperationException("Dashboard lost its normal bounds after manual window-state changes.");
                        var grid = Require<DataGridView>(form, "CustomerGV");
                        if (grid.Rows.Count != 2 || Convert.ToString(grid.Rows[0].Cells["CustomerId"].Value) != "INV-1001")
                            throw new InvalidOperationException("Dashboard window actions changed its invoice content.");
                        cases++;
                    }
                }
                Console.WriteLine("PASS dashboard opening: " + cases + " theme/direction/mode cases; initial state, Restore, manual maximize/minimize, theme/language refresh, normal bounds and invoice content; preview services only, no SQL.");
            }
            finally
            {
                Properties.Setings.Default.OpenScreensMaximized = originalOpening;
                Properties.Setings.Default.ThemeMode = originalTheme;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        internal static void VerifyDatabaseOpeningOnly()
        {
            bool originalOpening = Properties.Setings.Default.OpenScreensMaximized;
            string originalTheme = Properties.Setings.Default.ThemeMode;
            int cases = 0;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool maximize in new[] { true, false })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    Properties.Setings.Default.OpenScreensMaximized = maximize;
                    using (var form = new DatabaseSetingsForm(true, english) { ShowInTaskbar = false, Opacity = 0 })
                    {
                        form.Show(); Application.DoEvents();
                        var state = maximize ? FormWindowState.Maximized : FormWindowState.Normal;
                        if (form.WindowState != state)
                            throw new InvalidOperationException("Database settings ignored its selected opening state.");
                        Rectangle normal = maximize ? form.RestoreBounds : form.Bounds;
                        // Exercise production geometry only; connection actions remain
                        // disabled in this preview and no administrator/SQL flow runs.
                        form.FitOpeningToWorkingArea(); Application.DoEvents();
                        Console.WriteLine("Database opening: theme=" + theme + "; english=" + english +
                            "; maximize=" + maximize + "; state=" + form.WindowState +
                            "; restore=" + form.RestoreBounds + "; expected=" + normal);
                        if (form.WindowState != state || (maximize ? form.RestoreBounds : form.Bounds) != normal)
                            throw new InvalidOperationException("Database settings post-open fitting overwrote normal or restore geometry.");
                        form.WindowState = FormWindowState.Normal; Application.DoEvents();
                        if (form.Bounds != normal)
                            throw new InvalidOperationException("Database settings did not restore to its initial centered size.");
                        form.FitOpeningToWorkingArea(); Application.DoEvents();
                        if (form.WindowState != FormWindowState.Normal || form.Bounds != normal)
                            throw new InvalidOperationException("Database settings fitting was not stable after Restore.");
                        cases++;
                    }
                }
                Console.WriteLine("PASS database settings opening: " + cases + " theme/direction/mode cases; shared opening policy, post-open fit and normal restore bounds; preview geometry only, no SQL or administrator acceptance.");
            }
            finally
            {
                Properties.Setings.Default.OpenScreensMaximized = originalOpening;
                Properties.Setings.Default.ThemeMode = originalTheme;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

