        private static void VerifyOpeningPreferencePersistsAcrossRestart()
        {
            bool previous = ScreenModeSettings.LoadOpeningPreference();
            try
            {
                foreach (bool expected in new[] { false, true })
                {
                    if (!ScreenModeSettings.TrySaveOpeningPreference(expected))
                        throw new InvalidOperationException("Could not save the opening preference for restart verification.");

                    Properties.Setings.Default.Reload();
                    if (ScreenModeSettings.LoadOpeningPreference() != expected)
                        throw new InvalidOperationException("The opening preference did not survive Settings.Reload().");

                    var start = new System.Diagnostics.ProcessStartInfo
                    {
                        FileName = Application.ExecutablePath,
                        Arguments = "--verify-opening-preference-state " + expected.ToString(),
                        WorkingDirectory = Application.StartupPath,
                        UseShellExecute = false,
                        CreateNoWindow = true
                    };
                    using (var child = System.Diagnostics.Process.Start(start))
                    {
                        if (child == null)
                            throw new InvalidOperationException("Could not start the isolated preference restart verifier.");
                        if (!child.WaitForExit(15000))
                        {
                            try { child.Kill(); child.WaitForExit(5000); } catch { }
                            throw new TimeoutException("The opening preference restart verifier did not exit in time.");
                        }
                        if (child.ExitCode != 0)
                            throw new InvalidOperationException("The opening preference was not loaded after process restart.");
                    }
                }
            }
            finally
            {
                if (!ScreenModeSettings.TrySaveOpeningPreference(previous))
                    throw new InvalidOperationException("Could not restore the original opening preference after verification.");
                Properties.Setings.Default.Reload();
                if (ScreenModeSettings.LoadOpeningPreference() != previous)
                    throw new InvalidOperationException("The original opening preference was not restored after verification.");
            }
        }

        private static void VerifyAccessibilitySettingsEntry()
        {
            bool previousPreference = Properties.Setings.Default.OpenScreensMaximized;
            string previousTheme = Properties.Setings.Default.ThemeMode;
            try
            {
                Properties.Setings.Default.OpenScreensMaximized = true;
                using (var accessibility = new AccessibilitySettingsForm())
                {
                    var fullOption = accessibility.Controls.Find("openMaximized", true).OfType<RadioButton>().FirstOrDefault();
                    var centeredOption = accessibility.Controls.Find("openCentered", true).OfType<RadioButton>().FirstOrDefault();
                    if (fullOption == null || centeredOption == null || !fullOption.Checked || centeredOption.Checked)
                        throw new InvalidOperationException("Accessibility settings must present the full-screen default as selected while retaining centered mode.");
                }

                using (var settings = new SettingsForm(true, true, false))
                {
                    if (!settings.Controls.Find("antdOpen_accessibility", true).Any())
                        throw new InvalidOperationException("The full settings experience must expose the default accessibility card.");
                }

                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    foreach (bool maximize in new[] { false, true })
                    using (var accessibility = new AccessibilitySettingsForm
                    {
                        ShowInTaskbar = false, Opacity = 0, StartPosition = FormStartPosition.Manual,
                        Location = new Point(-20000, -20000)
                    })
                    {
                        accessibility.Show();
                        Application.DoEvents();
                        Size originalSize = accessibility.Size;
                        var fullOption = Require<RadioButton>(accessibility, "openMaximized");
                        var centeredOption = Require<RadioButton>(accessibility, "openCentered");
                        var status = Require<Label>(accessibility, "accessibilityStatus");
                        if (status.AccessibleName != status.Text || status.AccessibleDescription != "حالة حفظ تسهيلات الاستخدام")
                            throw new InvalidOperationException("Accessibility settings initial guidance is not exposed to assistive technology.");
                        fullOption.Checked = maximize;
                        centeredOption.Checked = !maximize;
                        Require<AntdUI.Button>(accessibility, "saveAccessibility").PerformClick();
                        Application.DoEvents();
                        Properties.Setings.Default.Reload();
                        if (ScreenModeSettings.LoadOpeningPreference() != maximize)
                            throw new InvalidOperationException("Accessibility Save action did not persist the selected mode.");
                        if (status.Text != "تم الحفظ؛ سيطبق الاختيار عند فتح الشاشة التالية." || status.AccessibleName != status.Text ||
                            status.ForeColor != UiTheme.Secondary)
                            throw new InvalidOperationException("Accessibility Save result is not exposed consistently to assistive technology.");
                        if (fullOption.Checked == centeredOption.Checked)
                            throw new InvalidOperationException("Accessibility opening choices are not mutually exclusive.");
                        if (accessibility.WindowState != FormWindowState.Normal || accessibility.Size != originalSize || accessibility.MaximizeBox)
                            throw new InvalidOperationException("Saving the opening preference resized or maximized its compact settings dialog.");
                        fullOption.Checked = !maximize;
                        centeredOption.Checked = maximize;
                        Require<AntdUI.Button>(accessibility, "closeAccessibility").PerformClick();
                        Application.DoEvents();
                        Properties.Setings.Default.Reload();
                        if (ScreenModeSettings.LoadOpeningPreference() != maximize)
                            throw new InvalidOperationException("Closing accessibility settings saved an unconfirmed selection.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = previousTheme;
                if (!ScreenModeSettings.TrySaveOpeningPreference(previousPreference))
                    throw new InvalidOperationException("Could not restore the preference after accessibility Save/Close verification.");
                Properties.Setings.Default.Reload();
            }
        }
