        public static void RunAll()
        {
            var checks = BuildLayoutChecks();
            foreach (var check in checks) RunLayoutCheck(check.Key, check.Value);
        }

        // The layout sweep is split into contiguous groups so the acceptance cycle can run
        // in parallel and a failure points at a smaller slice of the screens.
        public static void RunGroup(int groupIndex, int groupCount)
        {
            if (groupCount < 1) throw new ArgumentOutOfRangeException(nameof(groupCount));
            if (groupIndex < 0 || groupIndex >= groupCount) throw new ArgumentOutOfRangeException(nameof(groupIndex));
            var checks = BuildLayoutChecks();
            int size = (checks.Count + groupCount - 1) / groupCount;
            int from = groupIndex * size;
            int to = Math.Min(checks.Count, from + size);
            for (int index = from; index < to; index++) RunLayoutCheck(checks[index].Key, checks[index].Value);
            Console.WriteLine("PASS layout group " + groupIndex + "/" + groupCount + "; checks=" + Math.Max(0, to - from) + "; total=" + checks.Count);
        }

        private static List<KeyValuePair<string,Action>> BuildLayoutChecks()
        {
            var checks = new List<KeyValuePair<string,Action>>();
            checks.Add(new KeyValuePair<string,Action>(nameof(VerifyDesktopPresentationBootstrap), VerifyDesktopPresentationBootstrap));
            checks.Add(new KeyValuePair<string,Action>(nameof(VerifyAccountingLookupProjection), VerifyAccountingLookupProjection));
            checks.Add(new KeyValuePair<string,Action>(nameof(VerifyNativeSelectClosedFaceTheme), VerifyNativeSelectClosedFaceTheme));
            checks.Add(new KeyValuePair<string,Action>(nameof(VerifyNativeSelectFrameThemePersistence), VerifyNativeSelectFrameThemePersistence));
            checks.Add(new KeyValuePair<string,Action>(nameof(VerifyOutlinedActionStylePersistence), VerifyOutlinedActionStylePersistence));
            checks.Add(new KeyValuePair<string,Action>(nameof(VerifyDatabaseWorkflowLanguage), VerifyDatabaseWorkflowLanguage));
            checks.Add(new KeyValuePair<string,Action>(nameof(VerifyReturnWorkflowLanguage), VerifyReturnWorkflowLanguage));
