        public static void VerifyDesktopPresentationBootstrap()
        {
            using (var caption = new Label())
                if (caption.UseCompatibleTextRendering)
                    throw new InvalidOperationException("Layout automation must use the desktop GDI text rendering default before creating forms.");
            if (System.Windows.Forms.VisualStyles.VisualStyleInformation.IsSupportedByOS &&
                System.Windows.Forms.VisualStyles.VisualStyleInformation.IsEnabledByUser && !Application.RenderWithVisualStyles)
                throw new InvalidOperationException("Layout automation must enable the desktop visual styles before creating forms.");
            Console.WriteLine("PASS desktop presentation bootstrap: native visual styles where available and GDI label default; no forms/SQL/settings writes.");
        }
        private static void RunLayoutCheck(string name,Action verification)
        {
            var timer=System.Diagnostics.Stopwatch.StartNew();
            Console.WriteLine("BEGIN layout: "+name);Console.Out.Flush();
            try
            {
                verification();
                Console.WriteLine("PASS layout: "+name+"; elapsed_ms="+timer.ElapsedMilliseconds);Console.Out.Flush();
            }
            catch
            {
                Console.WriteLine("FAIL layout: "+name+"; elapsed_ms="+timer.ElapsedMilliseconds);Console.Out.Flush();
                throw;
            }
        }
        private static void VerifyAccountingLookupProjection()
        {
            string raw = " صندوق Cash 500 mg & الفرع ";
            var rows = new List<AccountLookupRow> {
                new AccountLookupRow("1100", raw, "Asset", null, false),
                new AccountLookupRow("1101", "فرع Branch", "Asset", "1100", true) };
            using (var table = AccountingLookupTableProjection.Accounts(rows.AsReadOnly()))
            {
                string[] names = { "AccountCode", "AccountName", "AccountType", "ParentAccountCode", "IsActive" };
                if (table.Columns.Count != 5 || table.Rows.Count != 2) throw new InvalidOperationException("Accounting lookup table shape changed.");
                for (int i = 0; i < names.Length; i++)
                    if (table.Columns[i].ColumnName != names[i] || table.Columns[i].DataType != (i == 4 ? typeof(bool) : typeof(string)))
                        throw new InvalidOperationException("Accounting lookup column names or types changed.");
                if ((string)table.Rows[0][1] != raw || !table.Rows[0].IsNull(3) || (bool)table.Rows[0][4] ||
                    (string)table.Rows[1][3] != "1100" || !(bool)table.Rows[1][4])
                    throw new InvalidOperationException("Accounting lookup projection changed raw text, null parent or active state.");
            }
            using (var table = AccountingLookupTableProjection.CostCenters(new List<CostCenterLookupRow> { new CostCenterLookupRow(7, raw) }.AsReadOnly()))
                if (table.Columns.Count != 2 || table.Columns[0].ColumnName != "CostCenterId" || table.Columns[0].DataType != typeof(int) ||
                    table.Columns[1].ColumnName != "CostCenterName" || table.Columns[1].DataType != typeof(string) ||
                    (int)table.Rows[0][0] != 7 || (string)table.Rows[0][1] != raw)
                    throw new InvalidOperationException("Cost center projection changed its data contract.");
            string user = SessionContext.CurrentUser, role = SessionContext.CurrentRole, employee = SessionContext.CurrentEmployeeId;
            bool authenticated = SessionContext.IsAuthenticated;
            try
            {
                SessionContext.Clear();
                bool refused = false;
                try { AccountingLookupDesktopService.LoadAccounts(true); } catch (UnauthorizedAccessException) { refused = true; }
                if (!refused) throw new InvalidOperationException("Unauthenticated desktop accounting lookup was not refused.");
                SessionContext.Start("lookup-test", "Manager");
                foreach (var actor in new[] { new OperationActor { UserName = "other", UserRole = "Manager" },
                    new OperationActor { UserName = "lookup-test", UserRole = "Cashier" } })
                {
                    refused = false;
                    try { ApplicationServices.AccountingLookups.LoadCostCenters(actor); } catch (UnauthorizedAccessException) { refused = true; }
                    if (!refused) throw new InvalidOperationException("A lookup actor differing from the active session was not refused.");
                }
            }
            finally { if (authenticated) SessionContext.Start(user, role, employee); else SessionContext.Clear(); }
        }


        private static void VerifyNativeSelectFrameThemePersistence()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (bool enabled in new[] { false, true })
                using (var form = new Form())
                using (var selector = new NativeThemedSelect { Name = "persistedSelect", Enabled = enabled, AccessibleName = "الحساب" })
                using (var frame = DesktopComponents.NativeSelectFrame(selector, "persistedSelectFrame", "الحساب"))
                {
                    frame.Width = 280;
                    form.Controls.Add(frame);
                    selector.Items.Add("1000 - الصندوق Cash"); selector.SelectedIndex = 0;
                    var arrow = frame.Controls.OfType<AntdUI.Button>().Single();
                    if (arrow.Enabled != enabled)
                        throw new InvalidOperationException("Native select dropdown ignores initial disabled state.");
                    foreach (string mode in new[] { "Light", "Dark", "Light" })
                    {
                        Properties.Setings.Default.ThemeMode = mode;
                        UiTheme.Apply(form);
                        UiTheme.ApplyTo(frame);
                        if (frame.Back != UiTheme.Surface || frame.BackColor != UiTheme.Surface ||
                            frame.Radius != DesktopDesignTokens.ActionRadius(frame.Height) || frame.Shadow != 0 ||
                            selector.Region != null || arrow.BorderWidth != 0 || arrow.DefaultBack != UiTheme.Surface ||
                            selector.BackColor != UiTheme.Surface || arrow.Enabled != enabled ||
                            selector.Text != "1000 - الصندوق Cash" || selector.SelectedIndex != 0 ||
                            selector.Items.Count != 1 || selector.Enabled != enabled)
                            throw new InvalidOperationException("Native select frame loses its field styling or selection after " + mode + ".");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; using (var palette = new Form()) UiTheme.Apply(palette); }
        }
        private static void VerifyNativeSelectClosedFaceTheme()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool enabled in new[] { false, true })
                using (var palette = new Form())
                using (var selector = new NativeThemedSelect())
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    UiTheme.Apply(palette);
                    selector.Font = AppFonts.Create(10F);
                    string first = "1100 - الصندوق Cash", second = "2000 - الموردون Supplier";
                    selector.Items.Add(first); selector.Items.Add(second); selector.SelectedIndex = 0;
                    using (var frame = DesktopComponents.NativeSelectFrame(selector, "selectThemeFrame", "اختيار الحساب"))
                    {
                        frame.Width = 280;
                        DesktopComponents.StyleNativeSelectFrame(frame, selector, english);
                        selector.Enabled = enabled;
                        frame.CreateControl(); selector.CreateControl();
                        foreach (int index in new[] { 0, 1, -1 })
                        {
                            selector.SelectedIndex = index;
                            string expected = index == 0 ? first : index == 1 ? second : string.Empty;
                            using (var bitmap = new Bitmap(selector.Width, selector.Height))
                            {
                                selector.DrawToBitmap(bitmap, new Rectangle(Point.Empty, bitmap.Size));
                                if (mode == "Dark")
                                {
                                    // A system disabled border appears as a bright horizontal line
                                    // in the top band, which contains no text or dropdown icon.
                                    for (int y = 0; y < Math.Min(4, bitmap.Height); y++)
                                    for (int x = 4; x < bitmap.Width - 4; x++)
                                    {
                                        Color pixel = bitmap.GetPixel(x, y);
                                        if (pixel.R > 200 && pixel.G > 200 && pixel.B > 200)
                                            throw new InvalidOperationException("Native select retains a bright system border in dark mode.");
                                    }
                                }
                            }
                            if (selector.Text != expected || selector.SelectedIndex != index ||
                                selector.Items.Count != 2 || selector.GetItemText(selector.Items[0]) != first ||
                                selector.GetItemText(selector.Items[1]) != second)
                                throw new InvalidOperationException("Native select rendering changed its selection or mixed Arabic text.");
                        }
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; using (var palette = new Form()) UiTheme.Apply(palette); }
        }
        private static void VerifyOutlinedActionStylePersistence()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                using (var cancel = DesktopComponents.Action("styleCancel", "إلغاء", AppIcon.Close))
                using (var delete = DesktopComponents.Action("styleDelete", "حذف", AppIcon.Delete))
                using (var dismiss = DesktopComponents.Action("styleDismiss", "Close", AppIcon.Close))
                {
                    DesktopComponents.StyleOutlinedFooterAction(cancel);
                    DesktopComponents.StyleOutlinedFooterAction(delete, true);
                    foreach (string mode in new[] { "Light", "Dark", "Light" })
                    {
                        Properties.Setings.Default.ThemeMode = mode;
                        using (var palette = new Form()) UiTheme.Apply(palette);
                        foreach (bool english in new[] { false, true })
                        {
                            cancel.Text = english ? "Cancel" : "إلغاء";
                            delete.Text = english ? "Delete" : "حذف";
                            foreach (int width in new[] { 144, 284, 168 })
                            {
                                cancel.Width = delete.Width = dismiss.Width = width;
                                AntdThemeAdapter.Apply(cancel);
                                AntdThemeAdapter.Apply(delete);
                                AntdThemeAdapter.Apply(dismiss);
                                if (cancel.Type != AntdUI.TTypeMini.Default || delete.Type != AntdUI.TTypeMini.Default ||
                                    cancel.ForeColor != UiTheme.Primary || delete.ForeColor != UiTheme.Danger ||
                                    cancel.DefaultBack != UiTheme.Surface || delete.DefaultBack != UiTheme.Surface ||
                                    cancel.DefaultBorderColor != UiTheme.Primary || delete.DefaultBorderColor != UiTheme.Primary ||
                                    dismiss.ForeColor != UiTheme.Primary || dismiss.DefaultBack != UiTheme.Surface ||
                                    dismiss.DefaultBorderColor != UiTheme.Primary)
                                    throw new InvalidOperationException("Explicit outlined action style was lost after resize, language or theme change.");
                            }
                        }
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; using (var palette = new Form()) UiTheme.Apply(palette); }
        }

        private static void VerifyDatabaseWorkflowLanguage()
        {
            foreach (bool english in new[] { false, true })
            using (var form = new DatabaseSetingsForm(true, english))
            {
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var busy = typeof(DatabaseSetingsForm).GetMethod("SetBusy", flags);
                busy.Invoke(form, new object[] { true, "جار اختبار الاتصال...", true });
                var status = Require<Label>(form, "databaseStatus");
                if (status.Text != (english ? "Testing connection..." : "جار اختبار الاتصال..."))
                    throw new InvalidOperationException("Database workflow busy state does not follow the requested language.");
                var closing = new FormClosingEventArgs(CloseReason.UserClosing, false);
                typeof(DatabaseSetingsForm).GetMethod("OnFormClosing", flags).Invoke(form, new object[] { closing });
                if (!closing.Cancel || status.Text != (english ? "Wait for the current operation to finish before closing this window." :
                    "انتظر حتى تكتمل العملية الحالية ثم أغلق النافذة."))
                    throw new InvalidOperationException("Database write-state closing message does not follow the requested language.");
                busy.Invoke(form, new object[] { false, null, false });
                string help = form.PresentConnectionHelp(new InvalidOperationException("Private diagnostic detail"));
                string confirmation = form.BuildConnectionChangeMessage("preview-server\\INSTANCE", "PreviewDb", 3);
                if (help.Contains("Private diagnostic detail") ||
                    !confirmation.Contains("preview-server\\INSTANCE") || !confirmation.Contains("PreviewDb") ||
                    !confirmation.Contains("3/4") || confirmation.Contains("{0}"))
                    throw new InvalidOperationException("Database support or connection-confirmation content changed identifiers or exposed exception details.");
                if (english ? help.Any(character => character >= '\u0600' && character <= '\u06FF') ||
                    !confirmation.StartsWith("The following connection will become active:") :
                    help != ConnectionSettingsService.BuildConnectionHelp(null) || !confirmation.StartsWith("سيصبح الاتصال التالي هو اتصال التشغيل:"))
                    throw new InvalidOperationException("Database support or confirmation message does not follow the requested language.");
                string issue = UiTheme.BuildOperationIssueMessage(english ? "save appearance" : "حفظ المظهر", "TEST-SUPPORT", english);
                if (!issue.Contains("TEST-SUPPORT") || (english ? !issue.StartsWith("Could not save appearance now.") :
                    !issue.StartsWith("تعذر حفظ المظهر الآن.")))
                    throw new InvalidOperationException("Shared operation-issue message lost its language or support code.");
                string localizedOperationIssue = UiTheme.BuildOperationIssueMessage("حفظ المظهر", "TEST-SUPPORT", true);
                if (localizedOperationIssue.Any(character => character >= '\u0600' && character <= '\u06FF') ||
                    typeof(UiTheme).GetMethod("ShowOperationIssue", new[] { typeof(IWin32Window), typeof(string), typeof(Exception) }) == null)
                    throw new InvalidOperationException("Shared operation-issue compatibility or operation-name translation is incomplete.");
                foreach (Size size in new[] { new Size(360, 320), new Size(760, 570) })
                {
                    Prepare(form, size);
                    busy.Invoke(form, new object[] { true, english ? help : confirmation, false });
                    int requiredHeight = TextRenderer.MeasureText(status.Text, status.Font,
                        new Size(status.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                    if (status.Height < requiredHeight || status.AccessibleName != status.Text)
                        throw new InvalidOperationException("Database workflow message is clipped or inaccessible at " + size + ".");
                    busy.Invoke(form, new object[] { false, null, false });
                }
            }
        }

        private static void VerifyReturnWorkflowLanguage()
        {
            foreach (bool english in new[] { false, true })
            using (var form = new CommercialSalesReturnForm(Guid.NewGuid(), true, english))
            {
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var submission = typeof(CommercialSalesReturnForm).GetMethod("SetSubmissionInProgress", flags);
                var status = Require<Label>(form, "commercialReturnStatus");
                var issue = Require<AntdUI.Button>(form, "issueCommercialReturn");
                submission.Invoke(form, new object[] { true });
                if (issue.Enabled || issue.Text != (english ? "Approve credit note" : "اعتماد الإشعار") ||
                    status.Text != (english ? "Posting return credit note..." : "جارٍ اعتماد إشعار المرتجع..."))
                    throw new InvalidOperationException("Commercial return submission state lost language or disabled action.");
                foreach (string validation in new[] {
                    "صحح قيمة الخلية الحالية قبل الاعتماد.", "سبب المرتجع مطلوب.", "اختر طريقة استرداد صالحة.",
                    "أدخل كمية مرتجع واحدة على الأقل.",
                    "كمية المرتجع يجب أن تكون عدداً صحيحاً غير سالب. أدخل صفراً لاستبعاد الدفعة.",
                    "كمية المرتجع تتجاوز المتاح للدفعة." })
                {
                    string message = form.BuildSubmissionFailureMessage(new InvalidOperationException(validation), "TEST-SUPPORT");
                    if (english ? message.Any(character => character >= '\u0600' && character <= '\u06FF') : !message.Contains(validation))
                        throw new InvalidOperationException("Commercial return validation lost its reason or language.");
                }
                string unknown = form.BuildSubmissionFailureMessage(new Exception("Private SQL detail"), "TEST-SUPPORT");
                if (unknown.Contains("Private SQL detail") || !unknown.Contains("TEST-SUPPORT"))
                    throw new InvalidOperationException("Commercial return failure exposed technical details or lost support code.");
                var request = new CommercialSalesReturnRequest { RequestId = "preview-request" };
                typeof(CommercialSalesReturnForm).GetField("pendingRequest", flags).SetValue(form, request);
                submission.Invoke(form, new object[] { false });
                // A pending request stays reviewable but frozen: the lots grid keeps scrolling and copying
                // while every column is read-only, matching the accepted recovery contract.
                DataGridView pendingLots = Require<DataGridView>(form, "commercialReturnLotsGrid");
                if (!issue.Enabled || issue.Text != (english ? "Retry same request" : "إعادة نفس الطلب") ||
                    status.Text != (english ? "Review the history or retry the same request without changes." : "راجع السجل أو أعد نفس الطلب دون تعديل.") ||
                    status.AccessibilityObject.Name != status.Text ||
                    !pendingLots.Enabled || !pendingLots.ReadOnly ||
                    !ReferenceEquals(typeof(CommercialSalesReturnForm).GetField("pendingRequest", flags).GetValue(form), request))
                    throw new InvalidOperationException("Commercial return retry state lost its language, accessible status, reviewable read-only lots or original request.");
                string uncertain = form.BuildSubmissionFailureMessage(new Exception("Private SQL detail"), "TEST-SUPPORT");
                if (!uncertain.Contains("preview-request") || !uncertain.Contains("TEST-SUPPORT") || uncertain.Contains("Private SQL detail") ||
                    (english && uncertain.Any(character => character >= '\u0600' && character <= '\u06FF')))
                    throw new InvalidOperationException("Commercial return uncertain outcome lost request identity or exposed technical details.");
                typeof(CommercialSalesReturnForm).GetMethod("Issue", flags).Invoke(form, null);
                if (status.Text != (english ? "Preview only; no return credit note was posted." : "المعاينة للعرض فقط؛ لم يُعتمد إشعار مرتجع."))
                    throw new InvalidOperationException("Commercial return preview status lost language or attempted posting.");
            }
        }

        private static void VerifyIntegrityFailureState()
        {
            foreach(bool accounting in new[]{false,true})
            foreach(bool english in new[]{false,true})
            using(Form form=accounting?(Form)new AccountingIntegrityForm(true):new InventoryIntegrityForm(true))
            {
                var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
                var type=form.GetType();
                type.GetMethod("ApplyPresentation",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(form,new object[]{english});
                form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();
                var grid=Require<DataGridView>(form,accounting?"accountingIntegrityGrid":"inventoryIntegrityGrid");
                var status=Require<Label>(form,accounting?"accountingIntegrityStatus":"inventoryIntegrityStatus");
                object data=grid.DataSource; int count=grid.Rows.Count;
                type.GetMethod("SetCountStatus",flags).Invoke(form,new object[]{"توجد {0} حركات تحتاج مراجعة. لم تُعدّل أي كمية تلقائياً.",count,(bool?)true});
                type.GetMethod("ApplyLoadFailure",flags).Invoke(form,null);
                string expected=english?"The check could not finish. Displayed results are from an earlier check; check the connection and run it again.":
                    "تعذر إكمال الفحص. النتائج المعروضة سابقة؛ أعد الفحص بعد التحقق من الاتصال.";
                if(status.Text!=expected || status.AccessibilityObject.Name!=expected || !ReferenceEquals(data,grid.DataSource) || grid.Rows.Count!=count)
                    throw new InvalidOperationException("Failed integrity check retained successful status or discarded previous rows.");
                type.GetMethod("ApplyPresentation",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(form,new object[]{!english});
                type.GetMethod("ApplyPresentation",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(form,new object[]{english});
                if(status.Text!=expected || Require<AntdUI.Button>(form,accounting?"refreshAccountingIntegrity":"refreshInventoryIntegrity").Enabled!=true)
                    throw new InvalidOperationException("Integrity failure state did not survive language changes or allow retry.");
                grid.DataSource=null;
                type.GetMethod("ApplyLoadFailure",flags).Invoke(form,null);
                if(status.Text!=(english?"The check could not finish. Check the connection, then retry.":"تعذر إكمال الفحص. تحقق من الاتصال ثم أعد المحاولة."))
                    throw new InvalidOperationException("Empty integrity failure incorrectly described stale results.");
            }
        }

