        private static void VerifyQuarantineRetryPreservesInput()
        {
            string previousUser=SessionContext.CurrentUser, previousRole=SessionContext.CurrentRole, previousId=SessionContext.CurrentEmployeeId;
            bool authenticated=SessionContext.IsAuthenticated;
            try
            {
                SessionContext.Start("Preview", "Manager");
                foreach(bool english in new[]{false,true})
                using (var form = new QuarantineResolutionForm(false, english))
                {
                form.CreateControl();
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                typeof(QuarantineResolutionForm).GetMethod("PopulatePreviewData", flags).Invoke(form, null);
                var source = Require<DataGridView>(form, "quarantineSourceGrid");
                source.BindingContext = new BindingContext();
                source.CurrentCell = source.Rows[0].Cells["الصنف"];
                var quantity = Require<NumericUpDown>(form, "quarantineResolutionQuantity");
                var reason = Require<TextBox>(form, "quarantineResolutionReason");
                var id = typeof(QuarantineResolutionForm).GetField("pendingRequestId", flags);
                quantity.Value = 3m;
                reason.Text = "Review partial quantity";
                typeof(QuarantineResolutionForm).GetField("hasCurrentSnapshot", flags).SetValue(form, true);
                id.SetValue(form, "same-partial-request");
                typeof(QuarantineResolutionForm).GetMethod("FinishSubmission", flags).Invoke(form, null);
                if (quantity.Value != 3m || reason.Text != "Review partial quantity" ||
                    (string)id.GetValue(form) != "same-partial-request" ||
                    !Require<AntdUI.Button>(form,"approveQuarantineResolution").Enabled)
                    throw new InvalidOperationException("Quarantine retry completion changed the partial quantity or discarded the original request: quantity=" + quantity.Value + "; request=" + id.GetValue(form) + "; approval=" + Require<AntdUI.Button>(form,"approveQuarantineResolution").Enabled + "; row=" + (source.CurrentRow != null));
                typeof(QuarantineResolutionForm).GetMethod("MarkSnapshotUnavailable", flags).Invoke(form, new object[]{true});
                typeof(QuarantineResolutionForm).GetMethod("FinishSubmission", flags).Invoke(form, null);
                var status=Require<Label>(form,"quarantineResolutionStatus");
                if(Require<AntdUI.Button>(form,"approveQuarantineResolution").Enabled || quantity.Value!=3m ||
                    status.AccessibilityObject.Name!=status.Text || status.Text!=(english ?
                    "Decision posted, but the list could not be refreshed. Reopen this screen before another decision." :
                    "تم اعتماد القرار، لكن تعذر تحديث القائمة. أعد فتح الشاشة قبل قرار جديد."))
                    throw new InvalidOperationException("Quarantine completion re-enabled a stale snapshot or hid the confirmed-save refresh failure.");
                quantity.Value=2m;
                if(id.GetValue(form)!=null) throw new InvalidOperationException("Changed quarantine quantity retained an old request identifier.");
                }
            }
            finally { if(authenticated) SessionContext.Start(previousUser,previousRole,previousId); else SessionContext.Clear(); }
        }

