        private static void VerifyWindowChromePolicy()
        {
            var openingMode = Properties.Setings.Default.Properties["OpenScreensMaximized"];
            bool defaultOpensMaximized;
            if (openingMode == null || !bool.TryParse(Convert.ToString(openingMode.DefaultValue), out defaultOpensMaximized) || !defaultOpensMaximized)
                throw new InvalidOperationException("New user profiles must default to opening screens maximized.");

            using (var owner = new Form())
            using (var dialog = new Form { Owner = owner, StartPosition = FormStartPosition.CenterParent, ShowInTaskbar = false })
            {
                UiTheme.Apply(dialog);
                if (dialog.StartPosition != FormStartPosition.CenterParent || dialog.ShowIcon || dialog.ShowInTaskbar || dialog.Owner != owner)
                    throw new InvalidOperationException("Themed dialogs must retain ownership and parent-centered placement without a legacy caption icon.");
            }
            using (var positioned = new Form { StartPosition = FormStartPosition.Manual, Location = new Point(100, 120) })
            {
                UiTheme.Apply(positioned);
                if (positioned.StartPosition != FormStartPosition.Manual || positioned.Location != new Point(100, 120) || positioned.ShowIcon)
                    throw new InvalidOperationException("Theme application must preserve an explicit window location.");
            }
            using (var form = new Form { Size = new Size(960, 640), MinimumSize = new Size(640, 480) })
            {
                ScreenModeSettings.Apply(form, false, new Size(960, 640));
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox || form.ShowIcon ||
                    form.WindowState != FormWindowState.Normal)
                    throw new InvalidOperationException("Main workspace must keep standard resize/minimize/maximize chrome.");

                ScreenModeSettings.Apply(form, true, new Size(960, 640));
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox || form.ShowIcon ||
                    form.WindowState != FormWindowState.Maximized)
                    throw new InvalidOperationException("Full-screen preference must use the accessible maximized window state.");
            }

            bool originalOpeningPreference = Properties.Setings.Default.OpenScreensMaximized;
            try
            {
                Rectangle area = Screen.FromPoint(Cursor.Position).WorkingArea;
                using (var form = new Form { Size = new Size(640, 420), MinimumSize = new Size(360, 300) })
                {
                    Properties.Setings.Default.OpenScreensMaximized = false;
                    ScreenModeSettings.ApplyOpeningPreference(form, null);
                    int requestedWidth = Math.Min(640, Math.Max(1, area.Width - 48));
                    int requestedHeight = Math.Min(420, Math.Max(1, area.Height - 48));
                    int expectedWidth = Math.Max(form.MinimumSize.Width, requestedWidth);
                    int expectedHeight = Math.Max(form.MinimumSize.Height, requestedHeight);
                    int expectedLeft = area.Left + Math.Max(0, (area.Width - expectedWidth) / 2);
                    int expectedTop = area.Top + Math.Max(0, (area.Height - expectedHeight) / 2);
                    if (form.WindowState != FormWindowState.Normal || form.Width != expectedWidth || form.Height != expectedHeight ||
                        form.Left != expectedLeft || form.Top != expectedTop)
                        throw new InvalidOperationException("Default opening preference must center a resizable screen within the active monitor working area.");

                    Properties.Setings.Default.OpenScreensMaximized = true;
                    ScreenModeSettings.ApplyOpeningPreference(form, null);
                    if (form.WindowState != FormWindowState.Maximized)
                        throw new InvalidOperationException("Full opening preference must maximize the screen without covering the taskbar.");
                }
            }
            finally
            {
                Properties.Setings.Default.OpenScreensMaximized = originalOpeningPreference;
            }

            VerifyOpeningPreferenceShownIntegration();
        }

        private static void VerifyCompactOpeningMatrix()
        {
            bool original = Properties.Setings.Default.OpenScreensMaximized;
            string originalTheme = Properties.Setings.Default.ThemeMode;
            int cases = 0;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool maximize in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    Properties.Setings.Default.OpenScreensMaximized = maximize;
                    using (var owner = new AccountingPeriodManagementForm(true))
                    {
                        owner.ShowInTaskbar = false; owner.Opacity = 0; owner.Show(); Application.DoEvents();
                        Rectangle before = owner.Bounds; FormWindowState beforeState = owner.WindowState;
                        foreach (int kind in new[] { 0, 1, 2, 3, 4, 5 })
                        {
                            Form dialog;
                            if (kind == 0) dialog = new AccessibilitySettingsForm();
                            else if (kind == 1) dialog = new ReportTemplateNameDialog("QA {0} تقرير", true);
                            else if (kind == 2) dialog = new ReportColumnLayoutDialog(new[] {
                                new DataGridViewTextBoxColumn { Name = "qa", HeaderText = "QA" } }, true);
                            else if (kind == 3) dialog = new ReportPrintOptionsDialog(new PharmacyProfile(), true, null, true);
                            else if (kind == 4) dialog = new UnsavedChangesDialog(true);
                            else dialog = new AppNotificationForm("QA compact", "QA", MessageBoxButtons.YesNo,
                                MessageBoxIcon.Warning, MessageBoxDefaultButton.Button2, true);
                            using (dialog)
                            {
                                Size normal = dialog.Size; string failure = null; bool observed = false;
                                dialog.ShowInTaskbar = false; dialog.Opacity = 0;
                                dialog.Shown += (sender, args) => dialog.BeginInvoke(new Action(() =>
                                {
                                    observed = true;
                                    if (dialog.WindowState != FormWindowState.Normal)
                                        failure = "Compact dialog maximized: " + dialog.GetType().Name;
                                    if (dialog.Width > Math.Max(normal.Width, dialog.MinimumSize.Width) + 4 ||
                                        dialog.Height > Math.Max(normal.Height, dialog.MinimumSize.Height) + 4)
                                        failure = "Compact dialog expanded beyond its own layout: " + dialog.GetType().Name;
                                    dialog.Close();
                                }));
                                dialog.ShowDialog(owner); Application.DoEvents();
                                if (!observed || failure != null) throw new InvalidOperationException(failure ?? "Compact dialog not observed.");
                                if (owner.WindowState != beforeState || owner.Bounds != before)
                                    throw new InvalidOperationException("Closing compact dialog changed its owner's geometry: " + dialog.GetType().Name);
                                ++cases;
                            }
                        }
                        owner.Close(); Application.DoEvents();
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.OpenScreensMaximized = original;
                Properties.Setings.Default.ThemeMode = originalTheme;
            }
            Console.WriteLine("PASS compact opening matrix: " + cases + " modal cases; six real compact dialogs, both themes/preferences; owner geometry retained; no SQL or Save actions.");
        }

        private static void VerifyBusinessOpeningMatrix()
        {
            bool original = Properties.Setings.Default.OpenScreensMaximized;
            string originalTheme = Properties.Setings.Default.ThemeMode;
            int cases = 0;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool maximize in new[] { false, true })
                foreach (int screen in new[] { 0, 1, 2, 3, 4 })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    Properties.Setings.Default.OpenScreensMaximized = maximize;
                    Form form;
                    if (screen == 0) { var f = new AccountingPeriodManagementForm(true); f.ApplyPresentation(english); form = f; }
                    else if (screen == 1) { var f = new PeriodCloseReadinessForm(true); f.ApplyPresentation(english); form = f; }
                    else if (screen == 2) { var f = new ActiveIngredientManagementForm(true); f.ApplyPresentation(english); form = f; }
                    else if (screen == 3) { var f = new InventoryIntegrityForm(true); f.ApplyPresentation(english); form = f; }
                    else form = new CurrencySettingsForm(true, english);
                    using (form)
                    {
                        Size normal = form.Size;
                        Size minimum = form.MinimumSize;
                        form.ShowInTaskbar = false; form.Opacity = 0;
                        form.Show(); Application.DoEvents();
                        Rectangle area = Screen.FromControl(form).WorkingArea;
                        if (form.WindowState != (maximize ? FormWindowState.Maximized : FormWindowState.Normal))
                            throw new InvalidOperationException("Business opening preference ignored: " + form.GetType().Name);
                        if (maximize) { form.WindowState = FormWindowState.Normal; Application.DoEvents(); }
                        int width = Math.Max(minimum.Width, Math.Min(normal.Width, Math.Max(1, area.Width - 48)));
                        int height = Math.Max(minimum.Height, Math.Min(normal.Height, Math.Max(1, area.Height - 48)));
                        Rectangle expected = new Rectangle(area.Left + Math.Max(0, (area.Width - width) / 2),
                            area.Top + Math.Max(0, (area.Height - height) / 2), width, height);
                        if (form.Bounds != expected)
                            throw new InvalidOperationException("Business screen lost centered restore bounds: " + form.GetType().Name +
                                "; theme=" + theme + "; english=" + english + "; maximize=" + maximize +
                                "; expected=" + expected + "; actual=" + form.Bounds);
                        if (form.MinimumSize != minimum || !form.MaximizeBox || form.FormBorderStyle != FormBorderStyle.Sizable)
                            throw new InvalidOperationException("Opening policy changed the screen's window contract.");
                        form.Close(); Application.DoEvents(); ++cases;
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.OpenScreensMaximized = original;
                Properties.Setings.Default.ThemeMode = originalTheme;
            }
            Console.WriteLine("PASS business opening matrix: " + cases + " cases; five real preview screens, centered/maximized/restore, both languages/themes; no SQL or persisted setting changes.");
        }

        private static void VerifyOpeningPreferenceShownIntegration()
        {
            bool original = Properties.Setings.Default.OpenScreensMaximized;
            try
            {
                foreach (bool maximize in new[] { false, true })
                foreach (bool applyBeforeShown in new[] { false, true })
                {
                    Properties.Setings.Default.OpenScreensMaximized = maximize;
                    Rectangle area = Screen.FromPoint(Cursor.Position).WorkingArea;
                    using (var form = new OpeningPreferenceProbeForm
                    {
                        StartPosition = FormStartPosition.Manual,
                        Location = new Point(area.Left + 24, area.Top + 24),
                        Size = new Size(640, 420),
                        MinimumSize = new Size(360, 300),
                        ShowInTaskbar = false,
                        Opacity = 0
                    })
                    {
                        UiTheme.Apply(form);
                        if (applyBeforeShown) ScreenModeSettings.ApplyOpeningPreference(form, null);
                        form.Show();
                        Application.DoEvents();
                        for (int application = 0; application < 2; application++)
                        {
                            if (application > 0)
                            {
                                ScreenModeSettings.ApplyOpeningPreference(form, null);
                                Application.DoEvents();
                            }
                            if (maximize)
                            {
                                if (form.WindowState != FormWindowState.Maximized)
                                    throw new InvalidOperationException("UiTheme did not apply the full-screen opening preference when the business form was shown.");
                                form.WindowState = FormWindowState.Normal;
                                Application.DoEvents();
                            }
                            int width = Math.Max(form.MinimumSize.Width, Math.Min(640, Math.Max(1, area.Width - 48)));
                            int height = Math.Max(form.MinimumSize.Height, Math.Min(420, Math.Max(1, area.Height - 48)));
                            int left = area.Left + Math.Max(0, (area.Width - width) / 2);
                            int top = area.Top + Math.Max(0, (area.Height - height) / 2);
                            if (form.WindowState != FormWindowState.Normal || form.Width != width || form.Height != height ||
                                form.Left != left || form.Top != top)
                                throw new InvalidOperationException("Opening preference lost centered normal/restore bounds: maximize=" + maximize +
                                    "; preapply=" + applyBeforeShown + "; application=" + application + "; actual=" + form.Bounds +
                                    "; expected=" + new Rectangle(left, top, width, height) + ".");
                        }
                        form.Close();
                        Application.DoEvents();
                    }
                }
                VerifyWorkspaceRestoreShownIntegration();
            }
            finally { Properties.Setings.Default.OpenScreensMaximized = original; }
        }

        private static void VerifyWorkspaceRestoreShownIntegration()
        {
            Rectangle area = Screen.FromPoint(Cursor.Position).WorkingArea;
            Size normalSize = new Size(640, 420);
            using (var form = new Form
            {
                StartPosition = FormStartPosition.Manual,
                Location = new Point(area.Left + 24, area.Top + 24),
                Size = normalSize,
                MinimumSize = new Size(360, 300),
                ShowInTaskbar = false,
                Opacity = 0
            })
            {
                form.Show();
                Application.DoEvents();
                foreach (bool maximize in new[] { false, true })
                for (int application = 0; application < 2; application++)
                {
                    ScreenModeSettings.Apply(form, maximize, normalSize);
                    Application.DoEvents();
                    if (maximize)
                    {
                        if (form.WindowState != FormWindowState.Maximized)
                            throw new InvalidOperationException("Main workspace did not maximize.");
                        form.WindowState = FormWindowState.Normal;
                        Application.DoEvents();
                    }
                    int width = Math.Min(normalSize.Width, Math.Max(360, area.Width - 48));
                    int height = Math.Min(normalSize.Height, Math.Max(420, area.Height - 48));
                    var expected = new Rectangle(area.Left + Math.Max(0, (area.Width - width) / 2),
                        area.Top + Math.Max(0, (area.Height - height) / 2), width, height);
                    if (form.WindowState != FormWindowState.Normal || form.Bounds != expected)
                        throw new InvalidOperationException("Main workspace lost normal restore bounds: actual=" + form.Bounds + "; expected=" + expected + ".");
                }
                form.Close();
                Application.DoEvents();
            }
        }

