        private static void VerifyRoundedShapePolicy()
        {
            using (var button = new Button { Size = new Size(140, 40) })
            using (var card = new Panel { Size = new Size(320, 160) })
            {
                WinFormsShapeAdapter.ApplyAction(button);
                WinFormsShapeAdapter.ApplyCard(card);
                if (button.Region == null || card.Region == null || button.Region.IsVisible(0, 0) || card.Region.IsVisible(0, 0))
                    throw new InvalidOperationException("Rounded action/card policy was not applied.");
                button.Height = 52;
                if (button.Region == null || button.Region.IsVisible(0, 0))
                    throw new InvalidOperationException("Rounded action radius was not refreshed after resize.");
            }
        }

        private static void VerifyReturnEditorSharedComponents()
        {
            string originalMode=Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string mode in new[]{"Light","Dark"})
                foreach(bool english in new[]{false,true})
                {
                    Properties.Setings.Default.ThemeMode=mode;
                    using(var form=new CommercialSalesReturnForm(Guid.NewGuid(),true,english))
                    {
                        form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();
                        var reason=Require<TextBox>(form,"commercialReturnReason");
                        var frame=Require<AntdUI.Panel>(form,"commercialReturnReasonFrame");
                        var card=Require<AntdUI.Panel>(form,"commercialReturnGridCard");
                        var grid=Require<DataGridView>(form,"commercialReturnLotsGrid");
                        var refund=Require<AntdUI.Select>(form,"commercialReturnRefund");
                        var pendingField=typeof(CommercialSalesReturnForm).GetField("pendingRequest",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);
                        var pending=new CommercialSalesReturnRequest { RequestId=Guid.NewGuid().ToString("N") };
                        pendingField.SetValue(form,pending);
                        var businessDate=typeof(CommercialSalesReturnForm).GetField("pendingBusinessDateUtc",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);
                        DateTime date=new DateTime(2026,9,30,12,0,0,DateTimeKind.Utc);businessDate.SetValue(form,date);
                        var originalText=reason.Text;
                        Size minimumClient=new Size(form.MinimumSize.Width-(form.Width-form.ClientSize.Width),form.MinimumSize.Height-(form.Height-form.ClientSize.Height));
                        foreach(Size size in new[]{minimumClient,new Size(960,640),new Size(1366,768)})
                        {
                            Prepare(form,size);Application.DoEvents();
                            var editor=Require<TableLayoutPanel>(form,"commercialReturnEditor");
                            if(frame.Height<44 || frame.Shadow!=0 || frame.Radius!=DesktopDesignTokens.ActionRadius(frame.Height) ||
                                card.Radius!=12 || card.Shadow!=0 || !editor.ClientRectangle.Contains(frame.Bounds) ||
                                !frame.ClientRectangle.Contains(reason.Bounds) || Math.Abs(reason.Top+reason.Height/2-frame.ClientSize.Height/2)>2 ||
                                reason.BorderStyle!=BorderStyle.None || reason.MaxLength!=500 || reason.Text!=originalText ||
                                reason.RightToLeft!=RightToLeft.Yes || reason.TextAlign!=HorizontalAlignment.Left ||
                                refund.SelectedIndex!=0 || pendingField.GetValue(form)!=pending || (DateTime)businessDate.GetValue(form)!=date ||
                                grid.Height<grid.ColumnHeadersHeight+grid.Rows[0].Height+2 || grid.Columns.Cast<DataGridViewColumn>().Any(column=>!column.ReadOnly))
                                throw new InvalidOperationException("Return editor layout changed draft values, retry request, or native field geometry.");
                        }
                        typeof(CommercialSalesReturnForm).GetMethod("SetSubmissionInProgress",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(form,new object[]{false});
                        // The locked request stays reviewable but frozen: the reason, the refund method
                        // and the lots remain visible for reading and copying, and none of them accepts
                        // an edit, so the retried request stays exactly the one that was saved.
                        if (!reason.Enabled || !reason.ReadOnly || refund.Enabled || !grid.Enabled || !grid.ReadOnly ||
                            pendingField.GetValue(form)!=pending)
                            throw new InvalidOperationException("An uncertain return must keep its exact locked request, reviewable but read-only.");
                        pendingField.SetValue(form,null);
                        var source=new DataTable();source.Columns.Add("LineId",typeof(Guid));source.Columns.Add("AllocationId",typeof(Guid));
                        source.Columns.Add("الصنف");source.Columns.Add("الدفعة");source.Columns.Add("المتاح للإرجاع",typeof(decimal));source.Columns.Add("كمية المرتجع",typeof(decimal));
                        source.Rows.Add(Guid.NewGuid(),Guid.NewGuid(),"باراسيتامول 500 mg","B-2026-17",12.5m,1m);
                        grid.DataSource=source;Application.DoEvents();
                        if(grid.Columns["LineId"].Visible || grid.Columns["AllocationId"].Visible ||
                            grid.Columns["الصنف"].HeaderText!=(english?"Medicine":"الصنف") ||
                            grid.Columns["المتاح للإرجاع"].HeaderText!=(english?"Available to return":"المتاح للإرجاع") ||
                            grid.Columns["كمية المرتجع"].HeaderText!=(english?"Return quantity":"كمية المرتجع") ||
                            (decimal)grid.Rows[0].Cells["المتاح للإرجاع"].Value!=12.5m)
                            throw new InvalidOperationException("Actual return lot columns must follow display language without changing quantities.");
                        var choices=(CommercialReturnChoice[])typeof(CommercialSalesReturnForm).GetMethod("CreateDispositionChoices",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(form,null);
                        if(choices.Length!=CommercialReturnPresentation.Dispositions.Count ||
                            choices.Where((choice,index)=>choice.Code!=CommercialReturnPresentation.Dispositions[index].Code ||
                                choice.Label!=(english?UiLanguageCatalog.Translate(CommercialReturnPresentation.Dispositions[index].Label):CommercialReturnPresentation.Dispositions[index].Label)).Any())
                            throw new InvalidOperationException("Localized return disposition choices must retain stored codes.");
                    }
                }
            }
            finally {Properties.Setings.Default.ThemeMode=originalMode;using(var refresh=new Form())UiTheme.Apply(refresh);}
        }

