                                card.Shadow!=0 || card.Radius!=12 || !editor.ClientRectangle.Contains(frame.Bounds) ||
                                reason.Parent!=frame || reason.BorderStyle!=BorderStyle.None || reason.MaxLength!=500 ||
                                reason.RightToLeft!=RightToLeft.Yes || reason.TextAlign!=HorizontalAlignment.Left ||
                                Math.Abs(reason.Top+reason.Height/2-frame.ClientSize.Height/2)>2 ||
                                !frame.ClientRectangle.Contains(reason.Bounds) || Require<AntdUI.Button>(form,"approveQuarantineResolution").Enabled)
                                throw new InvalidOperationException("Quarantine component layout lost review data, retry identity or native field geometry at "+size+"; theme="+mode+"; english="+english+"; reasonSame="+(reason.Text=="مراجعة دفعة BATCH-500 قبل اعتماد القرار")+"; quantitySame="+(quantity.Value==value)+"; choiceSame="+(choice.SelectedItem==selected)+"; requestSame="+((string)id.GetValue(form)=="same-review-request")+"; sourceHeight="+source.Height+"; requiredSource="+(source.ColumnHeadersHeight+source.Rows[0].Height+SystemInformation.HorizontalScrollBarHeight+2)+"; frame="+frame.Bounds+"; editor="+editor.ClientRectangle+"; nativeReason="+reason.Bounds+"; frameClient="+frame.ClientRectangle+"; reasonRTL="+reason.RightToLeft+"; reasonAlign="+reason.TextAlign);
                        }
                        reason.Text="Review BATCH-500";
