        private static void VerifyQaCsvImportLayout()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new QaCsvImportForm(true))
                    {
                        foreach (Size size in new[] { new Size(640, 480), new Size(720, 520), new Size(1024, 720), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            Panel header = Require<Panel>(form, "csvImportHeader");
                            FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "csvImportActions");
                            DataGridView grid = Require<DataGridView>(form, "qaCsvPreviewGrid");
                            AntdUI.Button import = Require<AntdUI.Button>(form, "executeCsvImport");
                            AntdUI.Select kind = Require<AntdUI.Select>(form, "csvImportKind");
                            Panel filter = Require<Panel>(form, "csvImportFilter");
                            Label kindLabel = Require<Label>(form, "csvImportKindLabel");
                            if (header.Top != 0 || actions.Bottom != form.ClientSize.Height ||
                                actions.HorizontalScroll.Visible || !grid.ReadOnly || grid.AllowUserToDeleteRows ||
                                !actions.ClientRectangle.Contains(import.Bounds) || import.DefaultBorderColor != UiTheme.Primary ||
                                import.Enabled || kind.Items.Count != 2 || grid.Rows.Count != 1 ||
                                kind.Right >= kindLabel.Left || filter.ClientSize.Width - kindLabel.Right > 26 ||
                                string.IsNullOrWhiteSpace(grid.AccessibleName))
                                throw new InvalidOperationException("Excel import layout or accessibility is invalid at " + size + " in " + mode + ".");
                        }
                        Require<AntdUI.Select>(form, "csvImportKind").SelectedIndex = 0;
                        if (Require<DataGridView>(form, "qaCsvPreviewGrid").Rows.Count != 0 ||
                            Require<AntdUI.Button>(form, "executeCsvImport").Enabled)
                            throw new InvalidOperationException("Changing the import category retained a stale preview.");
                        if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox)
                            throw new InvalidOperationException("Import window must support resize, maximize, and minimize.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        private static void VerifyInvoiceImportHintLayout()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool approveNow in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new InvoiceImportDraftForm(true))
                    {
                        form.ApplyPresentation(english);
                        if (approveNow) form.SetPreviewDirectMode(); else form.SetPreviewDraftMode();
                        if (form.Controls["__UiStatusStrip"] != null)
                            throw new InvalidOperationException("Invoice import preview must not display a database-ready status strip without a database session.");
                        Size minimumClient = new Size(form.MinimumSize.Width - (form.Width - form.ClientSize.Width),
                            form.MinimumSize.Height - (form.Height - form.ClientSize.Height));
                        foreach (Size size in new[] { minimumClient, new Size(660, 500), new Size(900, 650), new Size(1200, 800) })
                        {
                            Prepare(form, size);
                            Label hint = Require<Label>(form, "invoiceDraftHint");
                            int textHeight = TextRenderer.MeasureText(hint.Text, hint.Font,
                                new Size(hint.ClientSize.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                            if (textHeight > hint.ClientSize.Height)
                                throw new InvalidOperationException("Invoice import mode explanation is clipped: " +
                                    (english ? "English" : "Arabic") + "/" + approveNow + "/" + size +
                                    "; required=" + textHeight + "; available=" + hint.ClientSize.Height);
                            if (hint.AutoEllipsis || hint.AccessibleName != hint.Text ||
                                hint.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                hint.TextAlign != ContentAlignment.MiddleLeft ||
                                Require<Label>(form, "invoiceDraftTitle").RightToLeft != hint.RightToLeft ||
                                Require<DataGridView>(form, "invoiceDraftGrid").Height < 120 ||
                                Require<AntdUI.Button>(form, "invoiceDraftSave").Enabled ||
                                Require<AntdUI.Button>(form, approveNow ? "invoiceDraftApproveMode" : "invoiceDraftReviewMode")
                                    .AccessibleDescription != (english ? "Selected mode" : "الخيار المحدد"))
                                throw new InvalidOperationException("Invoice import explanation lost its full accessible text, selected mode or safe preview boundary.");
                        }
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = originalMode; }
        }

        private static void VerifyInvoiceImportDraftLayout()
        {
            VerifyConfirmedImportRefreshFailure();
            VerifyImportedDraftPostingStatus();
            VerifyInvoiceImportHintLayout();
            VerifyInvoiceImportFilePipeline();
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new InvoiceImportDraftForm(true))
                    {
                        if (Require<AntdUI.Button>(form, "invoiceDraftApproveMode").AccessibleDescription != "الخيار المحدد" ||
                            Require<AntdUI.Button>(form, "invoiceDraftReviewMode").AccessibleDescription == "الخيار المحدد")
                            throw new InvalidOperationException("Invoice import must start in direct approval mode.");
                        foreach (Size size in new[] { new Size(660, 500), new Size(900, 650), new Size(1200, 800) })
                        {
                            Prepare(form, size);
                            Panel header = Require<Panel>(form, "invoiceDraftHeader");
                            FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "invoiceDraftFooter");
                            DataGridView grid = Require<DataGridView>(form, "invoiceDraftGrid");
                            TextBox system = Require<TextBox>(form, "invoiceDraftSystemInput");
                            AntdUI.Button save = Require<AntdUI.Button>(form, "invoiceDraftSave");
                            AntdUI.Button directChoice = Require<AntdUI.Button>(form, "invoiceDraftApproveMode");
                            AntdUI.Button draftChoice = Require<AntdUI.Button>(form, "invoiceDraftReviewMode");
                            if (directChoice.Height < 44 || draftChoice.Height < 44 ||
                                directChoice.Width < TextRenderer.MeasureText(directChoice.Text, directChoice.Font).Width + 36 ||
                                draftChoice.Width < TextRenderer.MeasureText(draftChoice.Text, draftChoice.Font).Width + 36)
                                throw new InvalidOperationException("Invoice import mode choices clip at " + size + " in " + mode + ".");
                            if (header.Top != 0 || footer.Bottom != form.ClientSize.Height ||
                                footer.Controls.Cast<Control>().Where(control => control.Visible).Any(control => !footer.ClientRectangle.Contains(control.Bounds)) ||
                                grid.Height < 120 || grid.Rows.Count != 1 || !grid.ReadOnly ||
                                system.Text != "Legacy" || Require<AntdUI.Panel>(form, "invoiceDraftSystemFrame").Height < 44 || system.Width < 160 || save.Enabled || save.Height < 44)
                                throw new InvalidOperationException("Invoice draft preview clips or allows save at " + size + " in " + mode + ".");
                            grid.Rows[0].Selected = true;
                            typeof(InvoiceImportDraftForm).GetMethod("OpenCandidate", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                                .Invoke(form, null);
                            Prepare(form, size);
                            if (Require<Panel>(form, "invoiceDraftInputHost").Height != 72 ||
                                !Require<TextBox>(form, "invoiceDraftMetadata").Text.Contains("C-001") ||
                                Require<TextBox>(form, "invoiceDraftMetadata").TextAlign != HorizontalAlignment.Right ||
                                grid.Height < 120 || grid.Columns.Count != 10 ||
                                footer.Controls.Cast<Control>().Where(control => control.Visible).Any(control => !footer.ClientRectangle.Contains(control.Bounds)))
                                throw new InvalidOperationException("Invoice line review clips or omits metadata at " + size + " in " + mode + ".");
                            typeof(InvoiceImportDraftForm).GetMethod("ShowNew", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                                .Invoke(form, null);
                        }
                        form.ApplyPresentation(true);
                        Prepare(form, new Size(660, 500));
                        if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                            Require<Label>(form, "invoiceDraftTitle").Text != "Import and review Excel invoices" ||
                            Require<Label>(form, "invoiceDraftSystemLabel").Text != "Source system" ||
                            Require<TextBox>(form, "invoiceDraftSystemInput").RightToLeft != RightToLeft.No ||
                            Require<TextBox>(form, "invoiceDraftMetadata").TextAlign != HorizontalAlignment.Left ||
                            Require<FlowLayoutPanel>(form, "invoiceDraftFooter").FlowDirection != FlowDirection.LeftToRight ||
                            Require<DataGridView>(form, "invoiceDraftGrid").Columns[0].HeaderText != "Kind")
                            throw new InvalidOperationException("Invoice draft English presentation lost LTR or labels.");
                        DataGridView sourceGrid = Require<DataGridView>(form, "invoiceDraftGrid");
                        DataGridViewColumn partyColumn = sourceGrid.Columns[3];
                        int partyHeaderHeight = TextRenderer.MeasureText(partyColumn.HeaderText,
                            sourceGrid.ColumnHeadersDefaultCellStyle.Font,
                            new Size(Math.Max(1, partyColumn.Width - 8), int.MaxValue),
                            TextFormatFlags.WordBreak | TextFormatFlags.NoPadding).Height;
                        if (sourceGrid.ColumnHeadersHeight < partyHeaderHeight)
                            throw new InvalidOperationException("Invoice import customer/supplier header clips in the compact English interface.");
                        TextBox sourceName = Require<TextBox>(form, "invoiceDraftSystemInput");
                        AntdUI.Panel sourceFrame = Require<AntdUI.Panel>(form, "invoiceDraftSystemFrame");
                        sourceName.Text = "نظام Pharma 01";
                        UiTheme.Apply(form);
                        form.ApplyPresentation(true);
                        if (sourceName.Text != "نظام Pharma 01" || sourceName.RightToLeft != RightToLeft.Yes ||
                            sourceName.TextAlign != HorizontalAlignment.Left || sourceName.BorderStyle != BorderStyle.None ||
                            sourceFrame.Radius != DesktopDesignTokens.ActionRadius(sourceFrame.Height) || sourceFrame.Shadow != 0 ||
                            sourceName.Top != Math.Max(0, (sourceFrame.ClientSize.Height - sourceName.PreferredHeight) / 2))
                            throw new InvalidOperationException("Invoice source mixed Arabic input lost its direction, shared frame or centering after theme application.");
                        sourceName.Text = "Legacy";
                        if (sourceName.RightToLeft != RightToLeft.No)
                            throw new InvalidOperationException("Invoice source Latin text did not restore LTR in the English interface.");
                        typeof(InvoiceImportDraftForm).GetMethod("SelectImportMode", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                            .Invoke(form, new object[] { false });
                        Prepare(form, new Size(660, 500));
                        if (Require<AntdUI.Button>(form, "invoiceDraftReviewMode").AccessibleDescription != "Selected mode" ||
                            Require<AntdUI.Button>(form, "invoiceDraftSave").Text != "Save drafts" ||
                            !Require<AntdUI.Button>(form, "invoiceDraftReviewMode").Enabled)
                            throw new InvalidOperationException("Optional draft mode is unavailable. Selected=" +
                                Require<AntdUI.Button>(form, "invoiceDraftReviewMode").AccessibleDescription + "; Action=" +
                                Require<AntdUI.Button>(form, "invoiceDraftSave").Text + "; Enabled=" +
                                Require<AntdUI.Button>(form, "invoiceDraftReviewMode").Enabled);
                        typeof(InvoiceImportDraftForm).GetMethod("SelectImportMode", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                            .Invoke(form, new object[] { true });
                        Prepare(form, new Size(660, 500));
                        if (Require<AntdUI.Button>(form, "invoiceDraftApproveMode").AccessibleDescription != "Selected mode" ||
                            !Require<Label>(form, "invoiceDraftHint").Text.Contains("stock and accounts") ||
                            Require<AntdUI.Button>(form, "invoiceDraftSave").Enabled ||
                            Require<FlowLayoutPanel>(form, "invoiceDraftFooter").Controls.Cast<Control>()
                                .Where(control => control.Visible).Any(control =>
                                    !Require<FlowLayoutPanel>(form, "invoiceDraftFooter").ClientRectangle.Contains(control.Bounds)))
                            throw new InvalidOperationException("Direct invoice preview mode is clipped or writable at 660x500.");
                        VerifyInvoiceImportStatusAtMinimum(form);
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        private sealed class DraftSaveService : IInvoiceImportDraftService
        {
            private readonly List<InvoiceImportDraftSummary> summaries = new List<InvoiceImportDraftSummary>();
            internal int SaveCalls;
            public IReadOnlyList<Guid> SaveBatch(IReadOnlyList<InvoiceImportCandidate> batch, OperationActor actor)
            {
                SaveCalls++;
                var ids = new List<Guid>();
                foreach (InvoiceImportCandidate candidate in batch)
                {
                    Guid id = Guid.NewGuid(); ids.Add(id);
                    summaries.Add(new InvoiceImportDraftSummary { DraftId = id, SourceSystem = candidate.SourceSystem,
                        SourceInvoiceId = candidate.SourceInvoiceId, Kind = candidate.Kind, InvoiceDate = candidate.InvoiceDate,
                        PartyName = candidate.PartyName, Status = "Draft" });
                }
                return ids;
            }
            public InvoiceImportDraftRecord Get(Guid id, OperationActor actor)
            {
                InvoiceImportDraftSummary item = summaries.FirstOrDefault(summary => summary.DraftId == id);
                return item == null ? null : new InvoiceImportDraftRecord { DraftId = id, Status = item.Status };
            }
            public IReadOnlyList<InvoiceImportDraftSummary> ListRecent(OperationActor actor) { return summaries.ToArray(); }
        }
        private sealed class DraftStatusService : IInvoiceImportDraftService
        {
            internal InvoiceImportDraftRecord Record;
            internal int SaveCalls;
            internal bool FailList;
            public IReadOnlyList<Guid> SaveBatch(IReadOnlyList<InvoiceImportCandidate> batch, OperationActor actor)
            { SaveCalls++; throw new InvalidOperationException("This status test must never save."); }
            public InvoiceImportDraftRecord Get(Guid id, OperationActor actor) { return Record; }
            public IReadOnlyList<InvoiceImportDraftSummary> ListRecent(OperationActor actor)
            {
                if (FailList) throw new InvalidOperationException("Simulated list failure after a confirmed write.");
                return new[] { new InvoiceImportDraftSummary { DraftId = Record.DraftId,
                    SourceSystem = Record.Candidate.SourceSystem, SourceInvoiceId = Record.Candidate.SourceInvoiceId,
                    Kind = Record.Candidate.Kind, InvoiceDate = Record.Candidate.InvoiceDate,
                    PartyName = Record.Candidate.PartyName, Status = Record.Status } };
            }
        }

        private static void CompleteImportRead(InvoiceImportDraftForm form, string method, params object[] arguments)
        {
            var task = (System.Threading.Tasks.Task)typeof(InvoiceImportDraftForm).GetMethod(method,
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(form, arguments);
            var timer = System.Diagnostics.Stopwatch.StartNew();
            while (!task.IsCompleted && timer.ElapsedMilliseconds < 5000)
            { Application.DoEvents(); System.Threading.Thread.Sleep(1); }
            if (!task.IsCompleted) throw new InvalidOperationException("Invoice status test timed out.");
            task.GetAwaiter().GetResult();
        }

        private static void VerifyConfirmedImportRefreshFailure()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool approval in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    InvoiceImportCandidate candidate;
                    using (var sample = new InvoiceImportDraftForm(true))
                        candidate = ((IReadOnlyList<InvoiceImportCandidate>)typeof(InvoiceImportDraftForm).GetField("candidates",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(sample))[0];
                    var service = new DraftStatusService { Record = new InvoiceImportDraftRecord {
                        DraftId = Guid.NewGuid(), Candidate = candidate, Status = "Draft" } };
                    using (var form = new InvoiceImportDraftForm(false, service))
                    {
                        Prepare(form, new Size(660, 500));
                        CompleteImportRead(form, "ShowSavedAsync");
                        DataGridView grid = Require<DataGridView>(form, "invoiceDraftGrid");
                        grid.Rows[0].Selected = true;
                        CompleteImportRead(form, "OpenSelectedAsync");
                        service.FailList = true;
                        var actor = new OperationActor { UserName = "test", UserRole = "Admin" };
                        if (approval)
                            CompleteImportRead(form, "RefreshAfterConfirmedWriteAsync", null, "000321", service.Record.DraftId, actor);
                        else
                            CompleteImportRead(form, "ShowSavedAfterSaveAsync", 3, actor);
                        foreach (bool english in new[] { false, true, false })
                        {
                            form.ApplyPresentation(english);
                            form.Size = form.MinimumSize;
                            Label status = Require<Label>(form, "invoiceDraftStatus");
                            string expected = approval ? (english ? "Draft approved as 000321" : "اعتُمدت المسودة برقم 000321") :
                                (english ? "Saved 3 drafts" : "حُفظت 3 مسودة");
                            if (!status.Text.Contains(expected) || !status.Text.Contains(english ? "Support code:" : "رمز الدعم:") ||
                                status.AccessibleName != status.Text || service.SaveCalls != 0 ||
                                Require<AntdUI.Button>(form, "invoiceDraftSave").Visible ||
                                !Require<AntdUI.Button>(form, "invoiceDraftRefresh").Enabled)
                                throw new InvalidOperationException("Confirmed import success was lost after refresh failure.");
                            if (grid.Columns["Kind"].HeaderText != (english ? "Kind" : "النوع") ||
                                !Require<Label>(form, "invoiceDraftHint").Text.Contains(english ? "document's status" : "حالة كل مستند"))
                                throw new InvalidOperationException("The failed-refresh saved list retains another view's labels.");
                            int needed = TextRenderer.MeasureText(status.Text, status.Font,
                                new Size(Math.Max(1, status.ClientSize.Width - status.Padding.Horizontal), int.MaxValue),
                                TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                            if (needed > status.ClientSize.Height - status.Padding.Vertical)
                                throw new InvalidOperationException("Confirmed import refresh message is clipped.");
                        }
                        if (approval)
                        {
                            grid.Rows[0].Selected = true;
                            if (Require<AntdUI.Button>(form, "invoiceDraftApprove").Enabled)
                                throw new InvalidOperationException("Confirmed draft can be approved twice after refresh failure.");
                            service.FailList = false;
                            service.Record.Status = "Draft"; // Simulate a delayed reader with stale state.
                            CompleteImportRead(form, "ShowSavedAsync");
                            grid.Rows[0].Selected = true;
                            if (Require<AntdUI.Button>(form, "invoiceDraftApprove").Enabled)
                                throw new InvalidOperationException("A stale refresh enabled a confirmed draft.");
                            CompleteImportRead(form, "OpenSelectedAsync");
                            if (!Require<Label>(form, "invoiceDraftStatus").Text.Contains("000321") ||
                                Require<AntdUI.Button>(form, "invoiceDraftApprove").Enabled)
                                throw new InvalidOperationException("Reopening a confirmed draft lost its posting snapshot.");
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        private static void VerifyImportedDraftPostingStatus()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (string state in new[] { "Draft", "Approved", "Unknown" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    InvoiceImportCandidate candidate;
                    using (var sample = new InvoiceImportDraftForm(true))
                        candidate = ((IReadOnlyList<InvoiceImportCandidate>)typeof(InvoiceImportDraftForm).GetField("candidates",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(sample))[0];
                    var service = new DraftStatusService { Record = new InvoiceImportDraftRecord {
                        DraftId = Guid.NewGuid(), Candidate = candidate, Status = state, ApprovedReference = "000123" } };
                    using (var form = new InvoiceImportDraftForm(false, service))
                    {
                        Prepare(form, new Size(660, 500));
                        CompleteImportRead(form, "ShowSavedAsync");
                        DataGridView grid = Require<DataGridView>(form, "invoiceDraftGrid");
                        grid.Rows[0].Selected = true;
                        CompleteImportRead(form, "OpenSelectedAsync");
                        foreach (bool english in new[] { false, true, false })
                        {
                            form.ApplyPresentation(english);
                            form.Size = form.MinimumSize;
                            Label status = Require<Label>(form, "invoiceDraftStatus");
                            string expected = state == "Draft" ? (english ? "no stock or journal posting" : "لا توجد حركة مخزون") :
                                state == "Approved" ? (english ? "stock and journal were posted" : "أُثبت أثرها") :
                                (english ? "status is unknown" : "حالة المسودة غير معروفة");
                            if (!status.Text.Contains(expected) || status.AccessibleName != status.Text ||
                                (state == "Approved" && !status.Text.Contains("000123")) ||
                                Require<AntdUI.Button>(form, "invoiceDraftApprove").Enabled != (state == "Draft") ||
                                !Require<TextBox>(form, "invoiceDraftMetadata").Text.Contains(candidate.SourceInvoiceId) ||
                                grid.Rows.Count != candidate.Lines.Count || service.SaveCalls != 0)
                                throw new InvalidOperationException("Imported draft status misrepresents its posting state: " + state + "/" + english);
                            int needed = TextRenderer.MeasureText(status.Text, status.Font,
                                new Size(Math.Max(1, status.ClientSize.Width - status.Padding.Horizontal), int.MaxValue),
                                TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                            if (needed > status.ClientSize.Height - status.Padding.Vertical)
                                throw new InvalidOperationException("Imported document status is clipped at the minimum window size.");
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        private static void VerifyInvoiceImportStatusAtMinimum(InvoiceImportDraftForm form)
        {
            foreach (bool english in new[] { false, true })
            {
                form.ApplyPresentation(english);
                form.Size = form.MinimumSize;
                string[] messages = english ? new[] {
                    "Approval result is uncertain. Check draft status and invoice history before retrying.",
                    "Template saved. Dates: yyyy-MM-dd. IDs and barcodes retain zeros."
                } : new[] {
                    "تعذر تأكيد نتيجة الاعتماد؛ راجع حالة المسودة والفاتورة قبل إعادة المحاولة.",
                    "حُفظ القالب. التواريخ yyyy-MM-dd؛ أصفار المعرّفات والباركود محفوظة."
                };
                foreach (string message in messages)
                {
                    typeof(InvoiceImportDraftForm).GetMethod("SetStatus", System.Reflection.BindingFlags.Instance |
                        System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { message, false });
                    form.PerformLayout();
                    Application.DoEvents();
                    Label status = Require<Label>(form, "invoiceDraftStatus");
                    int textHeight = TextRenderer.MeasureText(status.Text, status.Font,
                        new Size(Math.Max(1, status.ClientSize.Width - status.Padding.Horizontal), int.MaxValue),
                        TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                    DataGridView grid = Require<DataGridView>(form, "invoiceDraftGrid");
                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "invoiceDraftFooter");
                    if (status.AutoEllipsis || status.AccessibleName != message ||
                        textHeight > status.ClientSize.Height - status.Padding.Vertical ||
                        grid.Height < 120 || footer.Bottom != form.ClientSize.Height ||
                        footer.Controls.Cast<Control>().Where(control => control.Visible).Any(control =>
                            !footer.ClientRectangle.Contains(control.Bounds)) ||
                        Require<AntdUI.Button>(form, "invoiceDraftSave").Enabled)
                        throw new InvalidOperationException("Invoice import status or actions clip at the real minimum window in " +
                            (english ? "English" : "Arabic") + ".");
                }
            }
        }

        private static void VerifyMedicineCatalogImportLayout()
        {
            VerifyMedicineCatalogFilePipeline();
            VerifyCatalogImportStatusPersistence();
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new MedicineCatalogImportForm(true))
                    {
                        if (form.Controls["__UiStatusStrip"] != null)
                            throw new InvalidOperationException("Medicine catalog preview must not display a database-ready status strip without a database session.");
                        foreach (Size size in new[] { new Size(640, 480), new Size(720, 520), new Size(1024, 720), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            Panel header = Require<Panel>(form, "catalogImportHeader");
                            FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "catalogImportFooter");
                            DataGridView grid = Require<DataGridView>(form, "catalogImportGrid");
                            AntdUI.Button approve = Require<AntdUI.Button>(form, "catalogImportApprove");
                            if (header.Top != 0 || footer.Bottom != form.ClientSize.Height ||
                                footer.HorizontalScroll.Visible || footer.Controls.Cast<Control>().Any(control => !footer.ClientRectangle.Contains(control.Bounds)) ||
                                Require<AntdUI.Button>(form, "catalogImportErrors").Enabled ||
                                approve.Enabled || approve.DefaultBorderColor != UiTheme.Primary ||
                                !grid.ReadOnly || grid.Rows.Count != 1 || grid.AllowUserToDeleteRows)
                                throw new InvalidOperationException("Production medicine import preview is clipped at " + size + " in " + mode + ".");
                            if (form.ClientSize != size || grid.Height < 120 || grid.ColumnHeadersHeight < 52)
                                throw new InvalidOperationException("Catalog import cannot adapt to the requested viewport " + size);
                            foreach (AntdUI.Button action in footer.Controls.OfType<AntdUI.Button>())
                                if (action.Width < TextRenderer.MeasureText(action.Text, action.Font).Width + 36)
                                    throw new InvalidOperationException("Catalog import action caption clips: " + action.Name + " at " + size);
                        }
                        typeof(MedicineCatalogImportForm).GetMethod("SetBusy", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                            .Invoke(form, new object[] { true });
                        if (Require<AntdUI.Button>(form, "catalogImportClose").Enabled ||
                            Require<AntdUI.Button>(form, "catalogImportApprove").Enabled)
                            throw new InvalidOperationException("Medicine import allows closing or approval during an operation.");
                        typeof(MedicineCatalogImportForm).GetMethod("SetBusy", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                            .Invoke(form, new object[] { false });
                        if (!Require<AntdUI.Button>(form, "catalogImportClose").Enabled ||
                            Require<AntdUI.Button>(form, "catalogImportApprove").Enabled)
                            throw new InvalidOperationException("Medicine import preview did not restore its safe control state.");
                        form.ApplyPresentation(true);
                        Prepare(form, new Size(720, 520));
                        DataGridView englishGrid = Require<DataGridView>(form, "catalogImportGrid");
                        FlowLayoutPanel englishFooter = Require<FlowLayoutPanel>(form, "catalogImportFooter");
                        if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                            form.Text != "Import medicine definitions from Excel" ||
                            Require<Label>(form, "catalogImportTitle").TextAlign != ContentAlignment.MiddleLeft ||
                            Require<Label>(form, "catalogImportFileName").Text != "No file selected." ||
                            Require<Label>(form, "catalogImportFileName").AccessibleName != "No file selected." ||
                            englishFooter.FlowDirection != FlowDirection.LeftToRight ||
                            englishFooter.HorizontalScroll.Visible ||
                            !englishFooter.ClientRectangle.Contains(Require<AntdUI.Button>(form, "catalogImportApprove").Bounds) ||
                            englishGrid.RightToLeft != RightToLeft.No ||
                            englishGrid.Columns[0].HeaderText != "Medicine name" ||
                            !Require<Label>(form, "catalogImportStatus").Text.Contains("Visual preview"))
                            throw new InvalidOperationException("Medicine import English shell or LTR layout is inconsistent.");
                        foreach (Size englishSize in new[] { new Size(640, 480), new Size(720, 520), new Size(1024, 720) })
                        {
                            Prepare(form, englishSize);
                            if (form.ClientSize != englishSize || englishGrid.Height < 120 || englishGrid.ColumnHeadersHeight < 52 ||
                                englishFooter.HorizontalScroll.Visible ||
                                englishFooter.Controls.Cast<Control>().Any(control => !englishFooter.ClientRectangle.Contains(control.Bounds)))
                                throw new InvalidOperationException("English catalog import clips at " + englishSize);
                            foreach (AntdUI.Button action in englishFooter.Controls.OfType<AntdUI.Button>())
                                if (action.Width < TextRenderer.MeasureText(action.Text, action.Font).Width + 36)
                                    throw new InvalidOperationException("English catalog action caption clips: " + action.Name);
                        }
                        form.ApplyPresentation(false);
                        Prepare(form, new Size(720, 520));
                        if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                            form.Text != "استيراد ملف إكسل لتعريفات الأصناف" ||
                            Require<FlowLayoutPanel>(form, "catalogImportFooter").FlowDirection != FlowDirection.RightToLeft ||
                            Require<DataGridView>(form, "catalogImportGrid").Columns[0].HeaderText != "اسم الدواء")
                            throw new InvalidOperationException("Medicine import did not restore Arabic RTL presentation.");
                        DataTable invalidWorkbook = MedicineCatalogWorkbook.CreateTemplate();
                        invalidWorkbook.Rows.Add("باراسيتامول 500 mg", "6281234567890", "0", "15",
                            "2026-01-01", "2027-01-01", "شركة الدواء");
                        invalidWorkbook.Rows.Add("", "6281234567891", "10", "15",
                            "2026-01-01", "2027-01-01", "شركة الدواء");
                        invalidWorkbook.Rows.Add("صنف ثالث", "6281234567892", "10", "15",
                            "2027-01-01", "2026-01-01", "شركة الدواء");
                        MedicineCatalogWorkbookPreview invalidPreview = MedicineCatalogWorkbook.Parse(invalidWorkbook);
                        if (invalidPreview.Issues.Count != 3 || invalidPreview.Issues[2].RowNumber != 4)
                            throw new InvalidOperationException("Medicine import did not retain all rejected rows.");
                        form.ApplyPresentation(true); form.ShowPreview(invalidPreview);
                        if (!Require<Label>(form, "catalogImportStatus").Text.Contains("Row 2: Purchase and sale prices") ||
                            Require<AntdUI.Button>(form, "catalogImportApprove").Enabled ||
                            !Require<AntdUI.Button>(form, "catalogImportErrors").Enabled)
                            throw new InvalidOperationException("English import preview did not show its typed row error safely.");
                        using (var englishIssues = new MedicineCatalogIssuesForm(invalidPreview.Issues, true))
                        {
                            Prepare(englishIssues, new Size(560, 420));
                            DataGridView issueGrid = Require<DataGridView>(englishIssues, "catalogIssuesGrid");
                            if (englishIssues.RightToLeft != RightToLeft.No || issueGrid.RowCount != invalidPreview.Issues.Count ||
                                issueGrid.Columns[0].HeaderText != "Row" || issueGrid.Columns[1].HeaderText != "Issue" ||
                        !Require<StatusStrip>(englishIssues, "__UiStatusStrip").Items[0].Text.Contains("File validation errors") ||
                                Convert.ToString(issueGrid.Rows[0].Cells[1].Value) != invalidPreview.Issues[0].FormatMessage(true) ||
                                Convert.ToString(issueGrid.Rows[2].Cells[0].Value) != "4" ||
                                Convert.ToString(issueGrid.Rows[2].Cells[1].Value) != invalidPreview.Issues[2].FormatMessage(true) ||
                                Require<AntdUI.Button>(englishIssues, "catalogIssuesClose").Text != "Close" ||
                                !Require<FlowLayoutPanel>(englishIssues, "catalogIssuesFooter").ClientRectangle.Contains(
                                    Require<AntdUI.Button>(englishIssues, "catalogIssuesClose").Bounds))
                                throw new InvalidOperationException("English medicine import issue list is incomplete or clipped.");
                        }
                        form.ApplyPresentation(false); form.ShowPreview(invalidPreview);
                        if (!Require<Label>(form, "catalogImportStatus").Text.Contains("السطر 2: سعر الشراء والبيع") ||
                            Require<AntdUI.Button>(form, "catalogImportApprove").Enabled ||
                            !Require<AntdUI.Button>(form, "catalogImportErrors").Enabled)
                            throw new InvalidOperationException("Arabic import preview did not restore its typed row error safely.");
                        using (var arabicIssues = new MedicineCatalogIssuesForm(invalidPreview.Issues, false))
                        {
                            Prepare(arabicIssues, new Size(560, 420));
                            DataGridView issueGrid = Require<DataGridView>(arabicIssues, "catalogIssuesGrid");
                            if (arabicIssues.RightToLeft != RightToLeft.Yes || issueGrid.RowCount != invalidPreview.Issues.Count ||
                                issueGrid.Columns[0].HeaderText != "الصف" || issueGrid.Columns[1].HeaderText != "المشكلة" ||
                        !Require<StatusStrip>(arabicIssues, "__UiStatusStrip").Items[0].Text.Contains("تفاصيل أخطاء الملف") ||
                                Convert.ToString(issueGrid.Rows[0].Cells[1].Value) != invalidPreview.Issues[0].FormatMessage(false) ||
                                Convert.ToString(issueGrid.Rows[2].Cells[0].Value) != "4" ||
                                Convert.ToString(issueGrid.Rows[2].Cells[1].Value) != invalidPreview.Issues[2].FormatMessage(false) ||
                                Require<AntdUI.Button>(arabicIssues, "catalogIssuesClose").Text != "إغلاق" ||
                                !Require<FlowLayoutPanel>(arabicIssues, "catalogIssuesFooter").ClientRectangle.Contains(
                                    Require<AntdUI.Button>(arabicIssues, "catalogIssuesClose").Bounds))
                                throw new InvalidOperationException("Arabic medicine import issue list is incomplete or clipped.");
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }
        private static void VerifyMedicineCatalogFilePipeline()
        {
            string validPath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "pharmacy-catalog-form-" + Guid.NewGuid().ToString("N") + ".xlsx");
            string invalidPath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "pharmacy-catalog-errors-" + Guid.NewGuid().ToString("N") + ".xlsx");
            try
            {
                using (DataTable valid = MedicineCatalogWorkbook.CreateTemplate())
                {
                    valid.Rows.Add("باراسيتامول 500 mg", "QA-CATALOG-000123", "10", "15",
                        DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd"), DateTime.Today.AddYears(1).ToString("yyyy-MM-dd"), "شركة اختبار");
                    using (var output = new System.IO.FileStream(validPath, System.IO.FileMode.CreateNew, System.IO.FileAccess.Write))
                        ExcelWorkbookWriter.Write(valid, valid.TableName, output);
                }
                using (DataTable invalid = MedicineCatalogWorkbook.CreateTemplate())
                {
                    invalid.Rows.Add("باراسيتامول 500 mg", "QA-CATALOG-000124", "0", "15",
                        DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd"), DateTime.Today.AddYears(1).ToString("yyyy-MM-dd"), "شركة اختبار");
                    using (var output = new System.IO.FileStream(invalidPath, System.IO.FileMode.CreateNew, System.IO.FileAccess.Write))
                        ExcelWorkbookWriter.Write(invalid, invalid.TableName, output);
                }
                using (var form = new MedicineCatalogImportForm(false))
                {
                    Prepare(form, new Size(900, 650));
                    CompleteCatalogFileRead(form, validPath);
                    DataGridView grid = Require<DataGridView>(form, "catalogImportGrid");
                    if (grid.Rows.Count != 1 || Convert.ToString(grid.Rows[0].Cells["اسم الدواء"].Value) != "باراسيتامول 500 mg" ||
                        Require<AntdUI.Button>(form, "catalogImportErrors").Enabled)
                        throw new InvalidOperationException("The real XLSX medicine file did not reach the form preview.");
                    CompleteCatalogFileRead(form, invalidPath);
                    if (grid.Rows.Count != 1 || !Require<AntdUI.Button>(form, "catalogImportErrors").Enabled ||
                        Require<AntdUI.Button>(form, "catalogImportApprove").Enabled)
                        throw new InvalidOperationException("The real XLSX validation error was not shown or approval remained enabled.");
                }
                Console.WriteLine("PASS: actual catalog XLSX file reaches the form preview; invalid price appears in the reviewable error state with approval blocked; no import invoked.");
            }
            finally
            {
                if (System.IO.File.Exists(validPath)) System.IO.File.Delete(validPath);
                if (System.IO.File.Exists(invalidPath)) System.IO.File.Delete(invalidPath);
            }
        }

        private static void CompleteCatalogFileRead(MedicineCatalogImportForm form, string path)
        {
            System.Threading.Tasks.Task task = form.LoadFileAsync(path);
            var timer = System.Diagnostics.Stopwatch.StartNew();
            while (!task.IsCompleted && timer.ElapsedMilliseconds < 5000)
            { Application.DoEvents(); System.Threading.Thread.Sleep(1); }
            if (!task.IsCompleted) throw new InvalidOperationException("Catalog file preview timed out.");
            task.GetAwaiter().GetResult();
        }

        private static void VerifyInvoiceImportFilePipeline()
        {
            string path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "pharmacy-invoice-form-" + Guid.NewGuid().ToString("N") + ".xlsx");
            try
            {
                using (DataTable workbook = InvoiceImportWorkbook.CreateTemplate(false))
                {
                    workbook.Rows.Add("بيع", "XLSX-UI-001", "1", DateTime.Today.ToString("yyyy-MM-dd"),
                        "عميل اختبار", "YER", "باراسيتامول 500 mg", "000123", "1.25", "12.50",
                        "C-001", "000000000", "0", "0", "شامل", "فحص ملف فعلي", "", "", "", "", "", "نقدي");
                    using (var output = new System.IO.FileStream(path, System.IO.FileMode.CreateNew, System.IO.FileAccess.Write))
                        ExcelWorkbookWriter.Write(workbook, workbook.TableName, output);
                }
                foreach (bool draft in new[] { false, true })
                {
                    using (var form = new InvoiceImportDraftForm(false, new DraftStatusService()))
                    {
                        Prepare(form, new Size(900, 650));
                        Require<TextBox>(form, "invoiceDraftSystemInput").Text = "QA-XLSX-UI";
                        if (draft)
                            typeof(InvoiceImportDraftForm).GetMethod("SelectImportMode",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { false });
                        CompleteImportRead(form, "LoadFileAsync", path);
                        DataGridView grid = Require<DataGridView>(form, "invoiceDraftGrid");
                        var candidates = (IReadOnlyList<InvoiceImportCandidate>)typeof(InvoiceImportDraftForm).GetField("candidates",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(form);
                        if (grid.Rows.Count != 1 || candidates == null || candidates.Count != 1 ||
                            candidates[0].SourceInvoiceId != "XLSX-UI-001" || candidates[0].Lines[0].Barcode != "000123" ||
                            !Require<Label>(form, "invoiceDraftStatus").Text.Contains(draft ? "مسودات فقط" : "لاعتمادها فورًا"))
                            throw new InvalidOperationException("The invoice form did not preview the real XLSX in the selected mode.");
                    }
                }
                var savingService = new DraftSaveService();
                using (var savingForm = new InvoiceImportDraftForm(false, savingService))
                {
                    Prepare(savingForm, new Size(900, 650));
                    Require<TextBox>(savingForm, "invoiceDraftSystemInput").Text = "QA-XLSX-UI";
                    typeof(InvoiceImportDraftForm).GetMethod("SelectImportMode",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(savingForm, new object[] { false });
                    CompleteImportRead(savingForm, "LoadFileAsync", path);
                    CompleteImportRead(savingForm, "SaveAsync");
                    if (savingService.SaveCalls != 1 ||
                        typeof(InvoiceImportDraftForm).GetField("candidates", System.Reflection.BindingFlags.Instance |
                            System.Reflection.BindingFlags.NonPublic).GetValue(savingForm) != null ||
                        Require<DataGridView>(savingForm, "invoiceDraftGrid").Rows.Count != 1 ||
                        !(Require<Label>(savingForm, "invoiceDraftStatus").Text.Contains("Latest 1 drafts") ||
                          Require<Label>(savingForm, "invoiceDraftStatus").Text.Contains("أحدث 1 مسودة")))
                        throw new InvalidOperationException("The invoice form did not save the selected XLSX candidate as one review draft. SaveCalls=" + savingService.SaveCalls + "; candidatesCleared=" + (typeof(InvoiceImportDraftForm).GetField("candidates", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(savingForm) == null) + "; rows=" + Require<DataGridView>(savingForm, "invoiceDraftGrid").Rows.Count + "; status=" + Require<Label>(savingForm, "invoiceDraftStatus").Text + "; view=" + typeof(InvoiceImportDraftForm).GetField("view", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(savingForm));
                }
                Console.WriteLine("PASS: actual invoice XLSX file reaches the form in direct/draft modes; draft save orchestration calls the service once; no SQL or approval invoked.");
            }
            finally { if (System.IO.File.Exists(path)) System.IO.File.Delete(path); }
        }
        private static void VerifyCatalogImportStatusPersistence()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var form = new MedicineCatalogImportForm(true))
                    {
                        DataTable input = MedicineCatalogWorkbook.CreateTemplate();
                        input.Rows.Add("", "000123", "0", "0", "2026-01-01", "2027-01-01", "");
                        input.Rows.Add("دواء Pharma", "000124", "0", "0", "2026-01-01", "2027-01-01", "شركة Pharma");
                        MedicineCatalogWorkbookPreview invalid = MedicineCatalogWorkbook.Parse(input);
                        form.ShowPreview(invalid);
                        foreach (bool english in new[] { false, true, false })
                        foreach (Size size in new[] { new Size(640, 480), new Size(1024, 720) })
                        {
                            form.ApplyPresentation(english);
                            if (size.Width == 640) { Prepare(form, size); form.Size = form.MinimumSize; }
                            else Prepare(form, size);
                            Label status = Require<Label>(form, "catalogImportStatus");
                            Label hint = Require<Label>(form, "catalogImportHint");
                            DataGridView grid = Require<DataGridView>(form, "catalogImportGrid");
                            if (!status.Text.Contains(english ? "errors: 2" : "أخطاء: 2") ||
                                !status.AccessibleDescription.Contains(invalid.Issues[0].Format(english)) ||
                                status.AccessibleName != status.Text ||
                                status.AccessibleRole != AccessibleRole.StatusBar ||
                                !ReferenceEquals(grid.DataSource, invalid.Table) || grid.Rows.Count != 2 ||
                                Require<AntdUI.Button>(form, "catalogImportApprove").Enabled ||
                                !Require<AntdUI.Button>(form, "catalogImportErrors").Enabled || grid.Height < 120)
                                throw new InvalidOperationException("Catalog validation state was lost or clips the table after language/size changes.");
                            foreach (Label label in new[] { status, hint })
                            {
                                int needed = TextRenderer.MeasureText(label.Text, label.Font,
                                    new Size(label.ClientSize.Width, int.MaxValue),
                                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                                if (needed > label.ClientSize.Height || label.AutoEllipsis)
                                    throw new InvalidOperationException("Catalog import hint/status text is clipped at " + form.Size);
                            }
                        }
                        var oversized = new MedicineCatalogWorkbookPreview { Table = input, Medicines = invalid.Medicines,
                            Errors = new[] { "duplicate" }, Issues = new[] { new MedicineCatalogValidationIssue {
                                Code = MedicineCatalogValidationCode.DuplicateColumn, Detail = new string('W', 600) } } };
                        form.ShowPreview(oversized);
                        form.ApplyPresentation(true);
                        form.Size = form.MinimumSize;
                        Label compactStatus = Require<Label>(form, "catalogImportStatus");
                        if (!compactStatus.Text.Contains("Open error details") ||
                            !compactStatus.AccessibleDescription.Contains(new string('W', 600)) ||
                            Require<DataGridView>(form, "catalogImportGrid").Height < 120 ||
                            !Require<AntdUI.Button>(form, "catalogImportErrors").Enabled)
                            throw new InvalidOperationException("Oversized catalog errors did not preserve details while protecting table space.");
                        var setter = typeof(MedicineCatalogImportForm).GetMethod("SetStatus",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                        setter.Invoke(form, new object[] { "اكتمل الاستيراد: {0} صنف جديد، {1} اسم موجود دون تعديل.",
                            (bool?)true, new object[] { 3, 2 } });
                        form.ApplyPresentation(true);
                        if (!Require<Label>(form, "catalogImportStatus").Text.Contains("3 new medicines, 2 existing"))
                            throw new InvalidOperationException("Catalog success counts were discarded or not translated.");
                        setter.Invoke(form, new object[] { "تعذر تأكيد نتيجة الاستيراد؛ راجع قائمة الأصناف قبل إعادة المحاولة.",
                            (bool?)false, new object[0] });
                        form.ApplyPresentation(false);
                        if (!Require<Label>(form, "catalogImportStatus").Text.Contains("تعذر تأكيد نتيجة الاستيراد"))
                            throw new InvalidOperationException("Catalog uncertain import status was replaced with preview copy.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }
        private static void VerifyReportTemplateDetails()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Static |
                System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    foreach (string name in new[] { new string('W', 60), new string('م', 60), "مُراجعة {0} — Pharmacy 500 mg" })
                    using (var form = new OperationalReportBuilderForm(true))
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        Type type = typeof(OperationalReportBuilderForm);
                        var template = new OperationalReportTemplate { Name = name, SourceKey = "DailyPerformance", TemplateId = Guid.NewGuid().ToString("N") };
                        object choice = Activator.CreateInstance(type.GetNestedType("TemplateChoice", flags), flags, null,
                            new object[] { name, template }, null);
                        ComboBox picker = Require<ComboBox>(form, "operationalReportTemplates");
                        AntdUI.Panel pickerFrame = Require<AntdUI.Panel>(form, "operationalReportTemplatesFrame");
                        AntdUI.Button dropdown = Require<AntdUI.Button>(form, "operationalReportTemplatesFrameDropdown");
                        picker.Items.Add(choice);
                        object snapshot = type.GetField("currentTable", flags).GetValue(form);
                        picker.SelectedIndex = 1;
                        foreach (bool english in new[] { false, true, false })
                        {
                            form.ApplyPresentation(english);
                            foreach (Size size in new[] { new Size(760, 560), new Size(1024, 700), new Size(1366, 768) })
                            {
                                Prepare(form, size);
                                AntdUI.Panel context = Require<AntdUI.Panel>(form, "operationalReportTemplateContext");
                                TextBox details = Require<TextBox>(form, "operationalReportTemplateDetails");
                                FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "operationalReportTemplateActions");
                                DataGridView grid = Require<DataGridView>(form, "operationalReportGrid");
                                int lines = details.GetLineFromCharIndex(details.TextLength) + 1;
                                int firstY = details.GetPositionFromCharIndex(0).Y;
                                int nativeLineHeight = lines > 1 ? details.GetPositionFromCharIndex(details.GetFirstCharIndexFromLine(1)).Y - firstY : details.Font.Height;
                                int lastY = details.GetPositionFromCharIndex(Math.Max(0, details.TextLength - 1)).Y;
                                string expectedSource = OperationalReportCatalog.GetSources().Single(item => item.Key == template.SourceKey).Title;
                                if (english) expectedSource = UiLanguageCatalog.Translate(expectedSource);
                                if (!context.Visible || !details.ReadOnly || !details.Multiline || !details.WordWrap ||
                                    picker.DropDownStyle != ComboBoxStyle.DropDownList || picker.DrawMode != DrawMode.OwnerDrawFixed ||
                                    pickerFrame.Height < 44 || pickerFrame.BorderWidth != 1 || pickerFrame.Shadow != 0 ||
                                    !pickerFrame.ClientRectangle.Contains(picker.Bounds) || !pickerFrame.ClientRectangle.Contains(dropdown.Bounds) ||
                                    string.IsNullOrWhiteSpace(dropdown.IconSvg) || dropdown.AccessibleName != picker.AccessibleName ||
                                    !details.Text.Contains(name) || !details.Text.Contains(expectedSource) || template.Name != name ||
                                    details.ClientSize.Height < lastY + nativeLineHeight || !context.ClientRectangle.Contains(details.Bounds) ||
                                    context.Top < actions.Bottom || grid.Top < context.Bottom || grid.Height < 80 ||
                                    grid.Bottom > Require<Label>(form, "operationalReportStatus").Top ||
                                    // Native TextBox mirrors Left to the physical right edge when RTL is enabled.
                                    details.TextAlign != HorizontalAlignment.Left || details.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                    picker.AccessibleDescription != details.Text || details.AccessibleDescription != details.Text ||
                                    !ReferenceEquals(snapshot, type.GetField("currentTable", flags).GetValue(form)) ||
                                    actions.Controls.Cast<Control>().Any(control => !actions.ClientRectangle.Contains(control.Bounds)))
                                    throw new InvalidOperationException("Report template name or source is clipped, modified or causes a premature load: " + mode + ", " + size +
                                        "; English=" + english + "; NameLength=" + name.Length + "; Details=" + details.Bounds +
                                        "; LastLineBottom=" + (lastY + nativeLineHeight) + "; Context=" + context.Bounds +
                                        "; Grid=" + grid.Bounds + "; Status=" + Require<Label>(form, "operationalReportStatus").Bounds +
                                        "; TextAlign=" + details.TextAlign + "; SameSnapshot=" + ReferenceEquals(snapshot, type.GetField("currentTable", flags).GetValue(form)));
                            }
                        }
                        picker.SelectedIndex = 0;
                        if (Require<AntdUI.Panel>(form, "operationalReportTemplateContext").Visible ||
                            Require<TextBox>(form, "operationalReportTemplateDetails").Text.Length != 0 || picker.AccessibleDescription.Length != 0)
                            throw new InvalidOperationException("Report template details remain visible after clearing the selection.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

