                            SearchText = "باراسيتامول 500 mg", VisibleColumns = new List<string> { "الصنف", "الكمية" },
                            ColumnOrder = new List<string> { "الكمية", "الصنف" }, HasPrintSettings = true,
                            PrintOrientation = "Landscape", PrintDensity = "Compact", PrintCompanyName = true, PrintLogo = true
                        };
                        int index = OperationalReportCatalog.GetSources().ToList().FindIndex(item => item.Key == template.SourceKey);
                        type.GetMethod("ApplyTemplateFields", flags).Invoke(form, new object[] { template, index });
                        var source = Require<AntdUI.Select>(form, "operationalReportSource");
                        var print = (ReportPrintOptions)type.GetField("currentPrintOptions", flags).GetValue(form);
                        if (((OperationalReportSource)source.Items[source.SelectedIndex]).Key != template.SourceKey ||
                            Require<AntdUI.DatePicker>(form, "operationalReportFrom").Value != template.FromDate ||
                            Require<AntdUI.DatePicker>(form, "operationalReportTo").Value != template.ToDate ||
                            Require<TextBox>(form, "operationalReportSearch").Text != template.SearchText ||
                            !ReferenceEquals(snapshot, type.GetField("currentTable", flags).GetValue(form)) ||
                            (int)type.GetField("reportLoadGeneration", flags).GetValue(form) != generation ||
                            (bool)type.GetField("applyingPresentation", flags).GetValue(form) ||
                            print.Orientation != ReportPageOrientation.Landscape || print.Density != ReportDensity.Compact || !print.ShowLogo)
                            throw new InvalidOperationException("Template fields started an early report load or lost their date, search or print settings.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

