                                if (!output.Columns.Cast<DataColumn>().Select(column => column.ColumnName).SequenceEqual(new[] { "البيان", "مدين", "التاريخ", "الصنف" }) ||
                                    output.Columns.Contains("دائن") || output.Rows.Count != 2 || grid.AutoGenerateColumns)
                                    throw new InvalidOperationException("Operational report hidden columns/order changed during presentation: " + mode + "/" + english +
                                        "; columns=" + string.Join("|", output.Columns.Cast<DataColumn>().Select(column => column.ColumnName)) +
                                        "; rows=" + output.Rows.Count + "; auto=" + grid.AutoGenerateColumns);
                                foreach (DataColumn column in output.Columns)
                                {
                                    if (column.DataType != table.Columns[column.ColumnName].DataType ||
                                        column.Caption != (english ? UiLanguageCatalog.Translate(column.ColumnName) : column.ColumnName))
                                        throw new InvalidOperationException("Operational print captions or output column types are stale.");
                                    for (int row = 0; row < table.Rows.Count; row++)
                                        if (!Equals(output.Rows[row][column], table.Rows[row][column.ColumnName]))
                                            throw new InvalidOperationException("Operational projection changed a value/null or reordered rows.");
                                }
                                var previousCulture = System.Threading.Thread.CurrentThread.CurrentCulture;
                                try
                                {
                                    System.Threading.Thread.CurrentThread.CurrentCulture = System.Globalization.CultureInfo.GetCultureInfo("fr-FR");
                                    string csv = ReportCsvWriter.Serialize(output);
                                    if (!csv.StartsWith("\"البيان\",\"مدين\",\"التاريخ\",\"الصنف\"") || !csv.Contains("\"-12.50\"") || csv.Contains("'-12.50") ||
                                        !csv.Contains("\"'  =1+1\"") || !csv.Contains("\"2026-09-30 13:45:59\"") || !csv.Contains("نص، \"\"مقتبس\"\"\nمتعدد"))
                                        throw new InvalidOperationException("Operational CSV lost typed numeric/date values, quoting or formula protection.");
                                }
                                finally { System.Threading.Thread.CurrentThread.CurrentCulture = previousCulture; }
                            }
                            if (!ReferenceEquals(table, grid.DataSource) || !ReferenceEquals(table, type.GetField("currentTable", flags).GetValue(form)) ||
                                generation != (int)type.GetField("reportLoadGeneration", flags).GetValue(form) ||
                                !Convert.ToString(type.GetField("loadedReportPeriod", flags).GetValue(form)).Contains("2026/09/30") ||
                                table.Columns["الصنف"].Caption != "الصنف")
                                throw new InvalidOperationException("Operational output presentation changed the accepted result or triggered loading.");
                        }
                        grid.Columns["مدين"].DisplayIndex = 0;
                        string[] draggedOrder = grid.Columns.Cast<DataGridViewColumn>().Where(column => column.Visible)
                            .OrderBy(column => column.DisplayIndex).Select(column => column.Name).ToArray();
                        grid.Columns.Add(new DataGridViewTextBoxColumn { Name = "unboundAction", HeaderText = "إجراء" });
                        foreach (bool english in new[] { true, false })
                        {
                            form.ApplyPresentation(english);
                            using (var dragged = (DataTable)type.GetMethod("GetVisibleTable", flags).Invoke(form, null))
                                if (!dragged.Columns.Cast<DataColumn>().Select(column => column.ColumnName).SequenceEqual(draggedOrder))
                                    throw new InvalidOperationException("Operational projection reset the user's drag order or exported an unbound UI column.");
                        }
                        type.GetField("visibleColumns", flags).SetValue(form, new List<string> { "RemovedColumn" });
                        type.GetField("columnOrder", flags).SetValue(form, new List<string> { "مدين", "مدين", "RemovedColumn" });
                        type.GetMethod("ApplyColumnLayout", flags).Invoke(form, null);
                        if (grid.Columns.Cast<DataGridViewColumn>().Any(column => !column.Visible))
                            throw new InvalidOperationException("An old operational template hides all current columns.");
                        foreach (DataGridViewColumn column in grid.Columns) column.Visible = false;
                        using (var empty = (DataTable)type.GetMethod("GetVisibleTable", flags).Invoke(form, null))
                            if (empty.Columns.Count != 0 || empty.Rows.Count != 0)
                                throw new InvalidOperationException("Operational output exposes hidden columns in an empty projection.");
                        using (var next = new DataTable())
                        {
                            next.Columns.Add("صافي المبيعات", typeof(decimal)); next.Rows.Add(2.375m);
                            type.GetField("currentTable", flags).SetValue(form, next);
                            type.GetMethod("BindReportTable", flags).Invoke(form, new object[] { next });
                            foreach (bool english in new[] { true, false })
                            {
                                form.ApplyPresentation(english);
                                using (var changed = (DataTable)type.GetMethod("GetVisibleTable", flags).Invoke(form, null))
                                    if (changed.Columns.Count != 1 || !changed.Columns.Contains("صافي المبيعات") ||
                                        changed.Columns[0].Caption != (english ? "Net sales" : "صافي المبيعات") || (decimal)changed.Rows[0][0] != 2.375m)
                                        throw new InvalidOperationException("Operational result schema did not regenerate or leaked previous result columns.");
                            }
                        }
                        type.GetMethod("ClearLoadedReport", flags).Invoke(form, null);
                        if (grid.DataSource != null || type.GetField("currentTable", flags).GetValue(form) != null || grid.Columns.Contains("صافي المبيعات"))
                            throw new InvalidOperationException("Operational clear leaves the previous bound schema/data visible.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = previousMode;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        private static void VerifyOperationalReportPresentationState()
        {
            foreach (System.Text.RegularExpressions.Match column in System.Text.RegularExpressions.Regex.Matches(
                PharmacyManagement.Infrastructure.SqlServer.SqlOperationalReportQueries.Get(
                    PharmacyManagement.Application.OperationalReportKind.DailyPerformance), @"AS \[([^\]]+)\]",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase))
                if (UiLanguageCatalog.Translate(column.Groups[1].Value) == column.Groups[1].Value)
                    throw new InvalidOperationException("Daily report column lacks an English translation: " + column.Groups[1].Value);
            string originalMode = Properties.Setings.Default.ThemeMode;
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new OperationalReportBuilderForm(true))
                    {
                        Type type = typeof(OperationalReportBuilderForm);
                        type.GetMethod("ShowPreviewData", flags).Invoke(form, null);
                        DataTable snapshot = (DataTable)type.GetField("currentTable", flags).GetValue(form);
                        DataGridView grid = Require<DataGridView>(form, "operationalReportGrid");
                        Label status = Require<Label>(form, "operationalReportStatus");
                        type.GetMethod("ExportCsv", flags).Invoke(form, null);
                        foreach (bool english in new[] { true, false, true })
                        {
                            form.ApplyPresentation(english);
                            Prepare(form, new Size(760, 560));
                            string expected = english ? UiLanguageCatalog.Translate("معاينة فقط؛ لم يُنشأ ملف.") : "معاينة فقط؛ لم يُنشأ ملف.";
                            if (status.Text != expected || status.AccessibleName != expected ||
                                !ReferenceEquals(snapshot, type.GetField("currentTable", flags).GetValue(form)) ||
                                grid.Columns[0].HeaderText != (english ? "Medicine" : "الصنف") ||
                                Convert.ToString(snapshot.Rows[0][0]) != "باراسيتامول 500 mg")
                                throw new InvalidOperationException("Report language change lost the operation status or data snapshot.");
                        }
                        type.GetMethod("SetReportStatus", flags).Invoke(form, new object[] { "تعذر تحميل التقرير.", (bool?)false });
                        form.ApplyPresentation(false);
                        form.ApplyPresentation(true);
                        if (status.Text != UiLanguageCatalog.Translate("تعذر تحميل التقرير."))
                            throw new InvalidOperationException("Report failure status was not preserved and translated.");
                        if (status.ForeColor != UiTheme.Danger)
                            throw new InvalidOperationException("Report failure color was lost after changing presentation.");
                        snapshot.Columns.Add("صافي المبيعات", typeof(decimal));
                        snapshot.Columns.Add("الربح الإجمالي المسجل", typeof(decimal));
                        snapshot.Rows[0][3] = 1250.50m;
                        snapshot.Rows[0][4] = 250.50m;
                        type.GetMethod("BindReportTable", flags).Invoke(form, new object[] { snapshot });
                        type.GetField("loadedSourceKey", flags).SetValue(form, "DailyPerformance");
                        type.GetField("loadedFromDate", flags).SetValue(form, new DateTime(2026, 9, 1));
                        type.GetField("loadedToDate", flags).SetValue(form, new DateTime(2026, 9, 30));
                        type.GetField("loadedUsesDates", flags).SetValue(form, true);
                        type.GetField("showingResultStatus", flags).SetValue(form, true);
                        type.GetField("statusSuccess", flags).SetValue(form, (bool?)true);
                        foreach (bool english in new[] { false, true, false })
                        {
                            form.ApplyPresentation(english);
                            foreach (Size size in new[] { new Size(760, 560), new Size(1024, 700) })
                            {
                                Prepare(form, size);
                                int required = TextRenderer.MeasureText(status.Text, status.Font,
                                    new Size(Math.Max(1, status.ClientSize.Width - status.Padding.Horizontal), int.MaxValue),
                                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                                if (status.ClientSize.Height - status.Padding.Vertical < required || grid.Height < 80 ||
                                    grid.Columns["صافي المبيعات"].HeaderText != (english ? "Net sales" : "صافي المبيعات") ||
                                    grid.Columns["الربح الإجمالي المسجل"].HeaderText != (english ? "Recorded gross profit" : "الربح الإجمالي المسجل") ||
                                    status.AccessibleDescription != status.Text || !status.Text.Contains("1") ||
                                    !Convert.ToString(type.GetField("loadedReportPeriod", flags).GetValue(form)).Contains("2026/09/01") ||
                                    !ReferenceEquals(snapshot, type.GetField("currentTable", flags).GetValue(form)))
                                    throw new InvalidOperationException("Report result status or print metadata is clipped or stale after presentation changes.");
                            }
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        private static void VerifyOperationalReportBuilderLayout()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new OperationalReportBuilderForm(true))
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        foreach (Size size in new[] { new Size(760, 560), new Size(1024, 700), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            Panel header = Require<Panel>(form, "operationalReportHeader");
                            TableLayoutPanel filters = Require<TableLayoutPanel>(form, "operationalReportFilters");
                            FlowLayoutPanel templateActions = Require<FlowLayoutPanel>(form, "operationalReportTemplateActions");
                            FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "operationalReportActions");
                            DataGridView grid = Require<DataGridView>(form, "operationalReportGrid");
                            Label status = Require<Label>(form, "operationalReportStatus");
                            AntdUI.Button close = Require<AntdUI.Button>(form, "closeOperationalReport");
                            AntdUI.Button show = Require<AntdUI.Button>(form, "showOperationalReport");
                            AntdUI.Select selector = Require<AntdUI.Select>(form, "operationalReportSource");
                            ComboBox saved = Require<ComboBox>(form, "operationalReportTemplates");
                            AntdUI.Panel searchFrame = Require<AntdUI.Panel>(form, "operationalReportSearchFrame");
                            TextBox reportSearch = Require<TextBox>(form, "operationalReportSearch");
                            if (!ReferenceEquals(searchFrame.Tag, DesktopComponents.NativeTextFrameMarker) ||
                                searchFrame.Shadow != 0 || reportSearch.BorderStyle != BorderStyle.None ||
                                !searchFrame.ClientRectangle.Contains(reportSearch.Bounds) ||
                                Math.Abs(reportSearch.Top * 2 + reportSearch.Height - searchFrame.ClientSize.Height) > 2)
                                throw new InvalidOperationException("Operational report search must use the shared centered native text frame.");
                            if (header.Top != 0 || header.BackColor != UiTheme.Background ||
                                form.Controls["__UiStatusStrip"] != null || filters.HorizontalScroll.Visible ||
                                templateActions.HorizontalScroll.Visible || actions.HorizontalScroll.Visible ||
                                actions.Bottom != form.ClientSize.Height || grid.Bottom > status.Top ||
                                !actions.ClientRectangle.Contains(close.Bounds) || !actions.ClientRectangle.Contains(show.Bounds) ||
                                templateActions.Controls.Cast<Control>().Any(control => !templateActions.ClientRectangle.Contains(control.Bounds)) ||
                                actions.Controls.Cast<Control>().Any(control => !actions.ClientRectangle.Contains(control.Bounds)) ||
                                selector.Items.Count < 7 || saved.Items.Count != 1 || searchFrame.BorderWidth != 1 ||
                                !grid.ReadOnly || grid.AllowUserToDeleteRows || close.DefaultBorderColor != UiTheme.Primary ||
                                show.DefaultBorderColor != UiTheme.Primary || grid.Rows.Count != 1)
                                throw new InvalidOperationException("Operational report builder layout is invalid at " + size + " in " + mode + ".");
                        }
                        if (!Require<AntdUI.Button>(form, "exportOperationalCsv").Enabled) throw new InvalidOperationException("Preview data did not enable the owned preview-only export action.");
                        Require<AntdUI.Button>(form, "exportOperationalCsv").PerformClick();
                        if (!Require<Label>(form, "operationalReportStatus").Text.Contains("معاينة"))
                            throw new InvalidOperationException("Report preview attempted file export.");
                        AntdUI.Select sourceSelector = Require<AntdUI.Select>(form, "operationalReportSource");
                        int purchaseLines = sourceSelector.Items.Cast<OperationalReportSource>().ToList().FindIndex(item => item.Key == "PurchaseLines");
                        if (purchaseLines < 0) throw new InvalidOperationException("Purchase-line report source is missing.");
                        sourceSelector.SelectedIndex = purchaseLines;
                        const string mixedSearch = "باراسيتامول 500 mg";
                        Require<TextBox>(form, "operationalReportSearch").Text = mixedSearch;
                        if (!Require<AntdUI.DatePicker>(form, "operationalReportFrom").Enabled ||
                            !Require<Label>(form, "operationalReportStatus").Text.Contains("معاينة"))
                            throw new InvalidOperationException("Changing report source did not preserve the preview boundary.");
                        form.ApplyPresentation(true);
                        Prepare(form, new Size(760, 560));
                        TextBox mixedEditor = Require<TextBox>(form, "operationalReportSearch");
                        if (mixedEditor.RightToLeft != RightToLeft.Yes || mixedEditor.TextAlign != HorizontalAlignment.Left ||
                            mixedEditor.Text != mixedSearch)
                            throw new InvalidOperationException("Arabic report search lost its natural content direction in English presentation.");
                        mixedEditor.Text = "Sales 2026";
                        if (mixedEditor.RightToLeft != RightToLeft.No || mixedEditor.Text != "Sales 2026")
                            throw new InvalidOperationException("Latin report search did not restore LTR without altering the value.");
                        mixedEditor.Text = mixedSearch;
                        DataGridView englishGrid = Require<DataGridView>(form, "operationalReportGrid");
                        Application.DoEvents();
                        if (englishGrid.RightToLeft != RightToLeft.No ||
                            englishGrid.GetColumnDisplayRectangle(0, true).Left >= englishGrid.GetColumnDisplayRectangle(1, true).Left)
                            throw new InvalidOperationException("English report grid must retain LTR after binding and place its first column on the left.");
                        englishGrid.Columns[2].DisplayIndex = 0;
                        UiTheme.ApplyDataGridQuality(englishGrid, "No matching results");
                        Application.DoEvents();
                        if (!englishGrid.AllowUserToOrderColumns || englishGrid.Columns[2].DisplayIndex != 0 ||
                            englishGrid.RightToLeft != RightToLeft.No)
                            throw new InvalidOperationException("Report styling must preserve the user's column order and reading direction.");
                        englishGrid.Columns[2].DisplayIndex = 2;
                        sourceSelector = Require<AntdUI.Select>(form, "operationalReportSource");
                        OperationalReportSource selectedEnglish = sourceSelector.SelectedIndex >= 0
                            ? sourceSelector.Items[sourceSelector.SelectedIndex] as OperationalReportSource : null;
                        if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                            form.Text != "Operational report builder" ||
                            Require<Label>(form, "operationalReportTitle").TextAlign != ContentAlignment.MiddleLeft ||
                            Require<FlowLayoutPanel>(form, "operationalReportTemplateActions").FlowDirection != FlowDirection.LeftToRight ||
                            Require<FlowLayoutPanel>(form, "operationalReportActions").FlowDirection != FlowDirection.LeftToRight ||
                            Convert.ToString(sourceSelector.Items[0]) != "Medicines and current stock" ||
                            selectedEnglish == null || selectedEnglish.Key != "PurchaseLines" ||
                            Require<TextBox>(form, "operationalReportSearch").Text != mixedSearch ||
                            Require<DataGridView>(form, "operationalReportGrid").Columns[0].HeaderText != "Medicine" ||
                            Require<AntdUI.Button>(form, "showOperationalReport").AccessibleName != "View report results" ||
                            form.Controls["__UiStatusStrip"] != null)
                            throw new InvalidOperationException("English report presentation did not translate or preserve the selected report state.");
                        if (!Require<AntdUI.Button>(form, "exportOperationalCsv").Enabled) throw new InvalidOperationException("Preview data did not enable the owned preview-only export action.");
                        Require<AntdUI.Button>(form, "exportOperationalCsv").PerformClick();
                        if (!Require<Label>(form, "operationalReportStatus").Text.StartsWith("Preview only", StringComparison.Ordinal))
                            throw new InvalidOperationException("English report preview status was not translated.");
                        form.ApplyPresentation(false);
                        Prepare(form, new Size(760, 560));
                        sourceSelector = Require<AntdUI.Select>(form, "operationalReportSource");
                        OperationalReportSource selectedArabic = sourceSelector.SelectedIndex >= 0
                            ? sourceSelector.Items[sourceSelector.SelectedIndex] as OperationalReportSource : null;
                        if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                            Require<FlowLayoutPanel>(form, "operationalReportActions").FlowDirection != FlowDirection.LeftToRight ||
                            selectedArabic == null || selectedArabic.Key != "PurchaseLines" ||
                            Require<TextBox>(form, "operationalReportSearch").Text != mixedSearch ||
                            Require<DataGridView>(form, "operationalReportGrid").Columns[0].HeaderText != "الصنف")
                            throw new InvalidOperationException("Arabic report presentation did not restore direction or selected report state.");
                        if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox)
                            throw new InvalidOperationException("Operational report builder must keep standard resize, maximize, and minimize chrome.");
                        DataGridView arabicGrid = Require<DataGridView>(form, "operationalReportGrid");
                        Application.DoEvents();
                        if (arabicGrid.RightToLeft != RightToLeft.Yes ||
                            arabicGrid.GetColumnDisplayRectangle(0, true).Left <= arabicGrid.GetColumnDisplayRectangle(1, true).Left)
                            throw new InvalidOperationException("Arabic report grid must retain RTL after binding and place its first column on the right.");
                        UiTheme.Apply(form);
                        form.ApplyPresentation(false);
                        if (form.Controls["__UiStatusStrip"] != null ||
                            Require<Label>(form, "operationalReportStatus").Parent != form)
                            throw new InvalidOperationException("Report theme refresh restored a duplicate status strip.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }
