                            options.TaxNumber != "123456789" || options.ShowLogo ||
                            !options.ShowCompanyName || options.CompanyName != "صيدلية المهندس")
                            throw new InvalidOperationException("Report print options were not mapped from selected identity fields: " +
                                (options == null ? "none" : options.Orientation + "/" + options.Density + "/tax=" + options.ShowTaxNumber));
                    }
                    foreach (bool english in new[] { false, true })
                    foreach (bool missing in new[] { false, true })
                    using (var form = new ReportPrintOptionsDialog(missing ? new PharmacyProfile() : profile, true))
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        form.ApplyPresentation(english);
                        foreach (Size size in new[] { new Size(580, 500), new Size(900, 650) })
                        {
                            Prepare(form, size);
                            TableLayoutPanel identity = Require<TableLayoutPanel>(form, "reportPrintIdentity");
                            int[] widths = identity.GetColumnWidths();
                            foreach (Control child in identity.Controls)
                            {
                                TableLayoutPanelCellPosition cell = identity.GetCellPosition(child);
                                int cellLeft = identity.Padding.Left + (cell.Column == 0 ? 0 : widths[0]);
                                if (child.Left < cellLeft || child.Right > cellLeft + widths[cell.Column] ||
                                    child.Height < 40 || child.AccessibleName != child.Text)
                                    throw new InvalidOperationException("Report identity choice exceeds its cell or loses its full accessible name: " + child.Name);
                                CheckBox choice = child as CheckBox;
                                if (choice != null)
                                {
                                    bool selected = choice.Checked;
                                    if (choice.AccessibilityObject.Role != AccessibleRole.CheckButton)
                                        throw new InvalidOperationException("Report choice must expose checkbox accessibility: " + child.Name);
                                    choice.AccessibilityObject.DoDefaultAction();
                                    if (choice.Checked == selected)
                                        throw new InvalidOperationException("Report choice cannot toggle through accessibility: " + child.Name);
                                    choice.AccessibilityObject.DoDefaultAction();
                                    if (choice.Checked != selected)
                                        throw new InvalidOperationException("Report choice did not restore selection: " + child.Name);
                                }
                                else if (!(child is Label) || !((Label)child).AutoEllipsis)
                                    throw new InvalidOperationException("Unavailable report data needs a contained caption: " + child.Name);
                            }
                        }
                        if (missing && Require<TableLayoutPanel>(form, "reportPrintIdentity").Controls.OfType<CheckBox>().Any())
                            throw new InvalidOperationException("Missing company data must not offer selectable identity fields.");
                    }
                    using (var form = new ReportPrintOptionsDialog(profile, true, new ReportPrintOptions
                    {
                        Orientation = ReportPageOrientation.Portrait, Density = ReportDensity.Compact,
                        ShowCompanyName = false, ShowTaxNumber = true
                    }))
                    {
                        if (Require<AntdUI.Select>(form, "reportPrintOrientation").SelectedIndex != 1 ||
                            Require<AntdUI.Select>(form, "reportPrintDensity").SelectedIndex != 1 ||
                            Require<CheckBox>(form, "reportPrintCompanyName").Checked ||
                            !Require<CheckBox>(form, "reportPrintTaxNumber").Checked)
                            throw new InvalidOperationException("Saved report print choices were not restored.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }
