                            AntdUI.Panel body = Require<AntdUI.Panel>(form, "reportColumnsBody");
                            FlowLayoutPanel movePanel = Require<FlowLayoutPanel>(form, "reportColumnMoveActions");
                            FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "reportColumnActions");
                            if (list.Items.Count != 4 || list.CheckedItems.Count != 3 ||
