                                movePanel.BackColor != UiTheme.Surface || footer.BackColor != UiTheme.Background ||
                                footer.Bottom != form.ClientSize.Height || body.Bottom > footer.Top || footer.HorizontalScroll.Visible ||
                                !footer.ClientRectangle.Contains(Require<AntdUI.Button>(form, "applyReportColumns").Bounds) ||
                                !footer.ClientRectangle.Contains(Require<AntdUI.Button>(form, "cancelReportColumns").Bounds) ||
                                Require<AntdUI.Button>(form, "moveReportColumnUp").Height < 44)
                                throw new InvalidOperationException("Report column dialog is clipped at " + size + " in " + mode +
                                    ". items=" + list.Items.Count + ", checked=" + list.CheckedItems.Count +
                                    ", footer=" + footer.Bounds + ", bodyClient=" + body.ClientRectangle +
                                    ", scroll=" + footer.HorizontalScroll.Visible +
                                    ", apply=" + Require<AntdUI.Button>(form, "applyReportColumns").Bounds +
                                    ", cancel=" + Require<AntdUI.Button>(form, "cancelReportColumns").Bounds +
                                    ", moveHeight=" + Require<AntdUI.Button>(form, "moveReportColumnUp").Height + ".");
                        }
                        form.ApplyPresentation(true);
                        Prepare(form, new Size(450, 410));
                        if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                            form.Text != "Customize report columns" ||
                            Require<FlowLayoutPanel>(form, "reportColumnActions").FlowDirection != FlowDirection.LeftToRight ||
                            Require<AntdUI.Button>(form, "moveReportColumnUp").AccessibleName != "Move the selected column up" ||
                            Require<AntdUI.Button>(form, "applyReportColumns").AccessibleName != "Apply report column customization" ||
                            !Require<StatusStrip>(form, "__UiStatusStrip").Items[0].Text.Contains("Customize report columns"))
                            throw new InvalidOperationException("Report column dialog English direction or accessibility is inconsistent.");
                        form.ApplyPresentation(false);
                        if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                            Require<FlowLayoutPanel>(form, "reportColumnActions").FlowDirection != FlowDirection.RightToLeft ||
                            Require<AntdUI.Button>(form, "cancelReportColumns").AccessibleName != "إلغاء تخصيص أعمدة التقرير" ||
                            !Require<StatusStrip>(form, "__UiStatusStrip").Items[0].Text.Contains("تخصيص أعمدة التقرير"))
                            throw new InvalidOperationException("Report column dialog did not restore Arabic direction.");
                    }
                    using (var form = new ReportTemplateNameDialog("المبيعات اليومية"))
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        Size minimumClient = new Size(form.MinimumSize.Width - (form.Width - form.ClientSize.Width),
                            form.MinimumSize.Height - (form.Height - form.ClientSize.Height));
                        foreach (Size size in new[] { minimumClient, new Size(460, minimumClient.Height), new Size(620, 320) })
                        {
                            Prepare(form, size);
                            FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "reportTemplateActions");
                            AntdUI.Button saveAction = Find<AntdUI.Button>(form, "saveReportTemplate");
                            AntdUI.Button cancelAction = Find<AntdUI.Button>(form, "cancelReportTemplate");
                            if (saveAction == null || cancelAction == null)
                                throw new InvalidOperationException("Report template actions are missing after resize. Footer controls=" +
                                    string.Join(",", footer.Controls.Cast<Control>().Select(control =>
                                        control.Name + ":" + control.GetType().FullName)));
                            if (footer.BackColor != UiTheme.Surface || footer.HorizontalScroll.Visible ||
                                !footer.ClientRectangle.Contains(saveAction.Bounds) ||
                                !footer.ClientRectangle.Contains(cancelAction.Bounds) ||
                                Require<TextBox>(form, "reportTemplateName").Width < 240)
                                throw new InvalidOperationException("Report template dialog is clipped at " + size + " in " + mode + ".");
                        }
                        const string mixedName = "قالب Daily 500";
                        Require<TextBox>(form, "reportTemplateName").Text = mixedName;
                        form.ApplyPresentation(true);
                        Prepare(form, minimumClient);
                        if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                            form.Text != "Save report template" ||
                            Require<TextBox>(form, "reportTemplateName").Text != mixedName ||
                            Require<TextBox>(form, "reportTemplateName").TextAlign != HorizontalAlignment.Left ||
                            Require<FlowLayoutPanel>(form, "reportTemplateActions").FlowDirection != FlowDirection.LeftToRight ||
                            Require<AntdUI.Button>(form, "saveReportTemplate").AccessibleName != "Save report template" ||
                            !Require<StatusStrip>(form, "__UiStatusStrip").Items[0].Text.Contains("Save report template"))
                            throw new InvalidOperationException("Report template English presentation changed the entered name or direction.");
                        form.ApplyPresentation(false);
                        if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                            Require<TextBox>(form, "reportTemplateName").Text != mixedName ||
                            Require<TextBox>(form, "reportTemplateName").RightToLeft != RightToLeft.Yes ||
                            Require<TextBox>(form, "reportTemplateName").TextAlign != HorizontalAlignment.Left ||
                            Require<FlowLayoutPanel>(form, "reportTemplateActions").FlowDirection != FlowDirection.RightToLeft ||
                            !Require<StatusStrip>(form, "__UiStatusStrip").Items[0].Text.Contains("حفظ قالب التقرير"))
                            throw new InvalidOperationException("Report template dialog did not restore Arabic direction.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        private static void VerifySystemMonitorReloadPresentation()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { true, false })
                using (var form = new SystemMonitorForm(true))
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    UiTheme.Apply(form);
                    form.ApplyPresentation(english);
                    form.ShowInTaskbar = false;
                    form.StartPosition = FormStartPosition.Manual;
                    form.Location = new Point(8, 8);
                    form.Opacity = 0;
                    form.WindowState = FormWindowState.Minimized;
                    form.Show();
                    Prepare(form, new Size(760, 540));
                    var tabs = Require<TabControl>(form, "tabs");
                    var navigation = Require<FlowLayoutPanel>(form, "monitorNavigation");
                    for (int target = 0; target < 3; target++)
                    {
                        var button = Require<AntdUI.Button>(form, "monitorPageTab" + target);
                        if (button.AccessibilityObject.Role != AccessibleRole.PageTab || !button.TabStop)
                            throw new InvalidOperationException("Monitor navigation must expose focusable page actions.");
                        button.AccessibilityObject.DoDefaultAction();
                        if (tabs.SelectedIndex != target || button.AccessibleName != tabs.TabPages[target].Text ||
                            !button.AccessibleDescription.Contains(english ? "Current tab" : "التبويب الحالي"))
                            throw new InvalidOperationException("Monitor accessible navigation selected the wrong page.");
                    }
                    object[] command = { Message.Create(form.Handle, 0, IntPtr.Zero, IntPtr.Zero), Keys.Control | Keys.Tab };
                    var processKey = typeof(SystemMonitorForm).GetMethod("ProcessCmdKey", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                    if (!(bool)processKey.Invoke(form, command) || tabs.SelectedIndex != 0)
                        throw new InvalidOperationException("Monitor Ctrl+Tab must wrap to the first page.");
                    command[1] = Keys.Control | Keys.Shift | Keys.Tab;
                    if (!(bool)processKey.Invoke(form, command) || tabs.SelectedIndex != 2)
                        throw new InvalidOperationException("Monitor Ctrl+Shift+Tab must wrap to the last page.");
                    string[] grids = { "alertsGrid", "auditGrid", "inventoryGrid" };
                    string[] localizers = { "LocalizeAlertsGrid", "LocalizeAuditGrid", "LocalizeInventoryGrid" };
                    for (int index = 0; index < grids.Length; index++)
                    {
                        tabs.SelectedIndex = index;
                        var grid = Require<DataGridView>(form, grids[index]);
                        // Reload happens after the language has already been selected.
                        var table = new DataTable();
                        table.Columns.Add(index == 0 ? "Type" : "Time", index == 0 ? typeof(string) : typeof(DateTime));
                        table.Columns.Add(index == 0 ? "Medicine" : index == 1 ? "Action" : "Direction", typeof(string));
                        table.Rows.Add(index == 0 ? (object)"Critical" : DateTime.Today, "باراسيتامول 500 mg");
                        grid.DataSource = table;
                        typeof(SystemMonitorForm).GetMethod(localizers[index], System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).Invoke(form, null);
                        grid.Columns[0].DisplayIndex = 1;
                        UiTheme.ApplyDataGridQuality(grid);
                        Application.DoEvents();
                        if (grid.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                            grid.Columns[0].HeaderText != (index == 0 ? (english ? "Type" : "النوع") : (english ? "Time" : "الوقت")) ||
                            grid.Columns[0].DisplayIndex != 1 || (string)grid.Rows[0].Cells[1].Value != "باراسيتامول 500 mg")
                            throw new InvalidOperationException("Monitor reload lost language, column order, or exact mixed text: " + grids[index]);
                        var card = grid.Parent as AntdUI.Panel;
                        if (card == null || card.Radius != 12 || card.Shadow != 0)
                            throw new InvalidOperationException("Monitor data must use the shared AntdUI card.");
                        foreach (Size size in new[] { new Size(744, 501), new Size(960, 640), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            Application.DoEvents();
                            foreach (AntdUI.Button button in navigation.Controls)
                                if (!navigation.ClientRectangle.Contains(button.Bounds) || button.Height < 44 ||
                                    button.Width < TextRenderer.MeasureText(button.Text, button.Font).Width + 24)
                                    throw new InvalidOperationException("Monitor navigation text or hit area is clipped.");
                            var firstTab = Require<AntdUI.Button>(form, "monitorPageTab0");
                            var secondTab = Require<AntdUI.Button>(form, "monitorPageTab1");
                            if (english ? firstTab.Left >= secondTab.Left : firstTab.Left <= secondTab.Left)
                                throw new InvalidOperationException("Monitor navigation starts on the wrong language edge.");
                            if (grid.Height < 120 || !card.ClientRectangle.Contains(grid.Bounds))
                                throw new InvalidOperationException("Monitor data viewport is clipped: " + grids[index] + " at " + size + "; grid=" + grid.Bounds + "; card=" + card.ClientRectangle);
                        }
                    }
                    Require<AntdUI.Button>(form, "refreshButton").PerformClick();
                    if (!Require<Label>(form, "summaryLabel").Text.Contains(english ? "Preview only" : "المعاينة"))
                        throw new InvalidOperationException("Monitor reload preview must remain isolated.");
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        private static void VerifySystemMonitorLayoutAndTheme()
        {
            VerifySystemMonitorReloadPresentation();
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new SystemMonitorForm(true))
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        foreach (Size size in new[] { new Size(760, 540), new Size(980, 620), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            Panel header = Require<Panel>(form, "header");
                            Panel footer = Require<Panel>(form, "systemMonitorFooter");
                            TabControl tabs = Require<TabControl>(form, "tabs");
                            AntdUI.Button refresh = Require<AntdUI.Button>(form, "refreshButton");
                            AntdUI.Button close = Require<AntdUI.Button>(form, "closeButton");
                            Label title = Require<Label>(header, "titleLabel");
                            Label subtitle = Require<Label>(header, "subtitleLabel");
                            if (form.Controls.Find("__UiStatusStrip", true).Length != 0)
                                throw new InvalidOperationException("System monitor preview shows runtime database readiness.");
                            int workspaceBottom = form.ClientSize.Height;
                            if (tabs.DrawMode != TabDrawMode.OwnerDrawFixed || tabs.TabPages.Cast<TabPage>().Any(page => page.BackColor != UiTheme.Surface) ||
                                header.BackColor != UiTheme.Background || header.Height > 110 || subtitle.Bottom > header.ClientSize.Height ||
                                title.ForeColor != UiTheme.Text || subtitle.ForeColor != UiTheme.MutedText ||
                                footer.Bottom != workspaceBottom || footer.BackColor != UiTheme.Background || tabs.Bottom > footer.Top ||
                                refresh.Parent != footer || close.Parent != footer || refresh.Bounds.IntersectsWith(close.Bounds) ||
                                !footer.ClientRectangle.Contains(refresh.Bounds) || !footer.ClientRectangle.Contains(close.Bounds) ||
                                refresh.Height < 44 || close.Height < 44 || refresh.DefaultBorderColor != UiTheme.Primary ||
                                close.DefaultBorderColor != UiTheme.Primary || refresh.BorderWidth != 1 || close.BorderWidth != 1 ||
                                refresh.Type != AntdUI.TTypeMini.Default || close.Type != AntdUI.TTypeMini.Default ||
                                refresh.DefaultBack != UiTheme.Surface || close.DefaultBack != UiTheme.Surface)
                                throw new InvalidOperationException("System monitor theme or footer actions are invalid at " + size + " in " + mode + ".");
                            if (UiDirection.IsLeftToRight ? refresh.Left >= close.Left : refresh.Left <= close.Left)
                                throw new InvalidOperationException("System monitor actions are on the wrong reading edge at " + size + ".");
                        }
                        Require<AntdUI.Button>(form, "refreshButton").PerformClick();
                        if (!Require<Label>(form, "summaryLabel").Text.Contains("المعاينة"))
                            throw new InvalidOperationException("System monitor preview attempted a database read.");
                        var auditFixture = new DataTable();
                        auditFixture.Columns.Add("Time", typeof(DateTime));
                        auditFixture.Columns.Add("Action", typeof(string));
                        Require<DataGridView>(form, "auditGrid").DataSource = auditFixture;
                        form.ApplyPresentation(true);
                        Prepare(form, new Size(760, 540));
                        TabControl englishTabs = Require<TabControl>(form, "tabs");
                        if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                            englishTabs.RightToLeft != RightToLeft.No || englishTabs.RightToLeftLayout ||
                            form.Controls.Find("__UiStatusStrip", true).Length != 0 ||
                            form.Text != "System monitoring" || englishTabs.TabPages[1].Text != "Audit log" ||
                            !Require<Label>(form, "summaryLabel").Text.Contains("Preview only") ||
                            Require<DataGridView>(form, "auditGrid").Columns["Action"].HeaderText != "Action" ||
                            Require<AntdUI.Button>(form, "refreshButton").Left >=
                                Require<AntdUI.Button>(form, "closeButton").Left)
                            throw new InvalidOperationException("System monitor English direction or data headers failed at 760x540.");
                        var markRefreshFailed = typeof(SystemMonitorForm).GetMethod("MarkRefreshFailed",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                        if (markRefreshFailed == null) throw new InvalidOperationException("Monitor refresh failure state is missing.");
                        markRefreshFailed.Invoke(form, null);
                        if (!Require<Label>(form, "summaryLabel").Text.Contains("outdated") ||
                            !Require<Label>(form, "auditLabel").Text.Contains("outdated") ||
                            !Require<Label>(form, "inventoryLabel").Text.Contains("outdated"))
                            throw new InvalidOperationException("Monitor refresh failure is not visible in every English page.");
                        form.ApplyPresentation(false);
                        Prepare(form, new Size(760, 540));
                        if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                            englishTabs.RightToLeft != RightToLeft.Yes || !englishTabs.RightToLeftLayout ||
                            form.Controls.Find("__UiStatusStrip", true).Length != 0 ||
                            englishTabs.TabPages[1].Text != "سجل التدقيق" ||
                            Require<DataGridView>(form, "auditGrid").Columns["Action"].HeaderText != "الإجراء" ||
                            Require<AntdUI.Button>(form, "refreshButton").Left <=
                                Require<AntdUI.Button>(form, "closeButton").Left)
                            throw new InvalidOperationException("System monitor did not restore Arabic direction and headings.");
                        if (!Require<Label>(form, "summaryLabel").Text.Contains("قديمة") ||
                            !Require<Label>(form, "auditLabel").Text.Contains("قديمة") ||
                            !Require<Label>(form, "inventoryLabel").Text.Contains("قديمة"))
                            throw new InvalidOperationException("Monitor refresh failure was lost when restoring Arabic.");
                        if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox ||
                            string.IsNullOrWhiteSpace(Require<TabControl>(form, "tabs").AccessibleName))
                            throw new InvalidOperationException("System monitor window chrome or accessibility metadata is incomplete.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }
        internal static void VerifyAccountingPeriodsLayout()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new AccountingPeriodManagementForm(true))
                    {
                        // Geometry checks use a normal owned frame; opening preference has its own verifier.
                        form.MaximizeBox = false;
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        foreach (bool leftToRight in new[] { false, true })
                        {
                        form.ApplyPresentation(leftToRight);
                        if (Require<DataGridView>(form, "accountingPeriodsGrid").RightToLeft !=
                            (leftToRight ? RightToLeft.No : RightToLeft.Yes))
                            throw new InvalidOperationException("Accounting period grid direction is wrong immediately after presentation: " + leftToRight);
                        OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
                        Size minimumClient = form.ClientSize;
                        foreach (Size size in new[] { minimumClient, new Size(760, minimumClient.Height), new Size(1024, 650), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            Panel header = Require<Panel>(form, "accountingPeriodsHeader");
                            AntdUI.Panel editor = Require<AntdUI.Panel>(form, "accountingPeriodsEditor");
                            AntdUI.Panel gridCard = Require<AntdUI.Panel>(form, "accountingPeriodsGridCard");
                            Panel footer = Require<Panel>(form, "accountingPeriodsFooter");
                            Label status = Require<Label>(form, "accountingPeriodsStatus");
                            TableLayoutPanel fields = Require<TableLayoutPanel>(form, "accountingPeriodsFields");
                            AntdUI.DatePicker from = Require<AntdUI.DatePicker>(fields, "periodFromDate");
                            AntdUI.DatePicker to = Require<AntdUI.DatePicker>(fields, "periodToDate");
                             TextBox notes = Require<TextBox>(fields, "periodNotes");
                            AntdUI.Panel notesFrame = Require<AntdUI.Panel>(fields, "periodNotesFrame");
                            FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "accountingPeriodsActions");
                            Control strip = form.Controls["__UiStatusStrip"];
                            if (strip != null)
                                throw new InvalidOperationException("Accounting period preview exposed the runtime connection status.");
                            int workspaceBottom = form.ClientSize.Height - (strip == null ? 0 : strip.Height);
                            if (header.Top != 0 || header.BackColor != UiTheme.Background ||
                                footer.Bottom != workspaceBottom || footer.BackColor != UiTheme.Background ||
                                actions.BackColor != UiTheme.Background || fields.BackColor != UiTheme.Surface ||
                                status.Bottom != footer.Top || editor.Bottom != status.Top ||
                                gridCard.Height < 80 || editor.Height < 90 || fields.HorizontalScroll.Visible ||
                                 fields.RightToLeft != RightToLeft.No ||
                                 from.Height < 44 || to.Height < 44 || notesFrame.Height < 44 || !from.Value.HasValue || !to.Value.HasValue ||
                                from.Format != "yyyy/MM/dd" || to.Format != "yyyy/MM/dd" ||
                                actions.HorizontalScroll.Visible)
                                throw new InvalidOperationException("Accounting period layout lost a usable area at " + size + " in " + mode +
                                    ": header=" + header.Bounds + ", editor=" + editor.Bounds + ", grid=" + gridCard.Bounds +
                                    ", status=" + status.Bounds + ", footer=" + footer.Bounds + ", bottom=" + workspaceBottom + ".");
                             RequireInside(fields, from, "accounting period from date " + size);
                             RequireInside(fields, to, "accounting period to date " + size);
                             RequireInside(fields, notesFrame, "accounting period notes frame " + size);
                             RequireInside(notesFrame, notes, "accounting period notes editor " + size);
                             if (notes.MaxLength != 500 || notesFrame.Shadow != 0 || editor.Radius != 12 || gridCard.Radius != 12 ||
                                 editor.Shadow != 0 || gridCard.Shadow != 0 ||
                                 Math.Abs(notes.Top + notes.Height / 2 - notesFrame.ClientSize.Height / 2) > 2)
                                 throw new InvalidOperationException("Accounting period shared field or card geometry failed.");
                             if (size.Width < 900)
                             {
                                 int expectedCompactWidth = fields.ClientSize.Width - 88 - 16;
                                 if (from.Width < expectedCompactWidth || to.Width < expectedCompactWidth || notesFrame.Width < expectedCompactWidth)
                                     throw new InvalidOperationException("Accounting period compact fields did not share the available width at " + size +
                                         ": fields=" + fields.ClientSize + ", from=" + from.Bounds + ", to=" + to.Bounds + ", notes=" + notes.Bounds + ".");
                             }
                             if (notes.RightToLeft != (leftToRight ? RightToLeft.No : RightToLeft.Yes) ||
                                 notes.TextAlign != HorizontalAlignment.Left)
                                 throw new InvalidOperationException("Accounting period notes direction does not follow the display language at " + size + ".");
                             const string mixedPeriodNotes = "September close — إقفال 2026";
                             notes.Text = mixedPeriodNotes;
                             form.PerformLayout();
                             if (!string.Equals(notes.Text, mixedPeriodNotes, StringComparison.Ordinal))
                                 throw new InvalidOperationException("Accounting period AntdUI notes changed mixed Arabic and English text.");
                            if (fields.Controls.OfType<Label>().Count() != 3 ||
                                fields.Controls.OfType<Label>().Any(label => label.ForeColor != UiTheme.Text || label.BackColor != UiTheme.Surface))
                                throw new InvalidOperationException("Accounting period field labels lost contrast at " + size + " in " + mode + ".");
                            foreach (string actionName in new[] { "createAccountingPeriod", "closeAccountingPeriod", "checkPeriodReadiness", "refreshAccountingPeriods", "closeAccountingPeriodWindow" })
                            {
                                AntdUI.Button action = Require<AntdUI.Button>(form, actionName);
                                if (action.Parent != actions || action.Width < 80 || action.Height < 44 ||
                                    action.DefaultBorderColor != UiTheme.Primary || action.DefaultBack != UiTheme.Surface ||
                                    action.BorderWidth != 1 || action.Type != AntdUI.TTypeMini.Default ||
                                    !actions.ClientRectangle.Contains(action.Bounds) || string.IsNullOrWhiteSpace(action.AccessibleName))
                                    throw new InvalidOperationException("Accounting period action lost its outlined accessible layout: " + actionName + " at " + size + ".");
                            }
                            AntdUI.Button create = Require<AntdUI.Button>(form, "createAccountingPeriod");
                            AntdUI.Button exit = Require<AntdUI.Button>(form, "closeAccountingPeriodWindow");
                            if (create.Top > exit.Top || create.Top == exit.Top && (leftToRight ? create.Left >= exit.Left : create.Left <= exit.Left))
                                throw new InvalidOperationException("Accounting period actions are on the wrong reading edge at " + size + ".");
                            Label title = Require<Label>(form, "accountingPeriodsTitle");
                            Label help = Require<Label>(form, "accountingPeriodsHelp");
                            foreach (Label heading in new[] { title, help })
                                if (heading.Height < TextRenderer.MeasureText(heading.Text, heading.Font,
                                    new Size(heading.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height ||
                                    heading.AccessibleName != heading.Text)
                                    throw new InvalidOperationException("Accounting period heading is clipped or inaccessible.");
                            if (title.Text != (leftToRight ? "Accounting periods" : "إدارة الفترات المحاسبية") ||
                                title.TextAlign != (leftToRight ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                                create.Text != (leftToRight ? "Create open period" : "إنشاء فترة مفتوحة") ||
                                !help.Text.Contains(leftToRight ? "Closing blocks" : "الإقفال يمنع"))
                                throw new InvalidOperationException("Accounting period heading or actions did not follow the display language.");
                            DataGridView periodGrid = Require<DataGridView>(form, "accountingPeriodsGrid");
                            if (!UiTheme.OwnsCustomGridColumns(periodGrid) || periodGrid.ColumnHeadersHeight < 60 ||
                                periodGrid.Columns["معرف الفترة"].Visible || !periodGrid.ReadOnly ||
                                periodGrid.Height < periodGrid.ColumnHeadersHeight + periodGrid.RowTemplate.Height + SystemInformation.HorizontalScrollBarHeight)
                                throw new InvalidOperationException("Accounting period source grid lost identity protection or its first row: " +
                                    "client=" + form.ClientSize + ", gridHeight=" + periodGrid.Height +
                                    ", header=" + periodGrid.ColumnHeadersHeight + ", row=" + periodGrid.RowTemplate.Height +
                                    ", hiddenId=" + !periodGrid.Columns["معرف الفترة"].Visible +
                                    ", ownsColumns=" + UiTheme.OwnsCustomGridColumns(periodGrid));
                            if (periodGrid.RightToLeft != (leftToRight ? RightToLeft.No : RightToLeft.Yes) ||
                                periodGrid.Rows.Count != 2 ||
                                Convert.ToString(periodGrid.Rows[0].Cells["الحالة"].Value) != "مفتوحة" ||
                                Convert.ToString(periodGrid.Rows[0].Cells["الحالة"].FormattedValue) != (leftToRight ? "Open" : "مفتوحة") ||
                                periodGrid.Columns["الحالة"].HeaderText != (leftToRight ? "Status" : "الحالة"))
                                throw new InvalidOperationException("Accounting period display translation changed saved status values: " +
                                    "ltr=" + leftToRight + ", rtl=" + periodGrid.RightToLeft +
                                    ", rows=" + periodGrid.Rows.Count +
                                    ", source=" + periodGrid.Rows[0].Cells["الحالة"].Value +
                                    ", display=" + periodGrid.Rows[0].Cells["الحالة"].FormattedValue +
                                    ", header=" + periodGrid.Columns["الحالة"].HeaderText + ".");
                        }
                        AntdUI.DatePicker typedFrom = Require<AntdUI.DatePicker>(form, "periodFromDate");
                        DateTime? originalFrom = typedFrom.Value;
                        typedFrom.Focus();
                        typedFrom.Text = "2026/09/23";
                        DateTime displayedDate;
                        if (!AntdDateInput.TryRead(typedFrom, out displayedDate) || displayedDate != new DateTime(2026, 9, 23))
                            throw new InvalidOperationException("Accounting period must read the visible date even before the picker commits its Value.");
                        typedFrom.Text = "2026/02/30";
                        if (AntdDateInput.TryRead(typedFrom, out displayedDate))
                            throw new InvalidOperationException("Accounting period accepted an impossible date.");
                        typedFrom.Text = "2026/09/23";
                        Require<AntdUI.DatePicker>(form, "periodToDate").Focus();
                        Application.DoEvents();
                        if (typedFrom.Value != new DateTime(2026, 9, 23))
                            throw new InvalidOperationException("Accounting period DatePicker text did not update its actual date value: text=" +
                                typedFrom.Text + ", value=" + typedFrom.Value + ".");
                        typedFrom.Value = originalFrom;
                        Require<AntdUI.Button>(form, "createAccountingPeriod").PerformClick();
                        if (!Require<Label>(form, "accountingPeriodsStatus").Text.Contains(leftToRight ? "Preview" : "المعاينة"))
                            throw new InvalidOperationException("Accounting period preview attempted a write.");
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        internal static void VerifyCurrencySettingsLayout()
        {
            foreach (bool leftToRight in new[] { false, true })
            {
                using (var form = new CurrencySettingsForm(true, leftToRight))
                {
                    form.ShowInTaskbar = false; form.Opacity = 0; form.MaximizeBox = false;
                    form.StartPosition = FormStartPosition.Manual; form.Location = new Point(-20000, -20000);
                    form.Show(); Application.DoEvents();
                    OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
                    foreach (Size size in new[] { form.ClientSize, new Size(520, 680), new Size(760, 680), new Size(1024, 680) })
                    {
                        Prepare(form, size);
                        foreach (var item in new[] {
                            new[] { "panelHeader", "Currencies and countries", "العملات والدول" },
                            new[] { "panelBody", "Currency settings", "إعدادات العملات" },
                            new[] { "panelGrid", "Currency list", "قائمة العملات" },
                            new[] { "gridCurrencies", "Currency list", "قائمة العملات" },
                            new[] { "panelEditor", "Currency details", "بيانات العملة" },
                            new[] { "currencyFields", "Currency details", "بيانات العملة" },
                            new[] { "currencyFooter", "Currency actions", "إجراءات العملات" },
                            new[] { "currencyActions", "Currency actions", "إجراءات العملات" },
                            new[] { "txtCurrencySymbol", "Currency symbol", "اختصار أو علامة العملة" } })
                        {
                            var named = form.Controls.Find(item[0], true).Single();
                            if (named.AccessibleName != item[leftToRight ? 1 : 2])
                            {
                                Console.Error.WriteLine("FAIL currency accessible name: " + item[0]);
                                throw new InvalidOperationException("Currency accessible name is missing or not localized: " + item[0]);
                            }
                        }

                        Panel readActions = Require<Panel>(form, "currencyReadActions");
                        AntdUI.Button refresh = Require<AntdUI.Button>(form, "refreshCurrencies");
                        RequireInside(readActions, refresh, "currency refresh action " + size);
                        int textWidth = TextRenderer.MeasureText(refresh.Text, refresh.Font).Width;
                        if (refresh.Width < textWidth + 28 || refresh.Text != (leftToRight ? "Refresh" : "تحديث") ||
                            string.IsNullOrEmpty(refresh.AccessibleDescription))
                            throw new InvalidOperationException("Currency refresh action is clipped or inaccessible at " + size);

                        AntdUI.Panel editor = Require<AntdUI.Panel>(form, "panelEditor");
                        Panel header = Require<Panel>(form, "panelHeader");
                        Label title = Require<Label>(header, "lblTitle");
                        Label subtitle = Require<Label>(header, "lblSubtitle");
                        Panel gridPanel = Require<Panel>(form, "panelGrid");
                        Panel footer = Require<Panel>(form, "currencyFooter");
                        Panel body = Require<Panel>(form, "panelBody");
                        TableLayoutPanel fields = Require<TableLayoutPanel>(form, "currencyFields");
                        FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "currencyActions");
                        if (form.Text != (leftToRight ? "Currency settings" : "إعدادات العملات") ||
                            title.Text != (leftToRight ? "Currencies and countries" : "العملات والدول") ||
                            title.TextAlign != (leftToRight ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                            title.Bottom + 4 > subtitle.Top || subtitle.Height < 24 ||
                            subtitle.Bottom > header.ClientSize.Height - header.Padding.Bottom ||
                            editor.Radius != 12 || editor.Shadow != 0 || editor.Height < 220 || gridPanel.Height < 70 || fields.HorizontalScroll.Visible || actions.HorizontalScroll.Visible ||
                            footer.Bottom != form.ClientSize.Height || body.Bottom != footer.Top ||
                            actions.Parent != footer || footer.BackColor.ToArgb() != UiTheme.Background.ToArgb())
                            throw new InvalidOperationException("Currency settings bilingual layout is not usable at " + size +
                                ": form='" + form.Text + "', title='" + title.Text + "', titleBounds=" + title.Bounds +
                                ", subtitleBounds=" + subtitle.Bounds + ", header=" + header.ClientRectangle +
                                ", editor=" + editor.Bounds + ", grid=" + gridPanel.Bounds +
                                ", fieldsHScroll=" + fields.HorizontalScroll.Visible + ", actionsHScroll=" + actions.HorizontalScroll.Visible +
                                ", titleAlign=" + title.TextAlign + ", actionsParent=" + (actions.Parent == footer) +
                                ", footerColor=" + footer.BackColor + "/" + UiTheme.Background +
                                ", footer=" + footer.Bounds + ", body=" + body.Bounds + ", ltr=" + leftToRight + ".");
                        DataGridView visibleCurrencyRows = Require<DataGridView>(form, "gridCurrencies");
                        if (visibleCurrencyRows.ClientSize.Height < visibleCurrencyRows.ColumnHeadersHeight + visibleCurrencyRows.RowTemplate.Height + 8)
                            throw new InvalidOperationException("Currency list cannot show a full row at " + size);
                        foreach (string labelName in new[] { "currencyCountryLabel", "currencyNameLabel", "currencyCodeLabel", "currencySymbolLabel" })
                        {
                            Label label = Require<Label>(fields, labelName);
                            if (label.ForeColor.ToArgb() != UiTheme.Text.ToArgb() || label.BackColor.ToArgb() != UiTheme.Surface.ToArgb() ||
                                label.TextAlign != (leftToRight ? ContentAlignment.BottomLeft : ContentAlignment.BottomRight) ||
                                label.Width < 100 || label.Height < 20)
                                throw new InvalidOperationException("Currency field label is clipped or loses theme contrast: " + labelName + " at " + size + ".");
                        }
                        CheckBox systemChoice = Require<CheckBox>(fields, "chkSystemCurrency");
                        if (systemChoice.Bottom > fields.ClientSize.Height || systemChoice.Top < 0)
                            throw new InvalidOperationException("Currency system choice is clipped by the field grid at " + size + ".");
                        foreach (string inputName in new[] { "txtCountry", "txtCurrencyName", "txtCurrencyCode", "txtCurrencySymbol" })
                        {
                            AntdUI.Input input = Require<AntdUI.Input>(fields, inputName);
                            RequireInside(fields, input, "currency input " + inputName + " " + size);
                            if (input.Height != 44 || string.IsNullOrWhiteSpace(input.AccessibleName))
                                throw new InvalidOperationException("Currency AntdUI field is too small or unnamed: " + inputName + " at " + size + ".");
                        }
                        AntdUI.Input codeInput = Require<AntdUI.Input>(fields, "txtCurrencyCode");
                        AntdUI.Input countryInput = Require<AntdUI.Input>(fields, "txtCountry");
                        if (codeInput.RightToLeft != RightToLeft.No || codeInput.TextAlign != HorizontalAlignment.Left ||
                            countryInput.RightToLeft != RightToLeft.Yes || countryInput.TextAlign != HorizontalAlignment.Right)
                            throw new InvalidOperationException("Currency names and ISO codes lost their intended text directions at " + size + ".");
                        foreach (string actionName in new[] { "btnSave", "btnSetSystem", "btnDelete", "btnClear" })
                        {
                            AntdUI.Button action = Require<AntdUI.Button>(actions, actionName);
                            RequireInside(actions, action, "currency footer action " + actionName + " " + size);
                            if (action.Width < 100 || action.Height < 44 || action.BorderWidth != 1 ||
                                !action.DefaultBorderColor.HasValue || action.DefaultBorderColor.Value.ToArgb() != UiTheme.Primary.ToArgb() || string.IsNullOrWhiteSpace(action.IconSvg) ||
                                string.IsNullOrWhiteSpace(action.AccessibleName))
                                throw new InvalidOperationException("Currency action is missing its green AntdUI outline and accessible label: " + actionName);
                        }
                    }
                    AntdUI.Input country = Require<AntdUI.Input>(form, "txtCountry");
                    AntdUI.Input currencyName = Require<AntdUI.Input>(form, "txtCurrencyName");
                    AntdUI.Input currencyCode = Require<AntdUI.Input>(form, "txtCurrencyCode");
                    CheckBox systemCurrency = Require<CheckBox>(form, "chkSystemCurrency");
                    if (country.Text != "اليمن" || currencyName.Text != "الريال اليمني" || currencyCode.Text != "YER" ||
                        !systemCurrency.Checked || Require<AntdUI.Button>(form, "btnSave").Enabled ||
                        Require<AntdUI.Button>(form, "btnDelete").Enabled || Require<AntdUI.Button>(form, "btnSetSystem").Enabled)
                        throw new InvalidOperationException("Currency preview must populate sample data without enabling persistent actions.");
                    DataGridView currencyGrid = Require<DataGridView>(form, "gridCurrencies");
                    if (currencyGrid.Columns["الدولة"].HeaderText != (leftToRight ? "Country" : "الدولة") ||
                        currencyGrid.RightToLeft != (leftToRight ? RightToLeft.No : RightToLeft.Yes))
                        throw new InvalidOperationException("Currency grid headers or direction are not localized.");
                    currencyGrid.ClearSelection();
                    currencyGrid.Rows[1].Selected = true;
                    if (country.Text != "السعودية" || currencyCode.Text != "SAR" || systemCurrency.Checked ||
                        Require<AntdUI.Button>(form, "btnDelete").Enabled)
                        throw new InvalidOperationException("Currency preview selection must update the editor without enabling deletion.");
                    var click = typeof(Control).GetMethod("OnClick", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                    click.Invoke(Require<AntdUI.Button>(form, "btnClear"), new object[] { EventArgs.Empty });
                    if (country.Text.Length != 0 || currencyName.Text.Length != 0 || currencyCode.Text.Length != 0 || systemCurrency.Checked ||
                        Require<AntdUI.Button>(form, "btnDelete").Enabled || Require<AntdUI.Button>(form, "btnSetSystem").Enabled)
                        throw new InvalidOperationException("New currency action must clear the preview editor without enabling writes.");
                }
            }
        }

        private static void VerifyLanguageSettingsLayout()
        {
            using (var liveSettings = new LanguageSettingsForm())
            {
                if (!Require<AntdUI.Button>(liveSettings, "languageSaveButton").Enabled ||
                    Require<RadioButton>(liveSettings, "languageEnglishOption").Enabled ||
                    !Require<RadioButton>(liveSettings, "languageArabicOption").Checked)
                    throw new InvalidOperationException("Language settings must keep Arabic available without enabling incomplete English.");
            }
            string previousLanguage = Properties.Setings.Default.UiLanguage;
            try
            {
                Properties.Setings.Default.UiLanguage = UiLanguageSettings.English;
                using (var settingsWithOldPreference = new LanguageSettingsForm())
                {
                    if (!Require<RadioButton>(settingsWithOldPreference, "languageArabicOption").Checked ||
                        Require<RadioButton>(settingsWithOldPreference, "languageEnglishOption").Checked ||
                        Require<RadioButton>(settingsWithOldPreference, "languageEnglishOption").Enabled)
                        throw new InvalidOperationException("An unavailable saved language must display the active Arabic option.");
                }
            }
            finally { Properties.Setings.Default.UiLanguage = previousLanguage; }
            foreach (bool leftToRight in new[] { false, true })
            {
                using (var form = new LanguageSettingsForm(true, leftToRight))
                {
                    form.ShowInTaskbar = false;
                    form.StartPosition = FormStartPosition.Manual;
                    form.Location = new Point(-20000, -20000);
                    form.Show();
                    foreach (Size size in new[] { new Size(420, 310), new Size(620, 420), new Size(900, 650) })
                    {
                        Prepare(form, size);
                        Panel header = Require<Panel>(form, "languageHeader");
                        Label title = Require<Label>(form, "languageTitle");
                        Label subtitle = Require<Label>(form, "languageSubtitle");
                        AntdUI.Panel body = Require<AntdUI.Panel>(form, "languageBody");
                        AntdUI.Panel arabicRow = Require<AntdUI.Panel>(form, "languageArabicRow");
                        Label arabicCaption = Require<Label>(arabicRow, "languageArabicCaption");
                        AntdUI.Panel englishRow = Require<AntdUI.Panel>(form, "languageEnglishRow");
                        Label englishCaption = Require<Label>(englishRow, "languageEnglishCaption");
                        RadioButton englishChoice = Require<RadioButton>(englishRow, "languageEnglishOption");
                        RadioButton arabicChoice = Require<RadioButton>(body, "languageArabicOption");
                        Label languageStatus = Require<Label>(form, "languageStatus");
                        Panel footer = Require<Panel>(form, "languageActions");
                        AntdUI.Button save = Require<AntdUI.Button>(footer, "languageSaveButton");
                        AntdUI.Button close = Require<AntdUI.Button>(footer, "languageCloseButton");
                        if (header.Top != 0 || header.BackColor != UiTheme.Background ||
                            title.ForeColor != UiTheme.Text ||
                            !body.Back.HasValue || body.Back.Value.ToArgb() != UiTheme.Surface.ToArgb() ||
                            body.BackColor.ToArgb() != UiTheme.Background.ToArgb() ||
                            body.Top != header.Bottom || body.Bottom != footer.Top ||
                            footer.Bottom != form.ClientSize.Height || !body.AutoScroll)
                            throw new InvalidOperationException("Language settings header, scrollable body, and fixed footer overlap at " + size + ".");
                        if (form.Text != (leftToRight ? "Language center" : "مركز اللغة") ||
                            title.Text != (leftToRight ? "Interface language" : "لغة الواجهة") ||
                            title.TextAlign != (leftToRight ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                            subtitle.TextAlign != title.TextAlign ||
                            arabicCaption.TextAlign != title.TextAlign ||
                            arabicCaption.Text != (leftToRight ? "Arabic (default)" : "العربية (الافتراضية)"))
                            throw new InvalidOperationException("Language settings visible text or direction failed at " + size + ".");
                        if (save.BorderWidth != 1 || close.BorderWidth != 1 ||
                            save.DefaultBorderColor != UiTheme.Primary || close.DefaultBorderColor != UiTheme.Primary ||
                            string.IsNullOrWhiteSpace(save.IconSvg) || string.IsNullOrWhiteSpace(close.IconSvg) ||
                            string.IsNullOrWhiteSpace(save.AccessibleName) || string.IsNullOrWhiteSpace(close.AccessibleName))
                            throw new InvalidOperationException("Language settings actions lost their accessible green AntdUI outline at " + size +
                                ": borders=" + save.BorderWidth + "/" + close.BorderWidth +
                                ", colors=" + save.DefaultBorderColor + "/" + close.DefaultBorderColor +
                                ", icons=" + !string.IsNullOrWhiteSpace(save.IconSvg) + "/" + !string.IsNullOrWhiteSpace(close.IconSvg) + ".");
                        RequireInside(footer, save, "language save " + size);
                        RequireInside(footer, close, "language close " + size);
                        RequireInside(arabicRow, arabicCaption, "language Arabic caption " + size);
                        RequireInside(englishRow, englishCaption, "language English caption " + size);
                        if (arabicRow.BackColor.ToArgb() != UiTheme.Surface.ToArgb() ||
                            (leftToRight ? arabicChoice.Left >= arabicCaption.Left : arabicChoice.Left <= arabicCaption.Left))
                            throw new InvalidOperationException("Arabic language option must remain beside its caption on the reading edge at " + size +
                                ": choice=" + arabicChoice.Bounds + ", caption=" + arabicCaption.Bounds +
                                ", rowColorMatch=" + (arabicRow.BackColor.ToArgb() == UiTheme.Surface.ToArgb()) +
                                ", leftToRight=" + leftToRight + ".");
                        if (englishChoice.Enabled || englishRow.BackColor.ToArgb() != UiTheme.Surface.ToArgb() ||
                            englishCaption.ForeColor.ToArgb() != UiTheme.MutedText.ToArgb() ||
                            englishCaption.Text != (leftToRight ? "English — in progress" : "English — قيد الإعداد") ||
                            (leftToRight ? englishChoice.Left >= englishCaption.Left : englishChoice.Left <= englishCaption.Left))
                            throw new InvalidOperationException("Unavailable English language must remain readable on the reading edge at " + size +
                                ": choice=" + englishChoice.Bounds + ", caption=" + englishCaption.Bounds +
                                ", colors=" + englishRow.BackColor + "/" + body.BackColor + "/" + englishCaption.ForeColor +
                                ", expected=" + UiTheme.MutedText +
                                ", enabled=" + englishChoice.Enabled +
                                ", rowColorMatch=" + (englishRow.BackColor.ToArgb() == UiTheme.Surface.ToArgb()) +
                                ", textColorMatch=" + (englishCaption.ForeColor.ToArgb() == UiTheme.MutedText.ToArgb()) +
                                ", captionText='" + englishCaption.Text +
                                "', expectedText='" + (leftToRight ? "English — in progress" : "English — قيد الإعداد") +
                                "', captionCodes=" + string.Concat(englishCaption.Text.Select(character => ((int)character).ToString("X4") + " ")) +
                                ", expectedCodes=" + string.Concat((leftToRight ? "English — in progress" : "English — قيد الإعداد").Select(character => ((int)character).ToString("X4") + " ")) +
                                "', leftToRight=" + leftToRight + ".");
                        if (arabicRow.Radius != 12 || englishRow.Radius != 12 || arabicRow.Shadow != 0 || englishRow.Shadow != 0 ||
                            !ReferenceEquals(form.AcceptButton, save) || !ReferenceEquals(form.CancelButton, close) ||
                            ((IButtonControl)close).DialogResult != DialogResult.Cancel || save.Enabled)
                            throw new InvalidOperationException("Language shared cards/dialog contract failed at " + size);
                        RequireInside(arabicRow, arabicChoice, "Arabic language option");
                        RequireInside(englishRow, englishChoice, "English language option");
                        RequireInside(arabicRow, arabicCaption, "Arabic language caption");
                        RequireInside(englishRow, englishCaption, "English language caption");
                        if (leftToRight ? save.Left >= close.Left : save.Left <= close.Left)
                            throw new InvalidOperationException("Language settings actions are not on the reading edge at " + size + ".");
                        if (save.Text != (leftToRight ? "Save" : "حفظ") ||
                            close.Text != (leftToRight ? "Close" : "إغلاق") ||
                            !languageStatus.AccessibleName.StartsWith(leftToRight ? "Language availability:" : "حالة توفر اللغة:", StringComparison.Ordinal))
                            throw new InvalidOperationException("Language settings actions or status are not fully localized at " + size + ".");
                        if (size.Height == 310)
                        {
                            body.ScrollControlIntoView(languageStatus);
                            Application.DoEvents();
                            if (!body.RectangleToScreen(body.ClientRectangle).Contains(
                                languageStatus.RectangleToScreen(languageStatus.ClientRectangle)))
                                throw new InvalidOperationException("Language status did not scroll into the visible card at minimum size.");
                        }
                    }
                }
            }
        }

        private static void VerifyDeviceSettingsLayout()
        {
            foreach (bool english in new[] { false, true })
            using (var form = new DeviceSettingsForm(true, english))
            {
                if (!ReferenceEquals(form.AcceptButton, Require<AntdUI.Button>(form, "saveDeviceSettings")) ||
                    !ReferenceEquals(form.CancelButton, Require<AntdUI.Button>(form, "closeDeviceSettings")))
                    throw new InvalidOperationException("Device settings must use shared Accept/Cancel actions.");
                foreach (Size size in new[] { new Size(480, 440), new Size(640, 520), new Size(1024, 700) })
                {
                    Prepare(form, size);
                    Label title = Require<Label>(form, "deviceSettingsTitle");
                    Label subtitle = Require<Label>(form, "deviceSettingsSubtitle");
                    if (form.Text != (english ? "Device center" : "مركز الأجهزة") ||
                        title.Text != (english ? "Device center" : "مركز الأجهزة") ||
                        title.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                        subtitle.TextAlign != title.TextAlign)
                        throw new InvalidOperationException("Device settings heading language or direction failed at " + size + ".");
                    foreach (string fieldName in new[] { "preferredPrinter", "receiptPaperFormat", "invoicePrintFormat" })
                    {
                        ComboBox field = Require<ComboBox>(form, fieldName);
                        AntdUI.Button dropdown = Require<AntdUI.Button>(form, fieldName + "Dropdown");
                        if (field.Height < 30 || field.Width < 200 ||
                            string.IsNullOrWhiteSpace(field.Text) || string.IsNullOrWhiteSpace(field.AccessibleName))
                            throw new InvalidOperationException("Device preference field is not usable: " + fieldName +
                                " bounds=" + field.Bounds + " host=" + field.Parent.Bounds + " text=" + field.Text);
                        if (field.Parent != dropdown.Parent || dropdown.Width < 30 || dropdown.Top < field.Top ||
                            dropdown.Bottom > field.Bottom || dropdown.Left < field.Left || dropdown.Right > field.Right ||
                            dropdown.Left != (english ? field.Right - dropdown.Width - 1 : field.Left + 1))
                            throw new InvalidOperationException("Device preference dropdown is not aligned to the reading edge: " + fieldName);
                    }
                    Panel actions = Require<Panel>(form, "deviceSettingsActions");
                    AntdUI.Panel body = Require<AntdUI.Panel>(form, "deviceSettingsBody");
                    TableLayoutPanel fields = Require<TableLayoutPanel>(body, "deviceSettingsFields");
                    if (body.Radius != DesktopDesignTokens.CardRadius || body.Shadow != 0 || fields.Width > 760 ||
                        body.RightToLeft != RightToLeft.No || fields.Left < 0)
                        throw new InvalidOperationException("Device settings lost its shared card or readable field width.");
                    Panel header = Require<Panel>(form, "deviceSettingsHeader");
                    if (!body.AutoScroll || fields.Parent != body || !fields.AutoSize ||
                        body.Top != header.Bottom || body.Bottom != actions.Top ||
                        actions.Bottom != form.ClientSize.Height || actions.BackColor.ToArgb() != UiTheme.Background.ToArgb())
                        throw new InvalidOperationException("Device settings must keep a scrollable body above the fixed footer at " + size + ".");
                    if (header.BackColor.ToArgb() != UiTheme.Background.ToArgb() || title.BackColor.ToArgb() != UiTheme.Background.ToArgb() ||
                        !body.Back.HasValue || body.Back.Value.ToArgb() != UiTheme.Surface.ToArgb() || body.BackColor.ToArgb() != UiTheme.Background.ToArgb() ||
                        fields.BackColor.ToArgb() != UiTheme.Surface.ToArgb() ||
                        Require<Label>(form, "devicePrinterLabel").BackColor.ToArgb() != UiTheme.Surface.ToArgb() ||
                        Require<Panel>(form, "preferredPrinterHost").BackColor.ToArgb() != UiTheme.Surface.ToArgb())
                        throw new InvalidOperationException("Device settings neutral header/body theme failed at " + size + ".");

                    foreach (string actionName in new[] { "saveDeviceSettings", "checkPreferredPrinter", "closeDeviceSettings" })
                    {
                        AntdUI.Button action = Require<AntdUI.Button>(actions, actionName);
                        RequireInside(actions, action, "device footer action " + actionName + " " + size);
                        if (action.Height < 44 || action.BorderWidth != 1 ||
                            action.DefaultBorderColor != UiTheme.Primary || string.IsNullOrWhiteSpace(action.IconSvg) ||
                            string.IsNullOrWhiteSpace(action.AccessibleName))
                            throw new InvalidOperationException("Device setting action lost its accessible green AntdUI outline: " + actionName);
                    }
                    AntdUI.Button save = Require<AntdUI.Button>(actions, "saveDeviceSettings");
                    AntdUI.Button close = Require<AntdUI.Button>(actions, "closeDeviceSettings");
                    if (save.Text != (english ? "Save settings" : "حفظ الإعدادات") ||
                        close.Text != (english ? "Close" : "إغلاق") ||
                        (english ? save.Left >= close.Left : save.Left <= close.Left))
                        throw new InvalidOperationException("Device footer actions start on the wrong reading edge at " + size + ".");
                    if (Require<ComboBox>(form, "receiptPaperFormat").Items.Cast<object>().Any(item =>
                        english ? item.ToString().Contains("المقاس") : item.ToString().Contains("default size")))
                        throw new InvalidOperationException("Device paper choices mixed interface languages at " + size + ".");
                }
            }
        }

        private static void VerifyBootstrapManagerLayout()
        {
            using (var form = new BootstrapManagerForm(true, false))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(480, 500), new Size(720, 650), new Size(1366, 768) })
                {
                    Prepare(form, size);
                    AntdUI.Panel fields = Require<AntdUI.Panel>(form, "bootstrapManagerFields");
                    AntdUI.Panel content = Require<AntdUI.Panel>(form, "bootstrapManagerContent");
                    if (fields.Radius != DesktopDesignTokens.CardRadius || fields.BorderWidth != 1 || fields.Width > 820)
                        throw new InvalidOperationException("Bootstrap manager fields are missing their rounded responsive card.");
                    foreach (string inputName in new[] { "bootstrapEmployeeId", "bootstrapEmployeeName", "bootstrapEmployeeAge", "bootstrapEmployeeSalary", "bootstrapEmployeePhone", "bootstrapPassword", "bootstrapConfirmPassword" })
                    {
                        TextBox input = Require<TextBox>(form, inputName);
                        AntdUI.Panel frame = input.Parent as AntdUI.Panel;
                        if (frame == null || frame.Height != 44 || !ReferenceEquals(frame.Tag, DesktopComponents.NativeTextFrameMarker) ||
                            input.BorderStyle != BorderStyle.None || input.Region != null || string.IsNullOrWhiteSpace(input.AccessibleName) || fields.Shadow != 0)
                            throw new InvalidOperationException("Bootstrap shared text frame failed: " + inputName);
                        RequireInside(frame, input, "bootstrap native editor " + inputName);
                        if (input.Height < 18 || input.Width < 120 || input.Right < 0 || input.Bottom < 0)
                            throw new InvalidOperationException("Bootstrap manager input is not usable: " + inputName);
                    }
                    if (!ReferenceEquals(form.AcceptButton, Require<AntdUI.Button>(form, "createBootstrapManager")) ||
                        !ReferenceEquals(form.CancelButton, Require<AntdUI.Button>(form, "cancelBootstrapManager")) ||
                        ((IButtonControl)form.CancelButton).DialogResult != DialogResult.Cancel)
                        throw new InvalidOperationException("Bootstrap dialog actions are not connected.");
                    foreach (string actionName in new[] { "createBootstrapManager", "cancelBootstrapManager" })
                    {
                        AntdUI.Button action = Require<AntdUI.Button>(form, actionName);
                        if (string.IsNullOrWhiteSpace(action.IconSvg) || action.Height < 44 || action.BorderWidth != 1)
                            throw new InvalidOperationException("Bootstrap manager action lost its outlined treatment: " + actionName);
                    }
                }
            }

            using (var form = new BootstrapManagerForm(true, true))
            {
                Prepare(form, new Size(720, 650));
                if (form.Text != "Initial manager setup" ||
                    Require<Label>(form, "bootstrapManagerTitle").Text != "Create the system's first manager" ||
                    Require<AntdUI.Button>(form, "createBootstrapManager").Text != "Create manager" ||
                    Require<AntdUI.Button>(form, "createBootstrapManager").Enabled)
                    throw new InvalidOperationException("Bootstrap manager English preview is incomplete or permits persistence.");
                if (Require<AntdUI.Button>(form, "createBootstrapManager").IconPosition != AntdUI.TAlignMini.Left ||
                    Require<FlowLayoutPanel>(form, "bootstrapManagerActions").FlowDirection != FlowDirection.LeftToRight)
                    throw new InvalidOperationException("Bootstrap manager English actions start on the wrong reading edge.");
            }
        }

