        // Explicit opt-in: writes and reloads user appearance preferences, then restores them.
        public static void VerifyAppearancePersistence()
        {
            string previousMode = Properties.Setings.Default.ThemeMode;
            string previousFont = Properties.Setings.Default.UiFontFamily;
            try
            {
                foreach (string mode in new[] { "Dark", "Light", "System" })
                {
                    UiTheme.SaveAppearance(mode, AppFonts.OfficialFamilyName);
                    UiTheme.SaveMode(mode);
                    Properties.Setings.Default.Reload();
                    if (UiTheme.LoadMode() != mode || UiTheme.LoadFontFamily() != AppFonts.OfficialFamilyName)
                        throw new InvalidOperationException("Appearance did not survive settings reload.");
                }
                UiTheme.SaveAppearance("Light", "__Missing_Pharmacy_Font__");
                Properties.Setings.Default.Reload();
                if (UiTheme.LoadFontFamily() != "__Missing_Pharmacy_Font__")
                    throw new InvalidOperationException("Missing font preference was lost instead of falling back at rendering.");
                AppFonts.Initialize(UiTheme.LoadFontFamily());
                using (Font font = AppFonts.Create(10F))
                    if (font.FontFamily.Name != AppFonts.OfficialFamilyName)
                        throw new InvalidOperationException("Packaged IBM fallback was not used.");
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = previousMode;
                Properties.Setings.Default.UiFontFamily = previousFont;
                Properties.Setings.Default.Save();
                Properties.Setings.Default.Reload();
                AppFonts.Initialize(UiTheme.LoadFontFamily());
            }
            if (Properties.Setings.Default.ThemeMode != previousMode || Properties.Setings.Default.UiFontFamily != previousFont)
                throw new InvalidOperationException("Original appearance preferences were not restored.");
            Console.WriteLine("Appearance persistence and missing-font fallback passed; original preferences restored.");
        }
        public static void VerifySettingsScrollNavigationOnly()
        {
            string oldTheme=Properties.Setings.Default.ThemeMode;
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach(string mode in new[]{"Light","Dark"})foreach(bool english in new[]{false,true})
                using(var form=new SettingsForm(true,true,english))
                {
                    Properties.Setings.Default.ThemeMode=mode;UiTheme.Apply(form);form.ApplyPresentation(english);
                    form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;
                    form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();
                    var host=Require<ThemedCardFlowPanel>(form,"antdSettingsCards");
                    foreach(Size size in new[]{new Size(360,360),new Size(760,570),new Size(1366,768)})
                    {
                        OwnedTestWindowViewport.Resize(form,size);host.ResetScroll();Application.DoEvents();
                        if(host.YScroll==null||!host.YScroll.Visible||host.YScroll.BackColor!=UiTheme.Background||host.CardViewport.BackColor!=UiTheme.Background||host.YScroll.TabStop)
                            throw new InvalidOperationException("Settings AntdUI scrollbar lost theme/visibility or altered Tab sequence at "+size);
                        var buttons=host.Cards.Select(c=>c.Controls.OfType<TableLayoutPanel>().Single().Controls.OfType<AntdUI.Button>().Single()).ToArray();
                        for(int index=0;index<buttons.Length;index++)
                        {
                            bool focused=index==0?buttons[0].Focus():form.SelectNextControl(form.ActiveControl,true,true,true,false);
                            Application.DoEvents();
                            Rectangle bounds=new Rectangle(host.CardViewport.PointToClient(buttons[index].PointToScreen(Point.Empty)),buttons[index].Size);
                            if(!focused||!buttons[index].Focused||!host.CardViewport.ClientRectangle.Contains(bounds))
                                throw new InvalidOperationException("Settings Tab focus/order or nested action scroll failed: "+buttons[index].Name+" at "+size+"; bounds="+bounds);
                        }
                        host.ResetScroll();Application.DoEvents();
                        buttons[0].Focus();Application.DoEvents();
                        Action<Keys> key=code=>{
                            var args=new KeyEventArgs(code);
                            typeof(Control).GetMethod("OnKeyDown",flags).Invoke(form.ActiveControl,new object[]{args});
                            Application.DoEvents();
                            if(!args.Handled||!args.SuppressKeyPress)throw new InvalidOperationException("Settings paging key was not handled.");
                            Control focused=form.ActiveControl;
                            Rectangle focusBounds=new Rectangle(host.CardViewport.PointToClient(focused.PointToScreen(Point.Empty)),focused.Size);
                            if(!host.CardViewport.ClientRectangle.Contains(focusBounds))throw new InvalidOperationException("Settings paging hides its focused action: "+code);
                        };
                        key(Keys.PageDown);int down=host.YScroll.Value;
                        if(down<=0)throw new InvalidOperationException("Settings PageDown did not move scroll.");
                        key(Keys.PageUp);if(host.YScroll.Value>=down)throw new InvalidOperationException("Settings PageUp did not move toward start.");
                        key(Keys.End);if(host.YScroll.Value<down)throw new InvalidOperationException("Settings End did not reach final content.");
                        key(Keys.Home);if(host.YScroll.Value!=0)throw new InvalidOperationException("Settings Home did not return to start.");
                        typeof(Control).GetMethod("OnMouseWheel",flags).Invoke(host.CardViewport,new object[]{new MouseEventArgs(MouseButtons.None,0,1,1,-120)});
                        Application.DoEvents();if(host.YScroll.Value<=0)throw new InvalidOperationException("Settings viewport wheel did not scroll.");
                        int wheel=host.YScroll.Value;host.YScroll.Value=host.YScroll.GetValue(wheel+100);Application.DoEvents();
                        if(host.YScroll.Value<=wheel)throw new InvalidOperationException("Settings scrollbar value did not move content.");
                        host.ScrollControlIntoView(buttons[buttons.Length-1]);Application.DoEvents();
                        Rectangle last=new Rectangle(host.CardViewport.PointToClient(buttons[buttons.Length-1].PointToScreen(Point.Empty)),buttons[buttons.Length-1].Size);
                        if(!host.CardViewport.ClientRectangle.Contains(last))throw new InvalidOperationException("Settings last nested action is not reachable after paging/wheel.");
                        buttons[buttons.Length-1].Focus();Application.DoEvents();
                        OwnedTestWindowViewport.Resize(form,new Size(360,360));
                        Rectangle compactFocus=new Rectangle(host.CardViewport.PointToClient(buttons[buttons.Length-1].PointToScreen(Point.Empty)),buttons[buttons.Length-1].Size);
                        if(!buttons[buttons.Length-1].Focused||!host.CardViewport.ClientRectangle.Contains(compactFocus))
                            throw new InvalidOperationException("Settings compact resize hides/losses focused final action.");
                        OwnedTestWindowViewport.Resize(form,size);
                        Console.WriteLine("PASS settings scroll navigation: theme="+mode+"; english="+english+"; client="+size+"; ten actual Tab targets, nested visibility, paging, wheel and scrollbar value; owned fixture only.");
                    }
                    form.Close();
                }
                Console.WriteLine("PASS settings 12 scroll/navigation cases; managed owned key/wheel events, no global keyboard/clipboard/SQL/DPI claim.");
            }
            finally{Properties.Setings.Default.ThemeMode=oldTheme;using(var palette=new Form())UiTheme.Apply(palette);}
        }


        public static void VerifySettingsNativeViewportOnly()
        {
            string oldTheme=Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})foreach(bool english in new[]{false,true})foreach(bool enlarged in new[]{false,true})
                {
                    Properties.Setings.Default.ThemeMode=theme;
                    using(var titleFont=AppFonts.Create(enlarged?16.5F:11F,FontStyle.Bold))
                    using(var descriptionFont=AppFonts.Create(enlarged?14.25F:9.5F))
                    using(var form=new SettingsForm(true,true,english))
                    {
                        foreach(Control card in Require<ThemedCardFlowPanel>(form, "antdSettingsCards").Controls)
                        foreach(Label label in card.Controls.OfType<TableLayoutPanel>().Single().Controls.OfType<Label>())
                            label.Font=label.Name.StartsWith("antdTitle_")?titleFont:descriptionFont;
                        form.ApplyPresentation(english);
                        form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;
                        form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();
                        Size minimum=form.MinimumSize;
                        foreach(Size size in new[]{new Size(360,360),new Size(360,570),new Size(760,570),new Size(1024,768),new Size(1366,768),new Size(1920,1080)})
                        {
                            OwnedTestWindowViewport.Resize(form,size);
                            if(form.MinimumSize!=minimum)throw new InvalidOperationException("Settings fixture changed original minimum.");
                            var host=Require<ThemedCardFlowPanel>(form, "antdSettingsCards");
                            host.ResetScroll();host.PerformLayout();Application.DoEvents();
                            var body=Require<Panel>(form,"panelBody");var hint=Require<Label>(form,"lblHint");
                            var status=Require<StatusStrip>(form,"__UiStatusStrip");
                            if(body.Bottom>hint.Top||hint.Bottom>status.Top||host.Cards.Any(card=>card.Left<0||card.Right>host.CardViewport.ClientSize.Width))
                                throw new InvalidOperationException("Settings native body/hint/status or horizontal scroll failed at "+size);
                            Control[] cards=host.Cards;
                            if(cards.Length!=12||!cards.Any(card=>card.Name=="antdCard_accessibility")||!cards.Any(card=>card.Name=="antdCard_sales-shortcuts"))throw new InvalidOperationException("Settings native card count changed.");
                            for(int index=0;index<cards.Length;index++)
                            {
                                Control card=cards[index];
                                if(card.Left<0||card.Right>host.CardViewport.ClientSize.Width)
                                    throw new InvalidOperationException("Settings native card outside viewport: "+card.Name+" at "+size);
                                var content=card.Controls.OfType<TableLayoutPanel>().Single();
                                foreach(Label label in content.Controls.OfType<Label>())
                                {
                                    int height=TextRenderer.MeasureText(label.Text,label.Font,
                                        new Size(Math.Max(1,label.ClientSize.Width-label.Padding.Horizontal),int.MaxValue),
                                        TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height;
                                    if(height>label.ClientSize.Height-label.Padding.Vertical)
                                        throw new InvalidOperationException("Settings native text clipped: "+label.Name+" at "+size+"; measured="+height+"; available="+label.ClientSize);
                                    if(label.TextAlign!=(english ? (label.Name.StartsWith("antdTitle_")?ContentAlignment.MiddleLeft:ContentAlignment.TopLeft) : (label.Name.StartsWith("antdTitle_")?ContentAlignment.MiddleRight:ContentAlignment.TopRight)))
                                        throw new InvalidOperationException("Settings native text reading edge changed: "+label.Name);
                                }
                                var open=content.Controls.OfType<AntdUI.Button>().Single();
                                if(open.Height<44||!content.ClientRectangle.Contains(open.Bounds)||string.IsNullOrWhiteSpace(open.AccessibleName))
                                    throw new InvalidOperationException("Settings native action clipped: "+card.Name+" at "+size);
                                for(int other=index+1;other<cards.Length;other++)if(card.Bounds.IntersectsWith(cards[other].Bounds))
                                    throw new InvalidOperationException("Settings native cards overlap at "+size);
                            }
                            if(host.ReadingColumns>1&&((cards[0].Left<cards[1].Left)!=english))
                                throw new InvalidOperationException("Settings native card reading order changed at "+size);
                            host.ScrollControlIntoView(cards[cards.Length-1]);Application.DoEvents();
                            var lastContent=cards[cards.Length-1].Controls.OfType<TableLayoutPanel>().Single();
                            foreach(Control target in new[]{lastContent.GetControlFromPosition(0,0),lastContent.GetControlFromPosition(0,2)})
                            {
                                host.ScrollControlIntoView(target);Application.DoEvents();
                                Rectangle visibleBounds=new Rectangle(host.CardViewport.PointToClient(target.PointToScreen(Point.Empty)),target.Size);
                                if(!host.CardViewport.ClientRectangle.Contains(visibleBounds))
                                    throw new InvalidOperationException("Settings last native title/action is not reachable at "+size+"; target="+target.Name+"; bounds="+visibleBounds+"; host="+host.ClientRectangle);
                            }
                            Console.WriteLine("PASS settings native viewport: theme="+theme+"; english="+english+"; enlargedText="+enlarged+"; client="+size+"; ten readable cards/last-card scroll/minimum preserved.");
                        }
                        form.Close();
                    }
                }
                Console.WriteLine("PASS settings 48 native viewport cases (default and enlarged card text); preview-only actions, no SQL/native keyboard/DPI or physical printer claim.");
            }
            finally {Properties.Setings.Default.ThemeMode=oldTheme;using(var palette=new Form())UiTheme.Apply(palette);}
        }


        private static void ShowSettingsLayout(Form form)
        {
            if (form.ShowInTaskbar) throw new InvalidOperationException("Settings layout requires an owned test form.");
            bool maximize = form.MaximizeBox;
            try
            {
                // Isolate responsive geometry from the independently tested opening preference.
                form.MaximizeBox = false;
                form.Show();
                Application.DoEvents();
            }
            finally { if (!form.IsDisposed) form.MaximizeBox = maximize; }
        }

        private static void VerifySettingsCards()
        {
            using (var form = new SettingsForm())
            {
                form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);ShowSettingsLayout(form);Application.DoEvents();
                foreach (int width in new[] { 360, 760 })
                {
                    OwnedTestWindowViewport.Resize(form, new Size(width, 570));
                    form.PerformLayout();
                    Control body = form.Controls["panelBody"];
                    Control hint = form.Controls["lblHint"];
                    Control status = form.Controls["__UiStatusStrip"];
                    if (hint == null || status == null || body.Bottom > hint.Top || hint.Bottom > status.Top)
                        throw new InvalidOperationException("Settings cards or hint overlap the fixed status bar at width " + width +
                            ": body=" + body.Bounds + " hint=" + (hint == null ? "missing" : hint.Bounds.ToString()) +
                            " status=" + (status == null ? "missing" : status.Bounds.ToString()) + ".");
                    Control antdHost = Find<ThemedCardFlowPanel>(form, "antdSettingsCards");
                    if (antdHost != null)
                    {
                        if (((ThemedCardFlowPanel)antdHost).Cards.Any(card => card.Left < 0 || card.Right > ((ThemedCardFlowPanel)antdHost).CardViewport.ClientSize.Width))
                            throw new InvalidOperationException("AntdUI settings should scroll vertically without a horizontal bar at width " + width + ".");
                        Control[] cards = ((ThemedCardFlowPanel)antdHost).Cards;
                        if (cards.Length != 12 || !cards.Any(card => card.Name == "antdCard_accessibility") || !cards.Any(card => card.Name == "antdCard_sales-shortcuts") || !cards.Any(card => card.Name == "antdCard_invoice-drafts") ||
                            !cards.Any(card => card.Name == "antdCard_cashboxes"))
                            throw new InvalidOperationException("AntdUI settings cards are missing or a QA card is exposed.");
                        if (width == 760 && cards[0].Left <= cards[1].Left)
                            throw new InvalidOperationException("Arabic settings cards must start at the right reading edge: first=" + cards[0].Bounds + ", second=" + cards[1].Bounds + ", flow=" + ((ThemedCardFlowPanel)antdHost).ReadingLeftToRight + ".");
                        for (int index = 0; index < cards.Length; index++)
                        {
                            Control card = cards[index];
                            if (card.Left < 0 || card.Right > antdHost.ClientSize.Width)
                                throw new InvalidOperationException("AntdUI settings card exceeds available width.");
                            TableLayoutPanel content = card.Controls.OfType<TableLayoutPanel>().Single();
                            AntdUI.Button open = content.Controls.OfType<AntdUI.Button>().Single();
                            if (card.Height < 156 || open.Height < 44 || string.IsNullOrWhiteSpace(open.AccessibleName))
                                throw new InvalidOperationException("AntdUI settings card lost readable sizing or access at width " + width +
                                    ": card=" + card.Bounds + " action=" + open.Bounds + " name=" + open.AccessibleName + ".");
                            Label description = (Label)content.GetControlFromPosition(0, 1);
                            int textHeight = TextRenderer.MeasureText(description.Text, description.Font,
                                new Size(Math.Max(1, description.ClientSize.Width), int.MaxValue),
                                TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                            if (textHeight > description.ClientSize.Height)
                                throw new InvalidOperationException("AntdUI settings description is clipped at width " + width + ": " + description.Text);
                            for (int otherIndex = index + 1; otherIndex < cards.Length; otherIndex++)
                                if (card.Bounds.IntersectsWith(cards[otherIndex].Bounds))
                                    throw new InvalidOperationException("AntdUI settings cards overlap.");
                        }
                        continue;
                    }
                    int count = 0;
                    foreach (Control card in body.Controls)
                    {
                        if (!(card is Panel)) continue;
                        count++;
                        if (card.Left < 0 || card.Right > body.ClientSize.Width)
                            throw new InvalidOperationException("Settings card exceeds available width.");
                        foreach (Control other in body.Controls)
                            if (other != card && other is Panel && card.Bounds.IntersectsWith(other.Bounds))
                                throw new InvalidOperationException("Settings cards overlap.");
