        internal static void VerifyTaxSharedShell()
        {
            VerifyTaxDialogActions();
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var palette = new Form()) UiTheme.Apply(palette);
                    foreach (bool english in new[] { false, true })
                    using (var form = new TaxSettingsForm(true, english))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.MaximizeBox = false; form.Show(); OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
                        ComboBox country = Require<ComboBox>(form, "cmbTaxCountry");
                        CheckBox enabled = Require<CheckBox>(form, "chkTaxEnabled");
                        NumericUpDown rate = Require<NumericUpDown>(form, "numTaxRate");
                        country.SelectedIndex = 1; enabled.Checked = true; rate.Value = 15m;
                        foreach (Size size in new[] { form.ClientSize, new Size(640, 500), new Size(1024, 680) })
                        {
                            Prepare(form, size);
                            foreach (string accessible in new[] { "taxSettingsHeader", "taxSettingsBody", "taxSettingsCard", "taxSettingsFields", "taxCountryHost", "taxCountryDropdownFrame", "taxEnabledRow", "taxRateFrame", "taxSettingsFooter", "taxSettingsActions", "taxEnabledCaption" })
                            {
                                Control named = Require<Control>(form, accessible);
                                if (string.IsNullOrWhiteSpace(named.AccessibleName) ||
                                    (english && named.AccessibleName.Any(c => c >= '\u0600' && c <= '\u06ff')))
                                    throw new InvalidOperationException("Tax accessible name missing or in the wrong language: " + accessible);
                            }
                            AntdUI.Panel card = Require<AntdUI.Panel>(form, "taxSettingsCard");
                            AntdUI.Panel rateFrame = Require<AntdUI.Panel>(form, "taxRateFrame");
                            Label status = Require<Label>(form, "taxSettingsStatus");
                            if (rate.Parent != rateFrame || rateFrame.Height < 44 || rateFrame.Shadow != 0 ||
                                rateFrame.Radius != DesktopDesignTokens.ActionRadius(rateFrame.Height) ||
                                rateFrame.Back != UiTheme.Surface || rate.BorderStyle != BorderStyle.None || rate.Region != null ||
                                !rateFrame.ClientRectangle.Contains(rate.Bounds) ||
                                Math.Abs(rate.Top * 2 + rate.Height - rateFrame.ClientSize.Height) > 1 ||
                                rate.Minimum != 0m || rate.Maximum != 100m || rate.DecimalPlaces != 2 ||
                                status.BorderStyle != BorderStyle.None || status.Region != null || status.BackColor != UiTheme.Surface)
                                throw new InvalidOperationException("Tax numeric frame or policy message lost its shared surface or native editing contract at " + size);
                            foreach (TextBox inner in rate.Controls.OfType<TextBox>())
                                if (inner.BorderStyle != BorderStyle.None || inner.Region != null || inner.BackColor != UiTheme.Surface)
                                    throw new InvalidOperationException("Tax numeric editor restored a second border inside its AntdUI frame.");
                            foreach (string name in new[] { "taxSettingsTitle", "taxSettingsSubtitle" })
                            {
                                Label label = Require<Label>(form, name);
                                if (label.Height < TextRenderer.MeasureText(label.Text, label.Font,
                                    new Size(label.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height ||
                                    label.AccessibleName != label.Text)
                                    throw new InvalidOperationException("Tax heading clipped: " + name);
                            }
                            int textHeight = TextRenderer.MeasureText(status.Text, status.Font,
                                new Size(Math.Max(1, status.Width - status.Padding.Horizontal), int.MaxValue),
                                TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                            if (card.Radius != 12 || card.Shadow != 0 || status.Height - status.Padding.Vertical < textHeight ||
                                status.AccessibleName != status.Text || country.SelectedIndex != 1 || !enabled.Checked || rate.Value != 15m ||
                                Require<AntdUI.Button>(form, "btnSaveTaxSettings").Enabled || form.AcceptButton == null || form.CancelButton == null)
                                throw new InvalidOperationException("Tax shared shell changed policy editing or clipped its explanation at " + size);
                            foreach (string rawStatus in new[]
                            {
                                "جار تأكيد حفظ سياسة الضريبة؛ انتظر اكتمال العملية قبل الإغلاق.",
                                "تعذر التحميل. أغلق النافذة وأعد المحاولة بعد التحقق من الاتصال."
                            })
                            {
                                status.Text = english ? UiLanguageCatalog.Translate(rawStatus) : rawStatus;
                                form.PerformLayout(); Application.DoEvents();
                                int required = TextRenderer.MeasureText(status.Text, status.Font,
                                    new Size(Math.Max(1, status.Width - status.Padding.Horizontal), int.MaxValue),
                                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                                if (status.Height - status.Padding.Vertical < required || status.AccessibleName != status.Text ||
                                    !card.ClientRectangle.Contains(Require<TableLayoutPanel>(form, "taxSettingsFields").Bounds) ||
                                    country.SelectedIndex != 1 || !enabled.Checked || rate.Value != 15m)
                                    throw new InvalidOperationException("Tax long operation status clipped or changed draft at " + size);
                            }
                        }
                        rate.Value = 15.25m;
                        UiTheme.ApplyTo(rate);
                        foreach (TextBox inner in rate.Controls.OfType<TextBox>())
                        {
                            UiTheme.ApplyTo(inner);
                            if (inner.BorderStyle != BorderStyle.None || inner.Region != null || inner.BackColor != UiTheme.Surface)
                                throw new InvalidOperationException("Tax numeric child theme refresh restored a second border.");
                        }
                        if (rate.Value != 15.25m || rate.BorderStyle != BorderStyle.None || rate.Region != null)
                            throw new InvalidOperationException("Tax numeric theme refresh changed its value or restored native clipping.");
                        rate.Value = 15m;
                        country.SelectedIndex = 0;
                        if (enabled.Enabled || rate.Enabled || rate.Value != 15m ||
                            !Require<Label>(form, "taxSettingsStatus").Text.Contains("0%"))
                            throw new InvalidOperationException("Tax shell changed Yemen policy or discarded the configured rate.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = original;
                using (var palette = new Form()) UiTheme.Apply(palette);
            }
        }
        private static void VerifyTaxDialogActions()
        {
            var dialogKey = typeof(Form).GetMethod("ProcessDialogKey",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            using (var dialog = new Form { ShowInTaskbar = false, StartPosition = FormStartPosition.Manual,
                Location = new Point(-20000, -20000) })
            {
                var save = DesktopComponents.Action("dialogSave", "Save", AppIcon.Save);
                int clicks = 0;
                save.Click += (sender, args) => clicks++;
                dialog.Controls.Add(save);
                dialog.AcceptButton = save;
                dialog.Show();
                dialogKey.Invoke(dialog, new object[] { Keys.Enter });
                if (clicks != 1) throw new InvalidOperationException("Shared AntdUI dialog action did not handle Enter exactly once.");
                save.Enabled = false;
                dialogKey.Invoke(dialog, new object[] { Keys.Enter });
                save.AccessibilityObject.DoDefaultAction();
                if (clicks != 1) throw new InvalidOperationException("Disabled shared dialog action was activated.");
            }
            using (var tax = new TaxSettingsForm(true))
            {
                var save = Require<AntdUI.Button>(tax, "btnSaveTaxSettings");
                var cancel = Require<AntdUI.Button>(tax, "btnCancelTaxSettings");
                if (!ReferenceEquals(tax.AcceptButton, save) || !ReferenceEquals(tax.CancelButton, cancel) ||
                    cancel.DialogResult != DialogResult.Cancel)
                    throw new InvalidOperationException("Tax dialog lost its save/cancel button contract.");
                tax.ShowInTaskbar = false;
                tax.StartPosition = FormStartPosition.Manual;
                tax.Location = new Point(-20000, -20000);
                tax.Show();
                dialogKey.Invoke(tax, new object[] { Keys.Enter });
                if (tax.IsDisposed || tax.DialogResult == DialogResult.OK)
                    throw new InvalidOperationException("Tax preview Enter must not save or close the form.");
                dialogKey.Invoke(tax, new object[] { Keys.Escape });
                if (tax.DialogResult != DialogResult.Cancel)
                    throw new InvalidOperationException("Tax dialog Escape did not cancel.");
            }
        }

        private static void VerifySaudiSharedComponents()
        {
