                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); ShowSettingsLayout(form); OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
