                            AntdUI.Panel card = Require<AntdUI.Panel>(form, "saudiCommercialCard");
                            DataGridView grid = Require<DataGridView>(form, "saudiFeaturesGrid");
                            RequireInside(frame, reason, "Saudi shared reason editor");
                            RequireInside(Require<Panel>(form, "saudiCommercialReasonPanel"), frame, "Saudi visible reason frame");
                            var footer = Require<FlowLayoutPanel>(form,"saudiCommercialActions");
                            foreach (var action in footer.Controls.OfType<AntdUI.Button>())
                                if (action.Height < DesktopDesignTokens.ActionHeight || !footer.ClientRectangle.Contains(action.Bounds))
                                    throw new InvalidOperationException("Saudi short viewport clips an action at " + size + "/" + theme + "/" + english);
                            foreach (string name in new[] { "saudiCommercialTitle", "saudiCommercialHint" })
                            {
                                Label label = Require<Label>(form, name);
                                if (label.Height < TextRenderer.MeasureText(label.Text, label.Font,
                                    new Size(label.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height ||
                                    label.AccessibleName != label.Text)
                                    throw new InvalidOperationException("Saudi shared heading clipped: " + name);
                            }
                            if (frame.Height < 44 || frame.Shadow != 0 || card.Radius != 12 || card.Shadow != 0 ||
                                reason.MaxLength != 500 || reason.Text != exactReason || reason.SelectionStart != 3 || reason.SelectionLength != 4 ||
                                reason.RightToLeft != RightToLeft.Yes || reason.TextAlign != HorizontalAlignment.Left ||
                                Math.Abs(reason.Top + reason.Height / 2 - frame.ClientSize.Height / 2) > 2 ||
                                grid.AutoGenerateColumns || grid.Columns.Count != 5 || grid.Columns["FeatureKey"].Visible ||
                                !UiTheme.OwnsCustomGridColumns(grid) || grid.ColumnHeadersHeight < 60 || grid.Columns["Description"].Width < 220 ||
                                grid.ScrollBars != ScrollBars.Both || Require<Label>(form, "saudiCommercialStatus").BorderStyle != BorderStyle.None ||
                                grid.Height < grid.ColumnHeadersHeight + grid.RowTemplate.Height + SystemInformation.HorizontalScrollBarHeight ||
                                Require<AntdUI.Button>(form, "saveSaudiCommercialSettings").Enabled)
                                throw new InvalidOperationException("Saudi shared components changed editing or preview safety at " + size+"; theme="+theme+"; english="+english+"; reasonSame="+(reason.Text==exactReason)+"; selection="+reason.SelectionStart+"/"+reason.SelectionLength+"; reasonRTL="+reason.RightToLeft+"; reasonBounds="+reason.Bounds+"; frame="+frame.ClientRectangle+"; frameHeight="+frame.Height+"; gridHeight="+grid.Height+"; requiredGrid="+(grid.ColumnHeadersHeight+grid.RowTemplate.Height+SystemInformation.HorizontalScrollBarHeight)+"; columns="+grid.Columns.Count+"; header="+grid.ColumnHeadersHeight+"; description="+grid.Columns["Description"].Width+"; saveEnabled="+Require<AntdUI.Button>(form,"saveSaudiCommercialSettings").Enabled);
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = original;
                using (var palette = new Form()) UiTheme.Apply(palette);
            }
        }

        private static void VerifyReportPrintPagination()
        {
            using (var table = new System.Data.DataTable())
            using (var bitmap = new Bitmap(1100, 800))
            using (Graphics graphics = Graphics.FromImage(bitmap))
            {
                table.Columns.Add("اليوم", typeof(string));
                for (int column = 1; column < 14; column++) table.Columns.Add("مؤشر يومي " + column, typeof(decimal));
                for (int row = 0; row < 80; row++)
                {
                    var values = new object[14];
                    values[0] = "2026-09-" + (row + 1);
                    for (int column = 1; column < 14; column++) values[column] = -40.25m;
                    table.Rows.Add(values);
                }
                using (var layout = new DataTablePrintPreview.TablePrintLayout("الأداء اليومي", "فحص الصفحات", table))
                {
                    int firstRunPages = 0;
                    for (int run = 0; run < 2; run++)
                    {
                        layout.Reset();
                        int pages = 0;
                        bool more;
                        do
                        {
                            var args = new System.Drawing.Printing.PrintPageEventArgs(graphics, new Rectangle(40, 40, 900, 600), new Rectangle(0, 0, 1100, 800), new System.Drawing.Printing.PageSettings());
                            layout.PrintPage(null, args);
                            more = args.HasMorePages;
                            if (++pages > 100) throw new InvalidOperationException("Report print pagination did not terminate.");
                        } while (more);
                        if (pages <= 1) throw new InvalidOperationException("Wide long report did not paginate.");
                        if (run == 0) firstRunPages = pages;
                        else if (pages != firstRunPages) throw new InvalidOperationException("Printing after preview lost pages.");
                        var field = typeof(DataTablePrintPreview.TablePrintLayout).GetField("columnGroups", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                        var groups = (System.Collections.Generic.List<System.Collections.Generic.List<System.Data.DataColumn>>)field.GetValue(layout);
                        foreach (var group in groups)
                            if (group[0].ColumnName != "اليوم") throw new InvalidOperationException("A printed column group lost its day identifier.");
                    }
                    layout.Reset();
                    bool rejected = false;
                    try { layout.PrintPage(null, new System.Drawing.Printing.PrintPageEventArgs(graphics, new Rectangle(0, 0, 300, 100), new Rectangle(0, 0, 300, 100), new System.Drawing.Printing.PageSettings())); }
                    catch (InvalidOperationException) { rejected = true; }
                    if (!rejected) throw new InvalidOperationException("Unprintable page must fail instead of generating endless pages.");
                }
                using (var rightToLeftLayout = new DataTablePrintPreview.TablePrintLayout("تقرير", "اختبار RTL", table, true))
                using (var leftToRightLayout = new DataTablePrintPreview.TablePrintLayout("Report", "LTR test", table, false))
                {
                    if (!rightToLeftLayout.IsRightToLeft || leftToRightLayout.IsRightToLeft)
                        throw new InvalidOperationException("Printed report direction does not follow the requested language direction.");
                    var printable = new System.Drawing.Printing.PrintPageEventArgs(graphics, new Rectangle(40, 40, 900, 600), new Rectangle(0, 0, 1100, 800), new System.Drawing.Printing.PageSettings());
                    rightToLeftLayout.PrintPage(null, printable);
                    leftToRightLayout.PrintPage(null, printable);
                }
            }
        }
