        private static void VerifyQuantityEditingPreservesInput()
        {
            using (var form = new Billing())
            {
                var combo = Require<ComboBox>(form, "MediComboCb");
                var quantity = Require<AntdUI.Input>(form, "txtQuantity");
                // Provide a loaded selection and stock preview without invoking database reads.
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var selection = typeof(Billing).GetMethod("MedicineSelectionChanged", flags);
                combo.SelectedIndexChanged -= (EventHandler)Delegate.CreateDelegate(typeof(EventHandler), form, selection);
                combo.Items.Add("صنف تحقق الكمية");
                combo.SelectedIndex = combo.Items.Count - 1;
                typeof(Billing).GetField("selectedStockPreview", flags).SetValue(form, (int?)5);
                foreach (string input in new[] { "", "0", "12", "123", "abc", "2147483648", "3" })
                {
                    quantity.Text = input;
                    if (quantity.Text != input)
                        throw new InvalidOperationException("Quantity editing unexpectedly replaced user input: " + input);
                }
            }
        }
