                                Control heading = Require<Control>(form, "quickSearchSuggestionsHeader");
                                DataGridView grid = Require<DataGridView>(form, "quickSearchResults");
                                Label status = Require<Label>(form, "quickSearchStatus");
                                Control footer = Require<Control>(form, "quickSearchFooter");
                                FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "quickSearchActions");
                                AntdUI.Button select = Require<AntdUI.Button>(form, "quickSearchSelect");
                                AntdUI.Button close = Require<AntdUI.Button>(form, "quickSearchClose");
                                int visibleColumns = grid.Columns.Cast<DataGridViewColumn>().Count(column => column.Visible);
                                int totalWidth = grid.Columns.Cast<DataGridViewColumn>().Where(column => column.Visible).Sum(column => column.Width);
                                int requiredDateWidth = TextRenderer.MeasureText("2099-12-31", grid.DefaultCellStyle.Font ?? grid.Font).Width
                                    + grid.DefaultCellStyle.Padding.Horizontal + 12;
                                if (title.Top >= searchFrame.Top || searchFrame.Bottom > heading.Top || heading.Bottom > grid.Top ||
                                    grid.Bottom > status.Top || status.Bottom > footer.Top || grid.Height < 80 ||
                                    grid.AutoGenerateColumns || grid.Columns.Count != 8 || grid.Columns["ChoiceCount"].Visible || grid.Rows.Count != 1 ||
                                    visibleColumns != (size.Width < 520 ? 4 : 6) || totalWidth > grid.ClientSize.Width ||
                                    (grid.ColumnHeadersDefaultCellStyle.BackColor != UiTheme.Surface && grid.ColumnHeadersDefaultCellStyle.BackColor != UiTheme.PrimaryDark) ||
                                    footer.Bottom > layout.Bottom || actions.HorizontalScroll.Visible || select.Enabled ||
                                    select.Height < 44 || close.Height < 44 ||
                                    select.DefaultBorderColor != UiTheme.Primary || close.DefaultBorderColor != UiTheme.Primary ||
                                    select.DefaultBack != UiTheme.Surface || close.DefaultBack != UiTheme.Surface ||
                                    !actions.ClientRectangle.Contains(select.Bounds) || !actions.ClientRectangle.Contains(close.Bounds))
                                    throw new InvalidOperationException("Quick search layout failed: english=" + english + ", size=" + size +
                                        ", visible=" + visibleColumns + ", total=" + totalWidth + ", client=" + grid.ClientSize.Width +
                                        ", gridMode=" + grid.AutoSizeColumnsMode + ", columns=" + string.Join(",", grid.Columns.Cast<DataGridViewColumn>()
                                            .Where(column => column.Visible).Select(column => column.Name + ":" + column.Width + "/" + column.MinimumWidth + "/" + column.AutoSizeMode)) + ".");
                                if (title.Text != (english ? "Quick medicine search" : "البحث السريع عن الأصناف") ||
                                    search.RightToLeft != RightToLeft.Yes ||
