                                    grid.Columns["MedName"].DisplayIndex != 0 ||
                                    grid.ColumnHeadersHeight < 58 ||
                                    search.Text != "باراسيتامول 500 mg" ||
                                    !status.Text.Contains(english ? "Search preview" : "معاينة البحث"))
                                    throw new InvalidOperationException("Quick search language or preview guard failed: english=" + english +
                                        ", title=" + title.Text + ", searchRtl=" + search.RightToLeft +
                                        ", header=" + grid.Columns["MedName"].HeaderText +
                                        ", display=" + grid.Columns["MedName"].DisplayIndex +
                                        ", headerHeight=" + grid.ColumnHeadersHeight + ", status=" + status.Text + ".");
                                UiTheme.ApplyDataGridQuality(grid);
                                Rectangle nameCell = grid.GetCellDisplayRectangle(grid.Columns["MedName"].Index, -1, false);
                                Rectangle quantityCell = grid.GetCellDisplayRectangle(grid.Columns["MedQty"].Index, -1, false);
                                if ((english ? nameCell.Left >= quantityCell.Left : nameCell.Left <= quantityCell.Left) ||
                                    grid.AutoGenerateColumns || grid.ColumnHeadersHeight < 58 || grid.Columns.Count != 8 || grid.Columns["ChoiceCount"].Visible ||
                                    grid.Columns["ExpDate"].Width < requiredDateWidth ||
                                    grid.Height < grid.ColumnHeadersHeight + grid.Rows[0].Height + 2 ||
                                    grid.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                    grid.Columns["MedName"].HeaderText != (english ? "Medicine" : "الصنف") ||
                                    searchFrame.Height < 44 || searchFrame.Shadow != 0 ||
                                    searchFrame.Radius != DesktopDesignTokens.ActionRadius(searchFrame.Height) ||
                                    search.Parent != searchFrame || search.BorderStyle != BorderStyle.None ||
                                    !searchFrame.ClientRectangle.Contains(search.Bounds) ||
                                    Math.Abs(search.Top + search.Height / 2 - searchFrame.ClientSize.Height / 2) > 2 ||
                                    search.TextAlign != HorizontalAlignment.Left)
                                    throw new InvalidOperationException("Quick search reading edge or shared native frame is inconsistent: english=" + english + "; name=" + nameCell + "; qty=" + quantityCell + "; gridRtl=" + grid.RightToLeft + "; frame=" + searchFrame.Bounds + "; editor=" + search.Bounds + "; radius=" + searchFrame.Radius + "; align=" + search.TextAlign);
                                if (english)
                                {
                                    search.Text = "Paracetamol 500 mg";
                                    if (search.RightToLeft != RightToLeft.No || search.TextAlign != HorizontalAlignment.Left)
                                        throw new InvalidOperationException("English quick search text did not restore LTR content direction.");
                                    search.Text = "باراسيتامول 500 mg";
                                }
                                if (english ? select.Left >= close.Left : select.Left <= close.Left)
                                    throw new InvalidOperationException("Quick search actions are on the wrong reading edge: english=" + english + ".");
                            }
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

