                            Require<AntdUI.Button>(form, "excelTransferImport").Text != "Open import" ||
                            Require<AntdUI.Button>(form, "excelTransferExport").AccessibleName != "Export to Excel" ||
                            Require<AntdUI.Button>(form, "excelTransferImport").AccessibleName != "Open import" ||
                            Require<AntdUI.Button>(form, "excelTransferClose").AccessibleName != "Close" ||
                            Require<AntdUI.Button>(form, "excelTransferImport").AccessibilityObject.DefaultAction != "Activate" ||
                            !Require<Label>(form, "excelTransferStatus").Text.Contains("preview") ||
                            Require<Label>(form, "excelTransferStatus").AccessibleName != Require<Label>(form, "excelTransferStatus").Text ||
                            Require<TextBox>(form, "excelTransferSearch").Text != "باراسيتامول 500 mg" ||
                            Require<TextBox>(form, "excelTransferSearch").RightToLeft != RightToLeft.Yes ||
                            Require<TextBox>(form, "excelTransferSearch").TextAlign != HorizontalAlignment.Left ||
                            form.Controls["__UiStatusStrip"] != null)
                            throw new InvalidOperationException("Excel export English text or LTR direction is inconsistent: direction=" + form.RightToLeft + ", layout=" + form.RightToLeftLayout + ", title=" + form.Text + ", label=" + Require<Label>(form, "excelTransferLabel0").Text + ", align=" + Require<Label>(form, "excelTransferLabel0").TextAlign + ", source=" + Convert.ToString(Require<AntdUI.Select>(form, "excelTransferSource").Items[0]) + ", flow=" + Require<FlowLayoutPanel>(form, "excelTransferActions").FlowDirection + ", status=" + Require<Label>(form, "excelTransferStatus").Text);
                        form.ApplyPresentation(false);
                        Prepare(form, new Size(520, 470));
                        if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                            Require<Label>(form, "excelTransferLabel0").Text != "نوع البيانات" ||
                            Require<FlowLayoutPanel>(form, "excelTransferActions").FlowDirection != FlowDirection.RightToLeft ||
                            Require<AntdUI.Button>(form, "excelTransferExport").AccessibleName != "تصدير إكسل" ||
                            Require<AntdUI.Button>(form, "excelTransferClose").AccessibleName != "إغلاق" ||
                            Require<AntdUI.Button>(form, "excelTransferImport").AccessibilityObject.DefaultAction != "تنفيذ" ||
                            Require<TextBox>(form, "excelTransferSearch").Text != "باراسيتامول 500 mg" ||
                            Require<TextBox>(form, "excelTransferSearch").RightToLeft != RightToLeft.Yes ||
                            Require<TextBox>(form, "excelTransferSearch").TextAlign != HorizontalAlignment.Left ||
                            Require<Label>(form, "excelTransferStatus").AccessibleName != Require<Label>(form, "excelTransferStatus").Text)
                            throw new InvalidOperationException("Excel export did not restore Arabic RTL presentation.");
                        VerifyExcelMinimumWindow(form);
                    }
                }
                using (var action = (AccessibleAntdButton)DesktopComponents.Action("explicitAccessibleAction", "فتح", AppIcon.Report))
                {
                    action.AccessibleName = "فتح تقرير الصيدلية";
                    action.Text = "عرض";
                    if (action.AccessibleName != "فتح تقرير الصيدلية")
                        throw new InvalidOperationException("A custom AntdUI action name must survive a caption change.");
                }
                if (ExcelDataTransferForm.ImportDestinationForSource("Medicines") !=
                        ExcelDataTransferForm.ImportDestination.Medicines ||
                    ExcelDataTransferForm.ImportDestinationForSource("SalesLines") !=
                        ExcelDataTransferForm.ImportDestination.Invoices ||
                    ExcelDataTransferForm.ImportDestinationForSource("PurchaseLines") !=
                        ExcelDataTransferForm.ImportDestination.Invoices ||
                    ExcelDataTransferForm.ImportDestinationForSource("CashBoxes") !=
                        ExcelDataTransferForm.ImportDestination.CashBoxes ||
                    ExcelDataTransferForm.ImportDestinationForSource("JournalLines") !=
                        ExcelDataTransferForm.ImportDestination.None ||
                    ExcelDataTransferForm.ImportDestinationForSource("InventoryMovements") !=
                        ExcelDataTransferForm.ImportDestination.None ||
                    ExcelDataTransferForm.ImportDestinationForSource("CashLedger") !=
                        ExcelDataTransferForm.ImportDestination.None ||
                    ExcelDataTransferForm.ImportDestinationForSource("LegacySalesLines") !=
                        ExcelDataTransferForm.ImportDestination.None)
                    throw new InvalidOperationException("Excel import routes do not match the supported data categories.");
                using (var form = new ExcelDataTransferForm())
                {
                    form.ShowInTaskbar = false;
                    form.StartPosition = FormStartPosition.Manual;
                    form.Location = new Point(-20000, -20000);
                    form.Show();
                    AntdUI.Select source = Require<AntdUI.Select>(form, "excelTransferSource");
                    AntdUI.Button import = Require<AntdUI.Button>(form, "excelTransferImport");
                    IReadOnlyList<OperationalReportSource> sources = ExcelDataExportService.GetSources();
                    for (int index = 0; index < sources.Count; index++)
                    {
                        source.SelectedIndex = index;
                        bool expected = ExcelDataTransferForm.ImportDestinationForSource(sources[index].Key) !=
                            ExcelDataTransferForm.ImportDestination.None;
                        if (import.Enabled != expected)
                            throw new InvalidOperationException("Excel import action availability is wrong for " + sources[index].Key);
                        if (Require<AntdUI.DatePicker>(form, "excelTransferFrom").Enabled != sources[index].UsesDateRange ||
                            Require<AntdUI.DatePicker>(form, "excelTransferTo").Enabled != sources[index].UsesDateRange)
                            throw new InvalidOperationException("Excel date filter availability is wrong for " + sources[index].Key);
                    }
                    form.ApplyPresentation(true);
                    source.SelectedIndex = sources.ToList().FindIndex(item => item.Key == "InventoryMovements");
                    if (!Require<Label>(form, "excelTransferStatus").Text.Contains("export-only"))
                        throw new InvalidOperationException("English Excel center does not explain unavailable import.");
                    source.SelectedIndex = sources.ToList().FindIndex(item => item.Key == "SalesLines");
                    if (!Require<Label>(form, "excelTransferStatus").Text.Contains("sales and purchases"))
                        throw new InvalidOperationException("Invoice import must explain the shared sales/purchase workflow.");
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }
        private static void VerifyExcelMinimumWindow(ExcelDataTransferForm form)
        {
            foreach (bool english in new[] { false, true })
            {
                form.ApplyPresentation(english);
                // MinimumSize is the whole native window, not the larger ClientSize used by the normal matrix.
                OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
                form.PerformLayout();
                Application.DoEvents();
                var body = Require<AntdUI.Panel>(form, "excelTransferBody");
                var fields = Require<TableLayoutPanel>(form, "excelTransferFields");
                foreach (string name in new[] { "excelTransferSource", "excelTransferSearchFrame", "excelTransferFrom", "excelTransferTo" })
                {
                    Control input = fields.Controls[name];
                    if (input == null || input.Height < 44 || !fields.ClientRectangle.Contains(input.Bounds))
                        throw new InvalidOperationException("Excel field is clipped at the real minimum window: " + name);
                }
                string message = "تُصدّر تعريفات الصناديق وإسناد الكاشير فقط دون أرصدة مالية، ويمكن استيراد الملف من شاشة صناديق النقد.";
                if (english) message = UiLanguageCatalog.Translate(message);
                typeof(ExcelDataTransferForm).GetMethod("SetStatusMessage", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    .Invoke(form, new object[] { message, null });
                Application.DoEvents();
                Label status = Require<Label>(form, "excelTransferStatus");
                int textHeight = TextRenderer.MeasureText(status.Text, status.Font,
                    new Size(status.ClientSize.Width - status.Padding.Horizontal, int.MaxValue),
                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                if (textHeight > status.Height - status.Padding.Vertical || status.AccessibleName != message)
                    throw new InvalidOperationException("Excel status message is clipped at the minimum window.");
                var scroll = (ScrollableControl)typeof(AntdUI.Panel).GetField("IPanel",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(body);
                if (scroll.HorizontalScroll.Visible || !body.AutoScroll || body.Back != UiTheme.Background)
                    throw new InvalidOperationException("Excel body must scroll vertically with the current theme.");
                var last = Require<AntdUI.DatePicker>(form, "excelTransferTo");
                scroll.ScrollControlIntoView(last);
                Application.DoEvents();
                Rectangle visible = scroll.RectangleToClient(last.RectangleToScreen(last.ClientRectangle));
                if (visible.Top < 0 || visible.Bottom > scroll.ClientSize.Height)
                    throw new InvalidOperationException("Excel final date field is not reachable by scrolling.");
                var actions = Require<FlowLayoutPanel>(form, "excelTransferActions");
                foreach (Control action in actions.Controls) RequireInside(actions, action, "Excel minimum-window action");
                if (Require<AntdUI.Button>(form, "excelTransferExport").Enabled)
                    throw new InvalidOperationException("Preview must not enable actual export.");
                if (Require<AntdUI.Button>(form, "excelTransferImport").Enabled)
                    throw new InvalidOperationException("Preview must not open an import workflow.");
            }
        }

        private static void VerifyConfiguredFonts()
        {
            string original = UiTheme.LoadFontFamily();
            try
            {
                string installed = SystemFonts.MessageBoxFont.FontFamily.Name;
                AppFonts.Initialize(installed);
                using (Font font = AppFonts.Create(10F))
                    if (!string.Equals(font.FontFamily.Name, installed, StringComparison.OrdinalIgnoreCase))
                        throw new InvalidOperationException("Installed user font was overridden by the bundled fallback.");
                AppFonts.Initialize("__Missing_Pharmacy_Font__");
                using (Font font = AppFonts.Create(10F, FontStyle.Bold))
                    if (font.Size <= 0 || string.IsNullOrWhiteSpace(font.FontFamily.Name))
                        throw new InvalidOperationException("Missing-font fallback did not produce a usable font.");
                using (Font icon = new Font("Marlett", 10F))
                    if (!AppFonts.IsIconFont(icon))
                        throw new InvalidOperationException("Icon font protection failed.");
            }
            finally { AppFonts.Initialize(original); }
        }

        private static void VerifyInventoryHomeLayout()
        {
            using (var form = new InventoryHomeForm())
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (int width in new[] { 760, 900, 1100 })
                {
                    OwnedTestWindowViewport.Resize(form, new Size(width, 720));
                    form.PerformLayout();
                    TableLayoutPanel grid = Require<TableLayoutPanel>(form, "tileGrid");
                    int availableWidth = Math.Max(0, grid.ClientSize.Width - grid.Padding.Horizontal);
                    int expectedColumns = availableWidth >= 960 ? 3 : availableWidth >= 620 ? 2 : 1;
                    if (grid.ColumnCount != expectedColumns)
                        throw new InvalidOperationException("Inventory home grid does not adapt at width " + width + ".");
                    if (grid.Controls.Count != 6)
                        throw new InvalidOperationException("Inventory home is missing its tracking tiles.");
                    if (!grid.Controls.Cast<Control>().Any(tile => tile.AccessibleName ==
                        UiLanguageCatalog.GetDisplayText("جرد التشغيلات والصلاحيات")))
                        throw new InvalidOperationException("Inventory home is missing the distinct lot stock report.");
                    AntdUI.Button firstTab = Require<AntdUI.Button>(form, "inventoryPageTab1");
                    AntdUI.Button secondTab = Require<AntdUI.Button>(form, "inventoryPageTab2");
                    if (firstTab.AccessibilityObject.Role != AccessibleRole.PageTab || secondTab.AccessibilityObject.Role != AccessibleRole.PageTab ||
                        firstTab.Height < 44 || secondTab.Height < 44 ||
                        firstTab.DefaultBorderColor != UiTheme.Primary ||
                        (UiDirection.IsLeftToRight ? firstTab.Left >= secondTab.Left : firstTab.Left <= secondTab.Left))
                        throw new InvalidOperationException("Inventory tabs lost their active style or leading-side order at width " + width + ".");
                    foreach (Control tile in grid.Controls)
                    {
                        AntdUI.Button action = tile as AntdUI.Button;
                        if (!(action is AccessibleAntdButton) || string.IsNullOrWhiteSpace(action.IconSvg) || action.BorderWidth != 1 ||
                            action.Radius != DesktopDesignTokens.CardRadius || !action.TabStop ||
                            string.IsNullOrWhiteSpace(action.AccessibleName))
                            throw new InvalidOperationException("Inventory home tile lost its accessible outlined action treatment.");
                        if (action.Left < 0 || action.Top < 0 || action.Right > grid.ClientSize.Width || action.Bottom > grid.ClientSize.Height)
                            throw new InvalidOperationException("Inventory home tile exceeds the grid at width " + width + ".");
                    }
                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "inventoryHomeFooter");
                    AntdUI.Button close = Require<AntdUI.Button>(footer, "closeButton");
                    if (footer.Bottom != form.ClientSize.Height || close.Height < 44 ||
                        close.DefaultBorderColor != UiTheme.Primary || close.Parent != footer ||
                        footer.HorizontalScroll.Visible || !footer.ClientRectangle.Contains(close.Bounds) ||
                        (UiDirection.IsLeftToRight ? close.Left > footer.ClientSize.Width / 2 : close.Right < footer.ClientSize.Width / 2))
                        throw new InvalidOperationException("Inventory home close action is not on the bottom reading edge at width " + width + ".");
                }
                OwnedTestWindowViewport.Resize(form, new Size(1600, 900));
                form.PerformLayout();
                TableLayoutPanel wideGrid = Require<TableLayoutPanel>(form, "tileGrid");
                if (wideGrid.ColumnCount != 3 || wideGrid.Padding.Left <= 28 || wideGrid.Padding.Top <= 24 ||
                    wideGrid.Controls.Cast<Control>().Any(tile => tile.Width > 430 || tile.Height > 220 || tile.Height < 44))
                    throw new InvalidOperationException("Inventory tiles become oversized or unreadable on a wide display.");
                var click = typeof(Control).GetMethod("OnClick", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (click == null) throw new InvalidOperationException("Inventory tab click cannot be verified.");
                AntdUI.Button trackingTab = Require<AntdUI.Button>(form, "inventoryPageTab1");
                AntdUI.Button operationTab = Require<AntdUI.Button>(form, "inventoryPageTab2");
                Control previousTile = Require<TableLayoutPanel>(form, "tileGrid").Controls[0];
                operationTab.AccessibilityObject.DoDefaultAction();
                if (!previousTile.IsDisposed)
                    throw new InvalidOperationException("Inventory home retains old tile icons after switching tabs.");
                if (!ReferenceEquals(trackingTab, Require<AntdUI.Button>(form, "inventoryPageTab1")) ||
                    !ReferenceEquals(operationTab, Require<AntdUI.Button>(form, "inventoryPageTab2")) ||
                    operationTab.DefaultBorderColor != UiTheme.Primary ||
                    trackingTab.DefaultBorderColor != UiTheme.Border ||
                    !operationTab.AccessibleDescription.StartsWith("التبويب الحالي.", StringComparison.Ordinal))
                    throw new InvalidOperationException("Inventory tabs were recreated or did not update their selected state.");
                if (Require<TableLayoutPanel>(form, "tileGrid").Controls.Count != 4)
                    throw new InvalidOperationException("Inventory operation tab did not show its four actions.");
                Control operationTile = Require<TableLayoutPanel>(form, "tileGrid").Controls[0];
                operationTab.AccessibilityObject.DoDefaultAction();
                if (!ReferenceEquals(operationTile, Require<TableLayoutPanel>(form, "tileGrid").Controls[0]))
                    throw new InvalidOperationException("Clicking the active inventory tab rebuilt its tiles.");
                trackingTab.AccessibilityObject.DoDefaultAction();
                if (Require<TableLayoutPanel>(form, "tileGrid").Controls.Count != 6)
                    throw new InvalidOperationException("Inventory tracking tab did not restore its six actions.");
                OwnedTestWindowViewport.Resize(form, new Size(760, 560));
                form.PerformLayout();
                TableLayoutPanel compactGrid = Require<TableLayoutPanel>(form, "tileGrid");
                foreach (Control tile in compactGrid.Controls)
                {
                    AntdUI.Button action = tile as AntdUI.Button;
                    if (action == null || action.Height < 44 || action.Right > compactGrid.ClientSize.Width ||
                        action.Bottom > compactGrid.ClientSize.Height ||
                        action.IconPosition != (UiDirection.IsLeftToRight ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right))
                        throw new InvalidOperationException("Inventory tracking action clips or loses its compact icon at 760×560.");
                }
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox ||
                    form.MinimumSize.Width > 760 || form.MinimumSize.Height > 600)
                    throw new InvalidOperationException("Inventory home must support standard resize, maximize, and minimize.");
            }
        }

        private static DataTable ChartSessionRows()
        {
            var rows=new DataTable();
            rows.Columns.Add("AccountCode",typeof(string));rows.Columns.Add("AccountName",typeof(string));
            rows.Columns.Add("AccountType",typeof(string));rows.Columns.Add("ParentAccountCode",typeof(string));rows.Columns.Add("IsActive",typeof(bool));
            rows.Rows.Add("00100","النقد Cash 500 mg","Asset",DBNull.Value,true);
            rows.Rows.Add("00101","صندوق فرعي","Asset","00100",true);return rows;
        }
        private static void VerifyChartSessionContext()
        {
            string user=SessionContext.CurrentUser,role=SessionContext.CurrentRole,employee=SessionContext.CurrentEmployeeId,mode=Properties.Setings.Default.ThemeMode;
            bool authenticated=SessionContext.IsAuthenticated;
            var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})foreach(bool english in new[]{false,true})
                {
                    Properties.Setings.Default.ThemeMode=theme;using(var palette=new Form())UiTheme.Apply(palette);
                    SessionContext.Start("chart-session-test","Manager","CHART-E");
                    Func<Func<bool>> capture=()=>{long revision=SessionContext.CurrentSessionRevision;return ()=>SessionContext.IsAuthenticated&&SessionContext.CurrentSessionRevision==revision;};
                    using(var form=new ChartOfAccountsForm(true,english,capture))
                    {
                        IntPtr handle=form.Handle;
                        CompleteUiTask(form.RefreshChartAsync(()=>System.Threading.Tasks.Task.FromResult(ChartSessionRows())));
                        var tree=Require<TreeView>(form,"accountsTree");var code=Require<AntdUI.Input>(form,"chartAccountCode");var name=Require<TextBox>(form, "chartAccountName");
                        TreeNode retained=tree.Nodes[0];
                        typeof(ChartOfAccountsForm).GetMethod("SelectAccountFromNode",flags).Invoke(form,new object[]{retained});
                        if(code.Text!="00100"||name.Text!="النقد Cash 500 mg")throw new InvalidOperationException("Chart current raw Arabic/leading-zero selection failed.");
                        SessionContext.Clear();SessionContext.Start("chart-session-test","Manager","CHART-E");
                        if(tree.GetNodeCount(true)!=0||code.Text.Length!=0||name.Text.Length!=0)
                            throw new InvalidOperationException("Inactive chart retained tree/editor before any selection after relogin.");
                        typeof(ChartOfAccountsForm).GetMethod("SelectAccountFromNode",flags).Invoke(form,new object[]{retained});
                        if(tree.GetNodeCount(true)!=0||code.Text.Length!=0||name.Text.Length!=0||Require<ComboBox>(form, "chartParentAccount").Items.Count!=0)
                            throw new InvalidOperationException("Chart retained tree/editor accepted a previous login of the same user.");
                        if(!Require<AntdUI.Button>(form,"chartRefreshAccount").Enabled||Require<AntdUI.Panel>(form,"chartOfAccountsEditorCard").Enabled)
                            throw new InvalidOperationException("Chart stale-context recovery actions are invalid.");
                        CompleteUiTask(form.RefreshChartAsync(()=>System.Threading.Tasks.Task.FromResult(ChartSessionRows())));
                        if(code.Text.Length!=0||name.Text.Length!=0||tree.GetNodeCount(true)!=2)throw new InvalidOperationException("Chart fresh reload restored an old editor or lost records.");
                        tree.SelectedNode=tree.Nodes[0];name.Text="مسودة Cash 500 mg";
                        CompleteUiTask(form.RefreshChartAsync(()=>{throw new InvalidOperationException("same context read failure");}));
                        if(tree.GetNodeCount(true)!=2||name.Text!="مسودة Cash 500 mg")throw new InvalidOperationException("Chart valid failed read lost its tree/editor.");
                        System.Threading.CancellationToken oldToken=default(System.Threading.CancellationToken);
                        var delayed=new System.Threading.Tasks.TaskCompletionSource<DataTable>();
                        var oldRead=form.RefreshChartAsync(null,token=>{oldToken=token;return delayed.Task;});
                        if(oldRead.IsCompleted||!oldToken.CanBeCanceled)throw new InvalidOperationException("Chart asynchronous read did not receive cancellation.");
                        CompleteUiTask(form.RefreshChartAsync(()=>System.Threading.Tasks.Task.FromResult(ChartSessionRows())));
                        var oldRows=ChartSessionRows();oldRows.Rows[0]["AccountName"]="OLD";bool disposed=false;oldRows.Disposed+=(sender,args)=>disposed=true;
                        delayed.SetResult(oldRows);CompleteUiTask(oldRead);
                        if(!oldToken.IsCancellationRequested||oldRead.Result||!disposed||tree.Nodes[0].Text.Contains("OLD"))throw new InvalidOperationException("Chart cancelled prior response was applied or retained.");
                        var relogin=new System.Threading.Tasks.TaskCompletionSource<DataTable>();var reloginRead=form.RefreshChartAsync(()=>relogin.Task);
                        SessionContext.Start("chart-session-test","Manager","CHART-E");
                        relogin.SetResult(ChartSessionRows());CompleteUiTask(reloginRead);
                        if(reloginRead.Result||tree.GetNodeCount(true)!=0||code.Text.Length!=0||name.Text.Length!=0)throw new InvalidOperationException("Chart pending previous-login result was accepted.");
                        CompleteUiTask(form.RefreshChartAsync(()=>System.Threading.Tasks.Task.FromResult(ChartSessionRows())));
                        SessionContext.Start("chart-session-test","Manager","CHART-E");
                        typeof(ChartOfAccountsForm).GetMethod("SaveAccount",flags).Invoke(form,null);
                        if(tree.GetNodeCount(true)!=0||code.Text.Length!=0)throw new InvalidOperationException("Chart save action failed to invalidate stale preview context.");
                        CompleteUiTask(form.RefreshChartAsync(()=>System.Threading.Tasks.Task.FromResult(ChartSessionRows())));
                        foreach(Size size in new[]{new Size(760,560),new Size(960,640),new Size(1024,768),new Size(1366,768)})
                        {
                            if(!form.Visible){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();}
                            OwnedTestWindowViewport.Resize(form,size);form.ApplyResponsiveLayout();
                            var footer=Require<FlowLayoutPanel>(form,"chartFooterActions");
                            if(footer.Controls.Cast<Control>().Any(c=>c.Left<0||c.Right>footer.ClientSize.Width||c.Bottom>footer.ClientSize.Height))throw new InvalidOperationException("Chart recovery footer is clipped at "+size);
                        }
                        var closePending=new System.Threading.Tasks.TaskCompletionSource<DataTable>();System.Threading.CancellationToken closeToken=default(System.Threading.CancellationToken);
                        var closing=form.RefreshChartAsync(null,token=>{closeToken=token;return closePending.Task;});
                        form.Dispose();closePending.SetResult(ChartSessionRows());CompleteUiTask(closing);
                        if(!closeToken.IsCancellationRequested||closing.Result)throw new InvalidOperationException("Chart dispose did not cancel/reject the pending read.");
                    }
                }
                Console.WriteLine("PASS chart: both themes/directions, retained same-user revision/editor rejection, raw Arabic/leading zeros, fresh recovery, valid failed-read retention, cancelled prior response disposal, relogin pending result rejection, four footer sizes and close cancellation; no SQL/native input.");
            }
            finally{if(authenticated)SessionContext.Start(user,role,employee);else SessionContext.Clear();Properties.Setings.Default.ThemeMode=mode;using(var palette=new Form())UiTheme.Apply(palette);}
        }

        private static void VerifyChartRefreshAndAcceptedPresentation()
        {
            string mode=Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})
                {
                    Properties.Setings.Default.ThemeMode=theme;using(var palette=new Form())UiTheme.Apply(palette);
                    foreach(bool english in new[]{false,true})
                    using(var form=new ChartOfAccountsForm(true,english))
                    {
                        form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();
                        var tree=Require<TreeView>(form,"accountsTree");
                        var status=Require<Label>(form,"chartOfAccountsStatus");
                        var rows=new DataTable();rows.Columns.Add("AccountCode",typeof(string));rows.Columns.Add("AccountName",typeof(string));rows.Columns.Add("AccountType",typeof(string));rows.Columns.Add("ParentAccountCode",typeof(string));rows.Columns.Add("IsActive",typeof(bool));
                        rows.Rows.Add("A","الأصول Cash 500 mg","Asset",DBNull.Value,true);rows.Rows.Add("B","فرعي","Asset","A",true);
                        rows.Rows.Add("C","حلقة1","Asset","D",true);rows.Rows.Add("D","حلقة2","Asset","C",true);rows.Rows.Add("E","يتيم","Asset","missing",true);
                        CompleteUiTask(form.RefreshChartAsync(()=>System.Threading.Tasks.Task.FromResult(rows)));
                        if(tree.GetNodeCount(true)!=5||tree.Nodes.Count!=4||!status.AccessibleDescription.Contains(english?"Invalid":"غير سليمة"))throw new InvalidOperationException("Chart cycle/orphan fallback hid accounts or failed to report invalid links.");
                        int nodeCount=tree.GetNodeCount(true);
                        CompleteUiTask(form.RefreshChartAsync(()=>{throw new InvalidOperationException("read failure");}));
                        if(tree.GetNodeCount(true)!=nodeCount||!status.AccessibleDescription.Contains(english?"previous":"السابق"))throw new InvalidOperationException("Chart failed read lost its previous view.");
                        var pending=new System.Threading.Tasks.TaskCompletionSource<DataTable>();var older=form.RefreshChartAsync(()=>pending.Task);
                        var fresh=rows.Copy();fresh.Rows.Add("F","صندوق جديد","Asset",DBNull.Value,true);
                        CompleteUiTask(form.RefreshChartAsync(()=>System.Threading.Tasks.Task.FromResult(fresh)));
                        pending.SetResult(rows.Copy());CompleteUiTask(older);
                        if(tree.GetNodeCount(true)!=6)throw new InvalidOperationException("Old chart refresh replaced a newer result.");
                        var key=typeof(ChartOfAccountsForm).GetField("acceptedAccountCode",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
                        bool captured=false;int reads=0;
                        CompleteUiTask(form.CompleteSavedAccountPresentationAsync(new AccountWriteResult("A",true),false,()=>{reads++;return System.Threading.Tasks.Task.FromResult(fresh.Copy());},()=>{captured=(string)key.GetValue(form)=="A";throw new InvalidOperationException("editor clear failure");}));
                        if(!captured||reads!=0||tree.GetNodeCount(true)!=6||!status.AccessibleDescription.Contains(english?"Do not repeat":"لا تعد تنفيذ"))throw new InvalidOperationException("Accepted chart operation became a posting failure after cleanup failed.");
                        CompleteUiTask(form.CompleteSavedAccountPresentationAsync(new AccountWriteResult("A",true),true,()=>{throw new InvalidOperationException("after delete read");}));
                        if((string)key.GetValue(form)!="A"||!status.AccessibleDescription.Contains(english?"deleted":"حذف")||tree.GetNodeCount(true)!=6)throw new InvalidOperationException("Accepted deletion lost its identity after read failure.");
                        CompleteUiTask(form.CompleteSavedAccountPresentationAsync(new AccountWriteResult("absent",false),true,()=>System.Threading.Tasks.Task.FromResult(fresh.Copy())));
                        if(!status.AccessibleDescription.Contains(english?"does not exist":"غير موجود"))throw new InvalidOperationException("Missing account was reported as a fresh deletion.");
                        var save=Require<AntdUI.Button>(form,"chartSaveAccount");var delete=Require<AntdUI.Button>(form,"chartDeleteAccount");var refresh=Require<AntdUI.Button>(form,"chartRefreshAccount");
                        if(save.Enabled||delete.Enabled||!refresh.Enabled||refresh.IconSvg==null)throw new InvalidOperationException("Chart preview write guard or semantic refresh action failed.");
                        foreach(Size size in new[]{new Size(760,560),new Size(960,640),new Size(1366,768)})
                        {OwnedTestWindowViewport.Resize(form, size);form.ApplyResponsiveLayout();var footer=Require<FlowLayoutPanel>(form,"chartFooterActions");foreach(Control action in footer.Controls)if(action.Left<0||action.Top<0||action.Right>footer.ClientSize.Width||action.Bottom>footer.ClientSize.Height)throw new InvalidOperationException("Chart footer action is clipped at "+size);}
                        CompleteUiTask(form.CompleteSavedAccountPresentationAsync(new AccountWriteResult("12345678901234567890",true),false,()=>{throw new InvalidOperationException("status wrap fixture");}));
                        status.Text+=english?" Support code: 20261001-230501-A1B2C3D4":" رمز الدعم: 20261001-230501-A1B2C3D4";
                        foreach(Size size in new[]{new Size(980,640),new Size(980,900),new Size(1024,640),new Size(1366,768)})
                        {
                            OwnedTestWindowViewport.Resize(form, size);form.ApplyResponsiveLayout();Application.DoEvents();
                            int needed=TextRenderer.MeasureText(status.Text,status.Font,new Size(status.ClientSize.Width,int.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height;
                            if(needed>status.ClientSize.Height||status.TextAlign!=(english?ContentAlignment.MiddleLeft:ContentAlignment.MiddleRight))throw new InvalidOperationException("Accepted chart status is clipped or misaligned at "+size);
                        }
                        var late=new System.Threading.Tasks.TaskCompletionSource<DataTable>();var closing=form.RefreshChartAsync(()=>late.Task);form.Dispose();late.SetResult(fresh.Copy());CompleteUiTask(closing);
                    }
                }
            }
            finally{Properties.Setings.Default.ThemeMode=mode;using(var palette=new Form())UiTheme.Apply(palette);}
        }


        private static void VerifyChartOfAccountsLayout()
        {
            VerifyChartSharedSurfaces();
            using (var form = new ChartOfAccountsForm(true))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1280, 760) })
                {
                    Prepare(form, size);
                    form.ApplyResponsiveLayout();
                    Panel treeHost = Require<Panel>(form, "chartOfAccountsTreeHost");
                    Panel editorHost = Require<Panel>(form, "chartOfAccountsEditorHost");
                    AntdUI.Panel editorCard = Require<AntdUI.Panel>(form, "chartOfAccountsEditorCard");
                    Panel contentHost = Require<Panel>(form, "chartOfAccountsContentHost");
                    TreeView tree = Require<TreeView>(form, "accountsTree");
                    Panel toolbar = Require<Panel>(form, "chartOfAccountsToolbar");
                    FlowLayoutPanel treeTools = Require<FlowLayoutPanel>(form, "chartOfAccountsTreeTools");
                    FlowLayoutPanel typeOptions = Require<FlowLayoutPanel>(form, "chartAccountTypeOptions");
                    AntdUI.Input accountCode = Require<AntdUI.Input>(form, "chartAccountCode");
                    TextBox accountName = Require<TextBox>(form, "chartAccountName");
                    ComboBox parentAccount = Require<ComboBox>(form, "chartParentAccount");
                    AntdUI.Select accountNature = Require<AntdUI.Select>(form, "chartAccountNature");
                    AntdUI.Button saveButton = Require<AntdUI.Button>(form, "chartSaveAccount");
                    bool compact = size.Width < 980;
                    if (form.AutoScroll || contentHost.BackColor != UiTheme.Background ||
                        editorCard.Back != UiTheme.Surface ||
                        Require<Label>(form, "chartOfAccountsStatus").BackColor != UiTheme.Background ||
                        toolbar.BackColor != UiTheme.Background || treeTools.BackColor != UiTheme.Surface ||
                        treeHost.Width < (compact ? 700 : 440) || editorHost.Width < (compact ? 700 : 260) ||
                        treeHost.Height < (compact ? 210 : 400) || !tree.RightToLeftLayout || toolbar.Height < 60 ||
                        treeHost.Bounds.IntersectsWith(editorHost.Bounds) ||
                        contentHost.Bounds.IntersectsWith(toolbar.Bounds) || contentHost.Bottom > toolbar.Top ||
                        !toolbar.Visible || !new Rectangle(Point.Empty, form.ClientSize).Contains(toolbar.Bounds))
                        throw new InvalidOperationException("Chart of accounts layout is invalid at " + size + ".");
                    if (treeTools.Controls.OfType<AntdUI.Button>().Count() != 4 ||
                        treeTools.Controls.OfType<AntdUI.Button>().Any(button => button.Height < 44 ||
                            button.BorderWidth != 1 || button.DefaultBorderColor != UiTheme.Primary))
                        throw new InvalidOperationException("Chart tree actions are not consistent AntdUI outline controls at " + size + ".");
                    foreach (AntdUI.Button action in toolbar.Controls.OfType<FlowLayoutPanel>().SelectMany(group => group.Controls.OfType<AntdUI.Button>()))
                        if (action.BorderWidth != 1 || action.DefaultBorderColor != UiTheme.Primary || action.Height < 44)
                            throw new InvalidOperationException("Chart footer action lost its green outline: " + action.Name + ".");
                    if (compact && (!contentHost.AutoScroll || editorHost.Top < treeHost.Bottom ||
                        Require<AntdUI.Panel>(form, "chartOfAccountsEditorCard").Height < 290))
                        throw new InvalidOperationException("Compact chart of accounts must scroll through complete tree and editor sections.");
                    if (typeOptions.Controls.Cast<Control>().Any(control => !control.Visible || control.Bottom > typeOptions.ClientSize.Height))
                        throw new InvalidOperationException("Chart of accounts type options are clipped at " + size + ".");
                    if (accountCode.RightToLeft != RightToLeft.No || accountName.RightToLeft != RightToLeft.Yes ||
                        parentAccount.RightToLeft != RightToLeft.Yes || accountNature.RightToLeft != RightToLeft.Yes ||
                        accountCode.Height < 26 || accountName.Height < accountName.Font.Height || tree.GetNodeCount(true) < 4 ||
                        string.IsNullOrWhiteSpace(saveButton.AccessibleName) || saveButton.AccessibleName != saveButton.Text)
                        throw new InvalidOperationException("Chart of accounts semantic check failed at " + size +
                            ": codeRTL=" + accountCode.RightToLeft + ", nameRTL=" + accountName.RightToLeft +
                            ", parentRTL=" + parentAccount.RightToLeft + ", natureRTL=" + accountNature.RightToLeft +
                            ", codeHeight=" + accountCode.Height + ", nameHeight=" + accountName.Height +
                            ", treeNodes=" + tree.GetNodeCount(true) + ", saveNameMatchesText=" +
                            (saveButton.AccessibleName == saveButton.Text) + ", saveNameLength=" +
                            (saveButton.AccessibleName ?? string.Empty).Length + ".");
                }
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox)
                    throw new InvalidOperationException("Chart of accounts must support resize, maximize, and minimize.");
            }
        }
        private static void VerifyChartSharedSurfaces()
        {
            string original = Properties.Setings.Default.ThemeMode;
            ChartMixedTextSelfTests.Verify();
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var palette = new Form()) UiTheme.Apply(palette);
                    foreach (bool english in new[] { false, true })
                    using (var form = new ChartOfAccountsForm(true, english))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show();
                        OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
                        var code = Require<AntdUI.Input>(form, "chartAccountCode");
                        var name = Require<TextBox>(form, "chartAccountName");
                        var nature = Require<AntdUI.Select>(form, "chartAccountNature");
                        var parent = Require<ComboBox>(form, "chartParentAccount");
                        code.Text = "105001"; name.Text = "صندوق النقد 500 mg"; nature.SelectedIndex = 2;
                        foreach (Size size in new[] { form.ClientSize, new Size(760, 560), new Size(960, 640), new Size(1024, 650), new Size(1366, 768) })
                        {
                            Prepare(form, size); form.ApplyResponsiveLayout();
                            foreach (string cardName in new[] { "chartOfAccountsTreeCard", "chartOfAccountsEditorCard" })
                            {
                                var card = Require<AntdUI.Panel>(form, cardName);
                                if (card.Radius != 12 || card.Shadow != 0 || card.Back != UiTheme.Surface)
                                    throw new InvalidOperationException("Chart card lost shared AntdUI style: " + cardName);
                            }
                            foreach (Control input in new Control[] { code, name.Parent, parent.Parent.Parent, nature })
                                if (input.Height != 44 || !input.Parent.ClientRectangle.Contains(input.Bounds))
                                    throw new InvalidOperationException("Chart editor is clipped or has inconsistent height: " + input.Name + " " + size);
                            var actions = Require<FlowLayoutPanel>(form, "chartFooterActions");
                            foreach (Control action in actions.Controls)
                                if (!actions.ClientRectangle.Contains(action.Bounds))
                                    throw new InvalidOperationException("Chart footer clipped an action: " + action.Name + " " + size);
                            if (Require<AntdUI.Button>(form, "chartExit").Text != (english ? "Close" : "خروج") ||
                                Require<AntdUI.Button>(form, "chartDeleteAccount").Text != (english ? "Delete" : "حذف") ||
                                (english ? code.Parent.Left >= name.Parent.Parent.Left : code.Parent.Left <= name.Parent.Parent.Left))
                                throw new InvalidOperationException("Chart action language or field reading order changed.");
                            foreach (string heading in new[] { "chartHeaderTitle", "chartHeaderHint" })
                            {
                                var label = Require<Label>(form, heading);
                                if (label.AccessibleName != label.Text || label.Height < TextRenderer.MeasureText(label.Text, label.Font,
                                    new Size(label.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height)
                                    throw new InvalidOperationException("Chart heading is clipped: " + heading);
                            }
                            if (code.Text != "105001" || name.Text != "صندوق النقد 500 mg" || nature.SelectedIndex != 2 ||
                                form.RightToLeftLayout == english || Require<TreeView>(form, "accountsTree").RightToLeftLayout == english ||
                                actions.FlowDirection != (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft))
                                throw new InvalidOperationException("Chart layout changed data or language direction.");
                        }
                        var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                        foreach (string stored in new[] { "Asset", "Liability", "Equity", "Revenue", "Expense" })
                        {
                            string display = (string)typeof(ChartOfAccountsForm).GetMethod("ToDisplayType", flags).Invoke(form, new object[] { stored });
                            string restored = (string)typeof(ChartOfAccountsForm).GetMethod("ToStoredType", flags).Invoke(form, new object[] { display });
                            if (restored != stored) throw new InvalidOperationException("Chart localization changed stored account type: " + stored);
                        }
                        if (parent.SelectedIndex != 0 || (string)typeof(ChartOfAccountsForm).GetMethod("SelectedParentCode", flags).Invoke(form, null) != string.Empty ||
                            Require<AntdUI.Button>(form, "chartSaveAccount").Enabled || Require<AntdUI.Button>(form, "chartDeleteAccount").Enabled)
                            throw new InvalidOperationException("Chart preview lost its no-parent sentinel or write protection.");
                        typeof(ChartOfAccountsForm).GetMethod("SaveAccount", flags).Invoke(form, null);
                        typeof(ChartOfAccountsForm).GetMethod("DeleteAccount", flags).Invoke(form, null);
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; using (var palette = new Form()) UiTheme.Apply(palette); }
        }

