                    ComboBox costCenter = Require<ComboBox>(form, "journalCostCenter");
                    TextBox entryNumber = Require<TextBox>(form, "journalEntryNumber");
                    AntdUI.DatePicker entryDate = Require<AntdUI.DatePicker>(form, "journalEntryDate");
                    AntdUI.Input debit = Require<AntdUI.Input>(form, "journalDebit");
                    AntdUI.Input credit = Require<AntdUI.Input>(form, "journalCredit");
                    AntdUI.Input exchangeRate = Require<AntdUI.Input>(form, "journalExchangeRate");
                    AntdUI.Input lineDate = Require<AntdUI.Input>(form, "journalLineDate");
                    TextBox headerDescription = Require<TextBox>(form, "journalHeaderDescription");
                    AntdUI.Button addLine = Require<AntdUI.Button>(form, "postJournalLine");
                    foreach (Control editor in new Control[] { account.Parent, currency, branch.Parent.Parent, status.Parent, costCenter.Parent.Parent, entryNumber.Parent, entryDate, debit, credit, exchangeRate, lineDate, headerDescription.Parent })
                    {
                        if (editor.Height < DesktopDesignTokens.InputHeight)
                            throw new InvalidOperationException("Journal editor below shared input height: " + editor.Name + "=" + editor.Height + " at " + size);
                    }                    FlowLayoutPanel primary = Require<FlowLayoutPanel>(form, "journalPrimaryActions");
                    FlowLayoutPanel secondary = Require<FlowLayoutPanel>(form, "journalSecondaryActions");
                    RequireHorizontallyInside(form, header, "journal header " + size);
                    RequireHorizontallyInside(form, lineFields, "journal line fields " + size);
                    RequireHorizontallyInside(form, toolbar, "journal toolbar " + size);
                    RequireHorizontallyInside(form, grid, "journal lines " + size);
                    bool compactJournal = size.Width < 1120;
                    if (titleBar.Top != 0 || screenTitle.Text != form.Text || toolbar.Dock != DockStyle.Bottom ||
                        toolbar.Bottom != form.ClientSize.Height || toolbar.BackColor != UiTheme.Surface ||
                        footerInfo.BackColor != UiTheme.Surface || totals.ForeColor != UiTheme.Text ||
                        header.Height < (compactJournal ? 120 : 130) || lineFields.Height < (compactJournal ? 210 : 160) ||
                        (compactJournal && grid.Height < 80) || toolbar.Height < 60 || !grid.ReadOnly ||
                        account.RightToLeft != RightToLeft.Yes ||
                        branch.RightToLeft != RightToLeft.Yes || status.RightToLeft != RightToLeft.Yes || !status.ReadOnly || status.Text != "يُعتمد عند الحفظ" || costCenter.RightToLeft != RightToLeft.Yes ||
                        account.Items.Count != 2 || currency.Items.Count != 2 || account.SelectedIndex < 0 || currency.SelectedIndex < 0 ||
                        entryDate.Height < DesktopDesignTokens.InputHeight || entryDate.RightToLeft != RightToLeft.No ||
                        entryDate.AccessibleName != "تاريخ القيد" || !entryDate.Value.HasValue ||
                        entryNumber.RightToLeft != RightToLeft.Yes || entryNumber.Text != "تلقائي عند الحفظ" ||
                        debit.RightToLeft != RightToLeft.No || credit.RightToLeft != RightToLeft.No ||
                        exchangeRate.RightToLeft != RightToLeft.No || lineDate.RightToLeft != RightToLeft.No ||
                        currency.RightToLeft != RightToLeft.No ||
                        headerDescription.RightToLeft != RightToLeft.Yes ||
                        addLine.AccessibleName != "تنزيل سطر القيد" ||
                        grid.Rows.Count != 2 || form.MinimumSize.Width > 760 || form.MinimumSize.Height > 600)
                        throw new InvalidOperationException("Journal entries check failed at " + size +
                            ": headerHeight=" + header.Height + ", lineFieldsHeight=" + lineFields.Height +
                            ", gridHeight=" + grid.Height + ", toolbarHeight=" + toolbar.Height +
                            ", gridReadOnly=" + grid.ReadOnly + ", accountRTL=" + account.RightToLeft +
                            ", currencyRTL=" + currency.RightToLeft + ", branchRTL=" + branch.RightToLeft +
                            ", statusRTL=" + status.RightToLeft + ", costCenterRTL=" + costCenter.RightToLeft +
                            ", accountItems=" + account.Items.Count + ", currencyItems=" + currency.Items.Count +
                            ", accountSelected=" + account.SelectedIndex + ", currencySelected=" + currency.SelectedIndex +
                            ", debitRTL=" + debit.RightToLeft + ", creditRTL=" + credit.RightToLeft +
                            ", exchangeRTL=" + exchangeRate.RightToLeft + ", lineDateRTL=" + lineDate.RightToLeft +
                            ", descriptionRTL=" + headerDescription.RightToLeft + ", addNameMatchesText=" +
                            (addLine.AccessibleName == addLine.Text) + ", addName='" + addLine.AccessibleName + "', addText='" + addLine.Text + "', rows=" + grid.Rows.Count +
                            ", min=" + form.MinimumSize + ".");
                    foreach (AntdUI.Button action in primary.Controls.OfType<AntdUI.Button>())
                    {
                        RequireInside(primary, action, "journal primary action " + size);
                        if (action.Width < 44 || action.Height < 44 || action.BorderWidth != 1 ||
                            action.DefaultBorderColor != UiTheme.Primary)
                            throw new InvalidOperationException("Journal primary action lost the green 44px outline at " + size + ".");
                    }
                    foreach (AntdUI.Button action in secondary.Controls.OfType<AntdUI.Button>().Where(button => button.Visible))
                    {
                        RequireInside(secondary, action, "journal secondary action " + size);
                        if (action.Width < 44 || action.Height < 44 || action.BorderWidth != 1 ||
                            action.DefaultBorderColor != UiTheme.Primary)
                            throw new InvalidOperationException("Journal secondary action lost the green 44px outline at " + size + ".");
                    }
                    decimal previewDebit = 0m;
                    decimal previewCredit = 0m;
                    foreach (DataGridViewRow row in grid.Rows)
                    {
                        previewDebit += Convert.ToDecimal(row.Cells["مدين محلي"].Value);
                        previewCredit += Convert.ToDecimal(row.Cells["دائن محلي"].Value);
                    }
                    if (previewDebit != previewCredit)
                        throw new InvalidOperationException("The in-memory journal preview must remain balanced at " + size + ".");
                    if (size.Width < 1120 &&
                        (secondary.Controls.OfType<AntdUI.Button>().Any(button => button.Visible &&
                            (button.AccessibleName == "السطر الأول" || button.AccessibleName == "السطر الأخير" || button.AccessibleName == "بدء قيد جديد")) ||
                         !secondary.Controls.OfType<AntdUI.Button>().Any(button => button.Visible && button.AccessibleName == "السطر السابق") ||
                         !secondary.Controls.OfType<AntdUI.Button>().Any(button => button.Visible && button.AccessibleName == "السطر التالي")))
                        throw new InvalidOperationException("Compact journal toolbar must preserve visible adjacent navigation and avoid duplicate actions.");
                }
                AntdUI.DatePicker journalDate = Require<AntdUI.DatePicker>(form, "journalEntryDate");
                Label journalStatus = Require<Label>(form, "journalStatus");
                var readDate = typeof(JournalEntriesForm).GetMethod("TryGetJournalDate",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (readDate == null) throw new InvalidOperationException("Journal date validation is unavailable.");
                journalDate.Value = null;
                object[] missingDate = { DateTime.MinValue };
                if ((bool)readDate.Invoke(form, missingDate) || !journalStatus.Text.Contains("اختر تاريخ"))
                    throw new InvalidOperationException("Journal accepted an empty accounting date.");
                journalDate.Value = new DateTime(2026, 9, 24);
                object[] selectedDate = { DateTime.MinValue };
                if (!(bool)readDate.Invoke(form, selectedDate) ||
                    (DateTime)selectedDate[0] != new DateTime(2026, 9, 24))
                    throw new InvalidOperationException("Journal changed the selected accounting date.");
                var savePreview = typeof(JournalEntriesForm).GetMethod("SaveEntryAsync",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (savePreview == null || ((System.Threading.Tasks.Task<int>)savePreview.Invoke(form, new object[] { false })).GetAwaiter().GetResult() != 0 ||
                    !journalStatus.Text.Contains("المعاينة للعرض فقط"))
                    throw new InvalidOperationException("Journal preview allowed a persistent accounting entry.");
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox)
                    throw new InvalidOperationException("Journal entries must support resize, maximize, and minimize.");
            }
        }
        private static void VerifyJournalEditorViewport()
        {
            string oldMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (string kind in new[] { "Manual", "OpeningEntry" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var form = new JournalEntriesForm("معاينة تأقلم القيد", kind, true))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show(); Application.DoEvents();
                        var viewport = Require<PhysicalScrollViewport>(form, "journalEditorViewport");
                        var grid = Require<DataGridView>(form, "journalLinesGrid");
                        var add = Require<AntdUI.Button>(form, "postJournalLine");
                        foreach (bool leftToRight in new[] { false, true })
                        foreach (Size size in new[] { new Size(760,600),new Size(960,640),new Size(1366,768),new Size(1920,1080) })
                        {
                            UiDirection.Apply(form, leftToRight); Prepare(form, size);
                            form.ApplyResponsiveLayout(); Application.DoEvents();
                            if (viewport.RightToLeft != RightToLeft.No || viewport.HorizontalScroll.Visible || grid.Height < 128 ||
                                add.Height < DesktopDesignTokens.ActionHeight || add.Width > 180)
                                throw new InvalidOperationException("Journal viewport/action size invalid at " + size + "; grid=" + grid.Height + "; scroll=" + viewport.HorizontalScroll.Visible + "; action=" + add.Size);
                            foreach (string name in new[] { "journalBranchFrame", "journalEntryNumberFrame", "journalEntryDate", "journalEntryStatusFrame", "journalHeaderDescriptionFrame",
                                "journalAccountFrame", "journalReferenceNumber", "journalCostCenterFrame", "journalDebit", "journalCredit", "journalExchangeRate", "journalCurrency", "journalLocalValue", "journalLineDate", "journalLineDescriptionFrame" })
                            {
                                Control editor = Require<Control>(form, name);
                                if (editor.Height < DesktopDesignTokens.InputHeight) throw new InvalidOperationException("Journal field height lost at " + size + ": " + name);
                                RequireInside(editor.Parent, editor, "journal 44px editor " + name);
                                var caption = editor.Parent.Controls.OfType<Label>().Single();
                                if (caption.Bottom > editor.Top) throw new InvalidOperationException("Journal caption overlaps editor " + name);
                                viewport.ScrollControlIntoView(editor.Parent); Application.DoEvents();
                                var visible = new Rectangle(viewport.PointToClient(editor.PointToScreen(Point.Empty)), editor.Size);
                                if (!viewport.ClientRectangle.Contains(visible))
                                    throw new InvalidOperationException("Journal field cannot scroll into view " + name + " at " + size + "; visible=" + visible + "; viewport=" + viewport.ClientRectangle);
                            }
                            viewport.ScrollControlIntoView(add); Application.DoEvents();
                            var actionBounds = new Rectangle(viewport.PointToClient(add.PointToScreen(Point.Empty)), add.Size);
                            if (!viewport.ClientRectangle.Contains(actionBounds)) throw new InvalidOperationException("Journal add action cannot scroll into view.");
                            Console.WriteLine("PASS journal viewport; Theme=" + mode + "; Kind=" + kind + "; LTR=" + leftToRight + "; Requested=" + size + "; ActualClient=" + form.ClientSize + "; Grid=" + grid.Height);
                            var summary = Require<Label>(form, "journalTotals");
                            var operationStatus = Require<Label>(form, "journalStatus");
                            foreach (Label label in new[] { summary, operationStatus })
                            {
                                RequireInside(label.Parent, label, "journal footer text " + size);
                                int needed = TextRenderer.MeasureText(label.Text, label.Font, new Size(Math.Max(1, label.Width - label.Padding.Horizontal), int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                                if (needed > label.Height || label.TextAlign != (leftToRight ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight))
                                    throw new InvalidOperationException("Journal footer text clips or starts on wrong edge at " + size);
                            }
                            var selector = Require<ComboBox>(form, "journalAccount");
                            var selectFrame = Require<AntdUI.Panel>(form, "journalAccountFrame");
                            if (selector.Text != "1000 - الصندوق" || !ReferenceEquals(selectFrame.Tag, DesktopComponents.NativeSelectFrameMarker) ||
                                selectFrame.Shadow != 0 || grid.Columns["CostCenterId"].Visible || grid.Columns["Action"].HeaderText != "الإجراء")
                                throw new InvalidOperationException("Journal native account or hidden/localized grid presentation changed.");                            viewport.AutoScrollPosition = Point.Empty;
                            var toolbar = Require<Panel>(form, "journalToolbar");
                            if (toolbar.Bottom != form.ClientSize.Height || toolbar.Parent != form)
                                throw new InvalidOperationException("Journal save toolbar scrolled with editor.");
                        }
                        int originalRows = grid.Rows.Count;
                        var doubleClick = typeof(DataGridView).GetMethod("OnCellDoubleClick", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                        grid.CurrentCell = grid.Rows[0].Cells["رقم الحساب"];
                        doubleClick.Invoke(grid, new object[] { new DataGridViewCellEventArgs(grid.Columns["رقم الحساب"].Index, 0) });
                        if (grid.Rows.Count != originalRows) throw new InvalidOperationException("Double-clicking journal details deleted a line.");
                        doubleClick.Invoke(grid, new object[] { new DataGridViewCellEventArgs(grid.Columns["Action"].Index, -1) });
                        if (grid.Rows.Count != originalRows) throw new InvalidOperationException("Double-clicking journal header deleted a line.");
                        doubleClick.Invoke(grid, new object[] { new DataGridViewCellEventArgs(grid.Columns["Action"].Index, 0) });
                        if (grid.Rows.Count != originalRows - 1) throw new InvalidOperationException("Explicit journal action no longer removes its selected line.");                        OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize); form.ApplyResponsiveLayout(); Application.DoEvents();
                        if (viewport.HorizontalScroll.Visible || grid.Height < 128)
                            throw new InvalidOperationException("Journal outer MinimumSize hides the grid or causes horizontal scrolling.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = oldMode; }
        }
        private static void VerifyJournalCurrencyCalculation()
        {
            string oldMode = Properties.Setings.Default.ThemeMode;
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (string kind in new[] { "Manual", "OpeningEntry" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var form = new JournalEntriesForm("معاينة حساب القيد", kind, true))
                    {
                        Func<string, Control> field = name => (Control)typeof(JournalEntriesForm).GetField(name, flags).GetValue(form);
                        var table = (DataTable)typeof(JournalEntriesForm).GetField("lines", flags).GetValue(form);
                        Action clear = () => typeof(JournalEntriesForm).GetMethod("NewEntry", flags).Invoke(form, null);
