                            throw new InvalidOperationException("Overflowing journal line changed the draft.");
                        field("exchangeRate").Text = "3";
                        if (field("localValue").Text != "6") throw new InvalidOperationException("Journal preview did not recover after correction.");
                        add();
                        if (table.Rows.Count != 1 || Convert.ToDecimal(table.Rows[0]["مدين محلي"]) != 6m)
                            throw new InvalidOperationException("Corrected journal conversion was not added.");
                        field("exchangeRate").Text = "1";
                        field("debit").Text = decimal.MaxValue.ToString();
                        add();
                        if (table.Rows.Count != 1 || !field("statusLabel").Text.Contains("مبلغ"))
                            throw new InvalidOperationException("Debit storage limit must be rejected before adding a row.");
                        clear();
                        field("credit").Text = PharmacyManagement.Domain.JournalEntryPreparation.MaximumLineAmount.ToString();
                        add();
                        field("credit").Text = PharmacyManagement.Domain.JournalEntryPreparation.MaximumLineAmount.ToString();
                        add();
                        if (table.Rows.Count != 2) throw new InvalidOperationException("Valid total above the per-line limit was rejected.");
                        field("credit").Text = decimal.MaxValue.ToString();
                        add();
                        if (table.Rows.Count != 2 || !field("statusLabel").Text.Contains("مبلغ"))
                            throw new InvalidOperationException("Credit storage limit must be rejected before adding a row.");
                        decimal localDebit, localCredit;
                        if (form.TryCalculateJournalLine(1m, 0m, 0m, out localDebit, out localCredit) || localDebit != 0m || localCredit != 0m)
                            throw new InvalidOperationException("Invalid conversion leaked partial calculated values.");
                        field("exchangeRate").Text = "invalid";
                        if (field("localValue").Text != "—") throw new InvalidOperationException("Invalid rate was silently treated as one.");
                        field("exchangeRate").Text = "0";
                        if (field("localValue").Text != "—") throw new InvalidOperationException("Zero rate was silently treated as one.");
                        field("exchangeRate").Text = "1";
                        field("credit").Text = "-1";
                        if (field("localValue").Text != "—") throw new InvalidOperationException("Negative amount preview was accepted.");
                        var corrupt = table.NewRow();
