                        typeof(JournalEntriesForm).GetMethod("UpdateTotals", flags).Invoke(form, null);
                        if (!field("totalsLabel").Text.Contains("تعذر")) throw new InvalidOperationException("Overflowing loaded draft total was displayed as valid.");
                        clear();
                        if (table.Rows.Count != 0 || !field("totalsLabel").Text.Contains("0.00"))
                            throw new InvalidOperationException("Journal totals did not recover after clearing.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = oldMode; }
