        private static void VerifyJournalAcceptedWriteAndPrint()
        {
            string oldMode = Properties.Setings.Default.ThemeMode;
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (string kind in new[] { "Manual", "OpeningEntry" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var form = new JournalEntriesForm("معاينة قيد", kind, true))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show(); Application.DoEvents();
                        var status = Require<Label>(form, "journalStatus");
                        var grid = Require<DataGridView>(form, "journalLinesGrid");
                        var idField = typeof(JournalEntriesForm).GetField("acceptedJournalId", flags);
                        var pending = new System.Threading.Tasks.TaskCompletionSource<int>(); int calls = 0;
                        var writing = form.RunJournalWriteAsync(() => { calls++; return pending.Task; }, false);
                        bool heartbeat = false; form.BeginInvoke(new Action(() => heartbeat = true)); Application.DoEvents();
                        var duplicate = form.RunJournalWriteAsync(() => { calls++; return System.Threading.Tasks.Task.FromResult(7); }, false);
                        if (!heartbeat || writing.IsCompleted || duplicate.Result != 0 || calls != 1 || grid.Enabled)
                            throw new InvalidOperationException("Journal pending write blocks dispatch or permits duplicate/editing.");
                        form.Close(); Application.DoEvents();
                        if (form.IsDisposed || !form.Visible || !status.Text.Contains("انتظر")) throw new InvalidOperationException("Pending journal can close.");
                        pending.SetResult(42); CompleteUiTask(writing);
                        if (writing.Result != 42 || (int)idField.GetValue(form) != 42 || !grid.Enabled || !status.Text.Contains("42"))
                            throw new InvalidOperationException("Journal acceptance was lost by NewEntry.");
                        var failed = form.RunJournalWriteAsync(() => System.Threading.Tasks.Task.FromException<int>(new InvalidOperationException("Controlled posting failure")), false);
                        CompleteUiTask(failed);
                        if (failed.Result != 0 || (int)idField.GetValue(form) != 42 || !grid.Enabled || !status.Text.Contains("تعذر حفظ")) throw new InvalidOperationException("Failed journal changed known acceptance.");
                        var saved = new JournalDocumentSnapshot(43, new DateTime(2024, 2, 29), kind, null, "Saved header", "qa",
                            new[] { new JournalDocumentLine(1,"1000","Saved cash",10m,0m,"Saved debit",null,null), new JournalDocumentLine(2,"2000","Saved partner",0m,10m,"Saved credit",null,null) });
                        int requested = 0, printed = 0;
                        var printedTask = form.RunJournalWriteAsync(() => System.Threading.Tasks.Task.FromResult(43), true,
                            id => { requested = id; return System.Threading.Tasks.Task.FromResult(saved); }, null,
                            document =>
                            {
                                using (var table = JournalDocumentDesktopService.PrintLines(document))
                                    if (table.Rows.Count != 2 || (decimal)table.Rows[0]["مدين محلي"] != 10m || (string)table.Rows[0]["البيان"] != "Saved debit")
                                        throw new InvalidOperationException("Journal print used draft values.");
                                printed++;
                            });
                        CompleteUiTask(printedTask);
                        if (printedTask.Result != 43 || requested != 43 || printed != 1) throw new InvalidOperationException("Journal print identity/projection is invalid.");
                        var wrong = form.RunJournalWriteAsync(() => System.Threading.Tasks.Task.FromResult(44), true,
                            id => System.Threading.Tasks.Task.FromResult(saved), null, doc => printed++);
                        CompleteUiTask(wrong);
                        if (wrong.Result != 44 || printed != 1 || !status.Text.Contains("44") || !status.Text.Contains("لا تعِد الحفظ"))
                            throw new InvalidOperationException("Wrong print identity hides acceptance or prints a different document.");
                        var clearFailed = form.RunJournalWriteAsync(() => System.Threading.Tasks.Task.FromResult(45), false, null,
                            () => { if ((int)idField.GetValue(form) != 45) throw new Exception("Acceptance not captured"); throw new InvalidOperationException("Controlled clear failure"); });
                        CompleteUiTask(clearFailed);
                        int retries = 0;
                        var retry = form.RunJournalWriteAsync(() => { retries++; return System.Threading.Tasks.Task.FromResult(99); }, false);
                        if (clearFailed.Result != 45 || retry.Result != 0 || retries != 0 || !status.Text.Contains("45") || !status.Text.Contains("لا تعِد الحفظ"))
                            throw new InvalidOperationException("Accepted draft can be reposted after editor failure.");
                        foreach (Size size in new[] { new Size(760,600),new Size(960,640),new Size(1366,768) })
                        {
                            Prepare(form,size); form.ApplyResponsiveLayout(); Application.DoEvents();
                            int needed = TextRenderer.MeasureText(status.Text,status.Font,new Size(Math.Max(1,status.Width-status.Padding.Horizontal),int.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height;
                            if (needed > status.Height) throw new InvalidOperationException("Journal accepted warning is clipped: " + size + "; needed=" + needed + "; label=" + status.Bounds + "; parent=" + status.Parent.Bounds);
                        }
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = oldMode; }
        }

