                        var old=form.RefreshQuickJournalHistoryAsync(null,(request,token)=>{oldToken=token;return pending.Task;});
                        AntdDateInput.SetDate(from,new DateTime(2026,9,2));
                        bool disposed=false;var oldRows=QuickSessionRows();oldRows.Disposed+=(sender,args)=>disposed=true;pending.SetResult(oldRows);CompleteUiTask(old);
