        private static void VerifyJournalEntriesQuickLayout()
        {
            using (var form = new JournalEntriesQuickForm(true))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(760, 600), new Size(860, 600), new Size(1120, 700) })
                {
                    Prepare(form, size);
                    form.ApplyQuickJournalLayout();
                    Panel editor = Require<Panel>(form, "accountingDataEditor");
                    Panel header = Require<Panel>(form, "accountingDataHeader");
                    AntdUI.Button headerClose = Require<AntdUI.Button>(form, "accountingDataCloseButton");
                    DataGridView grid = Require<DataGridView>(form, "accountingDataGrid");
                    ComboBox debit = Require<ComboBox>(form, "quickJournalDebitAccount");
                    ComboBox credit = Require<ComboBox>(form, "quickJournalCreditAccount");
                    AntdUI.Select source = Require<AntdUI.Select>(form, "quickJournalSource");
                    AntdUI.Input amount = Require<AntdUI.Input>(form, "quickJournalAmount");
                    TextBox description = Require<TextBox>(form, "quickJournalDescription");
                    AntdUI.Button save = Require<AntdUI.Button>(form, "quickJournalSave");
                    AntdUI.Button refresh = Require<AntdUI.Button>(form, "quickJournalRefresh");
                    AntdUI.Panel actionFooter = Require<AntdUI.Panel>(form, "quickJournalActions");
                    AntdUI.DatePicker startDate = Require<AntdUI.DatePicker>(form, "quickJournalFromDate");
                    AntdUI.DatePicker endDate = Require<AntdUI.DatePicker>(form, "quickJournalToDate");
                    DateTime parsedDate;
                    if (!AntdDateInput.TryRead(startDate, out parsedDate) || !AntdDateInput.TryRead(endDate, out parsedDate) ||
                        startDate.Height < 44 || endDate.Height < 44 || save.Height < 44 || refresh.Height < 44 ||
                        save.Parent != actionFooter || refresh.Parent != actionFooter ||
                        actionFooter.Left != 0 || actionFooter.Width != form.ClientSize.Width ||
                        editor.Bottom != actionFooter.Top || grid.Bottom != actionFooter.Top ||
                        actionFooter.Bottom > form.ClientSize.Height || save.Bottom > actionFooter.ClientSize.Height ||
                        refresh.Bottom > actionFooter.ClientSize.Height)
                        throw new InvalidOperationException("Quick journal dates or sticky actions are inaccessible at " + size + ".");
                    RequireHorizontallyInside(form, editor, "quick journal editor " + size);
                    RequireHorizontallyInside(form, grid, "quick journal grid " + size);
                    if (form.Controls["__UiStatusStrip"] != null || headerClose.Parent != actionFooter ||
                        headerClose.Height < 44 || headerClose.Left < 0 || headerClose.Right > actionFooter.ClientSize.Width ||
                        headerClose.Bottom > actionFooter.ClientSize.Height || headerClose.Bounds.IntersectsWith(save.Bounds) ||
                        headerClose.Bounds.IntersectsWith(refresh.Bounds) || headerClose.BorderWidth != 1 ||
                        headerClose.ForeColor != UiTheme.Primary || string.IsNullOrWhiteSpace(headerClose.AccessibleName))
                        throw new InvalidOperationException("Quick journal close action is inaccessible or overlaps footer actions at " + size + ".");
                    if (UiDirection.IsLeftToRight
                        ? editor.PointToScreen(Point.Empty).X >= grid.PointToScreen(Point.Empty).X
                        : editor.PointToScreen(Point.Empty).X <= grid.PointToScreen(Point.Empty).X)
                        throw new InvalidOperationException("Quick journal editor is not on the language's reading edge at " + size + ".");
                    if (editor.Width < 250 || editor.Width > 360 || !grid.ReadOnly || grid.Rows.Count != 1 ||
                        debit.RightToLeft != RightToLeft.Yes || credit.RightToLeft != RightToLeft.Yes ||
                        source.RightToLeft != RightToLeft.No || amount.RightToLeft != RightToLeft.No ||
                        description.RightToLeft != RightToLeft.Yes || save.AccessibleName != "حفظ القيد")
                        throw new InvalidOperationException("Quick journal check failed at " + size +
                            ": editorWidth=" + editor.Width + ", gridReadOnly=" + grid.ReadOnly + ", rows=" + grid.Rows.Count +
                            ", debitRTL=" + debit.RightToLeft + ", creditRTL=" + credit.RightToLeft +
                            ", sourceRTL=" + source.RightToLeft + ", amountRTL=" + amount.RightToLeft +
                            ", descriptionRTL=" + description.RightToLeft + ", saveNameMatchesText=" +
                            (save.AccessibleName == save.Text) + ", saveNameLength=" + (save.AccessibleName ?? string.Empty).Length + ".");
                    RequireHorizontallyInside(editor, debit, "quick journal debit selector " + size);
                    RequireHorizontallyInside(editor, credit, "quick journal credit selector " + size);
                    RequireHorizontallyInside(editor, amount, "quick journal amount " + size);
                    RequireHorizontallyInside(editor, description, "quick journal description " + size);
                    foreach (Control input in new Control[] { startDate, endDate, debit, credit, source, amount, description })
                    {
                        Control surface = input.Parent is AntdUI.Panel ? input.Parent : input;
                        Panel host = surface.Parent as Panel;
                        Label caption = host == null ? null : host.Controls.OfType<Label>().FirstOrDefault();
                        if (host == null || caption == null || caption.Bottom > surface.Top ||
                            surface.Bottom > host.ClientSize.Height || caption.Left < 0 || caption.Right > host.ClientSize.Width)
                            throw new InvalidOperationException("Quick journal field caption overlaps or follows its input: " + input.Name + " at " + size + ".");
                    }
                }
            }
        }
