                {
                    form.ShowInTaskbar=false; form.StartPosition=FormStartPosition.Manual; form.Location=new Point(-20000,-20000); form.Show(); Application.DoEvents();
                    var currency = Require<ComboBox>(form, "receiptVoucherCurrency");
                    var account = Require<ComboBox>(form, "receiptVoucherPartyAccount");
                    var amount = Require<AntdUI.Input>(form, "receiptVoucherAmount");
                    var first = new System.Threading.Tasks.TaskCompletionSource<ReceiptVoucherInitialDataSnapshot>();
                    System.Threading.CancellationToken firstToken=default(System.Threading.CancellationToken);
                    var loading = form.LoadReceiptInitialAsync(token => { firstToken=token; return first.Task; });
                    if (currency.Enabled || account.Enabled || loading.IsCompleted) throw new InvalidOperationException("Receipt editor is available before options load.");
                    var second=form.LoadReceiptInitialAsync(token=>System.Threading.Tasks.Task.FromResult(valid())); CompleteUiTask(second);
                    if(!firstToken.IsCancellationRequested || !second.Result || !currency.Enabled || currency.Text!="YER") throw new InvalidOperationException("Receipt load did not cancel predecessor/select actual system currency.");
                    var stale=valid(); first.SetResult(stale); CompleteUiTask(loading);
                    if(loading.Result || currency.Text!="YER")throw new InvalidOperationException("Receipt stale lookup replaced current options.");
                    var invalid=new ReceiptVoucherInitialDataSnapshot(new List<string>{"1100 - نقد"},new List<string>(),new List<string>{"USD"},"YER",new DataTable());
                    var failed=form.LoadReceiptInitialAsync(token=>System.Threading.Tasks.Task.FromResult(invalid));CompleteUiTask(failed);
                    if(failed.Result || currency.Enabled || account.Enabled || currency.Items.Count!=0)throw new InvalidOperationException("Receipt fabricated a currency or enabled failed editor.");
                    var error=form.LoadReceiptInitialAsync(token=>System.Threading.Tasks.Task.FromException<ReceiptVoucherInitialDataSnapshot>(new InvalidOperationException("fixture")));CompleteUiTask(error);
                    if(error.Result || currency.Enabled || account.Enabled)throw new InvalidOperationException("Receipt failed load reopened editor.");
                    var recover=form.LoadReceiptInitialAsync(token=>System.Threading.Tasks.Task.FromResult(valid()));CompleteUiTask(recover);
                    amount.Text="35";
                    var pending=new System.Threading.Tasks.TaskCompletionSource<ReceiptVoucherInitialDataSnapshot>();
                    var old=form.LoadReceiptInitialAsync(token=>pending.Task);
                    SessionContext.Start("receipt-initial-fixture","Manager","fixture");pending.SetResult(valid());CompleteUiTask(old);
                    if(old.Result || currency.Enabled || account.Items.Count!=0)throw new InvalidOperationException("Receipt options survived same-user reauthentication.");
                    var fresh=form.LoadReceiptInitialAsync(token=>System.Threading.Tasks.Task.FromResult(valid()));CompleteUiTask(fresh);
                    if(!fresh.Result || amount.Text.Length!=0)throw new InvalidOperationException("Receipt recovered old-session draft.");
                    System.Threading.CancellationToken closeToken=default(System.Threading.CancellationToken);
                    var closing=new System.Threading.Tasks.TaskCompletionSource<ReceiptVoucherInitialDataSnapshot>();
                    var closed=form.LoadReceiptInitialAsync(token=>{closeToken=token;return closing.Task;});form.Close();
                    if(!closeToken.IsCancellationRequested)throw new InvalidOperationException("Receipt close did not cancel initial options.");
                    closing.SetResult(valid());CompleteUiTask(closed);
                    if(closed.Result)throw new InvalidOperationException("Receipt delivered options after close.");
                }
            }
            Console.WriteLine("Receipt initial options: cancellation, supersession, strict currency, failure, recovery, same-user session and close passed (4 types).");
        }

