        private static void VerifyLegacyVoucherCommittedPresentation()
        {
            string previousMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (string type in new[] { "ReceiptExternal", "PaymentExternal", "ReceiptMulti", "PaymentMulti" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var form = new LegacyVoucherPreview(type))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show(); Application.DoEvents();
                        var status = Require<Label>(form, "legacyVoucherStatus");
                        var grid = Require<DataGridView>(form, "accountingDataGrid");
                        var save = Require<AntdUI.Button>(form, "legacyVoucherSave");
                        var editor = Require<Panel>(form, "accountingDataEditor");
                        foreach (Control field in editor.Controls)
                        foreach (Control child in field.Controls)
                            if (child is Label caption && child.Name.StartsWith("accountingFieldLabel_") &&
                                (caption.RightToLeft != RightToLeft.No || caption.TextAlign != (UiDirection.IsLeftToRight ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight)))
                                throw new InvalidOperationException("Accounting field caption inherits a second RTL mirror.");
                        var idField = typeof(VoucherForm).GetField("acceptedVoucherId", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                        var amount = (AntdUI.Input)typeof(VoucherForm).GetField("amount", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(form);
                        var notes = (TextBox)typeof(VoucherForm).GetField("notes", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(form);
                        amount.Text = "1250"; notes.Text = "بيان السند";
                        var initial = new DataTable(); initial.Columns.Add("رقم", typeof(int)); initial.Rows.Add(7); grid.DataSource = initial;
                        int reads = 0;
                        EventHandler failClear = (sender, args) =>
                        {
                            if ((int)idField.GetValue(form) != 42) throw new InvalidOperationException("Accepted identity was not captured before UI clearing.");
                            throw new InvalidOperationException("Controlled editor refresh failure");
                        };
                        amount.TextChanged += failClear;
                        try { CompleteUiTask(form.CompleteSavedVoucherPresentationAsync(42, null,
                            () => { reads++; return System.Threading.Tasks.Task.FromResult(new DataTable()); })); }
                        finally { amount.TextChanged -= failClear; }
                        if ((int)idField.GetValue(form) != 42 || reads != 0 || !status.Text.Contains("42") ||
                            !status.Text.Contains("لا تعد حفظ") || grid.DataSource != initial || save.Enabled)
                            throw new InvalidOperationException("Accepted legacy voucher was misreported after editor failure.");

                        var older = new System.Threading.Tasks.TaskCompletionSource<DataTable>();
                        var newer = new System.Threading.Tasks.TaskCompletionSource<DataTable>();
                        var oldTask = form.RefreshVoucherHistoryAsync(() => older.Task);
                        amount.Text = "2500";
                        var newTask = form.CompleteSavedVoucherPresentationAsync(43, null, () => newer.Task);
                        if (amount.Text.Length != 0 || notes.Text.Length != 0)
                            throw new InvalidOperationException("Accepted legacy voucher did not clear the next-entry fields before reading history.");
                        var latest = new DataTable(); latest.Columns.Add("رقم", typeof(int)); latest.Rows.Add(43);
                        newer.SetResult(latest); CompleteUiTask(newTask);
                        string success = status.Text;
                        older.SetException(new InvalidOperationException("Controlled stale failure")); CompleteUiTask(oldTask);
                        if ((int)idField.GetValue(form) != 43 || grid.DataSource != latest || status.Text != success || success.Contains("لا تعد حفظ"))
                            throw new InvalidOperationException("Stale history failure replaced the accepted legacy voucher result.");
                        CompleteUiTask(form.RefreshVoucherHistoryAsync(() => System.Threading.Tasks.Task.FromResult<DataTable>(null)));
                        if (grid.DataSource != latest || !status.Text.Contains("43") || !status.AccessibleDescription.Contains("لا تعد حفظ"))
                            throw new InvalidOperationException("Failed legacy history read discarded the previous rows or save confirmation.");
                        foreach (Size size in new[] { new Size(860, 560), new Size(1120, 700) })
                        {
                            OwnedTestWindowViewport.ResizeOuter(form, size); form.PerformLayout(); Application.DoEvents();
                            var footer = Require<AntdUI.Panel>(form, "legacyVoucherFooter");
                            int measured = TextRenderer.MeasureText(status.Text, status.Font, new Size(status.Width, int.MaxValue), TextFormatFlags.WordBreak).Height;
                            if (footer.Shadow != 0 || measured > status.Height || grid.Bottom > footer.Top ||
                                save.PointToScreen(Point.Empty).Y < footer.PointToScreen(Point.Empty).Y)
                                throw new InvalidOperationException("Legacy voucher footer clips status or overlaps history at " + size +
                                    ": measured=" + measured + ", label=" + status.Bounds + ", grid=" + grid.Bounds + ", footer=" + footer.Bounds + ", save=" + save.Bounds + ".");
                        }
                        var posting = new System.Threading.Tasks.TaskCompletionSource<int>();
                        int postCalls = 0;
                        var pendingPost = form.RunVoucherWriteAsync(() => { postCalls++; return posting.Task; },
                            () => System.Threading.Tasks.Task.FromResult(new DataTable()));
                        bool heartbeat = false;
                        form.BeginInvoke(new Action(() => heartbeat = true)); Application.DoEvents();
                        var duplicatePost = form.RunVoucherWriteAsync(() => { postCalls++; return System.Threading.Tasks.Task.FromResult(55); });
                        if (!heartbeat || pendingPost.IsCompleted || !duplicatePost.IsCompleted || duplicatePost.Result ||
                            postCalls != 1 || editor.Enabled || grid.Enabled || save.Enabled)
                            throw new InvalidOperationException("Pending voucher blocks dispatch or allows duplicate/editing.");
                        form.Close(); Application.DoEvents();
                        if (form.IsDisposed || !form.Visible || !status.Text.Contains("انتظر"))
                            throw new InvalidOperationException("Pending voucher can close before its result.");
                        posting.SetResult(44); CompleteUiTask(pendingPost);
                        if (!pendingPost.Result || (int)idField.GetValue(form) != 44 || !editor.Enabled || !grid.Enabled || save.Enabled)
                            throw new InvalidOperationException("Accepted pending voucher did not restore its prior preview state.");
                        var failedPost = new System.Threading.Tasks.TaskCompletionSource<int>();
                        var failureTask = form.RunVoucherWriteAsync(() => failedPost.Task);
                        var expectedFailure = new InvalidOperationException("Controlled posting failure");
                        failedPost.SetException(expectedFailure);
                        CompleteUiTask(failureTask);
                        if (failureTask.Result || !editor.Enabled || !grid.Enabled || save.Enabled ||
                            (int)idField.GetValue(form) != 44 || !status.Text.Contains("تعذر حفظ"))
                            throw new InvalidOperationException("Failed pending voucher changed acceptance or left controls disabled.");
                        var closing = new System.Threading.Tasks.TaskCompletionSource<DataTable>();
                        var closeTask = form.RefreshVoucherHistoryAsync(() => closing.Task);
                        form.Close(); string afterClose = status.Text;
                        closing.SetResult(new DataTable()); CompleteUiTask(closeTask);
                        if (status.Text != afterClose) throw new InvalidOperationException("Closed legacy voucher form was updated.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = previousMode; }
        }

