                        service.Controlled=true;var old=form.RefreshBalanceAsync();var oldCompletion=service.Pending.Last();var token=service.Tokens.Last();
                        var newer=form.RefreshBalanceAsync();var newCompletion=service.Pending.Last();
                        if(!token.IsCancellationRequested)throw new InvalidOperationException("Voucher account balance predecessor is not cancelled.");
                        newCompletion.SetResult(-125.75m);CompleteUiTask(newer);oldCompletion.SetResult(900m);CompleteUiTask(old);
