                        if(!account.Enabled||label.Text!=2500m.ToString("N2"))throw new InvalidOperationException("Voucher balance recovery cannot use current options.");
                        SessionContext.Start("balance-session-fixture","Manager","fixture");
                        typeof(Form).GetMethod("OnActivated",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(form,new object[]{EventArgs.Empty});
                        if(label.Text!="—"||account.Enabled)throw new InvalidOperationException("Retained displayed balance survives activation after relogin.");
                        service.Controlled=false;CompleteUiTask(form.LoadReceiptInitialAsync(ct=>System.Threading.Tasks.Task.FromResult(new ReceiptVoucherInitialDataSnapshot(new List<string>{"1100 - نقد"},new List<string>(),new List<string>{"YER"},"YER",new DataTable()))));
                        service.Controlled=true;var closing=form.RefreshBalanceAsync();var closingCompletion=service.Pending.Last();var closingToken=service.Tokens.Last();
                        form.Close();closingCompletion.SetResult(88m);CompleteUiTask(closing);
                        if(!closingToken.IsCancellationRequested||!form.IsDisposed)throw new InvalidOperationException("Voucher close does not cancel balance read.");
                        foreach(var completion in service.Pending)if(!completion.Task.IsCompleted)completion.SetResult(0m);
                    }
                }
