        private static void VerifyReceiptVoucherBalanceState()
        {
            string previousMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                using (var form = CreateBalancePreview(mode, out ControlledBalanceRead service))
                {
                    form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                    form.Location = new Point(-20000, -20000); form.Show(); Application.DoEvents();
                    var label = Require<Label>(form, "receiptVoucherBalance");
                    var selector = Require<ComboBox>(form, "receiptVoucherPartyAccount");
                    var date = Require<AntdUI.DatePicker>(form, "receiptVoucherDate");
                    var amount = Require<AntdUI.Input>(form, "receiptVoucherAmount");
                    var history = Require<DataGridView>(form, "receiptVoucherHistory");
                    object snapshot = history.DataSource; string amountSnapshot = amount.Text;
                    service.Controlled = true;
                    var failure = form.RefreshBalanceAsync();
                    if (label.Text != "..." || label.ForeColor != UiTheme.MutedText) throw new InvalidOperationException("Old balance remains visible while loading.");
                    service.Pending.Last().SetException(new InvalidOperationException("Simulated connection failure")); CompleteUiTask(failure);
                    if (label.Text != "غير متاح" || label.ForeColor != UiTheme.Danger || !label.AccessibleDescription.Contains("تعذر تحميل الرصيد"))
                        throw new InvalidOperationException("A failed balance read is presented as a real zero.");
                    foreach (Size size in new[] { new Size(960, 600), new Size(1366, 768) })
                    {
                        Prepare(form, size);
                        if (TextRenderer.MeasureText(label.Text, label.Font).Width > label.ClientSize.Width)
                            throw new InvalidOperationException("Balance error caption is clipped.");
                    }
                    var zero = form.RefreshBalanceAsync(); service.Pending.Last().SetResult(0m); CompleteUiTask(zero);
                    if (label.Text != 0m.ToString("N2") || label.ForeColor != UiTheme.Primary)
                        throw new InvalidOperationException("A real zero is not distinct from failure.");
                    var older = form.RefreshBalanceAsync(); var olderCompletion = service.Pending.Last();
                    selector.SelectedIndex = 1; Application.DoEvents();
                    var newer = form.RefreshBalanceAsync(); var newerCompletion = service.Pending.Last();
                    if (service.Requests.Last().AccountCode != "2100") throw new InvalidOperationException("Balance read did not capture the selected account.");
                    newerCompletion.SetResult(-125.75m); CompleteUiTask(newer);
                    olderCompletion.SetResult(900m); CompleteUiTask(older);
                    if (label.Text != (-125.75m).ToString("N2")) throw new InvalidOperationException("A stale balance overwrote the new account result.");
                    var staleFailure = form.RefreshBalanceAsync(); var staleFailureCompletion = service.Pending.Last();
                    AntdDateInput.SetDate(date, new DateTime(2026, 9, 30));
                    var fresh = form.RefreshBalanceAsync(); service.Pending.Last().SetResult(10.25m); CompleteUiTask(fresh);
                    staleFailureCompletion.SetException(new InvalidOperationException("Late failure")); CompleteUiTask(staleFailure);
                    if (label.Text != 10.25m.ToString("N2") || service.Requests.Last().ThroughDate != new DateTime(2026, 9, 30))
                        throw new InvalidOperationException("A stale error/date request overwrote the accepted balance.");
                    var beforeClear = form.RefreshBalanceAsync(); var clearCompletion = service.Pending.Last();
                    selector.SelectedIndex = -1; selector.Text = string.Empty; CompleteUiTask(form.RefreshBalanceAsync());
                    clearCompletion.SetResult(999m); CompleteUiTask(beforeClear);
                    if (label.Text != "—" || label.ForeColor != UiTheme.MutedText || !label.AccessibleDescription.Contains("اختر الحساب"))
                        throw new InvalidOperationException("Empty selection shows an old/zero balance.");
                    if (!ReferenceEquals(snapshot, history.DataSource) || amount.Text != amountSnapshot)
                        throw new InvalidOperationException("Balance reads changed voucher input or history.");
                    selector.SelectedIndex = 0; var closing = form.RefreshBalanceAsync(); var closingCompletion = service.Pending.Last();
                    form.Close(); string beforeClose = label.Text;
                    if (!form.IsDisposed) throw new InvalidOperationException("Balance preview did not close.");
                    closingCompletion.SetResult(55m); CompleteUiTask(closing);
                    if (label.Text != beforeClose) throw new InvalidOperationException("Closing voucher accepts a late balance.");
                    foreach (var pending in service.Pending) if (!pending.Task.IsCompleted) pending.SetResult(0m);
                    Application.DoEvents();
                }
            }
            finally { Properties.Setings.Default.ThemeMode = previousMode; using (var refresh = new Form()) UiTheme.Apply(refresh); }
        }

