        public static void VerifyVoucherDocumentAsyncOnly(){VerifyReceiptVoucherSavedPrintSource();VerifyVoucherDocumentLifetimeOnly();}
        public static void VerifyVoucherDocumentLifetimeOnly()
        {
            string previous=Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})
                {
                    SessionContext.Start("voucher-print-fixture","Manager","fixture");Properties.Setings.Default.ThemeMode=theme;
                    var saved=new VoucherDocumentSnapshot(42,new DateTime(2024,2,29,13,45,0),"PaymentInternal","عميل Pharmacy 500 mg","1100",1250.37m,"شيك — Bank 123",99,"saved-user");
                    var service=new MockVoucherDocumentRead{Snapshot=saved};
                    using(var form=new ReceiptVoucherForm("ReceiptExternal",true,new ControlledBalanceRead(),true,service))
                    {
                        form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();
                        int presentations=0;
                        service.Pending=new System.Threading.Tasks.TaskCompletionSource<VoucherDocumentSnapshot>();
                        var reading=form.OpenVoucherPrintAsync(42,doc=>{presentations++;return true;});var token=service.Token;
                        var duplicate=form.OpenVoucherPrintAsync(42,doc=>{presentations++;return true;});CompleteUiTask(duplicate);
                        if(duplicate.Result||service.Calls!=1||reading.IsCompleted)throw new InvalidOperationException("Voucher duplicate print request started a second reader.");
                        SessionContext.Start("voucher-print-fixture","Manager","fixture");service.Pending.SetResult(saved);CompleteUiTask(reading);
                        if(reading.Result||presentations!=0)throw new InvalidOperationException("Voucher preview opened after same-user login changed.");
                        service.Pending=null;
                        CompleteUiTask(form.LoadReceiptInitialAsync(ct=>System.Threading.Tasks.Task.FromResult(new ReceiptVoucherInitialDataSnapshot(new List<string>{"1100 - نقد"},new List<string>(),new List<string>{"YER"},"YER",new DataTable()))));
                        if(!Require<AntdUI.Button>(form,"receiptVoucherAction_Print_طباعة كاشير").Enabled)throw new InvalidOperationException("Recovered voucher options did not restore print action.");
                        var current=form.OpenVoucherPrintAsync(42,doc=>{presentations++;return ReferenceEquals(doc,saved)&&doc.Amount==1250.37m;});CompleteUiTask(current);
                        if(!current.Result||presentations!=1)throw new InvalidOperationException("Current voucher preview did not use its saved snapshot.");
                        service.Snapshot=new VoucherDocumentSnapshot(7,DateTime.Today,"ReceiptExternal","wrong","1100",1m,"",null,"");
                        var mismatch=form.OpenVoucherPrintAsync(42,doc=>{presentations++;return true;});CompleteUiTask(mismatch);
                        if(mismatch.Result||presentations!=1)throw new InvalidOperationException("Wrong-id voucher opened a preview.");
                        service.Snapshot=saved;service.Pending=new System.Threading.Tasks.TaskCompletionSource<VoucherDocumentSnapshot>();
                        var closing=form.OpenVoucherPrintAsync(42,doc=>{presentations++;return true;});var closingToken=service.Token;
                        form.Close();service.Pending.SetResult(saved);CompleteUiTask(closing);
                        if(!closingToken.IsCancellationRequested||closing.Result||presentations!=1||!form.IsDisposed)throw new InvalidOperationException("Closing voucher delivered a document or did not cancel SQL token.");
                    }
                }
                Console.WriteLine("PASS saved voucher preview lifetime: duplicate denial, same-user session rejection, saved snapshot identity, wrong-id rejection, close cancellation/no presentation; both themes; no native preview/input.");
            }
            finally{Properties.Setings.Default.ThemeMode=previous;SessionContext.Clear();}
        }

        private sealed class MockVoucherDocumentRead : PharmacyManagement.Application.IVoucherDocumentReadService
        {
            internal int Calls, RequestedId;
            internal PharmacyManagement.Application.VoucherDocumentSnapshot Snapshot;
            internal Exception Failure;
            internal System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.VoucherDocumentSnapshot> Pending;
            internal System.Threading.CancellationToken Token;
            public System.Threading.Tasks.Task<PharmacyManagement.Application.VoucherDocumentSnapshot> LoadAsync(PharmacyManagement.Application.VoucherDocumentReadRequest request,PharmacyManagement.Application.OperationActor actor,System.Threading.CancellationToken cancellationToken)
            {Token=cancellationToken;return LoadAsync(request,actor);}
            public System.Threading.Tasks.Task<PharmacyManagement.Application.VoucherDocumentSnapshot> LoadAsync(
                PharmacyManagement.Application.VoucherDocumentReadRequest request, PharmacyManagement.Application.OperationActor actor)
            {
                Calls++; RequestedId = request.VoucherId;
                if(Pending!=null)return Pending.Task;
                return Failure == null ? System.Threading.Tasks.Task.FromResult(Snapshot)
                    : System.Threading.Tasks.Task.FromException<PharmacyManagement.Application.VoucherDocumentSnapshot>(Failure);
            }
        }

