                        {
                            refreshCalls++;
                            typeof(ReceiptVoucherForm).GetField("lastSavedVoucherId", flags).SetValue(form, 7);
                        };
                        refreshed = (bool)completed.Invoke(form, new object[] { 43, "next saved snapshot", successfulRefresh });
                        if (!refreshed || refreshCalls != 2 || !status.Text.Contains("تم حفظ السند رقم 43") ||
                            status.Text.Contains("لا تعِد الحفظ") ||
                            status.AccessibleDescription != status.Text ||
                            (int)typeof(ReceiptVoucherForm).GetField("lastSavedVoucherId", flags).GetValue(form) != 43 ||
                            (string)typeof(ReceiptVoucherForm).GetField("lastSavedVoucherSummary", flags).GetValue(form) != "next saved snapshot")
                            throw new InvalidOperationException("Successful post-commit refresh did not preserve the saved document selection.");
                        if (Require<AntdUI.Button>(form, "receiptVoucherAction_Save_حفظ").Enabled)
                            throw new InvalidOperationException("Post-commit presentation enabled persistence in the mock preview.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = previousMode; using (var refresh = new Form()) UiTheme.Apply(refresh); }
        }

        private static void VerifyReceiptVoucherConversion()
        {
            string previousMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    foreach (string kind in new[] { "ReceiptExternal", "PaymentExternal", "ReceiptInternal", "PaymentInternal", "ReceiptMulti", "PaymentMulti" })
                    using (var form = new ReceiptVoucherForm(kind, true))
                    {
                        Prepare(form, new Size(960, 640));
                        var amount = Require<AntdUI.Input>(form, "receiptVoucherAmount");
                        var rate = Require<AntdUI.Input>(form, "receiptVoucherExchangeRate");
                        var local = Require<AntdUI.Input>(form, "receiptVoucherLocalValue");
                        var history = Require<DataGridView>(form, "receiptVoucherHistory"); object snapshot = history.DataSource;
                        amount.Text = "100"; rate.Text = "0";
                        if (local.Text != "—") throw new InvalidOperationException("Invalid exchange rate must not silently convert at rate one.");
                        foreach (string invalid in new[] { "-1", "", "not-a-rate" })
                        {
                            rate.Text = invalid;
                            if (local.Text != "—") throw new InvalidOperationException("Invalid voucher rate presented a usable amount.");
                        }
                        rate.Text = "1";
                        amount.Text = 123.455m.ToString();
                        if (local.Text != 123.46m.ToString("0.##")) throw new InvalidOperationException("Voucher preview must use the same rounding as persistence.");
                        amount.Text = "-1";
                        if (local.Text != "—") throw new InvalidOperationException("Negative voucher amount presented a usable amount.");
                        amount.Text = decimal.MaxValue.ToString(); rate.Text = "2";
                        if (local.Text != "—") throw new InvalidOperationException("Voucher conversion overflow must remain an invalid input state.");
                        amount.Text = "1250.50"; rate.Text = "3";
                        if (local.Text != 3751.5m.ToString("0.##") || !ReferenceEquals(snapshot, history.DataSource))
                            throw new InvalidOperationException("Voucher conversion did not recover or changed history.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = previousMode; using (var refresh = new Form()) UiTheme.Apply(refresh); }
        }

        public static void RenderReceiptSidebarPreviews(string directory)
        {
            if(string.IsNullOrWhiteSpace(directory))throw new ArgumentException("Preview directory required.");
            System.IO.Directory.CreateDirectory(directory);
            string previous=Properties.Setings.Default.ThemeMode;
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})foreach(bool enlarged in new[]{false,true})
                using(Font captionFont=AppFonts.Create(15.75F))using(Font titleFont=AppFonts.Create(27F))
                using(var form=new ReceiptVoucherForm("ReceiptExternal",true))
                {
                    Properties.Setings.Default.ThemeMode=theme;UiTheme.Apply(form);
                    UiDirection.Apply(form,false);form.ApplyReceiptCurrencyPresentation(false);
                    form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();
                    OwnedTestWindowViewport.ResizeOuter(form,enlarged?new Size(960,600):new Size(1366,768));
                    var methods=Require<TableLayoutPanel>(form,"receiptVoucherForm").Controls.OfType<FlowLayoutPanel>().Single();
                    typeof(ReceiptVoucherForm).GetMethod("SetPaymentMethod",flags).Invoke(form,new object[]{"Cheque",methods});
                    var panel=Require<Panel>(form,"receiptVoucherChequePanel");
                    if(enlarged)foreach(Label caption in panel.Controls.OfType<Label>())caption.Font=caption.Name=="receiptVoucherChequeTitle"?titleFont:captionFont;
                    var viewport=Require<ThemedDocumentViewport>(form,"receiptVoucherSideViewport");
                    foreach(bool focusedBank in new[]{false,true})
                    {
                        if(focusedBank)Require<TextBox>(form,"receiptVoucherChequeBank").Focus();else viewport.ResetScroll();
                        Application.DoEvents();
                        using(var bitmap=new Bitmap(form.Width,form.Height))
                        {
                            form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));
                            bitmap.Save(System.IO.Path.Combine(directory,theme+"-"+(enlarged?"enlarged":"default")+"-"+(focusedBank?"bank":"start")+".png"),System.Drawing.Imaging.ImageFormat.Png);
                        }
                    }
                }
            }
            finally{Properties.Setings.Default.ThemeMode=previous;}
            Console.WriteLine("PASS eight cheque-sidebar software-rendered previews; dummy data, no SQL/native input/DPI/printer claim.");
        }

        public static void VerifyReceiptSidebarNativeOnly()
        {
            string previous = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool enlarged in new[] { false, true })
                foreach (string kind in new[] { "ReceiptExternal", "PaymentExternal" })
                foreach (Size size in new[] { new Size(960, 600), new Size(1024, 768), new Size(1366, 768), new Size(1920, 1080) })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (Font captionFont = AppFonts.Create(15.75F))
                    using (Font titleFont = AppFonts.Create(27F))
                    using (var form = new ReceiptVoucherForm(kind, true))
                    {
                        string closeReason="none",closingStack="none",disposalStack="none";
                        form.FormClosing+=(sender,args)=>
                        {
                            closeReason=args.CloseReason.ToString();
                            closingStack=Environment.StackTrace.Replace(Environment.NewLine," | ");
                        };
                        form.Disposed+=(sender,args)=>
                        {
                            if(disposalStack=="none")disposalStack=Environment.StackTrace.Replace(Environment.NewLine," | ");
                        };
                        Action<Size> resizeOwned=requested=>
                        {
                            try { OwnedTestWindowViewport.ResizeOuter(form,requested); }
                            catch(ObjectDisposedException exception)
                            {
                                throw new InvalidOperationException("Receipt sidebar lifetime failure: theme="+theme+
                                    "; english="+english+"; enlarged="+enlarged+"; kind="+kind+"; requested="+requested+
                                    "; disposed="+form.IsDisposed+"; disposing="+form.Disposing+"; closeReason="+closeReason+
                                    "; closingStack="+closingStack+"; disposalStack="+disposalStack,exception);
                            }
                        };
                        UiDirection.Apply(form, english); form.ApplyReceiptCurrencyPresentation(english);
                        form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);
                        form.Show(); Application.DoEvents(); resizeOwned(size);
                        var methods=Require<TableLayoutPanel>(form,"receiptVoucherForm").Controls.OfType<FlowLayoutPanel>().Single();
                        typeof(ReceiptVoucherForm).GetMethod("SetPaymentMethod",flags).Invoke(form,new object[]{"Cheque",methods});
                        Application.DoEvents();
                        var panel=Require<Panel>(form,"receiptVoucherChequePanel");
                        var bankText=Require<TextBox>(form,"receiptVoucherChequeBank");
                        bankText.Text="بنك اليمن - Yemen 01";
                        foreach(string switched in new[]{theme=="Light"?"Dark":"Light",theme})
                        {
                            Properties.Setings.Default.ThemeMode=switched;UiTheme.Apply(form);
                            if(bankText.Text!="بنك اليمن - Yemen 01"||Require<Panel>(form,"receiptVoucherHeader").BackColor!=UiTheme.Background||Require<Panel>(form,"receiptVoucherToolbar").BackColor!=UiTheme.Background)
                                throw new InvalidOperationException("Receipt live theme switch changes bank data or loses flat surfaces.");
                        }
                        UiDirection.Apply(form,english);form.ApplyReceiptCurrencyPresentation(english);
                        resizeOwned(size);
                        if(Require<Panel>(form,"receiptVoucherHeader").BackColor!=UiTheme.Background||Require<Panel>(form,"receiptVoucherToolbar").BackColor!=UiTheme.Background||Require<Panel>(form,"receiptVoucherSideGap").BackColor!=UiTheme.Background)throw new InvalidOperationException("Receipt theme reapply loses its flat header/footer/gap.");
                        if(enlarged)foreach(Label caption in panel.Controls.OfType<Label>())caption.Font=caption.Name=="receiptVoucherChequeTitle"?titleFont:captionFont;
                        foreach(Label caption in panel.Controls.OfType<Label>())
                        {
                            int measured=TextRenderer.MeasureText(caption.Text,caption.Font,new Size(caption.ClientSize.Width,int.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height;
                            if(caption.Height<measured)throw new InvalidOperationException("Cheque sidebar caption clips: "+caption.Text+"; needed="+measured+"; actual="+caption.Height+"; frame="+size);
                        }
                        var side=Require<Panel>(form,"receiptVoucherSide");
                        var themed=Find<ThemedDocumentViewport>(form,"receiptVoucherSideViewport");
                        if(themed==null||themed.YScroll.BackColor!=UiTheme.Background||themed.ContentViewport.BackColor!=UiTheme.Background||themed.YScroll.TabStop)throw new InvalidOperationException("Cheque sidebar does not use the shared themed scrollbar.");
                        var host=Require<Panel>(form,"receiptVoucherSideContent");
                        if(host.Width!=themed.ContentViewport.ClientSize.Width)throw new InvalidOperationException("Sidebar content leaves duplicate scrollbar reserve: host="+host.Width+"; viewport="+themed.ContentViewport.ClientSize.Width);
                        Control clip=themed.ContentViewport;
                        foreach(string name in new[]{"receiptVoucherChequeNumber","receiptVoucherChequeDate","receiptVoucherChequeStatus","receiptVoucherChequeBank"})
                        {
                            Control input=Find<Control>(form,name);
                            if(input==null||!input.Focus())throw new InvalidOperationException("Cheque sidebar input cannot receive focus: "+name);
                            Application.DoEvents();
                            Control surface=input.Parent is AntdUI.Panel?input.Parent:input;
                            Label caption=Require<Label>(form,name+"Caption");
                            if(caption.Bottom>surface.Top)throw new InvalidOperationException("Cheque caption is below or overlaps its field: "+name);
                            if(surface.Height<44||!clip.RectangleToScreen(clip.ClientRectangle).Contains(surface.RectangleToScreen(surface.ClientRectangle)))
                                throw new InvalidOperationException("Cheque sidebar focused field remains outside viewport: "+name);
                        }
                        Require<AntdUI.Input>(form,"receiptVoucherChequeNumber").Focus();
                        foreach(string next in new[]{"receiptVoucherChequeDate","receiptVoucherChequeStatus","receiptVoucherChequeBank"})
                        {
                            if(!form.SelectNextControl(form.ActiveControl,true,true,true,false)||!Find<Control>(form,next).ContainsFocus)
                                throw new InvalidOperationException("Cheque sidebar Tab order changed at "+next+"; active="+form.ActiveControl?.Name);
                            Application.DoEvents();
                        }
                        resizeOwned(new Size(960,600));
                        Control bank=Require<TextBox>(form,"receiptVoucherChequeBank");
                        Control bankSurface=bank.Parent is AntdUI.Panel?bank.Parent:bank;
                        if(!bank.Focused||!clip.RectangleToScreen(clip.ClientRectangle).Contains(bankSurface.RectangleToScreen(bankSurface.ClientRectangle)))
                            throw new InvalidOperationException("Cheque sidebar resize hides focused bank field: theme="+theme+"; kind="+kind+"; enlarged="+enlarged+"; focused="+bank.Focused+"; clip="+clip.RectangleToScreen(clip.ClientRectangle)+"; field="+bankSurface.RectangleToScreen(bankSurface.ClientRectangle)+"; offset="+themed.YScroll.Value+"; maximum="+themed.YScroll.Maximum+"; host="+Require<Panel>(form,"receiptVoucherSideContent").Bounds);
                        Console.WriteLine("PASS cheque sidebar native frame: "+theme+"/"+english+"/"+kind+"/"+enlarged+"/"+size+"; readable captions and four focused fields.");
                    }
                }
            }
            finally{Properties.Setings.Default.ThemeMode=previous;}
            Console.WriteLine("PASS receipt sidebar 64 native frame cases; owned fixtures, no SQL/native input/DPI/printer acceptance.");
        }

        public static void VerifyReceiptNativeViewportOnly()
        {
            string previous = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool cheque in new[] { false, true })
                foreach (Size size in new[] { new Size(960, 600), new Size(1024, 768), new Size(1366, 768), new Size(1920, 1080) })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var form = new ReceiptVoucherForm("ReceiptExternal", true))
                    {
                        UiDirection.Apply(form, english);
                        form.ApplyReceiptCurrencyPresentation(english);
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show(); Application.DoEvents();
                        OwnedTestWindowViewport.ResizeOuter(form, size);
                        var editor = Require<TableLayoutPanel>(form, "receiptVoucherForm");
                        var methods = editor.Controls.OfType<FlowLayoutPanel>().Single();
                        typeof(ReceiptVoucherForm).GetMethod("SetPaymentMethod", flags).Invoke(form,
                            new object[] { cheque ? "Cheque" : "Cash", methods });
                        form.PerformLayout(); Application.DoEvents();
                        var viewport = Require<ThemedDocumentViewport>(form, "receiptVoucherContentViewport");
                        var toolbar = Require<Panel>(form, "receiptVoucherToolbar");
                        var status = Require<Label>(form, "receiptVoucherStatus");
                        if (viewport.Bottom > status.Top || status.RectangleToScreen(status.ClientRectangle).Bottom >
                            toolbar.RectangleToScreen(toolbar.ClientRectangle).Top)
                            throw new InvalidOperationException("Receipt content/status overlap the persistent footer at " + size);
                        foreach (Panel field in editor.Controls.OfType<Panel>())
                        foreach (Label caption in field.Controls.OfType<Label>())
                        {
                            int height = TextRenderer.MeasureText(caption.Text, caption.Font,
                                new Size(caption.ClientSize.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                            if (caption.Height < height)
                                throw new InvalidOperationException("Receipt caption clips at native frame " + size + ": " + caption.Text);
                        }
                        foreach (AntdUI.Button action in methods.Controls.OfType<AntdUI.Button>())
                            if (!methods.ClientRectangle.Contains(action.Bounds) || action.Height < 44)
                                throw new InvalidOperationException("Receipt payment action clips at native frame " + size + ": " + action.Text);
                        viewport.ScrollControlIntoView(methods);
                        Application.DoEvents();
                        Rectangle visible = viewport.ContentViewport.RectangleToScreen(viewport.ContentViewport.ClientRectangle);
                        if (!visible.Contains(methods.RectangleToScreen(methods.ClientRectangle)))
                            throw new InvalidOperationException("Receipt payment choices remain unreachable at " + size);
                        var history = Require<DataGridView>(form, "receiptVoucherHistory");
                        history.Focus(); viewport.ScrollControlIntoView(history); Application.DoEvents();
                        if (Rectangle.Intersect(visible, history.RectangleToScreen(history.ClientRectangle)).Height < 80)
                            throw new InvalidOperationException("Receipt history remains unreachable at " + size);
                        if (viewport.YScroll.BackColor != UiTheme.Background || viewport.ContentViewport.BackColor != UiTheme.Background || viewport.YScroll.TabStop)
                            throw new InvalidOperationException("Receipt scrollbar does not follow its theme or creates a focus trap.");
                        OwnedTestWindowViewport.ResizeOuter(form, new Size(960, 600));
                        // Pump the pending resize layout like every other step in this check; the
                        // assertion that follows must judge the settled state, not a mid-frame race.
                        Application.DoEvents();
                        form.PerformLayout();
                        // Parallel gate workers activate their own windows, so OS-level focus on an
                        // owned offscreen frame is uncontrollable; the guarded truth is the focus
                        // chain inside the form (ActiveControl), which the app fully owns.
                        bool historyRetainsFocus = history.Focused || ReferenceEquals(form.ActiveControl, history);
                        if (!historyRetainsFocus || Rectangle.Intersect(viewport.ContentViewport.RectangleToScreen(viewport.ContentViewport.ClientRectangle), history.RectangleToScreen(history.ClientRectangle)).Height < 80)
                            throw new InvalidOperationException("Receipt resize hides its focused history at " + size);
                        OwnedTestWindowViewport.ResizeOuter(form, size);
                        if (form.MinimumSize != new Size(960, 600) || form.Size != size)
                            throw new InvalidOperationException("Receipt test changed the declared minimum or native frame.");
                        Console.WriteLine("PASS receipt native frame: " + theme + "/" + english + "/" + cheque + "/" + size + "; captions, payment choices, history and persistent footer.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = previous; }
            Console.WriteLine("PASS receipt 32 native frame cases; owned preview fixtures only, no SQL/native keyboard/DPI/printer acceptance.");
        }

        private static void VerifyReceiptVoucherLayout()
        {
            using (var form = new ReceiptVoucherForm("ReceiptExternal", true))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(960, 600), new Size(1024, 640), new Size(1280, 760) })
                {
                    Prepare(form, size);
                    Panel main = Require<Panel>(form, "receiptVoucherMain");
                    ThemedDocumentViewport contentViewport = Require<ThemedDocumentViewport>(form, "receiptVoucherContentViewport");
                    Panel contentHost = Require<Panel>(form, "receiptVoucherContentHost");
                    if (contentHost.Top != 0 || contentViewport.YScroll.Value != 0)
                        throw new InvalidOperationException("Voucher must open at its first fields after resizing: host=" +
                            contentHost.Bounds + ", position=" + contentViewport.YScroll.Value +
                            ", active=" + form.ActiveControl?.Name + ", historyFocus=" +
                            Require<DataGridView>(form, "receiptVoucherHistory").Focused + ".");
                    Panel side = Require<Panel>(form, "receiptVoucherSide");
                    Panel balancePanel = Require<Panel>(form, "receiptVoucherBalancePanel");
                    Label balanceValue = Require<Label>(form, "receiptVoucherBalance");
                    Panel chequePanel = Require<Panel>(form, "receiptVoucherChequePanel");
                    Label chequeTitle = Require<Label>(form, "receiptVoucherChequeTitle");
                    TableLayoutPanel editor = Require<TableLayoutPanel>(form, "receiptVoucherForm");
                    Panel header = Require<Panel>(form, "receiptVoucherHeader");
                    Label screenTitle = Require<Label>(form, "receiptVoucherScreenTitle");
                    Panel toolbar = Require<Panel>(form, "receiptVoucherToolbar");
                    DataGridView history = Require<DataGridView>(form, "receiptVoucherHistory");
                    ComboBox partyAccount = Require<ComboBox>(form, "receiptVoucherPartyAccount");
                    ComboBox currency = Require<ComboBox>(form, "receiptVoucherCurrency");
                    ComboBox settlementAccount = Require<ComboBox>(form, "receiptVoucherSettlementAccount");
                    Require<AntdUI.Select>(form, "receiptVoucherBranch");
                    Require<ComboBox>(form, "receiptVoucherCostCenter");
                    Require<ComboBox>(form, "receiptVoucherRepresentative");
                    Require<AntdUI.Select>(form, "receiptVoucherChequeStatus");
                    AntdUI.DatePicker voucherDate = Require<AntdUI.DatePicker>(form, "receiptVoucherDate");
                    AntdUI.DatePicker chequeDate = Require<AntdUI.DatePicker>(form, "receiptVoucherChequeDate");
                    AntdUI.Input amount = Require<AntdUI.Input>(form, "receiptVoucherAmount");
                    AntdUI.Input exchangeRate = Require<AntdUI.Input>(form, "receiptVoucherExchangeRate");
                    AntdUI.Input localValue = Require<AntdUI.Input>(form, "receiptVoucherLocalValue");
                    TextBox partyName = Require<TextBox>(form, "receiptVoucherPartyName");
                    Require<TextBox>(form, "receiptVoucherNumber");
                    Require<TextBox>(form, "receiptVoucherNotes");
                    Require<TextBox>(form, "receiptVoucherChequeBank");
                    Require<AntdUI.Input>(form, "receiptVoucherChequeNumber");
                    AntdUI.Button save = FindControlByAccessibleName<AntdUI.Button>(form, "حفظ");
                    AntdUI.Button exit = FindControlByAccessibleName<AntdUI.Button>(form, "خروج");
                    if (chequePanel.Visible || side.Width != (size.Width < 1120 ? 260 : 315))
                        throw new InvalidOperationException("Cash voucher shows irrelevant cheque fields or wastes compact form width at " + size + ".");
                    if (size.Width < 1120)
                    {
                        var selectMethod = typeof(ReceiptVoucherForm).GetMethod("SetPaymentMethod",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                        AntdUI.Button chequeMethod = Require<AntdUI.Button>(form, "receiptVoucherMethod_Cheque");
                        AntdUI.Button cashMethod = Require<AntdUI.Button>(form, "receiptVoucherMethod_Cash");
                        if (selectMethod == null) throw new InvalidOperationException("Voucher payment-method action is missing.");
                        selectMethod.Invoke(form, new object[] { "Cheque", chequeMethod.Parent });
                        form.PerformLayout();
                        if (!chequePanel.Visible || side.Width != 315 || !chequePanel.Enabled)
                            throw new InvalidOperationException("Cheque fields did not appear with adequate width in compact mode: visible=" +
                                chequePanel.Visible + ", sideWidth=" + side.Width + ", enabled=" + chequePanel.Enabled + ".");
                        if (Require<AntdUI.DatePicker>(form, "receiptVoucherChequeDate").Height < 44 || chequePanel.Height < 330)
                            throw new InvalidOperationException("Cheque fields lost their 44-pixel interaction targets.");
                        selectMethod.Invoke(form, new object[] { "Cash", cashMethod.Parent });
                        form.PerformLayout();
                        if (chequePanel.Visible || side.Width != 260)
                            throw new InvalidOperationException("Returning to cash did not restore the compact layout.");
                    }
                    if (header.BackColor != UiTheme.Background || screenTitle.Text != form.Text ||
                        screenTitle.Bounds != header.ClientRectangle ||
                        header.Controls.OfType<AntdUI.Button>().Any() ||
                        header.Bottom > main.Top)
                        throw new InvalidOperationException("Receipt voucher title is not alone at the top at " + size +
                            ": header=" + header.Bounds + ", title=" + screenTitle.Bounds +
                            ", main=" + main.Bounds + ", titleText=" + screenTitle.Text +
                            ", formText=" + form.Text + ", headerButtons=" + header.Controls.OfType<AntdUI.Button>().Count() +
                            ", headerColor=" + header.BackColor + ", themeBackground=" + UiTheme.Background + ".");
                    RequireHorizontallyInside(form, editor, "receipt voucher editor " + size);
                    RequireHorizontallyInside(form, toolbar, "receipt voucher toolbar " + size);
                    RequireHorizontallyInside(form, history, "receipt voucher history " + size);
                    if (editor.Height < 436 || toolbar.Height < 60 || history.Height < 120 || !history.ReadOnly ||
                        !contentViewport.AutoScroll || contentHost.Height < editor.Height + 26 + 120 ||
                        contentViewport.Bottom > toolbar.Top ||
                        partyAccount.RightToLeft != RightToLeft.Yes || settlementAccount.RightToLeft != RightToLeft.Yes ||
                        currency.RightToLeft != RightToLeft.Yes || partyName.RightToLeft != RightToLeft.Yes ||
                        amount.RightToLeft != RightToLeft.No || exchangeRate.RightToLeft != RightToLeft.No ||
                        localValue.RightToLeft != RightToLeft.No || history.Rows.Count != 1 ||
                        voucherDate.RightToLeft != RightToLeft.No || chequeDate.RightToLeft != RightToLeft.No ||
                        !voucherDate.Value.HasValue || !chequeDate.Value.HasValue)
                        throw new InvalidOperationException("Receipt voucher AntdUI, responsive layout, or Arabic/numeric direction policy is invalid at " + size + ".");
                    DateTime documentDate, dueDate;
                    if (!AntdDateInput.TryRead(voucherDate, out documentDate) ||
                        !AntdDateInput.TryRead(chequeDate, out dueDate))
                        throw new InvalidOperationException("Voucher dates are not safely readable at " + size + ".");
                    if (size.Width == 960)
                    {
                        DateTime originalDate = documentDate;
                        voucherDate.Text = "2026/09/23";
                        if (!AntdDateInput.TryRead(voucherDate, out documentDate) ||
                            documentDate != new DateTime(2026, 9, 23))
                            throw new InvalidOperationException("Voucher did not read the visible document date before commit.");
                        voucherDate.Text = "1752/12/31";
                        if (AntdDateInput.TryRead(voucherDate, out documentDate))
                            throw new InvalidOperationException("Voucher accepted a date below the SQL-compatible minimum.");
                        AntdDateInput.SetDate(voucherDate, originalDate);
                        if (!AntdDateInput.TryRead(voucherDate, out documentDate) || documentDate != originalDate)
                            throw new InvalidOperationException("Voucher date reset did not restore visible and stored values.");
                    }
                    int minimumEditorHeight = 436;
                    int minimumInputHeight = 44;
                    if (main.BackColor != UiTheme.Surface || side.BackColor != UiTheme.Surface || balancePanel.BackColor != UiTheme.Surface || balanceValue.ForeColor != UiTheme.Primary || editor.BackColor != UiTheme.Surface || (chequePanel.Visible && chequePanel.BackColor != UiTheme.Surface) || chequeTitle.ForeColor != UiTheme.Text)
                        throw new InvalidOperationException("Receipt voucher content and editor cards must use the active surface palette at " + size + ".");
                    if (editor.Height < minimumEditorHeight)
                        throw new InvalidOperationException("Receipt voucher editor height is " + editor.Height + " at " + size + ".");
                    if (amount.Height < minimumInputHeight)
                        throw new InvalidOperationException("Receipt voucher amount input height is " + amount.Height + " at " + size + ".");
                    foreach (Panel fieldBox in editor.Controls.OfType<Panel>())
                    {
                        Label caption = fieldBox.Controls.OfType<Label>().FirstOrDefault();
                        Control input = fieldBox.Controls.Cast<Control>().FirstOrDefault(control => control != caption);
                        if (caption != null && input != null && (caption.Height < TextRenderer.MeasureText(caption.Text,caption.Font,new Size(caption.ClientSize.Width,int.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height || caption.Bottom > input.Top ||
                            input.Bottom > fieldBox.ClientSize.Height))
                            throw new InvalidOperationException("Receipt voucher field caption overlaps its input at " + size + ": " + caption.Text);
                    }
                    if (exchangeRate.Height < minimumInputHeight)
                        throw new InvalidOperationException("Receipt voucher exchange-rate input height is " + exchangeRate.Height + " at " + size + ".");
                    if (save == null || save.Parent.Parent != toolbar || exit == null ||
                        toolbar.BackColor != UiTheme.Background ||
                        toolbar.Controls.OfType<FlowLayoutPanel>().SelectMany(group => group.Controls.OfType<AntdUI.Button>())
                            .Any(action => action.BorderWidth != 1 || action.DefaultBorderColor != UiTheme.Primary ||
                                action.Height < 44 || action.Width < 44 || action.Type != AntdUI.TTypeMini.Default))
                        throw new InvalidOperationException("Receipt voucher footer actions lost their consistent green outline at " + size + ".");
                    foreach (FlowLayoutPanel group in toolbar.Controls.OfType<FlowLayoutPanel>())
                    {
                        foreach (AntdUI.Button action in group.Controls.OfType<AntdUI.Button>())
                        {
                            if (action.Left < 0 || action.Right > group.ClientSize.Width ||
                                action.Top < 0 || action.Bottom > group.ClientSize.Height)
                                throw new InvalidOperationException("Receipt voucher footer action wraps or clips at " + size + ": " + action.AccessibleName);
                        }
                    }
                }
                var previewSave = (System.Threading.Tasks.Task<int>)typeof(ReceiptVoucherForm).GetMethod("SaveVoucherAsync", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    .Invoke(form, null);
                CompleteUiTask(previewSave);
                if (previewSave.Result != 0)
                    throw new InvalidOperationException("Receipt voucher preview must never save a document.");
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox || form.MinimumSize.Width > 960)
                    throw new InvalidOperationException("Receipt vouchers must remain usable on compact desktop widths with standard window chrome.");
            }
        }
        private static void VerifyGeneralLedgerCheckboxAccessibility()
        {
            string originalTheme = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            var keyUp = typeof(AccessibleAntdCheckbox).GetMethod("OnKeyUp", flags);
            var click = typeof(AccessibleAntdCheckbox).GetMethod("OnClick", flags);
            int layouts = 0;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var form = new GeneralLedgerPreview())
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        form.MaximumSize = Size.Empty;
                        form.ApplyPresentation(english);
                        var filters = Require<TableLayoutPanel>(form, "generalLedgerFilters");
                        AccessibleObject lastAccessible = null;
                        foreach (string name in new[] { "generalLedgerIncludeOpening", "generalLedgerIncludePrevious" })
                        {
                            var box = Require<AccessibleAntdCheckbox>(form, name);
                            int changes = 0, clicks = 0;
                            System.Threading.Tasks.TaskCompletionSource<bool> pendingAccessibilityChange = null;
                            box.CheckedChanged += (sender, args) => { changes++; pendingAccessibilityChange?.TrySetResult(true); };
                            box.Click += (sender, args) => clicks++;
                            string caption = name == "generalLedgerIncludeOpening" ? "الرصيد الافتتاحي" : "الرصيد السابق";
                            if (english) caption = UiLanguageCatalog.Translate(caption);
                            foreach (Size size in new[] { new Size(760, 600), new Size(960, 640), new Size(1366, 768), new Size(1920, 1080) })
                            {
                                Prepare(form, size); Application.DoEvents();
                                RequireInside(filters, box, "ledger checkbox " + name + " at " + size);
                                if (form.ClientSize != size || box.Height != DesktopDesignTokens.InputHeight ||
                                    box.Padding != Padding.Empty || !box.TabStop || box.BackColor != Color.Transparent ||
                                    box.ForeColor != UiTheme.Text || box.Fill != UiTheme.Primary ||
                                    box.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                    box.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                                    box.Text != caption || box.AccessibilityObject.Name != caption ||
                                    box.AccessibilityObject.Role != AccessibleRole.CheckButton ||
                                    TextRenderer.MeasureText(box.Text, box.Font).Width + 30 > box.Width)
                                    throw new Exception("Ledger checkbox layout/accessibility failed: " + name + ", " + theme + ", " + english + ", " + size + ".");
                                bool initial = box.Checked;
                                int before = changes, priorClicks = clicks;
                                if (box.AccessibilityObject.State.HasFlag(AccessibleStates.Checked) != initial)
                                    throw new Exception("Ledger checkbox does not announce its checked state.");
                                box.AccessibilityObject.DoDefaultAction(); Application.DoEvents();
                                if (box.Checked == initial || changes != before + 1 || clicks != priorClicks + 1 ||
                                    box.AccessibilityObject.State.HasFlag(AccessibleStates.Checked) != box.Checked)
                                    throw new Exception("Ledger accessible action must toggle once.");
                                keyUp.Invoke(box, new object[] { new KeyEventArgs(Keys.Space) });
                                if (box.Checked != initial || changes != before + 2)
                                    throw new Exception("Ledger software Space must toggle once.");
                                click.Invoke(box, new object[] { EventArgs.Empty });
                                box.AccessibilityObject.DoDefaultAction();
                                if (box.Checked != initial || changes != before + 4)
                                    throw new Exception("Ledger pointer/access actions changed the filter semantics.");
                                filters.Enabled = false;
                                box.AccessibilityObject.DoDefaultAction();
                                keyUp.Invoke(box, new object[] { new KeyEventArgs(Keys.Space) });
                                click.Invoke(box, new object[] { EventArgs.Empty });
                                if (box.Checked != initial || changes != before + 4 ||
                                    !box.AccessibilityObject.State.HasFlag(AccessibleStates.Unavailable))
                                    throw new Exception("Disabled ledger filters still accept user actions.");
                                filters.Enabled = true;
                                layouts++;
                            }
                            bool retained = box.Checked; int count = changes;
                            Properties.Setings.Default.ThemeMode = Properties.Setings.Default.ThemeMode == "Light" ? "Dark" : "Light";
                            UiTheme.Apply(form);
                            if (box.Checked != retained || changes != count || box.Text != caption ||
                                box.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                                box.BackColor != Color.Transparent || box.ForeColor != UiTheme.Text || box.Fill != UiTheme.Primary)
                                throw new Exception("Live ledger theme changed a filter or lost its shared appearance.");
                            form.ApplyPresentation(!english); form.ApplyPresentation(english);
                            if (box.Checked != retained || changes != count || box.Text != caption)
                                throw new Exception("Ledger direction switch changed the filter or caption.");
                            lastAccessible = box.AccessibilityObject;
                            var accessible = lastAccessible;
                            // DoDefaultAction posts with BeginInvoke. Worker completion only proves scheduling;
                            // wait for the owned control's actual change, then keep exact once/count checks.
                            pendingAccessibilityChange = new System.Threading.Tasks.TaskCompletionSource<bool>();
                            try
                            {
                                CompleteUiTask(System.Threading.Tasks.Task.Run(() => accessible.DoDefaultAction()));
                                DateTime dispatchDeadline = DateTime.UtcNow.AddSeconds(10);
                                while (!pendingAccessibilityChange.Task.IsCompleted && DateTime.UtcNow < dispatchDeadline)
                                { Application.DoEvents(); System.Threading.Thread.Sleep(1); }
                                if (!pendingAccessibilityChange.Task.IsCompleted)
                                    throw new Exception("Ledger background accessibility dispatch did not complete: " + name +
                                        "; theme=" + theme + "; english=" + english + "; handle=" + box.IsHandleCreated +
                                        "; visible=" + box.Visible + "; enabled=" + box.Enabled + "; disposed=" + box.IsDisposed +
                                        "; checked=" + box.Checked + "; retained=" + retained + "; changes=" + changes + "; before=" + count + ".");
                                pendingAccessibilityChange.Task.GetAwaiter().GetResult(); Application.DoEvents();
                            }
                            finally { pendingAccessibilityChange = null; }
                            if (box.Checked == retained || changes != count + 1)
                                throw new Exception("Ledger background access action failed to dispatch once.");
                            accessible.DoDefaultAction();
                            if (box.Checked != retained || changes != count + 2)
                                throw new Exception("Ledger access action did not restore the filter.");
                        }
                        form.Close(); lastAccessible.DoDefaultAction();
                        if (!form.IsDisposed || !lastAccessible.State.HasFlag(AccessibleStates.Unavailable))
                            throw new Exception("Disposed ledger checkbox accessibility remains active.");
                    }
                }
                Console.WriteLine("PASS ledger checkbox: " + layouts + " actual-size layouts, checked/default action/Space/click, disabled parent, thread/disposal, theme/direction and captions; no SQL/native input.");
            }
            finally { Properties.Setings.Default.ThemeMode = originalTheme; }
        }
        private static void VerifyGeneralLedgerLayout()
        {
            using (var form = new GeneralLedgerForm())
            {
                foreach (Size size in new[] { new Size(760, 600), new Size(960, 600), new Size(1280, 760) })
                {
                    Prepare(form, size);
                    Panel top = Require<Panel>(form, "generalLedgerTop");
                    Panel footer = Require<Panel>(form, "generalLedgerActionsHost");
                    TableLayoutPanel filters = Require<TableLayoutPanel>(form, "generalLedgerFilters");
                    FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "generalLedgerActions");
                    FlowLayoutPanel summary = Require<FlowLayoutPanel>(form, "generalLedgerSummary");
                    DataGridView grid = Require<DataGridView>(form, "generalLedgerGrid");
                    Label status = Require<Label>(form, "generalLedgerStatus");
                    ComboBox account = Require<ComboBox>(form, "generalLedgerAccount");
                    AntdUI.Select sortBy = Require<AntdUI.Select>(form, "generalLedgerSortBy");
                    AntdUI.Select documentType = Require<AntdUI.Select>(form, "generalLedgerDocumentType");
                    AntdUI.DatePicker fromDate = Require<AntdUI.DatePicker>(form, "generalLedgerFromDate");
                    AntdUI.DatePicker toDate = Require<AntdUI.DatePicker>(form, "generalLedgerToDate");
                    RequireHorizontallyInside(form, top, "general ledger top " + size);
                    RequireHorizontallyInside(form, footer, "general ledger footer " + size);
                    RequireHorizontallyInside(form, filters, "general ledger filters " + size);
                    RequireHorizontallyInside(form, actions, "general ledger actions " + size);
                    RequireHorizontallyInside(form, summary, "general ledger summary " + size);
                    RequireHorizontallyInside(form, grid, "general ledger grid " + size);
                    if (filters.ColumnCount != 4 || filters.Height < 176 || actions.Controls.Count != 4 ||
                        summary.Height < 108 || !grid.ReadOnly ||
                         footer.Dock != DockStyle.Bottom || footer.Bottom != form.ClientSize.Height ||
                         actions.Parent != footer || grid.Bottom > footer.Top ||
                         !top.Controls.OfType<Label>().Any(label => label.Text == "حركة حساب خلال فترة" && label.Top == 0) ||
                         string.IsNullOrWhiteSpace(status.Name) ||
                         account.RightToLeft != RightToLeft.No)
                        throw new InvalidOperationException("General ledger layout or RTL input policy is invalid at " + size +
                            ": columns=" + filters.ColumnCount + ", filtersHeight=" + filters.Height +
                            ", actions=" + actions.Controls.Count + ", summaryHeight=" + summary.Height +
                            ", gridReadOnly=" + grid.ReadOnly + ", status=" + status.Name +
                            ", accountRTL=" + account.RightToLeft + ".");
                    if (form.Controls.Find("generalLedgerCurrency", true).Length != 0 ||
                        filters.Controls.OfType<Panel>().SelectMany(panel => panel.Controls.OfType<Label>())
                            .Any(label => label.Text == "الفرع" || label.Text == "العملة" || label.Text == "نوع الطباعة"))
                        throw new InvalidOperationException("General ledger shows filters that do not affect its query at " + size + ".");
                    if (top.Height > 400 || grid.Height < 100 || summary.HorizontalScroll.Visible ||
                        form.Controls.Find("generalLedgerModes", true).Length != 0)
                        throw new InvalidOperationException("General ledger leaves too little room for data or shows nonfunctional modes at " + size + ".");
                    if (top.BackColor != UiTheme.Surface || filters.BackColor != UiTheme.Surface ||
                        summary.BackColor != UiTheme.SurfaceVariant ||
                        Require<AntdUI.Checkbox>(form, "generalLedgerIncludeOpening").ForeColor != UiTheme.Text ||
                        Require<AntdUI.Checkbox>(form, "generalLedgerIncludePrevious").ForeColor != UiTheme.Text)
                        throw new InvalidOperationException("General ledger filter and summary surfaces do not follow the theme at " + size + ".");
                    foreach (AntdUI.Panel card in summary.Controls.OfType<AntdUI.Panel>())
                    {
                        if (!card.Controls.OfType<Label>().Any(label => label.Font.Bold && label.ForeColor == UiTheme.Text))
                            throw new InvalidOperationException("General ledger summary title is unreadable in the current theme at " + size + ".");
                        if (card.Left < 0 || card.Right > summary.ClientSize.Width)
                            throw new InvalidOperationException("General ledger summary requires horizontal scrolling at " + size + ".");
                    }
                    if (fromDate.Height < 44 || toDate.Height < 44 || fromDate.RightToLeft != RightToLeft.No ||
                        toDate.RightToLeft != RightToLeft.No || !fromDate.Value.HasValue || !toDate.Value.HasValue)
                        throw new InvalidOperationException("General ledger date fields lost their accessible AntdUI layout at " + size + ".");
                    if (sortBy.Height < 44 || documentType.Height < 44 || sortBy.Items.Count != 2 ||
                        documentType.Items.Count != 6 || sortBy.SelectedIndex != 0 || documentType.SelectedIndex != 0)
                        throw new InvalidOperationException("General ledger sort and source selectors lost their AntdUI defaults at " + size + ".");
                    if (actions.FlowDirection != (UiDirection.IsLeftToRight ? FlowDirection.LeftToRight : FlowDirection.RightToLeft))
                        throw new InvalidOperationException("General ledger actions are not ordered from the reading edge at " + size + ".");
                    foreach (Control control in actions.Controls)
                    {
                        AntdUI.Button action = control as AntdUI.Button;
                        if (action == null || action.Height < 44 || action.BorderWidth != 1 ||
                            action.DefaultBorderColor != UiTheme.Primary || string.IsNullOrWhiteSpace(action.IconSvg) ||
                            string.IsNullOrWhiteSpace(action.AccessibleName))
                            throw new InvalidOperationException("General ledger action lost its accessible outlined style at " + size +
                                ": type=" + control.GetType().Name + ", height=" + (action == null ? -1 : action.Height) +
                                ", border=" + (action == null ? -1F : action.BorderWidth) +
                                ", color=" + (action == null ? Color.Empty : action.DefaultBorderColor) +
                                ", icon=" + (action != null && !string.IsNullOrWhiteSpace(action.IconSvg)) +
                                ", name=" + (action == null ? string.Empty : action.AccessibleName) + ".");
                        RequireInside(actions, action, "general ledger action " + size);
                    }
                }
                AntdUI.DatePicker start = Require<AntdUI.DatePicker>(form, "generalLedgerFromDate");
                AntdUI.DatePicker end = Require<AntdUI.DatePicker>(form, "generalLedgerToDate");
                AntdUI.Select sourceType = Require<AntdUI.Select>(form, "generalLedgerDocumentType");
                ComboBox selectedAccount = Require<ComboBox>(form, "generalLedgerAccount");
                ComboBox selectedCostCenter = Require<ComboBox>(form, "generalLedgerCostCenter");
                selectedAccount.Items.Add("1100 - الصندوق Cash");
                selectedAccount.SelectedIndex = 0;
                selectedCostCenter.Items.Add("الكل");
                selectedCostCenter.Items.Add("بدون مركز تكلفة");
                selectedCostCenter.Items.Add("10 - الفرع الرئيسي");
                selectedCostCenter.SelectedIndex = 2;
                var readAccount = typeof(GeneralLedgerForm).GetMethod("SelectedAccount", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                var readCostCenter = typeof(GeneralLedgerForm).GetMethod("SelectedLedgerCostCenterId", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (readAccount == null || readCostCenter == null ||
                    !string.Equals((string)readAccount.Invoke(form, null), "1100", StringComparison.Ordinal) ||
                    (int?)readCostCenter.Invoke(form, null) != 10)
                    throw new InvalidOperationException("General ledger selectors changed account or cost-center identifiers.");
                var readSource = typeof(GeneralLedgerForm).GetMethod("SelectedLedgerSourceType", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (readSource == null) throw new InvalidOperationException("General ledger source mapping is unavailable.");
                sourceType.SelectedIndex = 3;
                if (!string.Equals((string)readSource.Invoke(form, null), "SalesInvoice", StringComparison.Ordinal))
                    throw new InvalidOperationException("Localized ledger source text changed the query code.");
                sourceType.SelectedIndex = 0;
                Label dateStatus = Require<Label>(form, "generalLedgerStatus");
                var readDates = typeof(GeneralLedgerForm).GetMethod("TryGetDateRange", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (readDates == null) throw new InvalidOperationException("General ledger date validation is unavailable.");
                start.Value = null;
                if ((bool)readDates.Invoke(form, new object[] { DateTime.MinValue, DateTime.MinValue }) ||
                    !dateStatus.Text.Contains("اختر تاريخ"))
                    throw new InvalidOperationException("General ledger accepted an empty date.");
                var loadData = typeof(GeneralLedgerForm).GetMethod("LoadDataAsync", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                var loadGeneration = typeof(GeneralLedgerForm).GetField("ledgerLoadGeneration", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (loadData == null || loadGeneration == null) throw new InvalidOperationException("General ledger request invalidation is unavailable.");
                int previousGeneration = (int)loadGeneration.GetValue(form);
                ((System.Threading.Tasks.Task)loadData.Invoke(form, null)).GetAwaiter().GetResult();
                if ((int)loadGeneration.GetValue(form) != previousGeneration + 1)
                    throw new InvalidOperationException("Invalid ledger filters did not invalidate the previous request.");
                start.Value = new DateTime(2026, 9, 2);
                end.Value = new DateTime(2026, 9, 1);
                if ((bool)readDates.Invoke(form, new object[] { DateTime.MinValue, DateTime.MinValue }) ||
                    !dateStatus.Text.Contains("تاريخ البداية"))
                    throw new InvalidOperationException("General ledger accepted an inverted date range.");
                end.Value = new DateTime(2026, 9, 3);
                var printReport = typeof(GeneralLedgerForm).GetMethod("PrintReport", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (printReport == null) throw new InvalidOperationException("General ledger print action is unavailable.");
                printReport.Invoke(form, null);
                if (!dateStatus.Text.Contains("لا توجد حركات"))
                    throw new InvalidOperationException("General ledger attempted to print without loaded rows.");
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox || form.MinimumSize.Width > 960)
                    throw new InvalidOperationException("General ledger must support compact desktop widths with standard window chrome.");
            }
        }
        private static void VerifyAccountingHomePresentation()
        {
            string previousMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var form = new AccountingHomeForm())
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show();
                        var footer = Require<FlowLayoutPanel>(form, "accountingHomeFooter");
                        var close = Require<AntdUI.Button>(form, "closeButton");
                        var tabs = Require<FlowLayoutPanel>(form, "tabs");
                        var heading = Require<Label>(form, "titleLabel");
                        var grid = Require<TableLayoutPanel>(form, "tileGrid");
                        foreach (Size size in new[] { new Size(760, 640), new Size(1024, 768), new Size(1366, 768) })
                        foreach (int page in new[] { 1, 2, 3 })
                        {
                            Prepare(form, size); Application.DoEvents();
                            Require<AntdUI.Button>(form, "accountingPageTab" + page).AccessibilityObject.DoDefaultAction(); Application.DoEvents();
                            int invokedPage=(int)typeof(AccountingHomeForm).GetField("activePage",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(form);
                            if(invokedPage!=page)throw new InvalidOperationException("Accounting home invocation did not select the requested page.");
                            var stableTiles = grid.Controls.Cast<Control>().ToArray();
                            var stableTabs = tabs.Controls.Cast<Control>().ToArray();
                            var stableCells=stableTiles.ToDictionary(tile=>tile,tile=>grid.GetPositionFromControl(tile));
                            var stableTabOrder=stableTabs.ToDictionary(tab=>tab,tab=>tab.TabIndex);
                            var rawNames = stableTiles.Select(tile => tile.Tag.GetType().GetProperty("Title").GetValue(tile.Tag, null).ToString()).ToArray();
                            foreach (bool english in new[] { false, true, false })
                            {
                                form.ApplyPresentation(english); Application.DoEvents();
                                if(grid.Controls.Count!=stableTiles.Length||tabs.Controls.Count!=stableTabs.Length||
                                    stableTiles.Any(tile=>!grid.Controls.Contains(tile)||grid.GetPositionFromControl(tile)!=stableCells[tile])||
                                    stableTabs.Any(tab=>!tabs.Controls.Contains(tab)||tab.TabIndex!=stableTabOrder[tab]))
                                    throw new InvalidOperationException("Accounting language change recreated navigation controls or changed their semantic positions/tab order.");
                                if (form.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                    grid.RightToLeft != form.RightToLeft || heading.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                                    tabs.FlowDirection != (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft) || footer.FlowDirection != tabs.FlowDirection ||
                                    heading.Text != (english ? UiLanguageCatalog.Translate("نظام الحسابات") : "نظام الحسابات"))
                                    throw new InvalidOperationException("Accounting center direction/title/navigation does not follow its language.");
                                if (close.Parent != footer || close.Height < 44 || close.BorderWidth != 1 || string.IsNullOrWhiteSpace(close.IconSvg) ||
                                    close.Text != (english ? UiLanguageCatalog.Translate("إغلاق") : "إغلاق") ||
                                    !footer.ClientRectangle.Contains(close.Bounds) || footer.Top < heading.Parent.Bottom || grid.Bottom > footer.Top ||
                                    footer.BackColor != UiTheme.Surface)
                                    throw new InvalidOperationException("Accounting center footer is clipped or inconsistent with the design system.");
                                for (int index = 0; index < stableTiles.Length; index++)
                                {
                                    var action = (AntdUI.Button)stableTiles[index];
                                    string expected = english ? UiLanguageCatalog.Translate(rawNames[index]) : rawNames[index];
                                    if (action.AccessibleName != expected || !action.Text.StartsWith(expected, StringComparison.Ordinal) ||
                                        string.IsNullOrWhiteSpace(action.IconSvg) || !grid.ClientRectangle.Contains(action.Bounds) || action.Height < 44)
                                        throw new InvalidOperationException("Accounting center tile caption/icon does not follow language or fit its grid.");
                                }
                            }
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = previousMode;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        private static void VerifyAccountingHomeLayout()
        {
            using (var form = new AccountingHomeForm())
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (int width in new[] { 760, 900, 1100 })
                {
                    OwnedTestWindowViewport.Resize(form, new Size(width, 720));
                    form.PerformLayout();
                    Label heading = Require<Label>(form, "titleLabel");
                    AntdUI.Button closeAction = Require<AntdUI.Button>(form, "closeButton");
                    if (closeAction.Parent.Top < heading.Parent.Bottom || heading.Width < 240 ||
                        !heading.Parent.ClientRectangle.Contains(heading.Bounds) ||
                        !closeAction.Parent.ClientRectangle.Contains(closeAction.Bounds))
                        throw new InvalidOperationException("Accounting header title overlaps its close action at width " + width + ".");
                    TableLayoutPanel grid = Require<TableLayoutPanel>(form, "tileGrid");
                    int availableWidth = Math.Max(0, grid.ClientSize.Width - grid.Padding.Horizontal);
                    int expectedColumns = availableWidth >= 960 ? 3 : availableWidth >= 620 ? 2 : 1;
                    if (grid.ColumnCount != expectedColumns)
                        throw new InvalidOperationException("Accounting home grid does not adapt at width " + width + ".");
                    if (grid.Controls.Count != 6)
                        throw new InvalidOperationException("Accounting home is missing its voucher and account tiles.");
                    AntdUI.Button firstTab = Require<AntdUI.Button>(form, "accountingPageTab1");
                    AntdUI.Button secondTab = Require<AntdUI.Button>(form, "accountingPageTab2");
                    AntdUI.Button thirdTab = Require<AntdUI.Button>(form, "accountingPageTab3");
                    if (firstTab.Height < 44 || firstTab.DefaultBorderColor != UiTheme.Primary ||
                        (UiDirection.IsLeftToRight
                            ? firstTab.Left >= secondTab.Left || secondTab.Left >= thirdTab.Left
                            : firstTab.Left <= secondTab.Left || secondTab.Left <= thirdTab.Left))
                        throw new InvalidOperationException("Accounting tabs lost their active style or leading-side order at width " + width + ".");
                    foreach (Control tile in grid.Controls)
                    {
                        AntdUI.Button action = tile as AntdUI.Button;
                        if (!(action is AccessibleAntdButton) || string.IsNullOrWhiteSpace(action.IconSvg) || action.BorderWidth != 1 ||
                            action.Radius != DesktopDesignTokens.CardRadius || !action.TabStop ||
                            string.IsNullOrWhiteSpace(action.AccessibleName))
                            throw new InvalidOperationException("Accounting home tile lost its accessible outlined action treatment.");
                        if (action.Left < 0 || action.Top < 0 || action.Right > grid.ClientSize.Width || action.Bottom > grid.ClientSize.Height)
                            throw new InvalidOperationException("Accounting home tile exceeds the grid at width " + width + ".");
                    }
                }
                var click = typeof(Control).GetMethod("OnClick", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (click == null) throw new InvalidOperationException("Accounting tab click cannot be verified.");
                AntdUI.Button accountsTab = Require<AntdUI.Button>(form, "accountingPageTab1");
                AntdUI.Button journalTab = Require<AntdUI.Button>(form, "accountingPageTab2");
                AntdUI.Button reportsTab = Require<AntdUI.Button>(form, "accountingPageTab3");
                Control previousTile = Require<TableLayoutPanel>(form, "tileGrid").Controls[0];
                journalTab.AccessibilityObject.DoDefaultAction();
                if (!previousTile.IsDisposed)
                    throw new InvalidOperationException("Accounting home retains old tile icons after switching tabs.");
                if (!ReferenceEquals(accountsTab, Require<AntdUI.Button>(form, "accountingPageTab1")) ||
                    !ReferenceEquals(journalTab, Require<AntdUI.Button>(form, "accountingPageTab2")) ||
                    journalTab.DefaultBorderColor != UiTheme.Primary ||
                    accountsTab.DefaultBorderColor != UiTheme.Border ||
                    !journalTab.AccessibleDescription.StartsWith("التبويب الحالي.", StringComparison.Ordinal))
                    throw new InvalidOperationException("Accounting tabs were recreated or did not update their selected state.");
                if (Require<TableLayoutPanel>(form, "tileGrid").Controls.Count != 4)
                    throw new InvalidOperationException("Accounting journals tab did not show its four actions.");
                Control journalTile = Require<TableLayoutPanel>(form, "tileGrid").Controls[0];
                journalTab.AccessibilityObject.DoDefaultAction();
                if (!ReferenceEquals(journalTile, Require<TableLayoutPanel>(form, "tileGrid").Controls[0]))
                    throw new InvalidOperationException("Clicking the active accounting tab rebuilt its tiles.");
                reportsTab.AccessibilityObject.DoDefaultAction();
                if (Require<TableLayoutPanel>(form, "tileGrid").Controls.Count != 8)
                    throw new InvalidOperationException("Accounting reports tab did not show its eight actions.");
                OwnedTestWindowViewport.Resize(form, new Size(760, 640));
                form.PerformLayout();
                TableLayoutPanel compactReports = Require<TableLayoutPanel>(form, "tileGrid");
                foreach (Control tile in compactReports.Controls)
                    if (tile.Right > compactReports.ClientSize.Width || tile.Bottom > compactReports.ClientSize.Height ||
                        tile.Height < 44 || !(tile is AntdUI.Button) ||
                        ((AntdUI.Button)tile).IconPosition != AntdUI.TAlignMini.Right)
                        throw new InvalidOperationException("Accounting reports tab clips an action at 760×640.");
                accountsTab.AccessibilityObject.DoDefaultAction();
                if (Require<TableLayoutPanel>(form, "tileGrid").Controls.Count != 6)
                    throw new InvalidOperationException("Accounting vouchers tab did not restore its six actions.");
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox ||
                    form.MinimumSize.Width > 760 || form.MinimumSize.Height > 600)
                    throw new InvalidOperationException("Accounting home must support standard resize, maximize, and minimize.");
            }
        }

        private static void VerifyAccountingCloseActions()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var quick = new JournalEntriesQuickForm(true))
                    using (var voucher = new VoucherForm("ReceiptExternal", true, english))
                    {
                        quick.ApplyQuickPresentation(english);
                        foreach (Form form in new Form[] { quick, voucher })
                        {
                            form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                            form.Location = new Point(-20000, -20000); form.Show();
                            foreach (Size size in new[] { new Size(960, 640), new Size(1024, 768), new Size(1366, 768), new Size(1920, 1080) })
                            {
                                Prepare(form, size); if (form == quick) quick.ApplyQuickJournalLayout();
                                Application.DoEvents();
                                var close = Require<AntdUI.Button>(form, "accountingDataCloseButton");
                                var footer = close.Parent; var header = Require<Panel>(form, "accountingDataHeader");
                                if (form.ClientSize != size || close.Height != 44 || close.Left < 0 || close.Right > footer.ClientSize.Width ||
                                    close.Top < 0 || close.Bottom > footer.ClientSize.Height ||
                                    !form.RectangleToScreen(form.ClientRectangle).Contains(footer.RectangleToScreen(footer.ClientRectangle)) ||
                                    footer.PointToScreen(Point.Empty).Y <= header.PointToScreen(new Point(0, header.Height)).Y || close.Text != (english ? "Close" : "إغلاق") ||
                                    close.AccessibleName != close.Text || close.BorderWidth != 1 || close.Radius <= 0 ||
                                    close.ForeColor != UiTheme.Primary || close.DefaultBack != UiTheme.Surface ||
                                    string.IsNullOrWhiteSpace(close.IconSvg) || !close.TabStop ||
                                    close.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right) ||
                                    TextRenderer.MeasureText(close.Text, close.Font).Width + 32 > close.ClientSize.Width)
                                    throw new InvalidOperationException("Shared accounting close is clipped, unthemed or untranslated at " + mode + "/" + english + "/" + size);
                                foreach (Control sibling in footer.Controls)
                                    if (sibling != close && sibling.Visible && sibling.Bounds.IntersectsWith(close.Bounds))
                                        throw new InvalidOperationException("Accounting footer actions overlap.");
                                if (form == voucher && (english ? close.Left > 16 : close.Right < footer.ClientSize.Width - 16))
                                    throw new InvalidOperationException("Accounting close is not on the language reading edge.");
                            }
                            bool rejected = false;
                            FormClosingEventHandler guard = (sender, args) => { rejected = true; args.Cancel = true; };
                            form.FormClosing += guard; closeAction(form);
                            if (!rejected || !form.Visible || form.IsDisposed)
                                throw new InvalidOperationException("Antd accounting close bypassed the existing closing guard.");
                            form.FormClosing -= guard; closeAction(form);
                            if (!form.IsDisposed) throw new InvalidOperationException("Accounting close did not close the form after guard release.");
                        }
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; }
        }
        private static void closeAction(Form form)
        {
            var close = Require<AntdUI.Button>(form, "accountingDataCloseButton");
            typeof(Control).GetMethod("OnClick", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                .Invoke(close, new object[] { EventArgs.Empty });
        }

        private static void VerifyInventoryAntdMetricCards()
        {
            InventoryMetricValueSelfTests.Verify();
            string original = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            var setSummary = typeof(InventoryDataForm).GetMethod("SetSummary", flags);
            var apply = typeof(InventoryDataForm).GetMethod("ApplyInventoryPresentation", flags);
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (Func<InventoryDataForm> create in new Func<InventoryDataForm>[] {
                    () => new InventoryStockReportForm(false, false), () => new InventoryStockReportForm(true, false),
                    () => new InventoryMovementForm(false), () => new InventoryMovementSummaryForm(false),
                    () => new InventoryAlertsForm(false), () => new InventoryTurnoverForm(false),
                    () => new InventoryOperationForm(InventoryOperationMode.Adjustment, false) })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var form = create())
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show();
                        setSummary.Invoke(form, new object[] { new[] {
                            new InventorySummaryItem("إجمالي الوارد", "1,250.125"),
                            new InventorySummaryItem("إجمالي الصادر", "0.125"),
                            new InventorySummaryItem("صافي الحركة", "-1,250.125"),
                            new InventorySummaryItem("الرصيد الحالي", "9,999,999.125") } });
                        foreach (Size size in new[] { new Size(640, 480), new Size(960, 640), new Size(1366, 768), new Size(1920, 1080) })
                        {
                            apply.Invoke(form, new object[] { !english }); apply.Invoke(form, new object[] { english }); OwnedTestWindowViewport.Resize(form, size); Application.DoEvents();
                            var host = Require<FlowLayoutPanel>(form, "inventoryDataSummary");
                            host.AutoScrollPosition = Point.Empty; Application.DoEvents();
                            if (form.ClientSize != size || host.Controls.Count != 4 || host.RightToLeft != RightToLeft.No ||
                                host.FlowDirection != (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft))
                                throw new InvalidOperationException("Inventory metric direction or fixture mismatch: " + form.GetType().Name + "/" + english + "/" + size + "; actual=" + form.ClientSize + "; cards=" + host.Controls.Count + "; RTL=" + host.RightToLeft + "; flow=" + host.FlowDirection);
                            string[] expectedValues = { "1,250.125", "0.125", "-1,250.125", "9,999,999.125" };
                            for (int index = 0; index < expectedValues.Length; index++)
                                if (Require<Label>(host.Controls[index], "inventoryMetricValue").Text != expectedValues[index])
                                    throw new InvalidOperationException("Inventory metric changed the supplied number text.");
                            var first = host.Controls[0];
                            if (Require<Label>(first, "inventoryMetricTitle").Text != (english ? "Total received" : "إجمالي الوارد"))
                                throw new InvalidOperationException("Inventory metric did not preserve its original caption for translation.");
                            foreach (Control child in host.Controls)
                            {
                                var card = child as AntdUI.Panel;
                                var title = Require<Label>(child, "inventoryMetricTitle"); var value = Require<Label>(child, "inventoryMetricValue");
                                if (card == null || card.Shadow != 0 || card.Radius != DesktopDesignTokens.CardRadius ||
                                    card.BackColor != UiTheme.Surface || card.Height != 96 || card.Left < 0 || card.Right > host.ClientSize.Width ||
                                    value.RightToLeft != RightToLeft.No || title.TextAlign != ContentAlignment.MiddleCenter || value.TextAlign != ContentAlignment.MiddleCenter || title.Bounds.IntersectsWith(value.Bounds) ||
                                    !card.ClientRectangle.Contains(title.Bounds) || !card.ClientRectangle.Contains(value.Bounds) ||
                                    TextRenderer.MeasureText(value.Text, value.Font).Width > value.ClientSize.Width ||
                                    TextRenderer.MeasureText(title.Text, title.Font, new Size(title.Width, int.MaxValue), TextFormatFlags.WordBreak).Height > title.Height ||
                                    card.AccessibleName != title.Text + ": " + value.Text)
                                    throw new InvalidOperationException("Inventory metric clips data or loses AntdUI theme at " + form.GetType().Name + "/" + mode + "/" + english + "/" + size);
                                foreach (Control other in host.Controls)
                                    if (other != card && card.Bounds.IntersectsWith(other.Bounds)) throw new Exception("Inventory metric cards overlap.");
                            }
                            var last = host.Controls[host.Controls.Count - 1]; host.ScrollControlIntoView(last); Application.DoEvents();
                            if (!host.RectangleToScreen(host.ClientRectangle).Contains(last.RectangleToScreen(last.ClientRectangle)))
                                throw new InvalidOperationException("Last inventory metric is not reachable: " + form.GetType().Name + "/" + english + "/" + size + "; host=" + host.ClientRectangle + "; display=" + host.DisplayRectangle + "; scroll=" + host.AutoScrollPosition + "; last=" + last.Bounds);
                            if (Require<DataGridView>(form, "inventoryDataGrid").Height < 80)
                                throw new InvalidOperationException("Inventory metric cards displaced the usable grid viewport: " + form.GetType().Name + "/" + mode + "/" + english + "/" + size + "; grid=" + Require<DataGridView>(form, "inventoryDataGrid").Bounds);
                        }
                        Properties.Setings.Default.ThemeMode = mode == "Light" ? "Dark" : "Light";
                        UiTheme.Apply(form); Application.DoEvents();
                        var themedHost = Require<FlowLayoutPanel>(form, "inventoryDataSummary");
                        foreach (Control card in themedHost.Controls)
                        {
                            var title = Require<Label>(card, "inventoryMetricTitle"); var value = Require<Label>(card, "inventoryMetricValue");
                            if (card.BackColor != UiTheme.Surface || title.ForeColor != UiTheme.MutedText || value.ForeColor != UiTheme.Primary ||
                                title.TextAlign != ContentAlignment.MiddleCenter || value.TextAlign != ContentAlignment.MiddleCenter ||
                                themedHost.RightToLeft != RightToLeft.No)
                                throw new InvalidOperationException("Live inventory theme reapplication lost metric colors, alignment or single RTL flow.");
                        }
                        Properties.Setings.Default.ThemeMode = mode;
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; }
        }

        private static void VerifyInventoryActionFooters()
        {
            string original = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            var apply = typeof(InventoryDataForm).GetMethod("ApplyInventoryPresentation", flags);
            var click = typeof(Control).GetMethod("OnClick", flags);
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (Func<InventoryDataForm> create in new Func<InventoryDataForm>[] {
                    () => new InventoryStockReportForm(false, false), () => new InventoryStockReportForm(true, false),
                    () => new InventoryMovementForm(false), () => new InventoryMovementSummaryForm(false),
                    () => new InventoryAlertsForm(false), () => new InventoryTurnoverForm(false),
                    () => new InventoryOperationForm(InventoryOperationMode.Adjustment, false) })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var form = create())
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show();
                        foreach (Size size in new[] { new Size(640, 480), new Size(960, 640), new Size(1366, 768), new Size(1920, 1080) })
                        {
                            apply.Invoke(form, new object[] { english }); Prepare(form, size); Application.DoEvents();
                            var footer = form.Controls.OfType<FlowLayoutPanel>().Single(panel => panel.Name.EndsWith("Footer", StringComparison.Ordinal));
                            var actions = footer.Controls.OfType<AntdUI.Button>().ToArray();
                            var close = Require<AntdUI.Button>(footer, "inventoryDataCloseButton");
                            if (actions.Length != (form is InventoryOperationForm ? 2 : 4) || footer.Controls.Count != actions.Length ||
                                footer.Bottom != form.ClientSize.Height || footer.RightToLeft != RightToLeft.No ||
                                footer.FlowDirection != (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft) ||
                                close.Text != (english ? "Close" : "إغلاق") || !close.Visible || !close.Enabled ||
                                Require<DataGridView>(form, "inventoryDataGrid").Height < 80)
                                throw new InvalidOperationException("Inventory footer contract failed: " + form.GetType().Name + "/" + mode + "/" + english + "/" + size);
                            foreach (var action in actions)
                            {
                                if (!footer.ClientRectangle.Contains(action.Bounds) || action.Height != DesktopDesignTokens.ActionHeight ||
                                    action.Radius <= 0 || string.IsNullOrWhiteSpace(action.IconSvg) || action.AccessibleName != action.Text ||
                                    TextRenderer.MeasureText(action.Text, action.Font).Width + 32 > action.Width ||
                                    action.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right))
                                    throw new InvalidOperationException("Inventory footer action clips or loses presentation: " + action.Name + "/" + english + "/" + size + "; bounds=" + action.Bounds + "; footer=" + footer.ClientRectangle);
                                foreach (var other in actions)
                                    if (other != action && action.Bounds.IntersectsWith(other.Bounds)) throw new Exception("Inventory footer actions overlap.");
                                if ((action.Name.IndexOf("Print", StringComparison.OrdinalIgnoreCase) >= 0 || action.Name.IndexOf("Export", StringComparison.OrdinalIgnoreCase) >= 0) && action.Enabled)
                                    throw new Exception("Inventory output enabled without report rows.");
                            }
                            if (english ? close.Left != actions.Min(action => action.Left) : close.Right != actions.Max(action => action.Right))
                                throw new Exception("Inventory close is not at the language's leading footer edge.");
                        }
                        var sharedFooter = form.Controls.OfType<FlowLayoutPanel>().Single(panel => panel.Name.EndsWith("Footer", StringComparison.Ordinal));
                        var retainedClose = Require<AntdUI.Button>(sharedFooter, "inventoryDataCloseButton");
                        Properties.Setings.Default.ThemeMode = mode == "Light" ? "Dark" : "Light";
                        UiTheme.Apply(form); apply.Invoke(form, new object[] { english }); Prepare(form, new Size(640, 480));
                        if (sharedFooter.BackColor != UiTheme.Surface || sharedFooter.Controls.OfType<AntdUI.Button>().Count(action => action.Name == retainedClose.Name) != 1)
                            throw new Exception("Inventory live theme duplicated close or lost footer color.");
                        int restoredFooterHeight = sharedFooter.Height;
                        var restoredActionBounds = sharedFooter.Controls.Cast<Control>().ToDictionary(action => action.Name, action => action.Bounds);
                        retainedClose.Text = english ? "Close this inventory report safely" : "إغلاق تقرير المخزون والعودة بأمان";
                        Application.DoEvents();
                        if (TextRenderer.MeasureText(retainedClose.Text, retainedClose.Font).Width + 32 > retainedClose.Width || sharedFooter.Controls.Cast<Control>().Any(action => !sharedFooter.ClientRectangle.Contains(action.Bounds)))
                            throw new Exception("Inventory footer did not measure and wrap a longer action caption.");
                        apply.Invoke(form, new object[] { english }); Application.DoEvents();
                        if (sharedFooter.Height != restoredFooterHeight || sharedFooter.Controls.Cast<Control>().Any(action => action.Bounds != restoredActionBounds[action.Name]))
                            throw new Exception("Inventory footer did not restore its measured layout: " + form.GetType().Name + "/" + mode + "/" + english + "; actual=" + sharedFooter.Height + "; expected=" + restoredFooterHeight);
                        Prepare(form, new Size(960, 640)); Application.DoEvents();
                        if (sharedFooter.Height != 64 || sharedFooter.Controls.Cast<Control>().Any(action => !sharedFooter.ClientRectangle.Contains(action.Bounds)))
                            throw new Exception("Inventory footer did not return to a single row at the supported demo width: " + form.GetType().Name + "/" + mode + "/" + english);
                        var operation = form as InventoryOperationForm;
                        if (operation != null)
                        {
                            var busy = typeof(InventoryOperationForm).GetField("inventoryWriteBusy", flags);
                            busy.SetValue(operation, true); click.Invoke(retainedClose, new object[] { EventArgs.Empty });
                            if (form.IsDisposed || !form.Visible) throw new Exception("Inventory footer close bypassed the active-write guard.");
                            busy.SetValue(operation, false);
                        }
                        click.Invoke(retainedClose, new object[] { EventArgs.Empty });
                        if (!form.IsDisposed) throw new Exception("Inventory footer close did not use normal form closure.");
                        Properties.Setings.Default.ThemeMode = mode;
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; }
        }
        private static void VerifyInventoryCheckboxAccessibility()
        {
            string original = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            var keyUp = typeof(AccessibleAntdCheckbox).GetMethod("OnKeyUp", flags);
            var click = typeof(AccessibleAntdCheckbox).GetMethod("OnClick", flags);
            int layouts = 0;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool lots in new[] { false, true })
                using (var form = new InventoryStockReportForm(lots, false))
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                    form.Location = new Point(-20000, -20000); form.Show(); UiTheme.Apply(form);
                    form.ApplyPresentation(english);
                    var box = Require<AccessibleAntdCheckbox>(form, "inventoryStockIncludeZero");
                    int changes = 0, clicks = 0;
                    box.CheckedChanged += (sender, args) => changes++;
                    box.Click += (sender, args) => clicks++;
                    foreach (Size size in new[] { new Size(640, 480), new Size(960, 640), new Size(1366, 768), new Size(1920, 1080) })
                    {
                        Prepare(form, size); Application.DoEvents();
                        if (!box.TabStop || box.BackColor != Color.Transparent || box.ForeColor != UiTheme.Text || box.Fill != UiTheme.Primary ||
                            box.AccessibilityObject.Role != AccessibleRole.CheckButton || box.AccessibilityObject.Name != box.Text ||
                            box.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                            box.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                            !box.Parent.ClientRectangle.Contains(box.Bounds) || TextRenderer.MeasureText(box.Text, box.Font).Width + 30 > box.Width)
                            throw new InvalidOperationException("Stock checkbox presentation/accessibility failed: " + theme + "/" + english + "/" + lots + "/" + size);
                        bool initial = box.Checked; int before = changes, priorClicks = clicks;
                        if (box.AccessibilityObject.State.HasFlag(AccessibleStates.Checked) != initial)
                            throw new Exception("Stock checkbox does not expose its checked state.");
                        box.AccessibilityObject.DoDefaultAction(); Application.DoEvents();
                        if (box.Checked == initial || changes != before + 1 || clicks != priorClicks + 1 ||
                            box.AccessibilityObject.State.HasFlag(AccessibleStates.Checked) != box.Checked || string.IsNullOrWhiteSpace(box.AccessibilityObject.DefaultAction))
                            throw new Exception("Stock accessibility action does not toggle exactly once.");
                        keyUp.Invoke(box, new object[] { new KeyEventArgs(Keys.Space) });
                        if (box.Checked != initial || changes != before + 2) throw new Exception("Stock software Space does not toggle exactly once.");
                        priorClicks = clicks; click.Invoke(box, new object[] { EventArgs.Empty });
                        if (box.Checked == initial || changes != before + 3 || clicks != priorClicks + 1) throw new Exception("Stock pointer click changed toggle semantics.");
                        box.AccessibilityObject.DoDefaultAction();
                        if (box.Checked != initial || changes != before + 4) throw new Exception("Stock second accessible action failed.");
                        Control parent = box.Parent; parent.Enabled = false;
                        if (!box.AccessibilityObject.State.HasFlag(AccessibleStates.Unavailable)) throw new Exception("Stock parent disable is not exposed.");
                        box.AccessibilityObject.DoDefaultAction(); keyUp.Invoke(box, new object[] { new KeyEventArgs(Keys.Space) }); click.Invoke(box, new object[] { EventArgs.Empty });
                        if (box.Checked != initial || changes != before + 4) throw new Exception("Disabled stock checkbox can be toggled by user actions.");
                        parent.Enabled = true; layouts++;
                    }
                    bool retained = box.Checked; int count = changes;
                    Properties.Setings.Default.ThemeMode = theme == "Light" ? "Dark" : "Light"; UiTheme.Apply(form); form.ApplyPresentation(english);
                    if (box.Checked != retained || changes != count || box.BackColor != Color.Transparent || box.ForeColor != UiTheme.Text || box.Fill != UiTheme.Primary)
                        throw new Exception("Live checkbox theme changed the filter or lost shared styling.");
                    var accessible = box.AccessibilityObject;
                    var background = System.Threading.Tasks.Task.Run(() => accessible.DoDefaultAction()); CompleteUiTask(background); Application.DoEvents();
                    if (box.Checked == retained || changes != count + 1) throw new Exception("Background accessible action did not dispatch to the UI once.");
                    form.Close(); accessible.DoDefaultAction();
                    if (!form.IsDisposed || !accessible.State.HasFlag(AccessibleStates.Unavailable)) throw new Exception("Disposed checkbox accessibility is not guarded.");
                }
                Console.WriteLine("PASS inventory checkbox: " + layouts + " layouts, check state/default action/Space/click/disable/thread/dispose/live theme; mock screens only.");
            }
            finally { Properties.Setings.Default.ThemeMode = original; }
        }
        private static void VerifySharedDataSurfaceLayouts()
        {
            VerifyAccountingCloseActions();
            using (var inventory = new InventoryDataPreview())
            using (var accounting = new AccountingDataPreview())
            {
                foreach (Size size in new[] { new Size(860, 560), new Size(1120, 700) })
                {
                    Prepare(inventory, size);
                    Prepare(accounting, size);

                    FlowLayoutPanel inventoryFilters = Require<FlowLayoutPanel>(inventory, "inventoryDataFilters");
                    FlowLayoutPanel inventorySummary = Require<FlowLayoutPanel>(inventory, "inventoryDataSummary");
                    AntdUI.Button inventoryClose = Require<AntdUI.Button>(inventory, "inventoryDataCloseButton");
                    AntdUI.Button inventoryAction = Require<AntdUI.Button>(inventory, "inventoryPreviewAction");
                    if (inventoryFilters.Height < 92 || inventoryFilters.Height > 210 || inventorySummary.Controls.Count != 2 ||
                        inventoryClose.Radius <= 0 || inventoryAction.Radius <= 0 || string.IsNullOrWhiteSpace(inventoryAction.IconSvg) ||
                        string.IsNullOrWhiteSpace(inventoryAction.AccessibleName))
                        throw new InvalidOperationException("Inventory shared data surface lost its responsive rounded controls.");
                    foreach (Control card in inventorySummary.Controls)
                    {
                        if (!(card is AntdUI.Panel) || ((AntdUI.Panel)card).Radius != DesktopDesignTokens.CardRadius || ((AntdUI.Panel)card).Shadow != 0 || card.Right > inventorySummary.ClientSize.Width)
                            throw new InvalidOperationException("Inventory summary card exceeds its responsive surface.");
                    }

                    Panel accountingEditor = Require<Panel>(accounting, "accountingDataEditor");
                    AntdUI.Button accountingClose = Require<AntdUI.Button>(accounting, "accountingDataCloseButton");
                    Button accountingAction = Require<Button>(accountingEditor, "accountingPreviewAction");
                    TextBox accountingField = Require<TextBox>(accountingEditor, "accountingPreviewField");
                    AntdUI.Input accountingAmount = Require<AntdUI.Input>(accountingEditor, "accountingPreviewAmount");
                    Panel amountHost = accountingAmount.Parent as Panel;
                    Label amountCaption = amountHost == null ? null : amountHost.Controls.OfType<Label>().FirstOrDefault();
                    if (amountHost == null || amountCaption == null || accountingAmount.Height < 44 ||
                        amountCaption.Bottom > accountingAmount.Top || accountingAmount.Bottom > amountHost.ClientSize.Height)
                        throw new InvalidOperationException("Shared accounting field clips its input or overlaps the caption at " + size + ".");
                    if (accountingEditor.Width < 280 || accountingClose.Radius <= 0 || accountingClose.BorderWidth != 1 || accountingClose.ForeColor != UiTheme.Primary || accountingAction.Region == null ||
                        accountingField.Region == null || string.IsNullOrWhiteSpace(accountingAction.AccessibleName))
                        throw new InvalidOperationException("Accounting shared data surface lost its themed accessible controls.");
                }
            }
        }

        private static void VerifyAccountingReportsLayout()
        {
            VerifyAccountingOutputColumns();
            VerifyAccountingReportLanguage();
            VerifyAccountingReportDirection();
            VerifyAccountingReportSnapshot();
            VerifyAccountingTemplateDetails();
            VerifyAccountingEffectiveFilters();
            using (var form = new AccountingReportsForm("TrialBalance", true))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1366, 768) })
                {
                    Prepare(form, size);
                    Application.DoEvents();
                    if (form.ClientSize != size)
                        throw new InvalidOperationException("Accounting report requested size was clamped: " + size + " actual=" + form.ClientSize);
                    FlowLayoutPanel tabs = Require<FlowLayoutPanel>(form, "accountingReportTabs");
                    FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "accountingReportActions");
                    TableLayoutPanel templates = Require<TableLayoutPanel>(form, "accountingReportTemplates");
                    ComboBox templateSelector = Require<ComboBox>(form, "savedReportTemplates");
                    AntdUI.Panel templateFrame = Require<AntdUI.Panel>(form, "savedReportTemplatesFrame");
                    DataGridView grid = Require<DataGridView>(form, "accountingReportGrid");
                    Panel top = Require<Panel>(form, "accountingReportsTop");
                    Panel footer = Require<Panel>(form, "accountingReportActionsHost");
                    TableLayoutPanel filters = Require<TableLayoutPanel>(form, "accountingReportFilters");
                    if (tabs.Controls.OfType<AntdUI.Button>().Count() != 6 ||
                        tabs.Controls.OfType<AntdUI.Button>().Count(tab => tab.Type == AntdUI.TTypeMini.Primary) != 1 ||
                        actions.Controls.OfType<AntdUI.Button>().Count() != 4 ||
                        templates.Controls.OfType<AntdUI.Button>().Count() != 4 ||
                        templateSelector.Items.Count == 0 || templateSelector.SelectedIndex != 0 ||
                        grid.BackgroundColor != UiTheme.Surface || grid.Height < 80)
                        throw new InvalidOperationException("Accounting report surface lost required responsive controls.");
                    if (footer.Bottom != form.ClientSize.Height || top.Bottom <= 0 || grid.Bottom != footer.Top)
                        throw new InvalidOperationException("Accounting report actions must remain fixed below the grid at " + size + ".");
                    foreach (Panel filter in filters.Controls.OfType<Panel>().Where(panel => panel.Visible))
                    {
                        Label caption = filter.Controls.OfType<Label>().Single();
                        Control editor = filter.Controls.Cast<Control>().Single(control => control != caption);
                        if (caption.Bottom > editor.Top || editor.Bottom > filter.ClientSize.Height)
                            throw new InvalidOperationException("Accounting report filter caption overlaps its editor at " + size + ": " + caption.Text +
                                " caption=" + caption.Bounds + " editor=" + editor.Bounds + " parent=" + filter.ClientSize);
                    }
                    int expectedTemplateRows = size.Width < 980 ? 2 : 1;
                    if (templates.RowCount != expectedTemplateRows ||
                        (expectedTemplateRows == 2 && templates.GetColumnSpan(templateFrame) != 4))
                        throw new InvalidOperationException("Accounting report template actions lost their readable responsive layout at " + size + ".");

                    Control[] sections = top.Controls.Cast<Control>().Where(control => control.Visible).OrderBy(control => control.Top).ToArray();
                    for (int index = 1; index < sections.Length; index++)
                        if (sections[index - 1].Bottom > sections[index].Top)
                            throw new InvalidOperationException("Accounting report sections overlap at " + size + ": " +
                                sections[index - 1].Name + " / " + sections[index].Name);

                    foreach (AntdUI.Button action in actions.Controls.OfType<AntdUI.Button>())
                    {
                        if (string.IsNullOrWhiteSpace(action.IconSvg) || action.BorderWidth != 1 ||
                            action.DefaultBorderColor != UiTheme.Primary || string.IsNullOrWhiteSpace(action.AccessibleName))
                            throw new InvalidOperationException("Accounting report footer lost its AntdUI green outline at " + size + ".");
                        if (action.Right > actions.ClientSize.Width || action.Bottom > actions.ClientSize.Height)
                            throw new InvalidOperationException("Accounting report footer action exceeds its host at " + size + ".");
                    }
                    foreach (AntdUI.Button action in templates.Controls.OfType<AntdUI.Button>())
                    {
                        if (string.IsNullOrWhiteSpace(action.IconSvg) || action.BorderWidth != 1 ||
                            action.DefaultBorderColor != UiTheme.Primary || string.IsNullOrWhiteSpace(action.AccessibleName))
                            throw new InvalidOperationException("Accounting report action lost its accessible outlined appearance.");
                        if (action.Right > action.Parent.ClientSize.Width || action.Bottom > action.Parent.ClientSize.Height)
                            throw new InvalidOperationException("Accounting report action exceeds its host at " + size + ".");
                    }
                }
                ComboBox savedTemplateSelector = Require<ComboBox>(form, "savedReportTemplates");
                const string mixedTemplateName = "قالب Pharma 500 mg — ميزان المراجعة";
                savedTemplateSelector.Items.Add(mixedTemplateName);
                savedTemplateSelector.SelectedIndex = savedTemplateSelector.Items.Count - 1;
                if (!string.Equals(savedTemplateSelector.Text, mixedTemplateName, StringComparison.Ordinal))
                    throw new InvalidOperationException("The AntdUI report template selector changed mixed Arabic/English text.");
                var table = new DataTable();
                table.Columns.Add("مدين", typeof(decimal));
                table.Columns.Add("دائن", typeof(decimal));
                table.Columns.Add("الرصيد", typeof(decimal));
                table.Rows.Add(1250m, 1250m, 0m);
                var reportFields = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                typeof(AccountingReportsForm).GetField("currentTable", reportFields).SetValue(form, table);
                typeof(AccountingReportsForm).GetMethod("RenderSummary", reportFields).Invoke(form, null);
                foreach (Size size in new[] { new Size(760, 640), new Size(1366, 768) })
                {
                    Prepare(form, size);
                    Application.DoEvents();
                    FlowLayoutPanel summary = Require<FlowLayoutPanel>(form, "accountingReportSummary");
                    Panel top = Require<Panel>(form, "accountingReportsTop");
                    Panel footer = Require<Panel>(form, "accountingReportActionsHost");
                    DataGridView grid = Require<DataGridView>(form, "accountingReportGrid");
                    if (!summary.Visible || summary.Controls.Count != 4 ||
                        summary.Controls.Cast<Control>().Any(card => card.Bottom > summary.ClientSize.Height) ||
                        grid.Height < 160 || footer.Bottom != form.ClientSize.Height ||
                        top.AutoScrollMinSize.Height < summary.Bottom)
                        throw new InvalidOperationException("Accounting report summary clips after data load at " + size + ".");
                }
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox || form.MinimumSize.Width > 760)
                    throw new InvalidOperationException("Accounting reports must support standard resize, maximize, and minimize.");
            }
        }

        private static void VerifyAccountingOutputColumns()
        {
            using (var form = new AccountingReportsForm("CostCenters", true))
            {
                form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000); form.Show();
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var type = typeof(AccountingReportsForm);
                using (var table = new DataTable())
                {
                    table.Columns.Add("اسم الحساب", typeof(string)); table.Columns.Add("مدين", typeof(decimal));
                    table.Columns.Add("دائن", typeof(decimal)); table.Columns.Add("التاريخ", typeof(DateTime));
                    table.Columns.Add("البيان", typeof(string));
                    table.Rows.Add("صيدلية Pharmacy 500 mg", -12.50m, 2.375m, new DateTime(2026, 9, 30, 13, 45, 59), "  =1+1");
                    table.Rows.Add("مُستَلزمات طِبّية", DBNull.Value, 0.125m, new DateTime(2026, 9, 29), "نص، \"مقتبس\"\nمتعدد");
                    type.GetField("currentTable", flags).SetValue(form, table);
                    var grid = Require<DataGridView>(form, "accountingReportGrid"); grid.DataSource = table;
                    int generation = (int)type.GetField("reportLoadGeneration", flags).GetValue(form);
                    type.GetField("activeVisibleColumns", flags).SetValue(form, new List<string> { "مدين", "اسم الحساب", "التاريخ", "البيان" });
                    type.GetField("activeColumnOrder", flags).SetValue(form, new List<string> { "البيان", "مدين", "التاريخ", "اسم الحساب" });
                    type.GetMethod("ApplyColumnLayout", flags).Invoke(form, null);
                    foreach (bool english in new[] { false, true, false })
                    {
                        form.ApplyPresentation(english);
                        using (var exportTable = (DataTable)type.GetMethod("GetVisibleTable", flags).Invoke(form, null))
                        using (var printTable = (DataTable)type.GetMethod("GetPrintTable", flags).Invoke(form, null))
                        {
                            string[] names = { "البيان", "مدين", "التاريخ", "اسم الحساب" };
                            if (!exportTable.Columns.Cast<DataColumn>().Select(column => column.ColumnName).SequenceEqual(names) ||
                                !printTable.Columns.Cast<DataColumn>().Select(column => column.ColumnName).SequenceEqual(names) ||
                                exportTable.Columns.Contains("دائن") || printTable.Columns.Contains("دائن") ||
                                exportTable.Rows.Count != 2 || printTable.Rows.Count != 2)
                                throw new InvalidOperationException("Accounting output columns/order differ from the visible report layout. export=" +
                                    string.Join("|", exportTable.Columns.Cast<DataColumn>().Select(column => column.ColumnName)) + "; print=" +
                                    string.Join("|", printTable.Columns.Cast<DataColumn>().Select(column => column.ColumnName)) +
                                    "; rows=" + exportTable.Rows.Count + "/" + printTable.Rows.Count + "; language=" + english);
                            foreach (DataColumn column in exportTable.Columns)
                            {
                                if (column.DataType != table.Columns[column.ColumnName].DataType ||
                                    printTable.Columns[column.ColumnName].Caption != (english ? UiLanguageCatalog.Translate(column.ColumnName) : column.ColumnName))
                                    throw new InvalidOperationException("Accounting projection lost column types or print captions.");
                                for (int row = 0; row < table.Rows.Count; row++)
                                    if (!Equals(exportTable.Rows[row][column], table.Rows[row][column.ColumnName]) ||
                                        !Equals(printTable.Rows[row][column.ColumnName], table.Rows[row][column.ColumnName]))
                                        throw new InvalidOperationException("Accounting output changed a value/null or reordered source rows.");
                            }
                            var previousCulture = System.Threading.Thread.CurrentThread.CurrentCulture;
                            try
                            {
                                System.Threading.Thread.CurrentThread.CurrentCulture = System.Globalization.CultureInfo.GetCultureInfo("fr-FR");
                                string csv = ReportCsvWriter.Serialize(exportTable);
                                if (!csv.StartsWith("\"البيان\",\"مدين\",\"التاريخ\",\"اسم الحساب\"") ||
                                    !csv.Contains("\"-12.50\"") || csv.Contains("'-12.50") || !csv.Contains("\"'  =1+1\"") ||
                                    !csv.Contains("\"2026-09-30 13:45:59\"") || !csv.Contains("\"2026-09-29\"") ||
                                    !csv.Contains("نص، \"\"مقتبس\"\"\nمتعدد"))
                                    throw new InvalidOperationException("Accounting CSV lost typed numbers, ISO dates, Arabic, quoting or formula protection.");
                            }
                            finally { System.Threading.Thread.CurrentThread.CurrentCulture = previousCulture; }
                        }
                        if (generation != (int)type.GetField("reportLoadGeneration", flags).GetValue(form) ||
                            !ReferenceEquals(table, grid.DataSource) || table.Columns.Count != 5 || (decimal)table.Rows[0]["دائن"] != 2.375m)
                            throw new InvalidOperationException("Accounting output projection changed its accepted source or triggered reading.");
                    }
                    // A user's live drag order takes precedence over the last template order on language changes.
                    grid.Columns["مدين"].DisplayIndex = 0;
                    string[] draggedOrder = grid.Columns.Cast<DataGridViewColumn>().Where(column => column.Visible)
                        .OrderBy(column => column.DisplayIndex).Select(column => column.Name).ToArray();
                    foreach (bool english in new[] { true, false })
                    {
                        form.ApplyPresentation(english);
                        using (var dragged = (DataTable)type.GetMethod("GetVisibleTable", flags).Invoke(form, null))
                            if (!dragged.Columns.Cast<DataColumn>().Select(column => column.ColumnName).SequenceEqual(draggedOrder) ||
                                dragged.Columns[0].ColumnName != "مدين")
                                throw new InvalidOperationException("Accounting presentation reset the user's live drag order to the template order.");
                    }
                    // Missing old schema names must recover a usable report, not hide every column.
                    type.GetField("activeVisibleColumns", flags).SetValue(form, new List<string> { "RemovedOldColumn" });
                    type.GetField("activeColumnOrder", flags).SetValue(form, new List<string> { "مدين", "مدين", "RemovedOldColumn", "اسم الحساب" });
                    type.GetMethod("ApplyColumnLayout", flags).Invoke(form, null);
                    if (grid.Columns.Cast<DataGridViewColumn>().Any(column => !column.Visible))
                        throw new InvalidOperationException("An outdated accounting template hides the whole current report.");
                    // Explicitly hidden columns cannot leak into export/print, including the zero-column case.
                    foreach (DataGridViewColumn column in grid.Columns) column.Visible = false;
                    using (var empty = (DataTable)type.GetMethod("GetVisibleTable", flags).Invoke(form, null))
                    using (var emptyPrint = (DataTable)type.GetMethod("GetPrintTable", flags).Invoke(form, null))
                        if (empty.Columns.Count != 0 || emptyPrint.Columns.Count != 0 || empty.Rows.Count != 0)
                            throw new InvalidOperationException("Accounting output exposed explicitly hidden columns.");
                    using (var nextTable = new DataTable())
                    {
                        nextTable.Columns.Add("الحساب", typeof(string)); nextTable.Columns.Add("صافي الضريبة", typeof(decimal));
                        nextTable.Rows.Add("حساب ضريبة", 2.375m);
                        type.GetField("currentTable", flags).SetValue(form, nextTable);
                        type.GetMethod("BindReportTable", flags).Invoke(form, new object[] { nextTable });
                        if (grid.Columns.Count != 2 || grid.Columns.Contains("اسم الحساب") || !grid.Columns.Contains("صافي الضريبة") || grid.AutoGenerateColumns)
                            throw new InvalidOperationException("Accounting result schema did not regenerate when accepting a different report.");
                        foreach (bool english in new[] { true, false })
                        {
                            form.ApplyPresentation(english);
                            using (var projected = (DataTable)type.GetMethod("GetPrintTable", flags).Invoke(form, null))
                                if (projected.Columns.Count != 2 || !projected.Columns.Contains("صافي الضريبة") ||
                                    (decimal)projected.Rows[0]["صافي الضريبة"] != 2.375m)
                                    throw new InvalidOperationException("Accounting schema/data drifted after language changes on the new result.");
                        }
                    }
                }
            }
        }

        private static void VerifyAccountingReportLanguage()
        {
            using (var form = new AccountingReportsForm("CostCenters", true))
            {
                form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000); form.Show();
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var type = typeof(AccountingReportsForm);
                var from = Require<AntdUI.DatePicker>(form, "fromDateFilter");
                var to = Require<AntdUI.DatePicker>(form, "toDateFilter");
                from.Value = new DateTime(2026, 9, 1); to.Value = new DateTime(2026, 9, 30);
                var request = type.GetMethod("CaptureReportRequest", flags).Invoke(form, null);
                type.GetField("loadedRequest", flags).SetValue(form, request);
                using (var table = new DataTable())
                {
                    table.Columns.Add("اسم الحساب", typeof(string)); table.Columns.Add("مدين", typeof(decimal));
                    table.Columns.Add("دائن", typeof(decimal)); table.Columns.Add("الصافي", typeof(decimal));
                    table.Rows.Add("صيدلية Pharmacy 500 mg", 12.50m, 2m, 10.50m);
                    type.GetField("currentTable", flags).SetValue(form, table);
                    var grid = Require<DataGridView>(form, "accountingReportGrid"); grid.DataSource = table;
                    int generation = (int)type.GetField("reportLoadGeneration", flags).GetValue(form);
                    foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1366, 768) })
                    foreach (bool english in new[] { false, true, false })
                    {
                        Prepare(form, size); form.ApplyPresentation(english); Application.DoEvents();
                        if (form.Text != (english ? "Cost center analysis" : "تقرير تحليل مراكز التكلفة") ||
                            grid.Columns["اسم الحساب"].HeaderText != (english ? "Account name" : "اسم الحساب") ||
                            grid.Columns["مدين"].HeaderText != (english ? "Debit" : "مدين"))
                            throw new InvalidOperationException("Accounting report title or raw-column display did not roundtrip.");
                        var tabs = Require<FlowLayoutPanel>(form, "accountingReportTabs");
                        var balanceTab = tabs.Controls.Cast<AntdUI.Button>().Single(tab => Convert.ToString(tab.Tag) == "BalanceSheet");
                        var actions = Require<FlowLayoutPanel>(form, "accountingReportActions");
                        if (balanceTab.Text != (english ? "Balance sheet" : "الميزانية العمومية") ||
                            actions.Controls[0].Text != (english ? "View results" : "عرض النتيجة") ||
                            actions.Controls[3].Text != (english ? "Exit" : "خروج") ||
                            actions.Controls.Cast<AntdUI.Button>().Any(button => button.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right)))
                            throw new InvalidOperationException("Accounting action/tab captions or icons did not follow presentation language.");
                        var opening = (CheckBox)type.GetField("includePreviousBalance", flags).GetValue(form);
                        var exclude = (CheckBox)type.GetField("excludeInventoryValue", flags).GetValue(form);
                        if (opening.Text != (english ? "Include opening balance" : "تضمين الرصيد الافتتاحي") ||
                            exclude.Text != (english ? "Exclude inventory from profit and loss" : "استثناء المخزون من الأرباح والخسائر"))
                            throw new InvalidOperationException("Accounting option captions remain untranslated.");
                        string period = (string)type.GetMethod("GetLoadedReportPeriod", flags).Invoke(form, null);
                        if (!period.StartsWith(english ? "Period: " : "الفترة: ") || !period.Contains("2026/09/30"))
                            throw new InvalidOperationException("Accounting loaded print period did not preserve its snapshot/language.");
                        using (var printTable = (DataTable)type.GetMethod("GetPrintTable", flags).Invoke(form, null))
                        {
                            if (ReferenceEquals(table, printTable) || printTable.Columns["اسم الحساب"].Caption != (english ? "Account name" : "اسم الحساب") ||
                                printTable.Columns["مدين"].Caption != (english ? "Debit" : "مدين") || printTable.Columns["مدين"].DataType != typeof(decimal) ||
                                (string)printTable.Rows[0][0] != "صيدلية Pharmacy 500 mg" || (decimal)printTable.Rows[0][1] != 12.50m ||
                                table.Columns["اسم الحساب"].Caption != "اسم الحساب")
                                throw new InvalidOperationException("Accounting print captions changed the raw snapshot, keys, types or values.");
                        }
                        string name = "صيدلية Pharmacy {name} 500 mg";
                        string confirmation = (string)type.GetMethod("FormatReportMessage", flags).Invoke(form,
                            new object[] { "هل تريد حذف قالب «{0}»؟ لا يؤثر ذلك على بيانات التقارير.", new object[] { name } });
                        if (!confirmation.Contains(name) || (english && !confirmation.StartsWith("Delete template")))
                            throw new InvalidOperationException("Accounting template confirmation changed a mixed name with braces.");
                        var summary = Require<FlowLayoutPanel>(form, "accountingReportSummary");
                        if (summary.Controls.Count != 5 || !summary.Controls.Cast<Control>().SelectMany(card => card.Controls.Cast<Control>()).Any(label =>
                            label.Text.Contains(english ? "Affected accounts" : "عدد الحسابات المتأثرة")))
                            throw new InvalidOperationException("Accounting loaded summary did not roundtrip.");
                        if (!ReferenceEquals(table, grid.DataSource) || !ReferenceEquals(request, type.GetField("loadedRequest", flags).GetValue(form)) ||
                            generation != (int)type.GetField("reportLoadGeneration", flags).GetValue(form) ||
                            (string)table.Rows[0][0] != "صيدلية Pharmacy 500 mg" || (decimal)table.Rows[0][1] != 12.50m)
                            throw new InvalidOperationException("Accounting translation mutated source values or triggered loading.");
                    }
                    foreach (string method in new[] { "LoadData", "ExportCsv", "PrintReport" })
                        type.GetMethod(method, flags).Invoke(form, null);
                    if (generation != (int)type.GetField("reportLoadGeneration", flags).GetValue(form))
                        throw new InvalidOperationException("Accounting preview invoked a live report operation.");
                    string[] reportKeys = { "Tax", "CostCenters", "GeneralJournal", "TrialBalance", "ProfitLoss", "BalanceSheet" };
                    string[] englishTitles = { "Tax report", "Cost center analysis", "General journal report", "Trial balance", "Profit and loss", "Balance sheet" };
                    for (int index = 0; index < reportKeys.Length; index++)
                    {
                        type.GetField("activeReport", flags).SetValue(form, reportKeys[index]);
                        type.GetMethod("ConfigureReportFilters", flags).Invoke(form,
                            new object[] { Require<TableLayoutPanel>(form, "accountingReportFilters") });
                        form.ApplyPresentation(true);
                        if (form.Text != englishTitles[index] || to.Parent.Controls.OfType<Label>().Single().Text !=
                            (reportKeys[index] == "TrialBalance" ? "As of date" : "To date"))
                            throw new InvalidOperationException("Accounting report title/date caption is untranslated: " + reportKeys[index]);
                        if (!grid.AccessibleDescription.Contains("Cost center analysis") || !grid.AccessibleDescription.Contains("2026/09/30"))
                            throw new InvalidOperationException("Pending accounting filters replaced accepted result metadata during translation.");
                    }
                }
            }
        }

        private static void VerifyAccountingReportDirection()
        {
            using (var form = new AccountingReportsForm("CostCenters", true))
            {
                form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000); form.Show();
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var type = typeof(AccountingReportsForm);
                var from = Require<AntdUI.DatePicker>(form, "fromDateFilter");
                var to = Require<AntdUI.DatePicker>(form, "toDateFilter");
                from.Value = new DateTime(2026, 9, 1); to.Value = new DateTime(2026, 9, 30);
                var request = type.GetMethod("CaptureReportRequest", flags).Invoke(form, null);
                type.GetField("loadedRequest", flags).SetValue(form, request);
                using (var table = new DataTable())
                {
                    table.Columns.Add("اسم الحساب", typeof(string)); table.Columns.Add("مدين", typeof(decimal));
                    table.Rows.Add("صيدلية Pharmacy 500 mg", 12.50m);
                    type.GetField("currentTable", flags).SetValue(form, table);
                    var grid = Require<DataGridView>(form, "accountingReportGrid");
                    grid.DataSource = table;
                    int generation = (int)type.GetField("reportLoadGeneration", flags).GetValue(form);
                    foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1366, 768) })
                    foreach (bool english in new[] { false, true, false })
                    {
                        Prepare(form, size);
                        form.ApplyTemplatePresentation(english);
                        // Recreate dynamic content after switching direction, as tab/result loading does.
                        type.GetMethod("BuildReportTabs", flags).Invoke(form, null);
                        type.GetMethod("RenderSummary", flags).Invoke(form, null);
                        type.GetMethod("FormatGrid", flags).Invoke(form, null);
                        Application.DoEvents();
                        RightToLeft direction = english ? RightToLeft.No : RightToLeft.Yes;
                        if (form.RightToLeft != direction || form.RightToLeftLayout == english || grid.RightToLeft != direction)
                            throw new InvalidOperationException("Accounting window/grid direction does not follow language.");
                        foreach (string name in new[] { "accountingReportTabs", "accountingReportActions", "accountingReportSummary" })
                        {
                            var flow = Require<FlowLayoutPanel>(form, name);
                            if (flow.FlowDirection != (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft) || flow.RightToLeft != (name == "accountingReportSummary" ? RightToLeft.No : direction))
                                throw new InvalidOperationException("Accounting dynamic flow direction is inconsistent: " + name);
                        }
                        if (Require<FlowLayoutPanel>(form, "accountingReportTabs").Controls.Cast<Control>().Any(tab => tab.RightToLeft != direction) ||
                            Require<FlowLayoutPanel>(form, "accountingReportSummary").Controls.Cast<Control>().Any(card => card.RightToLeft != RightToLeft.No) ||
                            from.RightToLeft != RightToLeft.No || to.RightToLeft != RightToLeft.No)
                            throw new InvalidOperationException("New accounting controls or structured dates changed direction incorrectly.");
                        if (!ReferenceEquals(table, grid.DataSource) || !ReferenceEquals(table, type.GetField("currentTable", flags).GetValue(form)) ||
                            !ReferenceEquals(request, type.GetField("loadedRequest", flags).GetValue(form)) ||
                            generation != (int)type.GetField("reportLoadGeneration", flags).GetValue(form) ||
                            table.Columns[0].ColumnName != "اسم الحساب" || (string)table.Rows[0][0] != "صيدلية Pharmacy 500 mg" || (decimal)table.Rows[0][1] != 12.50m)
                            throw new InvalidOperationException("Accounting direction change mutated the accepted data or triggered loading.");
                    }
                }
            }
        }

        private static void VerifyAccountingEffectiveFilters()
        {
            using (var form = new AccountingReportsForm("TrialBalance", true))
            {
                form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000); form.Show();
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var type = typeof(AccountingReportsForm);
                AntdUI.DatePicker from = Require<AntdUI.DatePicker>(form, "fromDateFilter");
                AntdUI.DatePicker to = Require<AntdUI.DatePicker>(form, "toDateFilter");
                ComboBox center = Require<ComboBox>(form, "costCenterFilter");
                var opening = (CheckBox)type.GetField("includePreviousBalance", flags).GetValue(form);
                var exclude = (CheckBox)type.GetField("excludeInventoryValue", flags).GetValue(form);
                var filters = Require<TableLayoutPanel>(form, "accountingReportFilters");
                var capture = type.GetMethod("CaptureReportRequest", flags);
                using (Font referenceFont = AppFonts.Create(10F))
                {
                    var typography = new List<Control> { from, to, center,
                        (Control)type.GetField("reportTitle", flags).GetValue(form),
                        (Control)type.GetField("templateDetails", flags).GetValue(form),
                        (Control)type.GetField("savedTemplates", flags).GetValue(form) };
                    typography.AddRange(Require<FlowLayoutPanel>(form, "accountingReportTabs").Controls.OfType<AntdUI.Button>());
                    typography.AddRange(Require<FlowLayoutPanel>(form, "accountingReportActions").Controls.OfType<AntdUI.Button>());
                    foreach (Control control in typography)
                        if (!string.Equals(control.Font.FontFamily.Name, referenceFont.FontFamily.Name, StringComparison.OrdinalIgnoreCase))
                            throw new InvalidOperationException("Accounting report typography diverged from the shared configured font: " + control.Name);
                }
                foreach (string key in new[] { "Tax", "CostCenters", "GeneralJournal", "TrialBalance", "ProfitLoss", "BalanceSheet" })
                {
                    type.GetField("activeReport", flags).SetValue(form, key);
                    type.GetMethod("ConfigureReportFilters", flags).Invoke(form, new object[] { filters });
                    foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1366, 768) })
                    {
                        Prepare(form, size); Application.DoEvents();
                        if (from.Parent.Visible != (key != "TrialBalance") || center.Parent.Parent.Visible != (key == "CostCenters") ||
                            opening.Visible != (key == "BalanceSheet" || key == "ProfitLoss") || exclude.Visible != (key == "ProfitLoss") ||
                            from.Height != 44 || to.Height != 44 || from.Width > 420 || to.Width > 420 ||
                            from.RightToLeft != RightToLeft.No || to.RightToLeft != RightToLeft.No ||
                            center.Items.Cast<object>().Any(value => Convert.ToString(value) == "بدون"))
                            throw new InvalidOperationException("Accounting filters show ignored options or lose the shared date contract: " + key + "; " + size);
                        foreach (Panel panel in filters.Controls.OfType<Panel>().Where(value => value.Visible))
                        {
                            Label caption = panel.Controls.OfType<Label>().Single();
                            Control editor = panel.Controls.Cast<Control>().Single(value => value != caption);
                            if (caption.Bottom > editor.Top || editor.Bottom > panel.ClientSize.Height || panel.Bottom > filters.ClientSize.Height)
                                throw new InvalidOperationException("Accounting effective filter overlaps: " + key + "; " + size + "; " + caption.Text);
                        }
                    }
                    from.Value = new DateTime(2026, 9, 1); to.Value = new DateTime(2026, 9, 30);
                    var request = (PharmacyManagement.Application.AccountingReportReadRequest)capture.Invoke(form, null);
                    if (request.ReportKey != key || request.ToDate != new DateTime(2026, 9, 30) ||
                        request.FromDate != (key == "TrialBalance" ? request.ToDate : new DateTime(2026, 9, 1)))
                        throw new InvalidOperationException("AntdUI dates changed accounting request mapping.");
                    from.Value = null;
                    if (key == "TrialBalance") capture.Invoke(form, null);
                    else AssertInvalidAccountingDate(capture, form);
                    from.Value = new DateTime(2026, 9, 1); to.Value = null;
                    AssertInvalidAccountingDate(capture, form);
                    to.Value = new DateTime(2026, 9, 30); to.Text = "invalid date";
                    AssertInvalidAccountingDate(capture, form);
                    // AntdUI does not rebuild Text when assigning the same cached Value.
                    to.Value = null;
                    to.Value = new DateTime(2026, 9, 30);
                }
                var legacy = new ReportTemplate { ReportKey = "ProfitLoss", FromDate = new DateTime(2026,9,1),
                    ToDate = new DateTime(2026,9,30), Branch = "الفرع الرئيسي", Level = "2", ValuationMethod = "آخر سعر تكلفة",
                    CostCenter = "الكل", IncludePreviousBalance = false, ExcludeInventoryValue = true };
                to.Text = "invalid date";
                int generation = (int)type.GetField("reportLoadGeneration", flags).GetValue(form);
                type.GetMethod("ApplyAccountingTemplateFields", flags).Invoke(form, new object[] { legacy });
                var restored = (PharmacyManagement.Application.AccountingReportReadRequest)capture.Invoke(form, null);
                if (restored.FromDate != legacy.FromDate || restored.ToDate != legacy.ToDate || restored.ReportKey != legacy.ReportKey ||
                    restored.IncludePreviousBalance || !restored.ExcludeInventoryValue ||
                    ((ComboBox)type.GetField("branch", flags).GetValue(form)).Text != legacy.Branch ||
                    ((ComboBox)type.GetField("level", flags).GetValue(form)).Text != legacy.Level ||
                    ((ComboBox)type.GetField("valuationMethod", flags).GetValue(form)).Text != legacy.ValuationMethod ||
                    generation != (int)type.GetField("reportLoadGeneration", flags).GetValue(form))
                    throw new InvalidOperationException("Accounting template application changed legacy metadata or retained invalid date text.");
                center.Items.Add("42 - صيدلية Pharmacy 500 mg"); center.SelectedIndex = center.Items.Count - 1;
                type.GetField("activeReport", flags).SetValue(form, "CostCenters");
                var centerRequest = (PharmacyManagement.Application.AccountingReportReadRequest)capture.Invoke(form, null);
                if (centerRequest.CostCenterId != 42 || center.Text != "42 - صيدلية Pharmacy 500 mg")
                    throw new InvalidOperationException("Native cost-center selection changed the identifier or mixed text.");
            }
        }

        private static void AssertInvalidAccountingDate(System.Reflection.MethodInfo capture, Form form)
        {
            try { capture.Invoke(form, null); }
            catch (System.Reflection.TargetInvocationException exception)
            {
                if (exception.InnerException is ArgumentException) return;
                throw;
            }
            throw new InvalidOperationException("Empty or invalid accounting date reached the query boundary.");
        }

        private static void VerifyAccountingTemplateDetails()
        {
            string originalTheme = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var form = new AccountingReportsForm("TrialBalance", true))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show();
                        var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                        var type = typeof(AccountingReportsForm);
                        var choices = (System.Collections.IList)type.GetField("savedTemplateChoices", flags).GetValue(form);
                        ComboBox picker = Require<ComboBox>(form, "savedReportTemplates");
                        AntdUI.Panel frame = Require<AntdUI.Panel>(form, "savedReportTemplatesFrame");
                        AntdUI.Panel context = Require<AntdUI.Panel>(form, "accountingReportTemplateContext");
                        TextBox details = Require<TextBox>(form, "accountingReportTemplateDetails");
                        var table = new DataTable(); table.Columns.Add("اسم الحساب", typeof(string)); table.Rows.Add("صيدلية Pharma 500 mg");
                        type.GetField("currentTable", flags).SetValue(form, table);
                        int generation = (int)type.GetField("reportLoadGeneration", flags).GetValue(form);
                        foreach (string name in new[] { new string('W', 60), new string('م', 60), "مُراجعة Pharmacy 500 mg {2026}" })
                        {
                            var template = new ReportTemplate { Name = name, ReportKey = "TrialBalance" };
                            object choice = Activator.CreateInstance(type.GetNestedType("ReportTemplateChoice", flags),
                                flags, null, new object[] { name + " — ميزان المراجعة", template }, null);
                            choices.Clear(); picker.Items.Clear(); choices.Add(choice); picker.Items.Add(choice.ToString()); picker.SelectedIndex = 0;
                            foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1366, 768) })
                            foreach (bool english in new[] { false, true, false })
                            {
                                Prepare(form, size); form.ApplyTemplatePresentation(english); Application.DoEvents();
                                int lines = details.GetLineFromCharIndex(details.TextLength) + 1;
                                int lineHeight = details.Font.Height;
                                if (lines > 1) lineHeight = Math.Max(lineHeight, details.GetPositionFromCharIndex(details.GetFirstCharIndexFromLine(1)).Y - details.GetPositionFromCharIndex(0).Y);
                                int lastY = details.GetPositionFromCharIndex(Math.Max(0, details.TextLength - 1)).Y;
                                if (!context.Visible || !details.Text.Contains(name) || !details.AccessibleDescription.Contains(name) ||
                                    !picker.AccessibleDescription.Contains(name) || template.Name != name || !details.ReadOnly || !details.WordWrap ||
                                    details.ClientSize.Height < lastY + lineHeight || context.Top < 0 || context.Bottom > context.Parent.ClientSize.Height ||
                                    frame.Height < 44 || frame.BorderWidth != 1 || frame.Shadow != 0 || context.Radius != 12 || context.Shadow != 0 ||
                                    picker.DrawMode != DrawMode.OwnerDrawFixed || picker.DropDownStyle != ComboBoxStyle.DropDownList ||
                                    !ReferenceEquals(table, type.GetField("currentTable", flags).GetValue(form)) ||
                                    generation != (int)type.GetField("reportLoadGeneration", flags).GetValue(form) ||
                                    (string)type.GetField("activeReport", flags).GetValue(form) != "TrialBalance")
                                    throw new InvalidOperationException("Accounting template details clipped, changed data or loaded a report: " + size + "; English=" + english);
                                if (Require<AntdUI.Button>(form, "saveAccountingReportTemplate").Enabled ||
                                    Require<AntdUI.Button>(form, "deleteAccountingReportTemplate").Enabled)
                                    throw new InvalidOperationException("Accounting preview must disable template writes.");
                            }
                        }
                        type.GetMethod("SaveCurrentTemplate", flags).Invoke(form, null);
                        type.GetMethod("DeleteSelectedTemplate", flags).Invoke(form, null);
                        picker.SelectedIndex = -1;
                        if (context.Visible || details.TextLength != 0)
                            throw new InvalidOperationException("Clearing a saved accounting template must remove its details.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = originalTheme; }
        }

        private static void VerifyAccountingReportSnapshot()
        {
            using (var form = new AccountingReportsForm("CostCenters", true))
            {
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var type = typeof(AccountingReportsForm);
                AntdUI.DatePicker from = (AntdUI.DatePicker)type.GetField("fromDate", flags).GetValue(form);
                AntdUI.DatePicker to = (AntdUI.DatePicker)type.GetField("toDate", flags).GetValue(form);
                from.Value = new DateTime(2026, 9, 1); to.Value = new DateTime(2026, 9, 30);
                var capture = type.GetMethod("CaptureReportRequest", flags);
                object request = capture.Invoke(form, null);
                type.GetField("loadedRequest", flags).SetValue(form, request);
                var table = new DataTable();
                table.Columns.Add("مدين", typeof(decimal)); table.Columns.Add("دائن", typeof(decimal));
                table.Columns.Add("الصافي", typeof(decimal)); table.Rows.Add(12m, 9m, 3m);
                type.GetField("currentTable", flags).SetValue(form, table);
                from.Value = new DateTime(2026, 10, 1); to.Value = new DateTime(2026, 10, 31);
                type.GetField("activeReport", flags).SetValue(form, "Tax");
                string title = (string)type.GetMethod("GetLoadedReportTitle", flags).Invoke(form, null);
                string period = (string)type.GetMethod("GetLoadedReportPeriod", flags).Invoke(form, null);
                type.GetMethod("PresentLoadedReportMetadata", flags).Invoke(form, null);
                var heading = (Label)type.GetField("reportTitle", flags).GetValue(form);
                var loadedGrid = (DataGridView)type.GetField("grid", flags).GetValue(form);
                if (heading.Text != title || !loadedGrid.AccessibleDescription.Contains(period))
                    throw new InvalidOperationException("Accounting result heading/accessibility must describe the loaded snapshot.");
                if (!title.Contains("مراكز التكلفة") || !period.Contains("2026/09/01") || !period.Contains("2026/09/30"))
                    throw new InvalidOperationException("Accounting print metadata drifted to unsubmitted filters.");
                type.GetMethod("RenderSummary", flags).Invoke(form, null);
                if (Require<FlowLayoutPanel>(form, "accountingReportSummary").Controls.Count != 5)
                    throw new InvalidOperationException("Accounting summary must describe the loaded report type.");
                to.Value = new DateTime(2026, 8, 1);
                try
                {
                    capture.Invoke(form, null);
                    throw new InvalidOperationException("Reversed accounting dates were accepted.");
                }
                catch (System.Reflection.TargetInvocationException exception)
                {
                    if (!(exception.InnerException is ArgumentException)) throw;
                }
                if (!ReferenceEquals(table, type.GetField("currentTable", flags).GetValue(form)) ||
                    !ReferenceEquals(request, type.GetField("loadedRequest", flags).GetValue(form)))
                    throw new InvalidOperationException("Accounting validation must preserve the previous result snapshot.");
            }
        }

        private static void VerifyIntegrityReadOnlyLayouts()
        {
            using (var form = new AccountingIntegrityForm(true))
                VerifyIntegrityReadOnlyLayout(form, "accountingIntegrity", "refreshAccountingIntegrity", "closeAccountingIntegrity");
            using (var form = new InventoryIntegrityForm(true))
                VerifyIntegrityReadOnlyLayout(form, "inventoryIntegrity", "refreshInventoryIntegrity", "closeInventoryIntegrity");
            using (var form = new PeriodCloseReadinessForm(true))
