                    "Entry number", "قيد بلا أسطر", "Entry without lines");
            using (var form = new InventoryIntegrityForm(true))
                VerifyIntegrityPresentation(form, form.ApplyPresentation, "inventoryIntegrity", "رقم الحركة",
                    "Movement number", "تسلسل الحركات غير متصل", "Movement sequence has a gap");
        }

        private static void VerifyIntegrityPresentation(Form form, Action<bool> applyPresentation, string prefix,
            string identifierColumn, string englishIdentifier, string arabicIssue, string englishIssue)
        {
            form.ShowInTaskbar = false;
            form.StartPosition = FormStartPosition.Manual;
            form.Location = new Point(-20000, -20000);
            form.Show();
            if (form.Controls["__UiStatusStrip"] != null)
                throw new InvalidOperationException("Integrity preview exposes the live application status strip: " + prefix);
            DataGridView grid = Require<DataGridView>(form, prefix + "Grid");
            if (grid.Rows.Count != 2)
                throw new InvalidOperationException("Integrity preview fixture must expose both representative issues without SQL: " + prefix);
            if (prefix == "accountingIntegrity")
            {
                AntdUI.DatePicker start = Require<AntdUI.DatePicker>(form, "integrityFromDate");
                AntdUI.DatePicker end = Require<AntdUI.DatePicker>(form, "integrityToDate");
                DateTime originalStart, originalEnd;
                if (!AntdDateInput.TryRead(start, out originalStart) || !AntdDateInput.TryRead(end, out originalEnd))
                    throw new InvalidOperationException("Accounting integrity date inputs are not readable before language changes.");
                if (start.Height < 44 || end.Height < 44 || originalStart > originalEnd)
                    throw new InvalidOperationException("Accounting integrity date targets are too small or reversed.");
                start.Text = "2026/09/23";
                DateTime visibleDate;
                if (!AntdDateInput.TryRead(start, out visibleDate) || visibleDate != new DateTime(2026, 9, 23))
                    throw new InvalidOperationException("Accounting integrity did not read the visible date before the picker commits it.");
                start.Value = originalStart;
            }
            applyPresentation(true);
            OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
            foreach (Size size in new[] { form.ClientSize, new Size(760, 520), new Size(940, 620), new Size(1280, 760) })
            {
                Prepare(form, size);
                VerifyIntegritySharedComponents(form, prefix);
                Panel footer = Require<Panel>(form, prefix + "Actions");
                AntdUI.Button refresh = Require<AntdUI.Button>(form,
                    prefix == "accountingIntegrity" ? "refreshAccountingIntegrity" : "refreshInventoryIntegrity");
                AntdUI.Button close = Require<AntdUI.Button>(form,
                    prefix == "accountingIntegrity" ? "closeAccountingIntegrity" : "closeInventoryIntegrity");
                if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                    grid.RightToLeft != RightToLeft.No || grid.Columns[identifierColumn].HeaderText != englishIdentifier ||
                    grid.Columns["الحالة"].DisplayIndex != 1 ||
                    grid.Columns["الحالة"].Width < (prefix == "inventoryIntegrity" ? 285 : 185) ||
                    Convert.ToString(grid.Rows[0].Cells["الحالة"].FormattedValue) != englishIssue ||
                    Convert.ToString(grid.Rows[0].Cells["الحالة"].Value) != arabicIssue ||
                    grid.ColumnHeadersDefaultCellStyle.SelectionForeColor != Color.White ||
                    refresh.Left >= close.Left || close.Right > footer.ClientSize.Width ||
                    !Require<Label>(form, prefix + "Status").Text.Contains("Read-only preview"))
                    throw new InvalidOperationException("Integrity English display changed data or clipped controls at " + size + ": " + prefix);
                if (prefix == "accountingIntegrity" &&
                    (Require<AntdUI.DatePicker>(form, "integrityFromDate").Height < 44 ||
                     Require<AntdUI.DatePicker>(form, "integrityToDate").Height < 44))
                    throw new InvalidOperationException("Accounting integrity dates lost their 44-pixel targets at " + size + ".");
            }
            applyPresentation(false);
            Prepare(form, new Size(760, 520));
            VerifyIntegritySharedComponents(form, prefix);
            AntdUI.Button arabicRefresh = Require<AntdUI.Button>(form,
                prefix == "accountingIntegrity" ? "refreshAccountingIntegrity" : "refreshInventoryIntegrity");
            AntdUI.Button arabicClose = Require<AntdUI.Button>(form,
                prefix == "accountingIntegrity" ? "closeAccountingIntegrity" : "closeInventoryIntegrity");
            if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                grid.RightToLeft != RightToLeft.Yes || grid.Columns[identifierColumn].HeaderText != identifierColumn ||
                grid.Columns["الحالة"].DisplayIndex != 1 ||
                grid.Columns["الحالة"].Width < (prefix == "inventoryIntegrity" ? 285 : 185) ||
                Convert.ToString(grid.Rows[0].Cells["الحالة"].FormattedValue) != arabicIssue ||
                arabicRefresh.Left <= arabicClose.Left)
                throw new InvalidOperationException("Integrity Arabic display did not restore the reading edge: " + prefix +
                    "; formRtl=" + form.RightToLeft + "/" + form.RightToLeftLayout +
                    "; gridRtl=" + grid.RightToLeft +
                    "; idHeader=" + grid.Columns[identifierColumn].HeaderText +
                    "; statusDisplay=" + grid.Columns["الحالة"].DisplayIndex +
                    "; statusWidth=" + grid.Columns["الحالة"].Width +
                    "; formatted=" + Convert.ToString(grid.Rows[0].Cells["الحالة"].FormattedValue) +
                    "; raw=" + Convert.ToString(grid.Rows[0].Cells["الحالة"].Value) +
                    "; actions=" + arabicRefresh.Left + "/" + arabicClose.Left + ".");
        }

        private static void VerifyIntegritySharedComponents(Form form, string prefix)
        {
            AntdUI.Panel card = Require<AntdUI.Panel>(form, prefix + "GridCard");
            DataGridView grid = Require<DataGridView>(form, prefix + "Grid");
            foreach (string suffix in new[] { "Title", "Subtitle" })
            {
                Label label = Require<Label>(form, prefix + suffix);
                int needed = TextRenderer.MeasureText(label.Text, label.Font,
                    new Size(Math.Max(1, label.Width - label.Padding.Horizontal), int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                if (label.Height < needed || label.AccessibleName != label.Text)
                    throw new InvalidOperationException("Integrity heading clipped or inaccessible: " + label.Name);
            }
            if (card.Radius != 12 || card.Shadow != 0 || !UiTheme.OwnsCustomGridColumns(grid) ||
                !UiTheme.OwnsLocalizedGridPresentation(grid) || !grid.ReadOnly || grid.ColumnHeadersHeight < 60 ||
                grid.Height < grid.ColumnHeadersHeight + grid.RowTemplate.Height + SystemInformation.HorizontalScrollBarHeight)
                throw new InvalidOperationException("Integrity shared components failed: " + prefix + " at " + form.ClientSize);
            if (prefix == "inventoryIntegrity" && grid.Columns["الصنف"].Width < 200)
                throw new InvalidOperationException("Inventory integrity medicine identity column is too narrow.");
        }

        internal static void VerifyPeriodReadinessPresentation()
        {
            using (var form = new PeriodCloseReadinessForm(true))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.MaximizeBox = false;
                form.Show();
                if (form.Controls["__UiStatusStrip"] != null)
                    throw new InvalidOperationException("Period readiness preview exposes the live application status strip.");
                DataGridView grid = Require<DataGridView>(form, "periodReadinessGrid");
                if (grid.Rows.Count != 4)
                    throw new InvalidOperationException("Period readiness preview fixture must expose all four read-only checks without SQL.");
                AntdUI.DatePicker readinessStart = Require<AntdUI.DatePicker>(form, "periodReadinessFromDate");
                AntdUI.DatePicker readinessEnd = Require<AntdUI.DatePicker>(form, "periodReadinessToDate");
                DateTime originalFrom;
                if (!AntdDateInput.TryRead(readinessStart, out originalFrom))
                    throw new InvalidOperationException("Period readiness start date is not readable.");
                DateTime visibleDate;
                readinessStart.Text = "2026/09/23";
                if (!AntdDateInput.TryRead(readinessStart, out visibleDate) || visibleDate != new DateTime(2026, 9, 23))
                    throw new InvalidOperationException("Period readiness did not read the visible date before it was committed.");
                readinessStart.Value = originalFrom;
                form.ApplyPresentation(true);
                OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
                foreach (Size size in new[] { form.ClientSize, new Size(760, 500), new Size(940, 620), new Size(1280, 760) })
                {
                    Prepare(form, size);
                    VerifyReadinessSharedHeader(form);
                    foreach (DataGridViewRow row in grid.Rows)
                    {
                        var cell = row.Cells["التفصيل"];
                        int width = Math.Max(1, cell.Size.Width - cell.InheritedStyle.Padding.Horizontal - 6);
                        int needed = TextRenderer.MeasureText(Convert.ToString(cell.FormattedValue),
                            cell.InheritedStyle.Font ?? grid.Font, new Size(width, int.MaxValue),
                            TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding).Height;
                        if (row.Height < needed + cell.InheritedStyle.Padding.Vertical)
                            throw new InvalidOperationException("Readiness detail must be fully readable without ellipsis at " + size);
                    }

                    Panel footer = Require<Panel>(form, "periodReadinessActions");
                    AntdUI.Button refresh = Require<AntdUI.Button>(form, "refreshPeriodReadiness");
                    AntdUI.Button close = Require<AntdUI.Button>(form, "closePeriodReadiness");
                    if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                        refresh.Left >= close.Left || close.Right > footer.ClientSize.Width ||
                        Require<TableLayoutPanel>(form, "periodReadinessFilters").RightToLeft != RightToLeft.No ||
                        grid.RightToLeft != RightToLeft.No || grid.Columns["الفحص"].HeaderText != "Check" ||
                        grid.Columns["التفصيل"].HeaderText != "Details" ||
                        Convert.ToString(grid.Rows[0].Cells["الحالة"].FormattedValue) != "Needs review" ||
                        Convert.ToString(grid.Rows[0].Cells["الفحص"].FormattedValue) != "Journal integrity" ||
                        Convert.ToString(grid.Rows[0].Cells["الحالة"].Value) != "يحتاج مراجعة" ||
                        grid.ColumnHeadersDefaultCellStyle.SelectionForeColor != Color.White ||
                        !Require<Label>(form, "periodReadinessStatus").Text.Contains("Read-only preview") ||
                        readinessStart.Height < 44 || readinessEnd.Height < 44)
                        throw new InvalidOperationException("Period readiness English presentation changed the result or clipped actions at " + size + ".");
                }
                form.ApplyPresentation(false);
                Prepare(form, new Size(760, 500));
                VerifyReadinessSharedHeader(form);
                if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                    grid.RightToLeft != RightToLeft.Yes || grid.Columns["الفحص"].HeaderText != "الفحص" ||
                    Convert.ToString(grid.Rows[0].Cells["الحالة"].FormattedValue) != "يحتاج مراجعة" ||
                    Require<AntdUI.Button>(form, "refreshPeriodReadiness").Left <=
                        Require<AntdUI.Button>(form, "closePeriodReadiness").Left ||
                    readinessStart.Value != originalFrom)
                    throw new InvalidOperationException("Period readiness did not restore Arabic or changed the selected date.");
            }
        }

        private static void VerifyReadinessSharedHeader(Form form)
        {
            AntdUI.Panel card = Require<AntdUI.Panel>(form, "periodReadinessGridCard");
            Label title = Require<Label>(form, "periodReadinessTitle");
            Label subtitle = Require<Label>(form, "periodReadinessSubtitle");
            DataGridView grid = Require<DataGridView>(form, "periodReadinessGrid");
            foreach (Label label in new[] { title, subtitle })
            {
                int needed = TextRenderer.MeasureText(label.Text, label.Font,
                    new Size(Math.Max(1, label.Width - label.Padding.Horizontal), int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                if (label.Height < needed || label.AccessibleName != label.Text)
                    throw new InvalidOperationException("Readiness heading is clipped or inaccessible: " + label.Name);
            }
            if (card.Radius != 12 || card.Shadow != 0 || !grid.ReadOnly ||
                grid.Height < grid.ColumnHeadersHeight + grid.RowTemplate.Height + SystemInformation.HorizontalScrollBarHeight)
                throw new InvalidOperationException("Readiness shared card or first result row is not available at " + form.ClientSize);
            if (!UiTheme.OwnsCustomGridColumns(grid) || !UiTheme.OwnsLocalizedGridPresentation(grid) ||
                grid.Columns["التفصيل"].Width < 280 || grid.Columns["عدد الملاحظات"].Width >= grid.Columns["الفحص"].Width ||
                grid.ScrollBars != ScrollBars.Both)
                throw new InvalidOperationException("Readiness result columns do not prioritize the check and details.");
        }

        private static void VerifyIntegrityReadOnlyLayout(Form form, string prefix, string refreshName, string closeName)
        {
            form.ShowInTaskbar = false;
            form.StartPosition = FormStartPosition.Manual;
            form.Location = new Point(-20000, -20000);
            form.Show();
            foreach (Size size in new[] { new Size(760, 520), new Size(940, 620), new Size(1280, 760) })
            {
                Prepare(form, size);
                Panel header = Require<Panel>(form, prefix + "Header");
                Panel footer = Require<Panel>(form, prefix + "Actions");
                Label title = Require<Label>(form, prefix + "Title");
                Label subtitle = Require<Label>(form, prefix + "Subtitle");
                  Label status = Require<Label>(form, prefix + "Status");
                DataGridView grid = Require<DataGridView>(form, prefix + "Grid");
                if (footer.Controls[refreshName] == null || footer.Controls[closeName] == null)
                    throw new InvalidOperationException("Integrity footer children missing at " + size + ": " + prefix +
                        ", found=" + string.Join(",", footer.Controls.Cast<Control>().Select(control => control.Name + "/" + control.GetType().Name)) + ".");
                if (!(footer.Controls[refreshName] is AntdUI.Button))
                    throw new InvalidOperationException("Integrity refresh has unexpected type at " + size + ": " +
                        footer.Controls[refreshName].GetType().FullName + ".");
                AntdUI.Button refresh = (AntdUI.Button)footer.Controls[refreshName];
                AntdUI.Button close = (AntdUI.Button)footer.Controls[closeName];
                Control statusStrip = form.Controls["__UiStatusStrip"];
                int workspaceBottom = form.ClientSize.Height - (statusStrip == null ? 0 : statusStrip.Height);
                if (header.Top != 0 || header.Width != form.ClientSize.Width ||
                    header.BackColor != UiTheme.Background || title.ForeColor != UiTheme.Text ||
                      subtitle.ForeColor != UiTheme.MutedText || status.BackColor != UiTheme.Background ||
                      footer.BackColor != UiTheme.Background ||
                    footer.Bottom != workspaceBottom || grid.Height < 180 || !grid.ReadOnly ||
                    refresh.BorderWidth != 1 || close.BorderWidth != 1 ||
                    refresh.DefaultBorderColor != UiTheme.Primary || close.DefaultBorderColor != UiTheme.Primary ||
                    refresh.Height < 44 || close.Height < 44)
                    throw new InvalidOperationException("Integrity screen theme or structure failed at " + size + ": " + prefix +
                        "; header=" + header.Bounds + "/" + header.BackColor +
                        "; title=" + title.ForeColor + "; subtitle=" + subtitle.ForeColor +
                        "; footer=" + footer.Bounds + "/" + footer.BackColor + "; bottom=" + workspaceBottom +
                        "; grid=" + grid.Bounds + "/readOnly=" + grid.ReadOnly +
                        "; refresh=" + refresh.Bounds + "/border=" + refresh.BorderWidth + "/color=" + refresh.DefaultBorderColor +
                        "; close=" + close.Bounds + "/border=" + close.BorderWidth + "/color=" + close.DefaultBorderColor + ".");
                if (refresh.Left < 0 || refresh.Right > footer.ClientSize.Width ||
                    close.Left < 0 || close.Right > footer.ClientSize.Width ||
                    refresh.Top < 0 || refresh.Bottom > footer.ClientSize.Height ||
                    close.Top < 0 || close.Bottom > footer.ClientSize.Height)
                    throw new InvalidOperationException("Integrity footer clips at " + size + ": " + prefix +
                        ", footer=" + footer.Bounds + ", refresh=" + refresh.Bounds + ", close=" + close.Bounds + ".");
                int refreshX = refresh.PointToScreen(Point.Empty).X;
                int closeX = close.PointToScreen(Point.Empty).X;
                if (UiDirection.IsLeftToRight ? refreshX >= closeX : refreshX <= closeX)
                    throw new InvalidOperationException("Integrity actions are on the wrong reading edge at " + size + ": " + prefix);
                if (size.Width == 760)
                {
                    refresh.PerformClick();
                    int expectedRows = prefix == "periodReadiness" ? 4 : 2;
                    if (!status.Text.Contains("المعاينة") || grid.Rows.Count != expectedRows)
                        throw new InvalidOperationException("Integrity preview attempted a database read: " + prefix);
                }
                  if (prefix == "accountingIntegrity" || prefix == "periodReadiness")
                  {
                      TableLayoutPanel filters = Require<TableLayoutPanel>(form, prefix + "Filters");
                      if (filters.BackColor != UiTheme.Background)
                          throw new InvalidOperationException("Integrity filters bypass the neutral surface at " + size + ".");
                  }
            }
        }

        private static void VerifyDatabaseSettingsLayout()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var palette = new Form()) UiTheme.Apply(palette);
                    VerifyDatabaseSettingsLayoutCases();
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = original;
                using (var palette = new Form()) UiTheme.Apply(palette);
            }
        }

        private static void VerifyDatabaseSettingsLayoutCases()
        {
            VerifyDatabaseSharedActions();
            foreach (bool english in new[] { false, true })
            using (var form = new DatabaseSetingsForm(true, english))
            {
                Size originalMinimum = form.MinimumSize;
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                Application.DoEvents();
                Size minimumClient = new Size(originalMinimum.Width - (form.Width - form.ClientSize.Width),
                    originalMinimum.Height - (form.Height - form.ClientSize.Height));
                foreach (Size size in new[] { minimumClient, new Size(360, 320), new Size(360, 570),
                    new Size(640, 570), new Size(760, 570), new Size(1024, 680), new Size(1920, 1080) })
                {
                    OwnedTestWindowViewport.Resize(form, size);
                    if (form.MinimumSize != originalMinimum)
                        throw new InvalidOperationException("Database settings fixture changed its declared minimum.");
                    Console.WriteLine("PASS database settings native viewport: theme=" + Properties.Setings.Default.ThemeMode +
                        "; english=" + english + "; client=" + size + "; minimum=" + originalMinimum);
                    var body = Require<AntdUI.Panel>(form, "databaseSettingsBody");
                    Panel footer = Require<Panel>(form, "databaseSettingsFooter");
                    Panel header = Require<Panel>(form, "databaseSettingsHeader");
                    Label title = Require<Label>(form, "databaseSettingsTitle");
                    Label subtitle = Require<Label>(form, "databaseSettingsSubtitle");
                    if (title.Bounds.IntersectsWith(subtitle.Bounds) ||
                        subtitle.Height < TextRenderer.MeasureText(subtitle.Text, subtitle.Font, new Size(subtitle.Width, int.MaxValue),
                            TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height || title.AccessibleName != title.Text || subtitle.AccessibleName != subtitle.Text)
                        throw new InvalidOperationException("Database settings title/hint are clipped or overlapping at " + size);
                    if (body.Dock != DockStyle.Fill || !body.AutoScroll ||
                        header.Dock != DockStyle.Top || header.Bottom > body.Top ||
                        footer.Dock != DockStyle.Bottom || footer.Bottom > form.ClientSize.Height ||
                        body.Bottom > footer.Top || footer.Height < 62 || subtitle.Bottom > header.ClientSize.Height)
                        throw new InvalidOperationException("Database settings body/footer overlap at " + size + ".");
                    if (title.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                        subtitle.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                        (english && title.Text != "Connection settings") || (!english && title.Text != "إعدادات الاتصال"))
                        throw new InvalidOperationException("Database settings heading direction or translation failed at " + size + ".");
                    if (Require<AntdUI.Button>(form, "databaseSaveConnection").Text != (english ? "Save" : "حفظ") ||
                        Require<AntdUI.Button>(form, "databaseFindServers").Text != (english ? "Search" : "بحث") ||
                        Require<AntdUI.Button>(form, "databaseClose").Text != (english ? "Close" : "إغلاق"))
                        throw new InvalidOperationException("Database settings visible action language failed at " + size + ".");
                    foreach (string actionName in new[] { "databaseFindServers", "databaseLoadCatalogs",
                        "databaseTestConnection", "databaseSaveConnection", "databaseSaveAppearance" })
                        if (Require<AntdUI.Button>(form, actionName).Enabled)
                            throw new InvalidOperationException("Database settings preview can execute: " + actionName);
                    foreach (Control control in body.Controls)
                    {
                        if (control.Left < 0 || control.Right > body.ClientSize.Width)
                            throw new InvalidOperationException("Database settings field exceeds width " + size + ": " + control.GetType().Name);
                        if (!(control is ComboBox) && control.Name != "databaseSaveAppearance") continue;
                        foreach (Control other in body.Controls)
                            if (other != control && (other is ComboBox || other.Name == "databaseSaveAppearance") && control.Bounds.IntersectsWith(other.Bounds))
                                throw new InvalidOperationException("Database settings inputs overlap at " + size);
                    }
                    foreach (Control action in footer.Controls)
                    {
                        if (action.Left < 0 || action.Right > footer.ClientSize.Width ||
                            action.Top < 0 || action.Bottom > footer.ClientSize.Height || action.Height < 44)
                            throw new InvalidOperationException("Database settings action clipped at " + size + ": " + action.Name);
                        foreach (Control other in footer.Controls)
                            if (other != action && action.Bounds.IntersectsWith(other.Bounds))
                                throw new InvalidOperationException("Database settings actions overlap at " + size);
                    }
                }
            }
            VerifyDatabaseCreationConfirmationLayout();
        }

        private static void VerifyDatabaseCreationConfirmationLayout()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var palette = new Form()) UiTheme.Apply(palette);
                    foreach (bool english in new[] { false, true })
                    using (var owner = new DatabaseSetingsForm(true, english))
                    using (Form dialog = owner.CreateNewDatabaseConfirmation("preview-server\\INSTANCE", "PreviewDb"))
                    {
                        dialog.StartPosition = FormStartPosition.Manual;
                        dialog.Location = new Point(-20000, -20000);
                        dialog.Show();
                        // Test the actual declared minimum: native frame metrics make the old 320x300 request one pixel too short here.
                        Size minimumClient = new Size(dialog.MinimumSize.Width - (dialog.Width - dialog.ClientSize.Width),
                            dialog.MinimumSize.Height - (dialog.Height - dialog.ClientSize.Height));
                        foreach (Size size in new[] { minimumClient, new Size(360, 320), new Size(560, 380) })
                        {
                            Prepare(dialog, size);
                            var body = Require<AntdUI.Panel>(dialog, "databaseCreationBody");
                            var viewport = Require<Panel>(dialog, "databaseCreationViewport");
                            var footer = Require<Panel>(dialog, "databaseCreationFooter");
                            var title = Require<Label>(dialog, "databaseCreationTitle");
                            var message = Require<Label>(dialog, "databaseCreationMessage");
                            var instruction = Require<Label>(dialog, "databaseCreationInstruction");
                            var input = Require<AntdUI.Input>(dialog, "databaseCreationName");
                            var create = Require<AntdUI.Button>(dialog, "databaseCreationConfirm");
                            var cancel = Require<AntdUI.Button>(dialog, "databaseCreationCancel");
                            if (dialog.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                dialog.RightToLeftLayout == english || !viewport.AutoScroll || viewport.Bottom > footer.Top ||
                                title.Bounds.IntersectsWith(message.Bounds) || message.Bounds.IntersectsWith(instruction.Bounds) ||
                                instruction.Bounds.IntersectsWith(input.Bounds) ||
                                input.Left < 0 || input.Right > body.ClientSize.Width || input.Height < 44 ||
                                viewport.AutoScrollMinSize.Height < input.Bottom + 16 ||
                                viewport.HorizontalScroll.Visible || body.Width > viewport.ClientSize.Width ||
                                (input.Bottom > viewport.ClientSize.Height && !viewport.VerticalScroll.Visible) ||
                                create.Bounds.IntersectsWith(cancel.Bounds))
                                throw new InvalidOperationException("Database creation confirmation overlaps or loses direction at " + size + ".");
                            foreach (AntdUI.Button action in new[] { create, cancel })
                                if (action.Height < 44 || action.Left < 0 || action.Right > footer.ClientSize.Width ||
                                    action.Top < 0 || action.Bottom > footer.ClientSize.Height ||
                                    action.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right))
                                    throw new InvalidOperationException("Database creation action is clipped at " + size + ".");
                            if (dialog.Text != (english ? "Confirm new database creation" : "تأكيد إنشاء قاعدة جديدة") ||
                                !message.Text.Contains("preview-server\\INSTANCE") || !message.Text.Contains("PreviewDb") ||
                                (english ? !message.Text.StartsWith("Server: ") : !message.Text.StartsWith("الخادم: ")) ||
                                !ReferenceEquals(dialog.AcceptButton, create) || !ReferenceEquals(dialog.CancelButton, cancel))
                                throw new InvalidOperationException("Database creation text or keyboard action is incorrect at " + size + ".");
                            input.Text = "OtherDb";
                            if (create.Enabled) throw new InvalidOperationException("Wrong database name enabled creation.");
                            input.Text = "PreviewDb";
                            if (!create.Enabled) throw new InvalidOperationException("Matching database name did not enable creation.");
                            input.Text = string.Empty;
                        }
                        dialog.Close();
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; using (var palette = new Form()) UiTheme.Apply(palette); }
        }
        private static void VerifyDatabaseSharedActions()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var palette = new Form()) UiTheme.Apply(palette);
                    foreach (bool english in new[] { false, true })
                    using (var form = new DatabaseSetingsForm(true, english))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show(); OwnedTestWindowViewport.ResizeOuter(form, form.MinimumSize);
                        var server = Require<ComboBox>(form, "databaseServer");
                        var database = Require<ComboBox>(form, "databaseCatalog");
                        server.Text = "preview-server\\INSTANCE"; database.Text = "PreviewDb";
                        foreach (Size size in new[] { form.ClientSize, new Size(360, 320), new Size(640, 570), new Size(760, 570), new Size(1024, 680) })
                        {
                            Prepare(form, size);
                            var body = Require<AntdUI.Panel>(form, "databaseSettingsBody");
                            if (body.ClientSize.Width - SystemInformation.VerticalScrollBarWidth >= 720)
                            {
                                var caption = Require<Label>(form, "databaseServerLabel");
                                if (english ? caption.Right > server.Left : server.Right > caption.Left)
                                    throw new InvalidOperationException("Database caption column does not follow interface language.");
                            }
                            foreach (string actionName in new[] { "databaseFindServers", "databaseLoadCatalogs", "databaseTestConnection",
                                "databaseSaveConnection", "databaseSaveAppearance", "databaseClose" })
                            {
                                var button = Require<AntdUI.Button>(form, actionName);
                                if (button.Height != 44 || button.BorderWidth != 1 || button.DefaultBorderColor != UiTheme.Primary ||
                                    button.Radius != DesktopDesignTokens.ActionRadius(button.Height) || string.IsNullOrWhiteSpace(button.IconSvg) ||
                                    button.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right) ||
                                    (actionName != "databaseSaveAppearance" && !button.Parent.ClientRectangle.Contains(button.Bounds)))
                                    throw new InvalidOperationException("Database action lost shared style or is clipped: " + actionName + " " + size);
                            }
                            if (server.Text != "preview-server\\INSTANCE" || database.Text != "PreviewDb" ||
                                server.RightToLeft != RightToLeft.No || database.RightToLeft != RightToLeft.No ||
                                !ReferenceEquals(form.AcceptButton, Require<AntdUI.Button>(form, "databaseSaveConnection")) ||
                                !ReferenceEquals(form.CancelButton, Require<AntdUI.Button>(form, "databaseClose")))
                                throw new InvalidOperationException("Database layout changed connection values or dialog contract.");
                        }
                        var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                        var busy = typeof(DatabaseSetingsForm).GetMethod("SetBusy", flags);
                        busy.Invoke(form, new object[] { true, "Long status message: wait for the current operation to finish before closing this window.", true });
                        if (Require<AntdUI.Button>(form, "databaseClose").Enabled)
                            throw new InvalidOperationException("Database write state did not disable closing.");
                        var closing = new FormClosingEventArgs(CloseReason.UserClosing, false);
                        typeof(DatabaseSetingsForm).GetMethod("OnFormClosing", flags).Invoke(form, new object[] { closing });
                        if (!closing.Cancel) throw new InvalidOperationException("Database write state did not reject window closure.");
                        busy.Invoke(form, new object[] { false, null, false });
                        foreach (string actionName in new[] { "databaseFindServers", "databaseLoadCatalogs", "databaseTestConnection", "databaseSaveConnection", "databaseSaveAppearance" })
                            if (Require<AntdUI.Button>(form, actionName).Enabled)
                                throw new InvalidOperationException("Database preview re-enabled operations after busy state.");
                        foreach (string method in new[] { "FindServers_Click", "LoadDatabases_Click", "TestConnection_Click", "Save_Click", "SaveAppearance_Click" })
                            typeof(DatabaseSetingsForm).GetMethod(method, flags).Invoke(form, new object[] { null, EventArgs.Empty });
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = original; using (var palette = new Form()) UiTheme.Apply(palette); }
        }

        private static void VerifyBillingAtCompactSize()
        {
            using (var form = new BillingPreview())
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[]
                {
                    new Size(960, 640), new Size(1024, 650),
                    new Size(1280, 760), new Size(1920, 1080)
                })
                {
                    Prepare(form, size);
                    if (form.ClientSize != size)
                        throw new InvalidOperationException("BILLING_REQUESTED_SIZE_CLAMPED requested=" + size + " actual=" + form.ClientSize + ".");
                    CommerceWorkspaceTheme.RefreshLayout(form);
                    form.PerformLayout();

                    Panel scanStrip = Require<Panel>(form, "pnlBillingScanStrip");
                    Panel sidebar = Require<Panel>(form, "pnlBillingSidebar");
                    Panel totals = Require<Panel>(form, "pnlTotals");
                    Panel cart = Require<Panel>(form, "pnlCartHost");
                    if (cart.Bounds.IntersectsWith(sidebar.Bounds) || totals.Visible)
                        throw new InvalidOperationException("BILLING_CART_OVERLAP size=" + size + ".");

                    foreach (string checkoutControlName in new[] { "lblCheckoutTitle", "PriceBDLabel", "PriceADLabel", "lblCheckoutPayment", "TimingLabel" })
                    {
                        Control customerTypeSelector = Require<Control>(sidebar, "btnBillingCustomerType");
                        RequireHorizontallyInside(sidebar, customerTypeSelector, "Customer type selector");
                        Control checkoutControl = Require<Control>(sidebar, checkoutControlName);
                        RequireHorizontallyInside(sidebar, checkoutControl, "Invoice summary/" + checkoutControlName);
                        if (checkoutControl.Parent != sidebar)
                            throw new InvalidOperationException("BILLING_SUMMARY_PARENT control=" + checkoutControlName);
                    }
                    Control customerType = Require<Control>(sidebar, "btnBillingCustomerType");
                    Control confirmAction = Require<Control>(sidebar, "btnConfirmCustomer");
                    if (!customerType.Visible || !customerType.Text.Contains("نوع العميل"))
                        throw new InvalidOperationException("BILLING_CUSTOMER_TYPE_NOT_VISIBLE size=" + size + ".");
                    RequireInside(sidebar, customerType, "Customer type indicator");
                    Control topControl = sidebar.GetChildAtPoint(
                        new Point(customerType.Left + customerType.Width / 2, customerType.Top + customerType.Height / 2),
                        GetChildAtPointSkip.Invisible);
                    if (topControl != customerType)
                        throw new InvalidOperationException("BILLING_CUSTOMER_TYPE_COVERED size=" + size + " by=" + (topControl == null ? "none" : topControl.Name) + ".");
                    if (customerType.AccessibleName == null || !customerType.AccessibleName.Contains("نوع العميل"))
                        throw new InvalidOperationException("BILLING_CUSTOMER_TYPE_ACCESSIBLE_NAME size=" + size + ".");
                    if (sidebar.Controls["openCustomerManagementFromBilling"] != null)
                        throw new InvalidOperationException("BILLING_SEPARATE_CUSTOMER_SELECTION_ACTION_VISIBLE size=" + size + ".");
                    if (confirmAction.Visible)
                        throw new InvalidOperationException("BILLING_REDUNDANT_CUSTOMER_CONFIRM_VISIBLE size=" + size + ".");
                    foreach (string personalControlName in new[]
                    {
                        "lblCustomerName", "lblCustomerPhone", "lblCustomerAddress",
                        "cmbCustomerName", "cmbCustomerPhone", "txtCustomerAddress",
                        "CustomerIdLabel", "CustomerNameLabel", "CustomerPhoneLabel",
                        "CustomerAddressLabel", "lblCheckoutCustomerTitle"
                    })
                    {
                        Control personalControl = Find<Control>(form, personalControlName);
                        if (personalControl == null) continue;
                        if (personalControl.Visible)
                            throw new InvalidOperationException("BILLING_CUSTOMER_PERSONAL_DATA_VISIBLE control=" + personalControlName + " size=" + size + ".");
                    }

                    Control customerCreditBalance = Require<Control>(sidebar, "lblCustomerCreditBalance");
                    Control useCustomerCredit = Require<Control>(sidebar, "chkUseCustomerCredit");
                    if (!(Require<Control>(sidebar, "SelectEmployee") is AntdUI.Select))
                        throw new InvalidOperationException("BILLING_CASHIER_SELECTOR_NOT_ANTDUI size=" + size + ".");
                    if (!(Require<Control>(sidebar, "txtDiscountPercent") is AntdUI.Input))
                        throw new InvalidOperationException("BILLING_DISCOUNT_INPUT_NOT_ANTDUI size=" + size + ".");
                    if (Require<AntdUI.Input>(sidebar, "txtDiscountPercent").RightToLeft != RightToLeft.No)
                        throw new InvalidOperationException("BILLING_DISCOUNT_DIRECTION size=" + size + ".");
                    TextBox notesEditor = Require<TextBox>(sidebar, "txtInvoiceNotes");
                    AntdUI.Input notesBacking = Require<AntdUI.Input>(form, "txtInvoiceNotesAntdBacking");
                    if (!notesEditor.Visible || notesBacking.Visible)
                        throw new InvalidOperationException("BILLING_NOTES_EDITOR_VISIBILITY size=" + size + ".");
                    string originalNotes = notesEditor.Text;
                    notesEditor.Text = "ملاحظة بيع — Paracetamol 500 mg";
                    if (notesBacking.Text != notesEditor.Text)
                        throw new InvalidOperationException("BILLING_NOTES_SAVE_SYNCHRONIZATION size=" + size + ".");
                    notesBacking.Text = "استعادة الفاتورة — Invoice 123";
                    if (notesEditor.Text != notesBacking.Text)
                        throw new InvalidOperationException("BILLING_NOTES_RESTORE_SYNCHRONIZATION size=" + size + ".");
                    notesEditor.Text = originalNotes;
                    if (customerCreditBalance.Visible)
                        throw new InvalidOperationException("BILLING_CUSTOMER_CREDIT_BALANCE_VISIBLE size=" + size + ".");

                    Control[] invoiceFlow = new[]
                    {
                        customerType,
                        Require<Control>(sidebar, "lblCheckoutTitle"),
                        Require<Control>(sidebar, "PriceBDLabel"),
                        Require<Control>(sidebar, "PriceADLabel"),
                        Require<Control>(sidebar, "lblCheckoutPayment"),
                        Require<Control>(sidebar, "TimingLabel"),
                        useCustomerCredit
                    };
                    for (int i = 1; i < invoiceFlow.Length; i++)
                    {
                        if (invoiceFlow[i - 1].Bottom > invoiceFlow[i].Top)
                            throw new InvalidOperationException("BILLING_SUMMARY_OVERLAP before=" + invoiceFlow[i - 1].Name + " after=" + invoiceFlow[i].Name + " size=" + size + ".");
                    }
                    RequireHorizontallyInside(sidebar, useCustomerCredit, "Customer credit invoice input");
                    Control barcode = Require<Control>(scanStrip, "txtBarcode");
                    if (barcode.Visible || barcode.TabStop || Require<Control>(scanStrip, "lblBarcode").Visible)
                        throw new InvalidOperationException("BILLING_LEGACY_BARCODE_INPUT_VISIBLE size=" + size + ".");
                    Control productSelector = Require<Control>(scanStrip, "MediComboCb");
                    if (!(productSelector is MedicineSearchComboBox) || !productSelector.Visible || !productSelector.TabStop)
                        throw new InvalidOperationException("BILLING_MEDICINE_SELECTOR_NOT_NATIVE_FALLBACK size=" + size + ".");
                    RequireInside(scanStrip, productSelector, "اختيار صنف البيع");
                    Control quantityInput = Require<Control>(scanStrip, "txtQuantity");
                    if (!(quantityInput is AntdUI.Input) || quantityInput.RightToLeft != RightToLeft.No)
                        throw new InvalidOperationException("BILLING_QUANTITY_INPUT_NOT_ANTDUI_LTR size=" + size + ".");
                    RequireInside(scanStrip, quantityInput, "كمية البيع");
                    RequireInside(scanStrip, Require<Control>(scanStrip, "btnAddToCart"), "زر إضافة البيع");
                    RequireInside(scanStrip, Require<Control>(scanStrip, "lblStockStatus"), "حالة مخزون البيع");

                    Control product = Require<Control>(scanStrip, "MediComboCb");
                    Control quantity = Require<Control>(scanStrip, "txtQuantity");
                    if (product.Top < quantity.Top && product.Bottom > quantity.Top)
                        throw new InvalidOperationException("BILLING_PRODUCT_QUANTITY_OVERLAP size=" + size + ".");

                    DataGridView grid = Require<DataGridView>(form, "BillingGV");
                    if (grid.Width < 200 || grid.Height < 80)
                        throw new InvalidOperationException("BILLING_GRID_SIZE size=" + size + " grid=" + grid.Size + " cart=" + cart.Size + " scan=" + scanStrip.Size + " sidebar=" + sidebar.Size + " main=" + form.Controls["pnlBillingMain"].Size + ".");

                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "flowFooterButtons");
                    AntdUI.Button checkoutAction = Require<AntdUI.Button>(form, "btnPreviewPrint");
                    if (checkoutAction.Parent != footer || checkoutAction.Width <= 0 || checkoutAction.Height <= 0)
                        throw new InvalidOperationException("BILLING_CHECKOUT_FOOTER size=" + size + ".");

                    Label netTotal = Require<Label>(sidebar, "PriceADLabel");
                    Rectangle original = netTotal.Bounds;
                    CommerceWorkspaceTheme.RefreshTotals(form);
                    if (netTotal.Bounds != original)
                        throw new InvalidOperationException("BILLING_TOTAL_MOVED size=" + size + ".");

                    foreach (string actionName in new[] { "btnPreviewPrint", "btnSaveOnly", "btnClearInvoice", "btnBack" })
                    {
                        AntdUI.Button action = Require<AntdUI.Button>(form, actionName);
                        int expectedRadius = DesktopDesignTokens.ActionRadius(
                            (int)Math.Round(action.Height * 96.0 / Math.Max(96, action.DeviceDpi)));
                        if (action.Radius != expectedRadius)
                            throw new InvalidOperationException("BILLING_RADIUS_NOT_REFRESHED control=" + actionName + ".");
                    }
                }
            }
        }

        private static void VerifyLoginLayout()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    using (var form = new Login(false, true, false))
                    {

                        const string mixedName = "مدير Admin";
                        Require<ComboBox>(form, "username").Text = mixedName;
                        foreach (bool english in new[] { false, true })
                        {
                            form.ApplyPresentation(english);
                            using (var interaction = new Login(false, true, english))
                            {
                                if (interaction.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                    interaction.RightToLeftLayout == english)
                                    throw new InvalidOperationException("Login native window direction does not match its initial presentation.");
                                interaction.ShowInTaskbar = false;
                                interaction.StartPosition = FormStartPosition.Manual;
                                interaction.Location = new Point(-20000, -20000);
                                interaction.Show();
                                Application.DoEvents();
                            TextBox passwordInput = Require<TextBox>(interaction, "password");
                            AntdUI.Button passwordToggle = Require<AntdUI.Button>(interaction, "passwordVisibilityButton");
                            passwordInput.Text = "qa-only-3";
                            passwordInput.Select(2, 3);
                            passwordToggle.PerformClick();
                            if (passwordInput.UseSystemPasswordChar || passwordInput.PasswordChar != '\0' ||
                                passwordInput.SelectionStart != 2 || passwordInput.SelectionLength != 3 ||
                                passwordToggle.Text != (english ? "Hide" : "إخفاء"))
                                throw new InvalidOperationException("Login reveal did not preserve text selection or expose text.");
                            passwordInput.SelectedText = "XYZ";
                            if (passwordInput.PasswordChar != '\0' || passwordInput.Text != "qaXYZly-3")
                                throw new InvalidOperationException("Editing a revealed login password hid or changed it.");
                            int caret = passwordInput.SelectionStart;
                            passwordToggle.PerformClick();
                            if (passwordInput.UseSystemPasswordChar || passwordInput.PasswordChar != DesktopDesignTokens.PasswordMaskCharacter ||
                                passwordInput.SelectionStart != caret || passwordInput.SelectionLength != 0 ||
                                passwordToggle.Text != (english ? "Show" : "إظهار"))
                                throw new InvalidOperationException("Login remasking lost the caret or visibility label.");
                            }
                            foreach (Size size in new[] { new Size(360, 400), new Size(640, 480), new Size(820, 600), new Size(1280, 720), new Size(360, 400) })
                            {
                                Prepare(form, size);
                                AntdUI.Panel card = Require<AntdUI.Panel>(form, "loginCard");
                                Panel hero = Require<Panel>(form, "loginHero");
                                string[] names = { "label1", "loginSubtitle", "databaseSettingsButton", "label2", "username", "label3", "password", "passwordVisibilityButton", "chkRememberMe", "rememberHint", "button1", "button3" };
                                foreach (string name in names)
                                {
                                    Control control = Require<Control>(card, name);
                                    if (control.Visible) RequireInside(card, control, "Login/" + name);
                                }
                                foreach (Control first in card.Controls.Cast<Control>().Where(control => control.Visible))
                                    foreach (Control second in card.Controls.Cast<Control>().Where(control => control.Visible && control != first))
                                        if (first.Bounds.IntersectsWith(second.Bounds) &&
                                            !((first.Name == "password" && second.Name == "passwordVisibilityButton") ||
                                              (second.Name == "password" && first.Name == "passwordVisibilityButton")))
                                            throw new InvalidOperationException("Login controls overlap: " + first.Name + "/" + second.Name);

                                AntdUI.Button signIn = Require<AntdUI.Button>(form, "button1");
                                AntdUI.Button close = Require<AntdUI.Button>(form, "button3");
                                AntdUI.Button database = Require<AntdUI.Button>(form, "databaseSettingsButton");
                                AntdUI.Button visibility = Require<AntdUI.Button>(form, "passwordVisibilityButton");
                                if (signIn.Height < 44 || close.Visible && close.Height < 44 || database.Height < 44 || visibility.Height < 44 ||
                                    signIn.Radius != DesktopDesignTokens.ActionRadius(signIn.Height) || card.Radius != DesktopDesignTokens.CardRadius || card.Shadow != 0)
                                    throw new InvalidOperationException("Login AntdUI actions or card tokens are inconsistent at " + size + " in " + mode + ".");
                                if (form.Text != (english ? "Sign in" : "تسجيل الدخول") ||
                                    form.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                    Require<Label>(form, "heroTitle").TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                                    Require<ComboBox>(form, "username").Text != mixedName ||
                                    signIn.AccessibleName != (english ? "Sign in to the system" : "دخول إلى النظام"))
                                    throw new InvalidOperationException("Login presentation or mixed username was not preserved at " + size + " in " + mode + ".");
                                if (hero.Visible && (english ? card.Left >= hero.Left : card.Left <= hero.Left))
                                    throw new InvalidOperationException("Login card is not on the reading edge at " + size + " in " + mode + ".");
                                if (size.Height < 500 &&
                                    (signIn.PointToScreen(Point.Empty).Y + signIn.Height > form.PointToScreen(Point.Empty).Y + form.ClientSize.Height ||
                                     Require<Control>(card, "pictureBox1").Visible || close.Visible))
                                    throw new InvalidOperationException("Compact login must show the primary action without scrolling past decoration at " + size + ".");
                            }
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        private static void VerifyActionRows()
        {
            using (var form = new Form())
            {
                var actions = new Panel { Name = "pnlPurchasesActions", Dock = DockStyle.Bottom, Padding = new Padding(12, 8, 12, 8) };
                var flow = new FlowLayoutPanel { Name = "flowFooterButtons", Dock = DockStyle.Fill, Padding = new Padding(0, 4, 0, 4) };
                form.Controls.Add(actions);
                actions.Controls.Add(flow);
                for (int i = 0; i < 7; i++) flow.Controls.Add(new Button { Text = "إجراء " + i });
                foreach (int width in new[] { 340, 500, 960, 1280, 340 })
                {
                    Prepare(form, new Size(width, 720));
                    CommerceWorkspaceTheme.RefreshLayout(form);
                    form.PerformLayout();
                    foreach (Control button in flow.Controls) RequireInside(flow, button, "Wrapped action");
                }
            }
        }

        private static void VerifyFontUnits()
        {
            using (Font font = AppFonts.Create(10F))
            {
                IntPtr dc = CreateCompatibleDC(IntPtr.Zero);
                IntPtr handle = font.ToHfont();
                IntPtr previous = SelectObject(dc, handle);
                try
                {
                    var face = new StringBuilder(128);
                    GetTextFace(dc, face.Capacity, face);
                    Console.WriteLine("Configured font: " + UiTheme.LoadFontFamily() + "; resolved: " + font.FontFamily.Name + "; GDI: " + face);
                    if (!string.Equals(face.ToString(), font.FontFamily.Name, StringComparison.OrdinalIgnoreCase))
                        throw new InvalidOperationException("GDI text rendering substitutes the configured font: " + face);
                }
                finally { SelectObject(dc, previous); DeleteObject(handle); DeleteDC(dc); }
            }
            using (var label = new Label())
            using (var pixelFont = new Font("Arial", 16F, FontStyle.Regular, GraphicsUnit.Pixel))
            {
                label.Font = pixelFont;
                float expectedPoints = pixelFont.SizeInPoints;
                UiTheme.ApplyTo(label);
                if (Math.Abs(label.Font.SizeInPoints - expectedPoints) > 0.1F)
                    throw new InvalidOperationException("Applying theme converts pixel font size into larger point size.");
                UiTheme.ApplyTo(label);
                if (Math.Abs(label.Font.SizeInPoints - expectedPoints) > 0.1F)
                    throw new InvalidOperationException("Reapplying theme changes font size.");
            }
        }

        [DllImport("gdi32.dll")] private static extern IntPtr CreateCompatibleDC(IntPtr dc);
        [DllImport("gdi32.dll")] private static extern IntPtr SelectObject(IntPtr dc, IntPtr value);
        [DllImport("gdi32.dll", CharSet = CharSet.Unicode)] private static extern int GetTextFace(IntPtr dc, int count, StringBuilder name);
        [DllImport("gdi32.dll")] private static extern bool DeleteObject(IntPtr value);
        [DllImport("gdi32.dll")] private static extern bool DeleteDC(IntPtr dc);

