        private static void SavePreview(Form form, Size size, string directory, string name)
        {
            form.ShowInTaskbar = false;
            form.StartPosition = FormStartPosition.Manual;
            form.Location = new Point(-20000, -20000);
            form.Show();
            form.WindowState = FormWindowState.Normal;
            Prepare(form, size);
            if (name == "tax-settings-compact-light" || name == "tax-settings-compact-dark")
            {
                Label countryLabel = Require<Label>(form, "taxCountryLabel");
                Label rateLabel = Require<Label>(form, "taxRateLabel");
                ComboBox country = Require<ComboBox>(form, "cmbTaxCountry");
                if (countryLabel.ForeColor != UiTheme.Text || rateLabel.ForeColor != UiTheme.Text ||
                    country.ForeColor != UiTheme.Text || country.SelectedIndex < 0)
                    throw new InvalidOperationException("Tax settings field contrast or country selection is invalid: " + name);
                Panel body = Require<Panel>(form, "taxSettingsBody");
                AntdUI.Panel card = Require<AntdUI.Panel>(form, "taxSettingsCard");
                Panel footer = Require<Panel>(form, "taxSettingsFooter");
                int rightEdge = body.ClientSize.Width - (body.VerticalScroll.Visible ? SystemInformation.VerticalScrollBarWidth : 0);
                if (body.HorizontalScroll.Visible || card.Left < body.Padding.Left || card.Right > rightEdge ||
                    (!body.VerticalScroll.Visible && card.Bottom > body.ClientSize.Height) ||
                    (body.VerticalScroll.Visible && body.AutoScrollMinSize.Height <= body.ClientSize.Height) ||
                    body.Bottom != footer.Top || footer.Bottom != form.ClientSize.Height)
                    throw new InvalidOperationException("Shown tax settings preview clips its compact card or footer: " + name);
            }
            if (form is Billing || form is Purchases) CommerceWorkspaceTheme.RefreshLayout(form);
            if (form is Dashboard)
            {
                var dashboard = (Dashboard)form;
                Panel viewport = Require<Panel>(dashboard, "dashboardViewport");
                dashboard.RefreshResponsiveLayout();
                dashboard.ActiveControl = null;
                viewport.AutoScrollPosition = Point.Empty;
                Application.DoEvents();
                if (size.Width < 1220 && viewport.HorizontalScroll.Visible)
                    throw new InvalidOperationException("Compact dashboard must scroll vertically without a horizontal scrollbar at " + size + ".");
                if (size.Width < 1220)
                {
                    Panel firstCard = Require<Panel>(dashboard, "SellsNumberPanel");
                    if (firstCard.Top < 88 || firstCard.Top > 150)
                        throw new InvalidOperationException("Compact dashboard opens away from its first metric card: scroll=" + viewport.AutoScrollPosition + ", card=" + firstCard.Bounds + ".");
                    StatusStrip statusStrip = Require<StatusStrip>(dashboard, "__UiStatusStrip");
                    if (statusStrip.Parent != dashboard || !statusStrip.Visible ||
                        statusStrip.Bottom != dashboard.ClientSize.Height || viewport.Bottom != statusStrip.Top)
                        throw new InvalidOperationException("Dashboard status strip must stay fixed below its scrollable viewport: strip=" + statusStrip.Bounds + ", viewport=" + viewport.Bounds + ".");
                    int fixedStatusTop = statusStrip.Top;
                    viewport.AutoScrollPosition = new Point(0, 200);
                    Application.DoEvents();
                    if (statusStrip.Top != fixedStatusTop || statusStrip.Bottom != dashboard.ClientSize.Height)
                        throw new InvalidOperationException("Dashboard status strip moved while scrolling the compact metrics.");
                    viewport.AutoScrollPosition = Point.Empty;
                }
            }
            form.PerformLayout();
            if (form is Manufacturer && size.Width < 1000)
            {
                var supplierGrid = ((Manufacturer)form).ActiveCompanyGrid;
                var supplierEditor = Require<AntdUI.Panel>(form, "manufacturerEditorCard");
                if (supplierGrid.Bounds.IntersectsWith(supplierEditor.Bounds))
                {
                    Console.WriteLine("Supplier preview overlap: grid=" + supplierGrid.Bounds + "; editor=" + supplierEditor.Bounds + "; size=" + size);
                    throw new InvalidOperationException("Supplier preview table overlaps the editor before rendering.");
                }
            }
            if (form is Agent || form is Billing) Application.DoEvents();
            if (form is CustomerSupplierManagementForm)
            {
                Require<AntdUI.Table>(form, "customerMasterTable").Refresh();
                Application.DoEvents();
            }
            if (name == "journal-entries-dark")
            {
                DataGridView journalGrid = Require<DataGridView>(form, "journalLinesGrid");
                if (journalGrid.BackgroundColor != UiTheme.Surface ||
                    journalGrid.DefaultCellStyle.BackColor != UiTheme.Surface)
                    throw new InvalidOperationException("Journal grid does not use the dark theme surface: background=" +
                        journalGrid.BackgroundColor + ", cells=" + journalGrid.DefaultCellStyle.BackColor +
                        ", surface=" + UiTheme.Surface + ".");
            }
            if (name == "accounting-reports-summary-compact")
            {
                Panel top = Require<Panel>(form, "accountingReportsTop");
                FlowLayoutPanel summary = Require<FlowLayoutPanel>(form, "accountingReportSummary");
                top.AutoScrollPosition = new Point(0, Math.Max(0, summary.Bottom - top.ClientSize.Height));
                Application.DoEvents();
            }
            if (form is Dashboard)
            {
                var dashboard = (Dashboard)form;
                Control grid = Require<Control>(dashboard, "CustomerGV");
                Control customerName = Require<Control>(dashboard, "txtCustomerName");
                Control footer = Require<Control>(dashboard, "panel2");
                if (size.Width >= 1220 && size.Height >= 660 &&
                    (grid.Bottom >= customerName.Top || customerName.Bottom > footer.Top))
                    throw new InvalidOperationException("Dashboard content overlaps its footer actions at " + size);
            }
            if (form is Billing)
                foreach (string controlName in new[] { "pnlBillingMain", "pnlBillingSidebar", "pnlTotals", "pnlCartHost", "BillingGV" })
                {
                    Control control = Require<Control>(form, controlName);
                    Console.WriteLine(name + "/" + controlName + " " + control.Bounds + " visible=" + control.Visible);
                }
            using (var bitmap = new Bitmap(form.Width, form.Height))
            {
                form.DrawToBitmap(bitmap, new Rectangle(Point.Empty, bitmap.Size));
                bitmap.Save(System.IO.Path.Combine(directory, name + ".png"), System.Drawing.Imaging.ImageFormat.Png);
            }
        }

