                costCenter.Items.Add("10 - الفرع الرئيسي");
                costCenter.SelectedIndex = 0;
                costCenter.Enabled = true;
            }
            protected override void OnLoad(EventArgs e) { /* layout only; never load SQL */ }
        }

        private static void VerifyMedicineManagementLayout()
        {
            SessionContext.Start("Preview", "Manager");
            try
            {
                foreach (bool dark in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = dark ? "Dark" : "Light";
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    foreach (bool english in new[] { false, true })
                    {
                        using (var form = new MedicinePreview(english))
                        {
                            form.ShowInTaskbar = false;
                            form.StartPosition = FormStartPosition.Manual;
                            form.Location = new Point(-20000, -20000);
                            form.Show();
                            if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox ||
                                Require<Control>(form, "label8").Visible)
                                throw new InvalidOperationException("Medicine window chrome is incomplete.");
                            foreach (Size size in new[] { new Size(760, 640), new Size(1024, 768), new Size(1366, 768) })
                            {
                                Prepare(form, size);
                                form.RefreshResponsiveLayout();
                                Panel header = Require<Panel>(form, "panel1");
                                AntdUI.Panel content = Require<AntdUI.Panel>(form, "medicineContentHost");
                                Panel footer = Require<Panel>(form, "medicineActionBar");
                                Label title = Require<Label>(form, "label2");
                                AntdUI.Button ingredient = Require<AntdUI.Button>(form, "activeIngredientsButton");
                                DataGridView grid = Require<DataGridView>(form, "MedicineGV");
                                TextBox name = Require<TextBox>(form, "MedicineTb");
