                                AntdUI.Button dropdown = Require<AntdUI.Button>(content, "medicineCompanyDropdown");
                                AntdUI.DatePicker production = Require<AntdUI.DatePicker>(form, "ProdDate");
                                AntdUI.DatePicker expiry = Require<AntdUI.DatePicker>(form, "ExpDate");
                                string expectedTitle = english ? "Medicines" : "الأدوية";
                                int expectedIngredientX = english ? Math.Max(24, header.Width - 194) : 24;
                                if (title.Text != expectedTitle || title.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                                    ingredient.Left != expectedIngredientX || ingredient.Enabled || content.Bottom != footer.Top || footer.Bottom != form.ClientSize.Height)
