                                    throw new InvalidOperationException("Medicine input direction failed at " + size + ".");
                                if (grid.Rows.Count != 1 ||
                                    grid.Columns["MedName"].HeaderText != (english ? "Medicine name" : "اسم الدواء") ||
                                    grid.ColumnHeadersDefaultCellStyle.Alignment != (english ? DataGridViewContentAlignment.MiddleLeft : DataGridViewContentAlignment.MiddleRight) ||
                                    grid.DefaultCellStyle.Alignment != (english ? DataGridViewContentAlignment.MiddleLeft : DataGridViewContentAlignment.MiddleRight) ||
                                    grid.ColumnHeadersDefaultCellStyle.SelectionBackColor.ToArgb() != UiTheme.Primary.ToArgb() ||
                                    grid.ColumnHeadersDefaultCellStyle.SelectionForeColor.ToArgb() != Color.White.ToArgb())
                                    throw new InvalidOperationException("Medicine preview grid failed: english=" + english + ", dark=" + dark + ", size=" + size +
                                        ": rows=" + grid.Rows.Count + ", rtl=" + grid.RightToLeft +
                                        ", header=" + grid.Columns["MedName"].HeaderText +
                                        ", headerOk=" + (grid.Columns["MedName"].HeaderText == (english ? "Medicine name" : "اسم الدواء")) +
                                        ", headerAlign=" + grid.ColumnHeadersDefaultCellStyle.Alignment +
                                        ", selectedBack=" + grid.ColumnHeadersDefaultCellStyle.SelectionBackColor +
                                        ", backOk=" + (grid.ColumnHeadersDefaultCellStyle.SelectionBackColor.ToArgb() == UiTheme.Primary.ToArgb()) +
                                        ", selectedFore=" + grid.ColumnHeadersDefaultCellStyle.SelectionForeColor + ".");
                                AntdUI.Panel card = Require<AntdUI.Panel>(form, "medicineEditorCard");
                                AntdUI.Panel frame = Require<AntdUI.Panel>(form, "medicineNameFrame");
                                if (card.Radius != 12 || card.Shadow != 0 || frame.Height != 44 ||
                                    name.Region != null || name.BorderStyle != BorderStyle.None ||
                                    form.MinimumSize != new Size(760, 600) || grid.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes))
                                    throw new InvalidOperationException("Medicine shared surfaces/direction failed at " + size);
                                foreach (string fieldName in new[] { "BpriceTb", "SpriceTb", "QtTb", "BarcodeTb", "ProdDate", "ExpDate" })
                                    if (Require<Control>(form, fieldName).Height != 44)
                                        throw new InvalidOperationException("Medicine field height failed: " + fieldName);
                                string firstPhysical = grid.Columns.Cast<DataGridViewColumn>().OrderBy(c => c.DisplayIndex).First().Name;
                                if (firstPhysical != "MedName")
                                    throw new InvalidOperationException("Medicine physical column order failed at " + size + ": " + firstPhysical + ".");
                                int totalColumnWidth = grid.Columns.Cast<DataGridViewColumn>().Where(c => c.Visible).Sum(c => c.Width);
                                if (totalColumnWidth > grid.ClientSize.Width)
                                    throw new InvalidOperationException("Medicine columns overflow at " + size + ": total=" + totalColumnWidth +
                                        ", client=" + grid.ClientSize.Width + ", modes=" + string.Join(",", grid.Columns.Cast<DataGridViewColumn>()
                                            .Select(c => c.Name + ":" + c.Width + "/" + c.AutoSizeMode)) + ".");
                                RequireHorizontallyInside(content, grid, "Medicine grid " + size);
                                RequireHorizontallyInside(name.Parent, name, "Medicine name " + size);
                                RequireHorizontallyInside(company.Parent, company, "Medicine company " + size);
                                if (dropdown.Top != company.Top || dropdown.Height != company.Height ||
                                    (english ? dropdown.Right != company.Right : dropdown.Left != company.Left))
                                    throw new InvalidOperationException("Medicine dropdown edge failed at " + size + ".");
                                foreach (string actionName in new[] { "button4", "button3", "button1", "button5", "button2" })
                                {
                                    AntdUI.Button action = Require<AntdUI.Button>(footer, actionName);
                                    RequireInside(footer, action, "Medicine action " + actionName + " " + size);
                                    if (action.Height < 44 || action.BorderWidth != 1 || string.IsNullOrWhiteSpace(action.IconSvg))
                                        throw new InvalidOperationException("Medicine action styling failed at " + size + ".");
                                }
                            }
                            TextBox nameInput = Require<TextBox>(form, "MedicineTb");
                            nameInput.Text = "باراسيتامول 500 mg";
                            if (nameInput.Text != "باراسيتامول 500 mg")
                                throw new InvalidOperationException("Medicine mixed text changed in preview.");
                        }
                    }
                }
            }
            finally { SessionContext.Clear(); }
        }

        private static void VerifyHomeWorkspacePreferences()
        {
            string directory = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "pharmacy-home-workspace-" + Guid.NewGuid().ToString("N"));
            string path = System.IO.Path.Combine(directory, "home-workspaces.xml");
            try
            {
                var custom = new HomeWorkspacePreferences(HomeWorkspaceMode.Custom,
                    new[] { "Sales", "Dashboard", "Inventory" });
                HomeWorkspacePreferencesStore.Save("Preview A", custom, path);
                HomeWorkspacePreferencesStore.Save("Preview B",
                    new HomeWorkspacePreferences(HomeWorkspaceMode.Basic, HomeWorkspaceModuleCatalog.BasicIds()), path);

                HomeWorkspacePreferences loaded = HomeWorkspacePreferencesStore.Load("Preview A", path);
                if (loaded.Mode != HomeWorkspaceMode.Custom ||
                    !loaded.OrderedVisibleModuleIds.SequenceEqual(new[] { "Sales", "Dashboard", "Inventory" }))
                    throw new InvalidOperationException("Home workspace custom order did not round-trip per user.");

                HomeWorkspacePreferences second = HomeWorkspacePreferencesStore.Load("Preview B", path);
                if (second.Mode != HomeWorkspaceMode.Basic)
                    throw new InvalidOperationException("Home workspace profile isolation failed.");

                HomeWorkspacePreferences missing = HomeWorkspacePreferencesStore.Load("Unknown", path);
                if (missing.Mode != HomeWorkspaceMode.Full || missing.OrderedVisibleModuleIds.Count != HomeWorkspaceModuleCatalog.Items.Count)
                    throw new InvalidOperationException("Home workspace upgrade default must preserve the full established navigation.");

                // Keep a backup containing both profiles, then simulate a damaged primary.
                // The next save must retain the recovered users rather than start a new file.
                HomeWorkspacePreferencesStore.Save("Preview A", custom, path);
                if (!System.IO.File.Exists(path + ".previous"))
                    throw new InvalidOperationException("Home workspace settings backup was not created.");
                System.IO.File.WriteAllText(path, "<HomeWorkspacePreferences><broken>");
                HomeWorkspacePreferences recovered = HomeWorkspacePreferencesStore.Load("Preview B", path);
                if (recovered.Mode != HomeWorkspaceMode.Basic)
                    throw new InvalidOperationException("Home workspace settings did not recover the previous valid file.");
                HomeWorkspacePreferencesStore.Save("Preview C",
                    new HomeWorkspacePreferences(HomeWorkspaceMode.Custom, new[] { "Medicines" }), path);
                if (HomeWorkspacePreferencesStore.Load("Preview A", path).Mode != HomeWorkspaceMode.Custom ||
                    HomeWorkspacePreferencesStore.Load("Preview B", path).Mode != HomeWorkspaceMode.Basic ||
                    !HomeWorkspacePreferencesStore.Load("Preview C", path).OrderedVisibleModuleIds.SequenceEqual(new[] { "Medicines" }))
                    throw new InvalidOperationException("Home workspace recovery lost another user's profile during save.");

                foreach (bool leftToRight in new[] { false, true })
                using (var dialog = new HomeWorkspaceSettingsForm(custom, leftToRight))
                {
                    CheckedListBox orderedModules = Require<CheckedListBox>(dialog, "homeWorkspaceModuleList");
                    string firstModule = Convert.ToString(orderedModules.Items[0]);
                    orderedModules.SelectedIndex = 0;
                    typeof(HomeWorkspaceSettingsForm).GetMethod("MoveSelected",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                        .Invoke(dialog, new object[] { 1 });
                    if (orderedModules.SelectedIndex != 1 ||
                        Convert.ToString(orderedModules.Items[1]) != firstModule ||
                        !orderedModules.GetItemChecked(1))
                        throw new InvalidOperationException("Home workspace keyboard/button reordering did not preserve the selected module state.");

                    string[] customOrder = Enumerable.Range(0, orderedModules.Items.Count)
                        .Where(index => orderedModules.GetItemChecked(index))
                        .Select(index => Convert.ToString(orderedModules.Items[index]))
                        .ToArray();
                    foreach (string modeName in new[] { "homeWorkspaceFullOption", "homeWorkspaceBasicOption" })
                    {
                        Require<RadioButton>(dialog, modeName).Checked = true;
                        Require<RadioButton>(dialog, "homeWorkspaceCustomOption").Checked = true;
                        string[] restoredOrder = Enumerable.Range(0, orderedModules.Items.Count)
                            .Where(index => orderedModules.GetItemChecked(index))
                            .Select(index => Convert.ToString(orderedModules.Items[index]))
                            .ToArray();
                        if (!restoredOrder.SequenceEqual(customOrder))
                            throw new InvalidOperationException("Home workspace custom draft changed after previewing " + modeName + ".");
                    }

                    foreach (Size size in new[] { new Size(520, 520), new Size(680, 610), new Size(900, 680) })
                    {
                        Prepare(dialog, size);
                        AntdUI.Panel body = Require<AntdUI.Panel>(dialog, "homeWorkspaceBody");
                        CheckedListBox list = Require<CheckedListBox>(dialog, "homeWorkspaceModuleList");
                        Panel listActions = Require<Panel>(dialog, "homeWorkspaceListActions");
                        AccessibleAntdButton save = Require<AccessibleAntdButton>(dialog, "homeWorkspaceSave");
                        AccessibleAntdButton reset = Require<AccessibleAntdButton>(dialog, "homeWorkspaceReset");
                        AccessibleAntdButton close = Require<AccessibleAntdButton>(dialog, "homeWorkspaceClose");
                        if (dialog.Controls["__UiStatusStrip"] != null)
                            throw new InvalidOperationException("Home workspace status strip covers the bottom of the module list.");
                        if (body.Width < 300 || list.Width < 180 || list.Height < 170 ||
                            save.Height < 44 || reset.Height < 44 || close.Height < 44 ||
                            save.Bounds.IntersectsWith(reset.Bounds) || reset.Bounds.IntersectsWith(close.Bounds) ||
                            (leftToRight ? listActions.Right > list.Left : listActions.Left < list.Right))
                            throw new InvalidOperationException("Home workspace editor is clipped or its actions overlap at " + size + ".");
                    }
                }
            }
            finally
            {
                try
                {
                    if (System.IO.Directory.Exists(directory)) System.IO.Directory.Delete(directory, true);
                }
                catch
                {
                    // A failed cleanup must not hide a functional assertion.
                }
            }
        }

        private static void VerifyHomeActionCaptions(Form form)
        {
            foreach (string name in new[] { "dailyOperationsButton", "monitorButton", "screenModeButton", "layoutModeButton", "workspaceButton", "workspaceToggleButton", "addFirstMedicineButton", "openFirstPurchaseButton" })
            {
                var action = Require<AntdUI.Button>(form, name);
                int textWidth = TextRenderer.MeasureText(action.Text, action.Font, Size.Empty, TextFormatFlags.SingleLine | TextFormatFlags.NoPadding).Width;
                if (textWidth + 40 > action.ClientSize.Width || string.IsNullOrWhiteSpace(action.IconSvg) || !action.TabStop ||
                    action.Font.Size != 9.5F || action.Font.Style != FontStyle.Bold ||
                    action.IconPosition != (form.RightToLeft == RightToLeft.No ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right))
                    throw new InvalidOperationException("Home action caption/icon/identity does not fit: " + name + " text=" + action.Text + " needed=" + (textWidth+40) + " bounds=" + action.Bounds);
            }
            var header = Require<Panel>(form, "panel1");
            var names = new[] { "dailyOperationsButton", "monitorButton", "screenModeButton", "layoutModeButton", "workspaceToggleButton", "workspaceButton" };
            var actions = names.Select(name => Require<AntdUI.Button>(form, name)).ToArray();
            bool leftToRight = form.RightToLeft == RightToLeft.No;
            if (actions[0].AccessibleName != (leftToRight ? "Daily operations log" : "سجل العمليات اليومية"))
                throw new InvalidOperationException("Home daily operations accessible name does not follow the current language.");
            for (int i = 0; i < actions.Length; i++)
            {
                var action = actions[i];
                var row = actions.Where(a => a.Top == action.Top).ToArray();
                if (action.Left < 0 || action.Right > header.ClientSize.Width || action.Bottom > header.ClientSize.Height || !action.Visible)
                    throw new InvalidOperationException("Home action lies outside the visible header: " + names[i]);
                if (i == 0 || action.Top != actions[i - 1].Top)
                {
                    if (action.Left != (leftToRight ? row.Min(a => a.Left) : row.Max(a => a.Left)))
                        throw new InvalidOperationException("Home first action does not start at the language leading edge: " + names[i]);
                }
                if (i > 0 && (action.Top < actions[i - 1].Top || (action.Top == actions[i - 1].Top &&
                    (leftToRight ? action.Left <= actions[i - 1].Left : action.Left >= actions[i - 1].Left))))
                    throw new InvalidOperationException("Home actions lost their logical language order: " + names[i]);
                if (actions.Skip(i + 1).Any(other => action.Bounds.IntersectsWith(other.Bounds)))
                    throw new InvalidOperationException("Home header actions overlap: " + names[i]);
            }
        }
        private sealed class HomeAlertSessionFake : PharmacyManagement.Application.IInventoryAlertSessionReadService
        {
            internal readonly TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult> Reply =
                new TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>();
            internal int Calls, Stock, Days;
            public Task<PharmacyManagement.Application.OperationalReportResult> GetAlertsAsync(
                PharmacyManagement.Application.InventoryAlertRequest request, PharmacyManagement.Application.OperationActor actor,
                System.Threading.CancellationToken cancellation)
            { Calls++; Stock = request.LowStockThreshold; Days = request.ExpiringWithinDays; return Reply.Task; }
        }

        private static PharmacyManagement.Application.OperationalReportResult HomeAlertRows(int count)
        {
            var columns = new[] {
                new PharmacyManagement.Application.OperationalReportColumn("نوع التنبيه", typeof(string)),
                new PharmacyManagement.Application.OperationalReportColumn("الصنف", typeof(string)),
                new PharmacyManagement.Application.OperationalReportColumn("الكمية", typeof(decimal)),
                new PharmacyManagement.Application.OperationalReportColumn("تاريخ الانتهاء", typeof(DateTime)),
                new PharmacyManagement.Application.OperationalReportColumn("الشركة", typeof(string)),
                new PharmacyManagement.Application.OperationalReportColumn("التفاصيل", typeof(string)) };
            return new PharmacyManagement.Application.OperationalReportResult(columns,
                Enumerable.Range(0, count).Select(i => new object[] { "منتهي", "باراسيتامول 500 mg", 1.250m, new DateTime(2026, 9, 1), "شركة", "تنبيه" }));
        }

        private static void FinishHomeAlertRead(Task task)
        {
            var timer = System.Diagnostics.Stopwatch.StartNew();
            while (!task.IsCompleted && timer.ElapsedMilliseconds < 5000) { Application.DoEvents(); System.Threading.Thread.Sleep(1); }
            if (!task.IsCompleted) throw new InvalidOperationException("Home alert fixture timed out.");
            task.GetAwaiter().GetResult();
        }

        private static void VerifyHomeAntdAlertCards()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    SessionContext.Start("card-preview", "Manager");
                    using (var form = new HomePreview())
                    {
                        typeof(Home).GetField("isFullScreen", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).SetValue(form, false);
                        form.WindowState = FormWindowState.Normal; form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual; form.Location = new Point(-20000, -20000); form.Show();
                        var strip = (FlowLayoutPanel)typeof(Home).GetField("alertStrip", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(form);
                        var create = typeof(Home).GetMethod("CreateAlertCard", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                        strip.Controls.Add((Control)create.Invoke(form, new object[] { "أصناف منتهية", 12, UiTheme.Danger, "Expired" }));
                        strip.Controls.Add((Control)create.Invoke(form, new object[] { "قرب الانتهاء", 25, UiTheme.Warning, "Expiring Soon" }));
                        strip.Controls.Add((Control)create.Invoke(form, new object[] { "مخزون منخفض", 9999, UiTheme.Primary, "Low Stock" }));
                        strip.Visible = true;
                        foreach (bool english in new[] { false, true })
                        foreach (Size size in new[] { new Size(320, 640), new Size(760, 640), new Size(960, 640), new Size(1366, 768) })
                        {
                            Prepare(form, size); form.ApplyPresentation(english); Application.DoEvents();
                            if (form.ClientSize != size) throw new Exception("Home card fixture size mismatch.");
                            foreach (Control child in strip.Controls)
                            {
                                var card = child as AccessibleAntdActionCard;
                                if (card == null) throw new Exception("Home alert card is not AntdUI.");
                                var title = Require<Label>(card, "homeAlertCardTitle"); var count = Require<Label>(card, "homeAlertCardCount");
                                var measured = TextRenderer.MeasureText(title.Text, title.Font);
                                if (card.Shadow != 0 || card.Radius != DesktopDesignTokens.CardRadius || card.BorderWidth != 1 ||
                                    card.BackColor != UiTheme.Surface || !card.TabStop || card.AccessibilityObject.Role != AccessibleRole.PushButton ||
                                    card.Left < 0 || card.Right > strip.ClientSize.Width || card.Bottom > strip.ClientSize.Height ||
                                    title.Bounds.IntersectsWith(count.Bounds) || measured.Width > title.Width ||
                                    TextRenderer.MeasureText(count.Text, count.Font).Width > count.Width ||
                                    count.RightToLeft != RightToLeft.No ||
                                    title.TextAlign != (english ? ContentAlignment.MiddleLeft : ContentAlignment.MiddleRight) ||
                                    (english ? title.Left >= count.Left : title.Left <= count.Left) ||
                                    card.AccessibleName != title.Text + ": " + count.Text)
                                    throw new Exception("Home alert card clipping/direction/style failure: " + mode + "/" + english + "/" + size + "/" + card.Name);
                            }
                            var first = strip.Controls[0];
                            var leading = strip.Controls.Cast<Control>().Where(c => c.Top == first.Top).Select(c => c.Left);
                            if (first.Left != (english ? leading.Min() : leading.Max())) throw new Exception("Home alert row starts at wrong language edge.");
                            foreach (Control a in strip.Controls) foreach (Control b in strip.Controls)
                                if (!ReferenceEquals(a, b) && a.Bounds.IntersectsWith(b.Bounds)) throw new Exception("Home alert cards overlap.");
                        }
                        using (var action = new AccessibleAntdActionCard { Size = new Size(100, 44), Location = new Point(10, 10) })
                        {
                            form.Controls.Add(action); action.BringToFront(); int clicks = 0; action.Click += (s, e) => clicks++;
                            action.AccessibilityObject.DoDefaultAction(); action.Enabled = false; action.AccessibilityObject.DoDefaultAction();
                            if (clicks != 1) throw new Exception("Action card accessibility does not respect disabled state.");
                            action.Enabled = true; action.Focus();
                            var command = typeof(AccessibleAntdActionCard).GetMethod("ProcessCmdKey", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                            foreach (Keys key in new[] { Keys.Enter, Keys.Space })
                            {
                                object[] arguments = { new Message(), key };
                                if (!(bool)command.Invoke(action, arguments)) throw new Exception("Action card keyboard command was not handled.");
                            }
                            if (clicks != 3) throw new Exception("Action card keyboard activation failed.");
                        }
                    }
                }
                Console.WriteLine("PASS AntdUI home alert cards: 16 actual size/theme/direction layouts; measured captions/counts, wrapping, no overlap, language leading edge and accessibility/Enter/Space/disabled actions; no SQL or native input.");
            }
            finally { SessionContext.Clear(); Properties.Setings.Default.ThemeMode = original; using (var refresh = new Form()) UiTheme.Apply(refresh); }
        }


        private static void VerifyHomeAlertDesktopReads()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    SessionContext.Start("home-preview", "Manager");
                    using (var form = new HomePreview())
                    {
                        var pending = new System.Collections.Generic.List<HomeAlertSessionFake>();
                        bool homeContextCurrent = true;
                        form.HomeAlertSessionFactory = () => {
                            long revision = SessionContext.CurrentSessionRevision;
                            var fake = new HomeAlertSessionFake(); pending.Add(fake);
                            return new HomeOperationalAlertReadSession(new InventoryAlertReadSession(fake,
                                new PharmacyManagement.Application.OperationActor { UserName = "home-preview", UserRole = "Manager" },
                                () => homeContextCurrent && SessionContext.IsAuthenticated && SessionContext.CurrentSessionRevision == revision)); };
                        typeof(Home).GetField("isFullScreen", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).SetValue(form, false);
                        form.WindowState = FormWindowState.Normal; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.ShowInTaskbar = false;
                        form.Show(); Prepare(form, new Size(960, 640)); form.ApplyPresentation(english);
                        var strip = (FlowLayoutPanel)typeof(Home).GetField("alertStrip", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(form);
                        if (pending.Count != 0) throw new Exception("Home preview construction/show started a database read.");
                        var first = form.RefreshHomeAlertsAsync();
                        if (first.IsCompleted || strip.Controls.Find("homeAlertStatus", true).Length != 1) throw new Exception("Home loading state missing.");
                        var second = form.RefreshHomeAlertsAsync(); pending[1].Reply.SetResult(HomeAlertRows(1)); FinishHomeAlertRead(second);
                        pending[0].Reply.SetResult(HomeAlertRows(3)); FinishHomeAlertRead(first);
                        if (strip.Controls.Count != 1 || !strip.Controls[0].Controls.OfType<Label>().Any(l => l.Text == "1")) throw new Exception("Late home reply replaced current cards.");
                        var failed = form.RefreshHomeAlertsAsync(); pending[2].Reply.SetException(new InvalidOperationException("fixture failure")); FinishHomeAlertRead(failed);
                        if (strip.Controls.Find("homeAlertStatus", true).Length != 1) throw new Exception("Home failure was shown as healthy inventory.");
                        var empty = form.RefreshHomeAlertsAsync(); pending[3].Reply.SetResult(HomeAlertRows(0)); FinishHomeAlertRead(empty);
                        if (strip.Visible || strip.Controls.Count != 0) throw new Exception("Empty home alerts were not hidden.");
                        var stale = form.RefreshHomeAlertsAsync(); SessionContext.Start("home-other", "Manager");
                        if (strip.Visible || strip.Controls.Count != 0) throw new Exception("Home session change did not immediately clear cards.");
                        pending[4].Reply.SetResult(HomeAlertRows(3)); FinishHomeAlertRead(stale);
                        if (strip.Controls.Count != 0) throw new Exception("Old user alerts reappeared.");
                        bool opened = false, closed = false;
                        form.HomeAlertDialogPresenter = dialog => {
                            dialog.Show(form); opened = dialog.Owner == form;
                            SessionContext.Start("home-next", "Manager");
                            closed = !dialog.Visible; };
                        var detail = form.OpenHomeAlertDetailsAsync("Expired", UiTheme.Danger);
                        pending[5].Reply.SetResult(HomeAlertRows(1)); FinishHomeAlertRead(detail);
                        if (!opened || !closed) throw new Exception("Home alert dialog retained previous session data.");
                        form.HomeAlertDialogPresenter = dialog => {
                            dialog.Show(form); homeContextCurrent = false;
                            var timer = System.Diagnostics.Stopwatch.StartNew();
                            while (dialog.Visible && timer.ElapsedMilliseconds < 2000) { Application.DoEvents(); System.Threading.Thread.Sleep(1); }
                            if (dialog.Visible) throw new Exception("Home dialog context timer did not close revoked context."); };
                        var contextDetail = form.OpenHomeAlertDetailsAsync("Expired", UiTheme.Danger);
                        pending[pending.Count - 1].Reply.SetResult(HomeAlertRows(1)); FinishHomeAlertRead(contextDetail);
                        homeContextCurrent = true;
                        SessionContext.Clear(); int calls = pending.Count; FinishHomeAlertRead(form.RefreshHomeAlertsAsync());
                        if (pending.Count != calls || strip.Controls.Count != 0) throw new Exception("Anonymous home alerts reached the repository.");
                        SessionContext.Start("home-preview", "Manager");
                        var disposed = form.RefreshHomeAlertsAsync(); form.Dispose(); pending[pending.Count - 1].Reply.SetResult(HomeAlertRows(1)); FinishHomeAlertRead(disposed);
                    }
                }
                Console.WriteLine("PASS home async desktop: loading, late replies, failure/recovery/empty, session clear, owned dialog and periodic context close, anonymous denial and Dispose; both themes/directions; fake SQL boundary.");
            }
            finally { SessionContext.Clear(); Properties.Setings.Default.ThemeMode = originalMode; using (var refresh = new Form()) UiTheme.Apply(refresh); }
        }


        private static void VerifyHomeAlertReadFoundation()
        {
            using (var source = new DataTable())
            {
                source.Columns.Add("نوع التنبيه"); source.Columns.Add("الصنف");
                source.Columns.Add("الكمية", typeof(decimal)); source.Columns.Add("تاريخ الانتهاء", typeof(DateTime));
                source.Columns.Add("الشركة"); source.Columns.Add("التفاصيل");
                source.Rows.Add("مخزون منخفض", "دواء Z", 0.125m, DBNull.Value, DBNull.Value, "low");
                source.Rows.Add("قريب الانتهاء", "دواء B", 1.250m, new DateTime(2026, 10, 8), "شركة", "soon");
                source.Rows.Add("منتهي", "دواء A 500 mg", 2.005m, new DateTime(2026, 9, 1), "شركة", "expired");
                var result = new PharmacyManagement.Application.OperationalReportResult(
                    source.Columns.Cast<DataColumn>().Select(c => new PharmacyManagement.Application.OperationalReportColumn(c.ColumnName, c.DataType)),
                    source.Rows.Cast<DataRow>().Select(r => r.ItemArray));
                using (var mapped = HomeOperationalAlertPresentation.ToTable(result))
                {
                    if (!mapped.Columns.Cast<DataColumn>().Select(c => c.ColumnName).SequenceEqual(
                            new[] { "Type", "Medicine", "Quantity", "Expiry", "Company", "Message" }) ||
                        mapped.Columns["Quantity"].DataType != typeof(decimal) ||
                        mapped.Columns["Expiry"].DataType != typeof(DateTime) ||
                        !mapped.Rows.Cast<DataRow>().Select(r => (string)r["Type"]).SequenceEqual(new[] { "Expired", "Expiring Soon", "Low Stock" }) ||
                        (decimal)mapped.Rows[0]["Quantity"] != 2.005m || mapped.Rows[2]["Expiry"] != DBNull.Value ||
                        source.Columns[0].ColumnName != "نوع التنبيه" || (string)source.Rows[0][0] != "مخزون منخفض")
                        throw new InvalidOperationException("Home alert mapping changed raw values, schema, order or source.");
                }
                foreach (string scenario in new[] { "success", "cancel", "stale", "before" })
                {
                    var fake = new HomeAlertSessionFake(); bool current = scenario != "before";
                    var inventory = new InventoryAlertReadSession(fake,
                        new PharmacyManagement.Application.OperationActor { UserName = "preview", UserRole = "Manager" }, () => current);
                    var session = new HomeOperationalAlertReadSession(inventory);
                    using (var cancellation = new System.Threading.CancellationTokenSource())
                    {
                        Task<DataTable> read = session.LoadAsync(cancellation.Token);
                        if (scenario != "before" && (fake.Calls != 1 || fake.Stock != 10 || fake.Days != 30))
                            throw new InvalidOperationException("Home alert policy defaults changed.");
                        if (scenario == "cancel") cancellation.Cancel();
                        if (scenario == "stale") current = false;
                        fake.Reply.SetResult(result);
                        bool rejected = false;
                        try { using (var table = read.GetAwaiter().GetResult()) { if (table.Rows.Count != 3) throw new Exception("Missing rows."); } }
                        catch (OperationCanceledException) { rejected = scenario == "cancel"; }
                        catch (InvalidOperationException) { rejected = scenario == "stale" || scenario == "before"; }
                        if ((scenario == "success" && rejected) || (scenario != "success" && !rejected) ||
                            (scenario == "before" && fake.Calls != 0))
                            throw new InvalidOperationException("Home alert read guard failed: " + scenario);
                    }
                }
            }
            Console.WriteLine("PASS home alert foundation: six-column raw mapping, decimals/null/date, source preserved, stable policy 10/30, canceled/stale results rejected, invalid context makes no repository call.");
        }


        private static void VerifyHomeAlertDetails()
        {
            string originalMode = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var refresh = new Form()) UiTheme.Apply(refresh);
                    using (var home = new HomePreview())
                    foreach (bool english in new[] { false, true })
                    {
                        home.ApplyPresentation(english);
                        foreach (string type in new[] { "Expired", "Expiring Soon", "Low Stock" })
                        foreach (Size size in new[] { new Size(320, 240), new Size(640, 480), new Size(960, 640) })
                        {
                            var rows = new DataTable();
                            rows.Columns.Add("Type"); rows.Columns.Add("Medicine");
                            rows.Columns.Add("Quantity", typeof(decimal)); rows.Columns.Add("Expiry", typeof(DateTime));
                            rows.Columns.Add("Company"); rows.Columns.Add("Message");
                            rows.Rows.Add(type, "باراسيتامول 500 mg", 1.250m, new DateTime(2026, 10, 4), "شركة الاختبار", "تنبيه تجريبي");
                            using (Form dialog = home.CreateAlertDetailsDialog(type, rows, UiTheme.Warning, new Size(1200, 900)))
                            {
                                dialog.StartPosition = FormStartPosition.Manual;
                                dialog.Location = new Point(-20000, -20000);
                                dialog.Show(); Prepare(dialog, size);
                                if (dialog.ClientSize != size) throw new InvalidOperationException("Alert fixture size mismatch.");
                                var button = Require<AntdUI.Button>(dialog, "alertDetailsClose");
                                var header = Require<AntdUI.Panel>(dialog, "alertDetailsHeader");
                                var grid = Require<DataGridView>(dialog, "alertDetailsGrid");
                                var footer = Require<Panel>(dialog, "alertDetailsFooter");
                                var title = Require<Label>(dialog, "alertDetailsTitle");
                                var count = Require<Label>(dialog, "alertDetailsCount");
                                if (dialog.ShowInTaskbar || !dialog.MaximizeBox || dialog.Owner != null ||
                                    dialog.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                    dialog.AcceptButton != button || dialog.CancelButton != button ||
                                    button.Text != (english ? "Close" : "إغلاق") ||
                                    button.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right) ||
                                    button.ForeColor != UiTheme.Primary || button.BorderWidth != 1 ||
                                    string.IsNullOrEmpty(button.IconSvg) || !button.TabStop || button.Height != 44 ||
                                    button.Left < 0 || button.Right > footer.ClientSize.Width ||
                                    button.Bottom > footer.ClientSize.Height ||
                                    title.Bounds.IntersectsWith(count.Bounds) || title.Width < 100 ||
                                    title.Text != dialog.Text || count.Text != "1" ||
                                    header.Shadow != 0 || header.BackColor != UiTheme.Surface ||
                                    grid.ClientSize.Height < 100 || !grid.ReadOnly || grid.AllowUserToAddRows ||
                                    grid.Columns["Medicine"].Width < 120 ||
                                    grid.Columns["Medicine"].HeaderText != (english ? "Medicine" : "الصنف") ||
                                    grid.Columns["Expiry"].DefaultCellStyle.Format != "yyyy-MM-dd" ||
                                    !ReferenceEquals(grid.DataSource, rows) || rows.Rows[0]["Medicine"].ToString() != "باراسيتامول 500 mg" ||
                                    (decimal)rows.Rows[0]["Quantity"] != 1.250m)
                                    throw new InvalidOperationException("Home alert layout/data contract failed: " + mode + "/" + english + "/" + type + "/" + size + "; close=" + button.Bounds + "; footer=" + footer.ClientSize + "; title=" + title.Bounds + "; count=" + count.Bounds + "; grid=" + grid.ClientSize + "; text=" + button.Text + "; dir=" + dialog.RightToLeft + "; header=" + header.BackColor + "; icon=" + button.IconPosition + "; gridtitle=" + grid.Columns["Medicine"].HeaderText + "; max=" + dialog.MaximizeBox + "; task=" + dialog.ShowInTaskbar + "; owner=" + (dialog.Owner != null) + "; accept=" + (dialog.AcceptButton == button) + "; cancel=" + (dialog.CancelButton == button) + "; fore=" + button.ForeColor + "/" + UiTheme.Primary + "; border=" + button.BorderWidth + "; shadow=" + header.Shadow + "; rows=" + grid.ReadOnly + "/" + grid.AllowUserToAddRows + "; col=" + grid.Columns["Medicine"].Width + "; format=" + grid.Columns["Expiry"].DefaultCellStyle.Format);
                                button.AccessibilityObject.DoDefaultAction(); Application.DoEvents();
                                if (dialog.Visible) throw new InvalidOperationException("Home alert close action did not close the dialog.");
                            }
                        }
                    }
                }
                Console.WriteLine("PASS home alert dialog: 36 theme/direction/type/size cases; close action, raw rows and native read-only grid; no SQL.");
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalMode;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }


        private static void VerifyHomeHeaderActions()
