                            var layout = typeof(Home).GetMethod("LayoutHomeTiles", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic,
                                null, new[] { typeof(bool) }, null);
                            if (layoutMode == null || layout == null)
                                throw new InvalidOperationException("Home tile layout direction hook is unavailable.");
