        private static void VerifyVisibleWorkspaceLayouts()
        {
            using (var settings = new SettingsPreview())
            {
                settings.ShowInTaskbar = false;
                settings.StartPosition = FormStartPosition.Manual;
                settings.Location = new Point(-20000, -20000);
                settings.Show();
                ThemedCardFlowPanel cards = Require<ThemedCardFlowPanel>(settings, "antdSettingsCards");
                Panel body = Require<Panel>(settings, "panelBody");
                Label hint = Require<Label>(settings, "lblHint");
                var layoutCards = typeof(SettingsForm).GetMethod("LayoutAntdCards",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic,
                    null, new[] { typeof(bool) }, null);
                if (layoutCards == null) throw new InvalidOperationException("Settings card direction layout hook is missing.");
                foreach (Size size in new[] { new Size(360, 570), new Size(480, 620), new Size(960, 720), new Size(360, 570) })
                {
                    Prepare(settings, size);
                    StatusStrip statusStrip = Require<StatusStrip>(settings, "__UiStatusStrip");
                    ToolStripStatusLabel statusInfo = statusStrip.Items["__UiStatusInfo"] as ToolStripStatusLabel;
                    ToolStripStatusLabel statusClock = statusStrip.Items["__UiStatusClock"] as ToolStripStatusLabel;
                    if (statusInfo == null || statusClock == null)
                        throw new InvalidOperationException("Settings status strip is missing its information or clock item.");
                    if (size.Width < 520 && (statusClock.Visible || statusInfo.Text.Length > 42 ||
                        statusInfo.ToolTipText.Length <= statusInfo.Text.Length))
                        throw new InvalidOperationException("Compact settings status must fit, hide the clock, and retain full details in its tooltip at " + size + ".");
                    if (size.Width >= 520 && (!statusClock.Visible || statusInfo.Text != statusInfo.ToolTipText))
                        throw new InvalidOperationException("Wide settings status must restore the full text and clock at " + size + ".");
                    bool wide = size.Width >= 620;
                    foreach (bool leftToRight in new[] { false, true })
                    {
                        settings.ApplyPresentation(leftToRight);
                        settings.PerformLayout();
                        if (body.HorizontalScroll.Visible || cards.Cards.Any(card => card.Left < 0 || card.Right > cards.CardViewport.ClientSize.Width) || body.Bounds.IntersectsWith(hint.Bounds) ||
                            cards.ReadingLeftToRight != leftToRight || cards.ReadingColumns != (wide ? 2 : 1) ||
                            settings.Text != (leftToRight ? "Settings" : "الإعدادات"))
                            throw new InvalidOperationException("Settings content overflows or has incorrect direction at " + size +
                                " in " + (leftToRight ? "LTR" : "RTL"));
                    }
                }
            }
            foreach (Form form in new Form[] { new BillingPreview(), new PurchasesPreview() })
            using (form)
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                if (form.DeviceDpi == 96 && (form.MinimumSize != new Size(960, 640) ||
                    form.AutoScaleMode != AutoScaleMode.Dpi || form.AutoScaleDimensions != new SizeF(96F, 96F)))
                    throw new InvalidOperationException("Commerce first Show must preserve its 96-DPI minimum and scale baseline.");
                foreach (Size size in new[] { new Size(960, 640), new Size(1024, 768), new Size(1440, 900), new Size(1920, 1080), new Size(960, 640) })
                {
                    Prepare(form, size);
                    CommerceWorkspaceTheme.RefreshLayout(form);
                    CommerceWorkspaceTheme.RefreshTotals(form);
                    Panel cart = Require<Panel>(form, form is Billing ? "pnlCartHost" : "pnlPurchaseCartHost");
                    Panel sidebar = Require<Panel>(form, form is Billing ? "pnlBillingSidebar" : "pnlPurchasesSidebar");
                    if (cart.Bounds.IntersectsWith(sidebar.Bounds))
                        throw new InvalidOperationException("Cart overlaps sidebar at " + size);
                    Control medicine = Require<Control>(form, "MediComboCb");
                    if (medicine.Width < 100)
                        throw new InvalidOperationException("Medicine selector collapsed at " + size);
                    RequireHorizontallyInside(medicine.Parent, medicine, "medicine selector " + size);
                    if (form is Purchases)
                    {
                        foreach (string field in new[] { "cmbSupplier", "txtBarcode", "MediComboCb", "txtQuantity",
                            "dtpProdDate", "dtpExpDate", "SelectEmployee", "txtPurchaseNotesInput", "btnConfirmPurchase" })
                        {
                            Control input = Require<Control>(sidebar, field);
                            RequireHorizontallyInside(input.Parent, input, "visible purchase field " + field + " " + size);
                        }
                    }
                }
            }
        }

        private static void VerifyPurchasesAtCompactSize()
        {
            foreach (bool english in new[] { false, true })
            using (var form = new PurchasesPreview(english))
            {
                foreach (Size size in new[] { new Size(960, 640), new Size(1024, 768), new Size(1366, 768), new Size(1920, 1080) })
                {
                    Prepare(form, size);
                    if (form.ClientSize != size)
                        throw new InvalidOperationException("PURCHASE_REQUESTED_SIZE_CLAMPED requested=" + size + " actual=" + form.ClientSize + ".");
                    CommerceWorkspaceTheme.RefreshLayout(form);
                    form.PerformLayout();

                    DataGridView purchaseGrid = Require<DataGridView>(form, "PurchasesGV");
                    if (purchaseGrid.Columns.Cast<DataGridViewColumn>().Where(c => c.Visible).Sum(c => c.Width) > purchaseGrid.ClientSize.Width
                        || !purchaseGrid.Columns["TotalAmount"].Visible || !purchaseGrid.Columns["RemoveCartItem"].Visible)
                        throw new InvalidOperationException("Purchase total and removal must remain inside the grid viewport at " + size + "; client=" + purchaseGrid.ClientSize + "; widths=" + string.Join(",", purchaseGrid.Columns.Cast<DataGridViewColumn>().Select(c => c.Name + ":" + c.Width + ":" + c.Displayed)));
                    foreach (string dateColumn in new[] { "ProdDate", "ExpDate" })
                    {
                        DataGridViewCell dateCell = purchaseGrid.Rows[0].Cells[dateColumn];
                        string rawDate = Convert.ToString(dateCell.Value, System.Globalization.CultureInfo.InvariantCulture);
                        int requiredWidth = TextRenderer.MeasureText(rawDate, dateCell.InheritedStyle.Font,
                            Size.Empty, TextFormatFlags.SingleLine | TextFormatFlags.NoPadding).Width + 12;
                        if (dateCell.OwningColumn.Width < requiredWidth ||
                            dateCell.InheritedStyle.WrapMode != DataGridViewTriState.False ||
                            !string.Equals(Convert.ToString(dateCell.FormattedValue, System.Globalization.CultureInfo.InvariantCulture), rawDate, StringComparison.Ordinal))
                            throw new InvalidOperationException("Purchase dates must remain complete and unchanged at " + size + ".");
                    }
                    if (((DataGridViewButtonColumn)purchaseGrid.Columns["RemoveCartItem"]).Text != (english ? "Remove" : "إزالة"))
                        throw new InvalidOperationException("Purchase removal action must follow the screen language.");
                    Panel purchaseHeader = Require<Panel>(form, "pnlPurchasesHeader");
                    Label purchaseTitle = Require<Label>(purchaseHeader, "lblPurchasesTitle");
                    Label cartTab = Require<Label>(purchaseHeader, "lblTabCart");
                    Label historyTab = Require<Label>(purchaseHeader, "lblTabHistory");
                    if (Require<Label>(purchaseHeader, "btnClosePurchases").Visible ||
                        purchaseTitle.Right > purchaseHeader.ClientSize.Width ||
                        (english
                            ? purchaseTitle.Right >= historyTab.Left
                            : historyTab.Right >= purchaseTitle.Left) ||
                        cartTab.Bounds.IntersectsWith(historyTab.Bounds))
                        throw new InvalidOperationException("Purchase header title and tabs overlap at " + size + ".");

                    Panel sidebar = Require<Panel>(form, "pnlPurchasesSidebar");
                    if (purchaseTitle.Text != (english ? "Purchases" : "المشتريات") ||
                        sidebar.Dock != (english ? DockStyle.Left : DockStyle.Right))
                        throw new InvalidOperationException("Purchase title or sidebar direction is incorrect at " + size + ".");
                    if (Require<Label>(sidebar, "lblSidebarTitle").ForeColor != UiTheme.Primary ||
                        Require<Label>(form, "PriceADLabel").ForeColor != UiTheme.Primary)
                        throw new InvalidOperationException("Purchase accent text has insufficient dark-surface contrast at " + size + ".");
                    if (!sidebar.AutoScroll)
                        throw new InvalidOperationException("لوحة المشتريات يجب أن تدعم التمرير العمودي.");
                    if (sidebar.HorizontalScroll.Visible || form.HorizontalScroll.Visible)
                        throw new InvalidOperationException("PURCHASE_HORIZONTAL_SCROLL size=" + size + " sidebar=" + sidebar.ClientSize + " panelScroll=" + sidebar.HorizontalScroll.Visible + " formScroll=" + form.HorizontalScroll.Visible + ".");

                    Panel purchaseActions = Require<Panel>(form, "pnlPurchasesActions");
                    FlowLayoutPanel purchaseFooter = Require<FlowLayoutPanel>(purchaseActions, "flowFooterButtons");
                    purchaseFooter.PerformLayout();
                    foreach (string actionName in new[] { "btnSaveOnly", "btnPreviewPrint", "btnPrintA4", "btnSavePdf", "btnClearPurchase", "btnBack" })
                    {
                        Control action = Require<Control>(purchaseFooter, actionName);
                        RequireInside(purchaseFooter, action, "purchase footer " + actionName + " " + size);
                    }
                    if (size.Width >= 960 && Require<Control>(purchaseFooter, "btnBack").Top !=
                        Require<Control>(purchaseFooter, "btnSaveOnly").Top)
                        throw new InvalidOperationException("Purchase footer actions wrapped unexpectedly at " + size + ".");

                    string[] fields =
                    {
                        "cmbSupplier", "txtBarcode", "MediComboCb", "txtQuantity",
                        "dtpProdDate", "dtpExpDate", "SelectEmployee",
                        "txtPurchaseNotesInput", "btnConfirmPurchase"
                    };

                    foreach (string field in fields)
                    {
                        Control control = Require<Control>(sidebar, field);
                        RequireHorizontallyInside(sidebar, control, "المشتريات/" + field + " " + size);
                    }

                    AntdUI.Select supplier = Require<AntdUI.Select>(sidebar, "cmbSupplier");
                    TextBox purchaseNotes = Require<TextBox>(sidebar, "txtPurchaseNotesInput");
                    if (Find<Control>(form, "txtPurchaseNotes") != null)
                        throw new InvalidOperationException("Purchase form must not show a second note field outside the saved invoice input.");
                    AntdUI.Input barcode = Require<AntdUI.Input>(sidebar, "txtBarcode");
                    if (barcode.TabStop || barcode.Visible || Require<Control>(sidebar, "lblBarcode").Visible)
                        throw new InvalidOperationException("Purchase must expose one name/barcode input and exclude the legacy scan input from Tab.");
                    AntdUI.Input quantity = Require<AntdUI.Input>(sidebar, "txtQuantity");
                    ComboBox medicine = Require<ComboBox>(sidebar, "MediComboCb");
                    if (!(medicine is MedicineSearchComboBox) || medicine.DropDownStyle != ComboBoxStyle.DropDown || medicine.AutoCompleteMode != AutoCompleteMode.None || medicine.SelectedItem == null || medicine.Text != Convert.ToString(medicine.SelectedItem))
                        throw new InvalidOperationException("Purchase medicine selection must preserve the displayed item exactly.");
                    AntdUI.Select employee = Require<AntdUI.Select>(sidebar, "SelectEmployee");
                    AntdUI.DatePicker productionDate = Require<AntdUI.DatePicker>(sidebar, "dtpProdDate");
                    AntdUI.DatePicker expiryDate = Require<AntdUI.DatePicker>(sidebar, "dtpExpDate");
                    char supplierFirst = (supplier.Text ?? string.Empty).FirstOrDefault(character => !char.IsWhiteSpace(character));
                    bool supplierContentIsArabic = supplierFirst >= '\u0600' && supplierFirst <= '\u06FF';
                    if (supplier.List || supplier.AccessibleRole != AccessibleRole.ComboBox ||
                        supplier.RightToLeft != (supplierContentIsArabic ? RightToLeft.Yes : RightToLeft.No) ||
                        supplier.TextAlign != (supplierContentIsArabic ? HorizontalAlignment.Right : HorizontalAlignment.Left) ||
                        supplier.BackColor != UiTheme.Surface ||
                        medicine.AccessibleRole != AccessibleRole.ComboBox || employee.AccessibleRole != AccessibleRole.ComboBox ||
                        productionDate.AccessibleRole != AccessibleRole.ComboBox || expiryDate.AccessibleRole != AccessibleRole.ComboBox ||
                        productionDate.RightToLeft != RightToLeft.No || expiryDate.RightToLeft != RightToLeft.No ||
                        productionDate.Value.GetValueOrDefault().Date != DateTime.Today || expiryDate.Value.GetValueOrDefault().Date != DateTime.Today.AddYears(1))
                        throw new InvalidOperationException("AntdUI purchase selectors and dates must retain accessible roles, LTR dates, and safe initial values. roles=" +
                            medicine.AccessibleRole + "/" + employee.AccessibleRole + "/" + productionDate.AccessibleRole + "/" + expiryDate.AccessibleRole +
                            "; dateDirections=" + productionDate.RightToLeft + "/" + expiryDate.RightToLeft +
                            "; dates=" + productionDate.Value + "/" + expiryDate.Value + ".");
                    supplier.Text = "مورد تجريبي جديد";
                    if (supplier.Text != "مورد تجريبي جديد" || supplier.SelectedIndex >= 0)
                        throw new InvalidOperationException("Editable AntdUI supplier selector lost free-text entry at " + size + ".");
                    const string noteSample = "ملاحظة شراء — Paracetamol 500 mg";
                    purchaseNotes.Text = noteSample;
                    if (!purchaseNotes.Multiline || purchaseNotes.Text != noteSample ||
                        purchaseNotes.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                        purchaseNotes.TextAlign != (english ? HorizontalAlignment.Left : HorizontalAlignment.Right))
                        throw new InvalidOperationException("Purchase note lost mixed Arabic text or direction at " + size +
                            "; multiline=" + purchaseNotes.Multiline + "; exact=" + (purchaseNotes.Text == noteSample) +
                            "; rtl=" + purchaseNotes.RightToLeft + "; alignment=" + purchaseNotes.TextAlign + ".");
                    foreach (AntdUI.Input input in new[] { barcode, quantity })
                    {
                        if (input.RightToLeft != RightToLeft.No || input.TextAlign != HorizontalAlignment.Left ||
                            input.AccessibleRole != AccessibleRole.Text || string.IsNullOrWhiteSpace(input.AccessibleName))
                            throw new InvalidOperationException("Purchase barcode and quantity inputs must remain accessible and LTR.");
                    }
                    object selectedMedicine = medicine.SelectedItem;
                    medicine.SelectedIndex = -1;
                    medicine.Text = "001-A123456789";
                    quantity.Text = "12";
                    if (medicine.Text != "001-A123456789" || quantity.Text != "12")
                        throw new InvalidOperationException("Unified purchase search and quantity did not retain typed values.");
                    medicine.SelectedItem = selectedMedicine;

                    Control[] purchaseTabOrder =
                    {
                        Require<Control>(sidebar, "cmbSupplier"),
                        Require<Control>(sidebar, "MediComboCb"), quantity,
                        Require<Control>(sidebar, "btnAddToPurchase"),
                        Require<Control>(sidebar, "dtpProdDate"), Require<Control>(sidebar, "dtpExpDate"),
                        Require<Control>(sidebar, "SelectEmployee"), Require<Control>(sidebar, "txtPurchaseNotesInput"),
                        Require<Control>(sidebar, "btnConfirmPurchase")
                    };
                    for (int index = 0; index < purchaseTabOrder.Length; index++)
                        if (purchaseTabOrder[index].TabIndex != index || !purchaseTabOrder[index].TabStop || string.IsNullOrWhiteSpace(purchaseTabOrder[index].AccessibleName))
                            throw new InvalidOperationException("Purchase keyboard/accessibility order is invalid at step " + index + ".");

                    AntdUI.Button confirmPurchase = Require<AntdUI.Button>(sidebar, "btnConfirmPurchase");
                    int expectedRadius = DesktopDesignTokens.ActionRadius(
                        (int)Math.Round(confirmPurchase.Height * 96.0 / Math.Max(96, confirmPurchase.DeviceDpi)));
                    if (confirmPurchase.Radius != expectedRadius)
                        throw new InvalidOperationException("Purchase confirmation did not refresh its rounded radius.");
                }

                // تبديل مورد مختار إلى اسم حر يجب أن يستخدم النص المرئي عند حفظ الطلب.
                // نعزل حدث تغيير الاختيار هنا عن SQL لأن هذا فحص واجهة بلا قاعدة بيانات.
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var syncing = typeof(Purchases).GetField("isSyncingSupplierSelection", flags);
                var getName = typeof(Purchases).GetMethod("GetSupplierName", flags);
                if (syncing == null || getName == null)
                    throw new InvalidOperationException("Purchase supplier selection contract is missing.");
                AntdUI.Select supplierSelector = Require<AntdUI.Select>(form, "cmbSupplier");
                syncing.SetValue(form, true);
                try
                {
                    supplierSelector.Items.Clear();
                    supplierSelector.Items.Add("مورد مسجل");
                    supplierSelector.SelectedIndex = 0;
                    if (!string.Equals(supplierSelector.SelectedValue?.ToString(), "مورد مسجل", StringComparison.Ordinal) ||
                        !string.Equals(getName.Invoke(form, null) as string, "مورد مسجل", StringComparison.Ordinal))
                        throw new InvalidOperationException("AntdUI supplier selection did not retain the listed supplier.");
                    supplierSelector.Text = "مورد جديد حر";
                    if (!string.Equals(getName.Invoke(form, null) as string, "مورد جديد حر", StringComparison.Ordinal))
                        throw new InvalidOperationException("Purchase request would use a stale selected supplier instead of the edited free text.");
                }
                finally
                {
                    syncing.SetValue(form, false);
                }
            }
        }

        private static void VerifyAgentAtCommonDesktopSize()
        {
            using (var form = new AgentPreview())
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox ||
                    Require<Control>(form, "label8").Visible)
                    throw new InvalidOperationException("Employee window must use standard resize/minimize/maximize chrome without a duplicate close control.");
                Prepare(form, new Size(1024, 768));
                form.PerformLayout();
                VerifyEmployeeHeader(form, new Size(1024, 768));
                AntdUI.Panel content = Require<AntdUI.Panel>(form, "employeeContentHost");
                Panel footer = Require<Panel>(form, "employeeActionBar");
                Control statusStrip = form.Controls["__UiStatusStrip"];
                if (footer.Bottom != form.ClientSize.Height - (statusStrip != null ? statusStrip.Height : 0) ||
                    content.Bottom != footer.Top || !content.AutoScroll)
                    throw new InvalidOperationException("Employee action bar overlaps the editor or status strip. footer=" + footer.Bounds +
                        ", content=" + content.Bounds + ", status=" + (statusStrip == null ? "missing" : statusStrip.Bounds.ToString()) +
                        ", client=" + form.ClientSize + ".");

                string[] controls =
                {
                    "EmployeeGV", "tb1", "tb2", "tb3", "tb4", "tb5", "tb6",
                    "roleCombo", "button1", "button2", "button3", "button4", "button5"
                };

                foreach (string control in controls)
                {
                    Control parent = control.StartsWith("button", StringComparison.Ordinal) ? (Control)footer : content;
                    RequireHorizontallyInside(parent, Require<Control>(parent, control), "الموظفون/" + control);
                }
                foreach (string actionName in new[] { "button4", "button3", "button1", "button5", "button2" })
                {
                    AntdUI.Button action = Require<AntdUI.Button>(footer, actionName);
                    RequireInside(footer, action, "إجراء الموظفين/" + actionName);
                    if (action.BorderWidth != 1 || action.DefaultBorderColor != UiTheme.Primary)
                        throw new InvalidOperationException("Employee action must use the shared green outline.");
                }
                AntdUI.Input employeeId = Require<AntdUI.Input>(form, "tb1");
                TextBox employeeName = Require<TextBox>(form, "tb2");
                AntdUI.Input age = Require<AntdUI.Input>(form, "tb3");
                AntdUI.Input salary = Require<AntdUI.Input>(form, "tb4");
                AntdUI.Input phone = Require<AntdUI.Input>(form, "tb5");
                TextBox password = Require<TextBox>(form, "tb6");
                if (employeeId.RightToLeft != RightToLeft.No || employeeName.RightToLeft != RightToLeft.Yes ||
                    age.RightToLeft != RightToLeft.No || salary.RightToLeft != RightToLeft.No ||
                    phone.RightToLeft != RightToLeft.No || password.PasswordChar != DesktopDesignTokens.PasswordMaskCharacter)
                    throw new InvalidOperationException("Employee fields lost structured LTR, Arabic RTL, or password masking.");
                employeeName.Text = "محمد أحمد — Admin";
                employeeId.Text = "EMP-001";
                phone.Text = "777123456";
                if (employeeName.Text != "محمد أحمد — Admin" || employeeId.Text != "EMP-001" ||
                    phone.Text != "777123456" || string.IsNullOrWhiteSpace(employeeName.AccessibleName))
                    throw new InvalidOperationException("Employee inputs lost mixed Arabic, ID, or phone values.");
                AntdUI.Select role = Require<AntdUI.Select>(form, "roleCombo");
                if (!role.List || role.AccessibleRole != AccessibleRole.ComboBox ||
                    role.RightToLeft != (UiDirection.IsLeftToRight ? RightToLeft.No : RightToLeft.Yes) ||
                    role.BackColor != UiTheme.Surface ||
                    !string.Equals(role.SelectedValue?.ToString(), "Cashier", StringComparison.Ordinal) ||
                    !string.Equals(role.Text, UiLanguageCatalog.GetDisplayText("كاشير"), StringComparison.Ordinal))
                    throw new InvalidOperationException("Employee role selector lost AntdUI theme, direction, or default permission.");
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var readRole = typeof(Agent).GetMethod("GetSelectedRole", flags);
                var chooseRole = typeof(Agent).GetMethod("SelectRole", flags);
                if (readRole == null || chooseRole == null)
                    throw new InvalidOperationException("Employee role mapping contract is missing.");
                chooseRole.Invoke(form, new object[] { "Manager" });
                if (!string.Equals(readRole.Invoke(form, null) as string, "Manager", StringComparison.Ordinal))
                    throw new InvalidOperationException("Employee editor changed the saved Manager permission code.");
                chooseRole.Invoke(form, new object[] { "UnknownRole" });
                if (!string.Equals(readRole.Invoke(form, null) as string, "Cashier", StringComparison.Ordinal))
                    throw new InvalidOperationException("Unknown employee role did not safely fall back to Cashier.");

                Prepare(form, new Size(760, 640));
                Application.DoEvents();
                VerifyEmployeeHeader(form, new Size(760, 640));
                if (footer.Bottom != form.ClientSize.Height - (statusStrip != null ? statusStrip.Height : 0) ||
                    content.Bottom != footer.Top)
                    throw new InvalidOperationException("Employee footer moved out of the compact window.");
                foreach (string control in controls)
                {
                    Control parent = control.StartsWith("button", StringComparison.Ordinal) ? (Control)footer : content;
                    RequireHorizontallyInside(parent, Require<Control>(parent, control), "الموظفون المضغوط/" + control);
                }
                if (!content.AutoScroll || Require<Control>(content, "roleCombo").Bottom <= content.ClientSize.Height)
                    throw new InvalidOperationException("شاشة الموظفين المضغوطة لا توفر منطقة محرر قابلة للتمرير.");
            }

            string originalTheme = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    foreach (bool english in new[] { false, true })
                    using (var form = new Agent(true, english))
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            AntdUI.Panel content = Require<AntdUI.Panel>(form, "employeeContentHost");
                            Panel footer = Require<Panel>(form, "employeeActionBar");
                            Panel header = Require<Panel>(form, "panel1");
                            Label title = Require<Label>(form, "label2");
                            DataGridView grid = Require<DataGridView>(form, "EmployeeGV");
                            AntdUI.Button add = Require<AntdUI.Button>(form, "button4");
                            AntdUI.Button close = Require<AntdUI.Button>(form, "button2");
                            TextBox name = Require<TextBox>(form, "tb2");
                            if (form.Text != (english ? "Employees" : "الموظفون") ||
                                title.Text != (english ? "Employees" : "الموظفون") ||
                                form.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                name.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                grid.ScrollBars != ScrollBars.Both ||
                                grid.Rows.Count < 2 || add.Enabled || add.Height < 44 || close.Height < 44 ||
                                header.BackColor != UiTheme.Background || title.ForeColor != UiTheme.Text ||
                                content.Bottom != footer.Top || footer.BackColor != UiTheme.Background)
                                throw new InvalidOperationException("Employee bilingual preview is inconsistent at " + size + " in " + mode +
                                    ": formDirection=" + form.RightToLeft + ", nameDirection=" + name.RightToLeft +
                                    ", gridDirection=" + grid.RightToLeft + ", scrollBars=" + grid.ScrollBars +
                                    ", rows=" + grid.Rows.Count + ", add=" + add.Bounds + "/" + add.Enabled +
                                    ", close=" + close.Bounds + ", content=" + content.Bounds +
                                    ", footer=" + footer.Bounds + ", header=" + header.BackColor +
                                    ", title=" + title.ForeColor + ".");
                            int expectedEmployeeIdIndex = 0;
                            int expectedPasswordStatusIndex = grid.Columns.Count - 1;
                            if (grid.Columns[nameof(EmployeeRecord.EmployeeId)].DisplayIndex != expectedEmployeeIdIndex ||
                                grid.Columns[nameof(EmployeeRecord.PasswordStatus)].DisplayIndex != expectedPasswordStatusIndex ||
                                grid.Columns[nameof(EmployeeRecord.EmployeeId)].HeaderCell.Style.Alignment !=
                                    (english ? DataGridViewContentAlignment.MiddleLeft : DataGridViewContentAlignment.MiddleRight) ||
                                grid.Columns[nameof(EmployeeRecord.UserName)].DefaultCellStyle.Alignment !=
                                    (english ? DataGridViewContentAlignment.MiddleLeft : DataGridViewContentAlignment.MiddleRight) ||
                                grid.Columns[nameof(EmployeeRecord.PasswordStatus)].HeaderText !=
                                    (english ? "Password status" : "حالة كلمة المرور"))
                                throw new InvalidOperationException("Employee grid did not follow the physical reading order at " + size + " in " + mode +
                                    ": employeeIdIndex=" + grid.Columns[nameof(EmployeeRecord.EmployeeId)].DisplayIndex +
                                    "/" + expectedEmployeeIdIndex + ", passwordIndex=" +
                                    grid.Columns[nameof(EmployeeRecord.PasswordStatus)].DisplayIndex + "/" + expectedPasswordStatusIndex +
                                    ", headerAlignment=" + grid.Columns[nameof(EmployeeRecord.EmployeeId)].HeaderCell.Style.Alignment +
                                    ", userAlignment=" + grid.Columns[nameof(EmployeeRecord.UserName)].DefaultCellStyle.Alignment +
                                    ", passwordHeader=" + grid.Columns[nameof(EmployeeRecord.PasswordStatus)].HeaderText + ".");
                            if (english ? add.Left >= close.Left : add.Right <= close.Right)
                                throw new InvalidOperationException("Employee actions do not start from the reading edge at " + size + " in " + mode + ".");
                            var editorCard = Require<AntdUI.Panel>(form, "employeeEditorCard");
                            if (form.MinimumSize != new Size(760, 640) || form.AutoScaleMode != AutoScaleMode.Dpi ||
                                editorCard.Shadow != 0 || editorCard.Radius != 12 || editorCard.Back != UiTheme.Surface)
                                throw new InvalidOperationException("Employee editor card or stable minimum size regressed.");
                            foreach (string frameName in new[] { "employeeNameFrame", "employeePasswordFrame" })
                            {
                                var frame = Require<AntdUI.Panel>(form, frameName);
                                var input = frame.Controls.OfType<TextBox>().Single();
                                if (frame.Height != 44 || frame.Tag != DesktopComponents.NativeTextFrameMarker ||
                                    frame.Radius != DesktopDesignTokens.ActionRadius(frame.Height) || input.Region != null ||
                                    input.BorderStyle != BorderStyle.None)
                                    throw new InvalidOperationException("Employee native field lost its shared single-border frame.");
                                RequireInside(frame, input, "Employee centered native field");
                                RequireInside(editorCard, frame, "Employee field within card");
                            }
                            foreach (string fieldName in new[] { "tb1", "tb3", "tb4", "tb5", "roleCombo" })
                            {
                                var field = Require<Control>(form, fieldName);
                                RequireInside(editorCard, field, "Employee AntdUI field within card");
                                if (field.Height != 44) throw new InvalidOperationException("Employee field heights must be consistent.");
                            }
                            var password = Require<TextBox>(form, "tb6");
                            password.Text = "qa-only-3";
                            name.Text = "محمد أحمد — Admin";
                            name.Select(2, 3);
                            typeof(Agent).GetMethod("LayoutResponsiveScreen", System.Reflection.BindingFlags.NonPublic |
                                System.Reflection.BindingFlags.Instance).Invoke(form, null);
                            UiDirection.Apply(form, english);
                            if (password.PasswordChar != DesktopDesignTokens.PasswordMaskCharacter || password.RightToLeft != RightToLeft.No || password.Text != "qa-only-3" ||
                                name.Text != "محمد أحمد — Admin" || name.SelectionStart != 2 || name.SelectionLength != 3)
                                throw new InvalidOperationException("Employee resize changed password masking, input text or selection.");
                            foreach (string labelName in new[] { "label9", "roleLabel" })
                            {
                                var caption = Require<Label>(form, labelName);
                                if (caption.Height < TextRenderer.MeasureText(caption.Text, caption.Font,
                                    new Size(caption.Width, 1000), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height)
                                    throw new InvalidOperationException("Employee field caption clips in a narrow editor.");
                            }
                            UiTheme.ApplyDataGridQuality(grid);
                            Application.DoEvents();
                            if (grid.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                Convert.ToString(grid.Rows[0].Cells[nameof(EmployeeRecord.Phone)].Value) != "+967 711 222 333")
                                throw new InvalidOperationException("Employee shared grid formatting changed direction or phone data.");
                            foreach (DataGridViewColumn column in grid.Columns)
                            {
                                int needed = TextRenderer.MeasureText(column.HeaderText,
                                    grid.ColumnHeadersDefaultCellStyle.Font ?? grid.Font,
                                    new Size(Math.Max(30, column.Width - 16), 1000),
                                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height + 12;
                                if (grid.ColumnHeadersHeight < needed)
                                    throw new InvalidOperationException("Employee column caption clips: " + column.Name);
                            }
                            foreach (AntdUI.Button action in new[]
                            {
                                add, Require<AntdUI.Button>(form, "button3"), Require<AntdUI.Button>(form, "button1"),
                                Require<AntdUI.Button>(form, "button5"), close
                            })
                                if (action.BorderWidth != 1 || action.DefaultBorderColor != UiTheme.Primary ||
                                    string.IsNullOrWhiteSpace(action.AccessibleName) || !footer.ClientRectangle.Contains(action.Bounds))
                                    throw new InvalidOperationException("Employee action lost its shared outlined treatment: " + action.Name);
                            name.Clear();
                            password.Clear();
                        }
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalTheme;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        private static void VerifyEmployeeHeader(Agent form, Size size)
        {
            Panel header = Require<Panel>(form, "panel1");
            Label obsoleteTitle = Require<Label>(form, "label1");
            Label title = Require<Label>(form, "label2");
            if (header.Width != form.ClientSize.Width || header.Height < 78 || obsoleteTitle.Visible ||
                title.Left < 0 || title.Right > header.ClientSize.Width || title.Text != UiLanguageCatalog.GetDisplayText("الموظفون") ||
                header.Controls.OfType<Label>().Count(label => label.Visible) != 1)
            {
                throw new InvalidOperationException("Employee header is clipped or no longer spans the window at " + size + ".");
            }
        }

