        public static void SaveBillingReadPreviews(string directory, bool barcodeIssue = false)
        {
            System.IO.Directory.CreateDirectory(directory); string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string mode in new[] { "Light", "Dark" }) foreach(bool english in new[] { false, true })
                foreach(var size in new[] { new Size(960,640), new Size(1366,768) })
                {
                    Properties.Setings.Default.ThemeMode=mode;
                    using(var form=new NonActivatingBillingReadPreview(english))
                    {
                        form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);
                        form.Show();form.WindowState=FormWindowState.Normal;Prepare(form,size);CommerceWorkspaceTheme.RefreshLayout(form);Application.DoEvents();
                        Prepare(form,size);CommerceWorkspaceTheme.RefreshLayout(form);
                        if(barcodeIssue)
                        {
                            var status=Require<Label>(form,"lblStockStatus");
                            string message="الباركود مكرر. اختر الصنف بالاسم أو صححه في إدارة الأدوية.";
                            UiTheme.SetStatus(status,english?UiLanguageCatalog.Translate(message):message,false);
                            var measured=TextRenderer.MeasureText(status.Text,status.Font,Size.Empty,TextFormatFlags.SingleLine|TextFormatFlags.NoPadding);
                            Console.WriteLine("Barcode status text="+measured+" available="+status.Size+" visible="+status.Visible);
                            if(!status.Visible || measured.Width>status.Width || measured.Height>status.Height || !status.Parent.ClientRectangle.Contains(status.Bounds))
                                throw new Exception("Barcode recovery message is hidden or clipped at supported POS size.");
                        }
                        Console.WriteLine("POS render requested="+size+" actualClient="+form.ClientSize+" minimum="+form.MinimumSize+" dpi="+form.DeviceDpi);
                        if(form.DeviceDpi==96 && form.MinimumSize.Height>700)throw new Exception("POS font autoscale inflates minimum height beyond the supported compact screen.");
                        using(var picture=new Bitmap(form.Width,form.Height))
                        {
                            form.DrawToBitmap(picture,new Rectangle(0,0,form.Width,form.Height));
                            var colors=new HashSet<int>();for(int y=50;y<picture.Height-30;y+=10)for(int x=30;x<picture.Width-30;x+=10)colors.Add(picture.GetPixel(x,y).ToArgb());
                            if(colors.Count<8)throw new Exception("POS preview is blank; render is not accepted.");
                            picture.Save(System.IO.Path.Combine(directory,(barcodeIssue?"billing-barcode-":"billing-")+(size.Width==960?"compact":"wide")+"-"+(english?"english":"arabic")+"-"+mode.ToLowerInvariant()+".png"));
                        }
                        form.Close();
                    }
                }
            }
            finally{Properties.Setings.Default.ThemeMode=original;}
            Console.WriteLine("PASS eight POS preview renders"+(barcodeIssue?" with visible, unclipped barcode recovery status":" with outlined refresh")+"; mock data/currency, no invoice commit or native interaction.");
        }

