        public static void VerifyBillingCurrencySnapshot()
        {
            string theme=Properties.Setings.Default.ThemeMode;
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach(string mode in new[]{"Light","Dark"}) foreach(bool english in new[]{false,true})
                {
                    Properties.Setings.Default.ThemeMode=mode;SessionContext.Start("currency-pos","Manager","POS-E");
                    var reader=new PendingPosCurrencyService();var medicines=new PendingPosMedicineService();
                    using(var form=new Billing(false,english,medicines,currencyReadService:reader))
                    {
                        Prepare(form,new Size(960,640));IntPtr handle=form.Handle;
                        typeof(Billing).GetMethod("InitializeBillingGrid",flags).Invoke(form,null);
                        var grid=Require<DataGridView>(form,"BillingGV");grid.Rows.Add("DRAFT-1","دواء 500 mg",25,3,75);
                        var status=Require<Label>(form,"lblStockStatus");
                        Func<string> money=()=>Convert.ToString(typeof(Billing).GetMethod("FormatMoney",flags).Invoke(form,new object[]{75m}));
                        if(reader.Pending.Count!=0 || !money().Contains(english?"Currency unavailable":"عملة غير متاحة"))throw new Exception("POS constructor/format invented currency or performed SQL.");
                        bool denied=false;try{form.CreateSalesIssueRequest("0","عميل","000000000","",75m,"cashier",DateTime.Today,"");}catch(InvalidOperationException){denied=true;}
                        if(!denied)throw new Exception("POS can build persistence request before currency is known.");
                        if(form.AddMedicineToCartAsync().GetAwaiter().GetResult() || medicines.Lookups.Count!=0)throw new Exception("Unknown currency allows cart quote/add.");
                        var unavailable=form.LoadCurrencySnapshotAsync();reader.Pending[0].SetResult(null);FinishMovementRead(unavailable);
                        if(unavailable.GetAwaiter().GetResult() || grid.Rows.Count!=1 || money().Contains("ر.س"))throw new Exception("Unknown currency cleared draft or invented Saudi fallback.");
                        var failed=form.LoadCurrencySnapshotAsync();reader.Pending[1].SetException(new Exception("provider detail"));FinishMovementRead(failed);
                        if(failed.GetAwaiter().GetResult() || status.Text.Contains("provider detail") || grid.Rows.Count!=1)throw new Exception("Currency failure exposes provider or loses draft.");
                        var old=form.LoadCurrencySnapshotAsync();var current=form.LoadCurrencySnapshotAsync();
                        if(!reader.Tokens[2].IsCancellationRequested || old.IsCompleted || current.IsCompleted)throw new Exception("Currency overlapping reads not canceled/pending.");
                        bool pumped=false;form.BeginInvoke(new Action(()=>pumped=true));Application.DoEvents();if(!pumped)throw new Exception("Currency wait blocks UI.");
                        reader.Pending[3].SetResult(PosCurrency("YER","ر.ي"));FinishMovementRead(current);
                        reader.Pending[2].SetResult(PosCurrency("SAR","ر.س"));FinishMovementRead(old);
                        if(!current.GetAwaiter().GetResult() || old.GetAwaiter().GetResult() || !money().EndsWith("ر.ي") || grid.Rows.Count!=1)throw new Exception("Late currency replaced current identity or lost rows.");
                        for(int i=0;i<20;i++)if(!money().EndsWith("ر.ي"))throw new Exception("Currency formatting changed identity.");
                        var frozen=form.LoadCurrencySnapshotAsync();FinishMovementRead(frozen);
                        if(!frozen.GetAwaiter().GetResult() || reader.Pending.Count!=4)throw new Exception("Known draft currency was re-read.");
                        var request=form.CreateSalesIssueRequest("0","عميل","000000000","",75m,"cashier",DateTime.Today,"memo");
                        if(request.ExpectedCurrencyCode!="YER" || request.DisplayedGrossTotal!=75m || request.DisplayedNetTotal!=75m ||
                            request.Lines.Count!=1 || request.Lines[0].Quantity!=3 || request.Lines[0].DisplayedSellingPrice!=25 || request.Notes!="memo")
                            throw new Exception("Actual POS request mapping lost currency or raw values.");
                        if(english && (!Require<Label>(form,"PriceBDLabel").Text.StartsWith("Total") || !Require<Label>(form,"PriceADLabel").Text.StartsWith("Net total")))
                            throw new Exception("Async currency update restored Arabic totals in English UI.");
                        var connection=(Func<bool>)typeof(Billing).GetField("currencyConnectionIsCurrent",flags).GetValue(form);
                        typeof(Billing).GetField("currencyConnectionIsCurrent",flags).SetValue(form,new Func<bool>(()=>false));
                        denied=false;try{form.CreateSalesIssueRequest("0","عميل","000000000","",75m,"cashier",DateTime.Today,"");}catch(InvalidOperationException){denied=true;}
                        if(!denied || money().EndsWith("ر.ي"))throw new Exception("Currency identity crosses connection context.");
                        typeof(Billing).GetField("currencyConnectionIsCurrent",flags).SetValue(form,connection);
                        SessionContext.Start("other","Manager","OTHER-E");if(money().EndsWith("ر.ي"))throw new Exception("Currency identity crosses user/employee context.");
                        SessionContext.Start("currency-pos","Manager","POS-E");
                        typeof(Billing).GetField("savedLegacyCurrencyText",flags).SetValue(form,"ر.ي");
                        typeof(Billing).GetField("currencySnapshot",flags).SetValue(form,PosCurrency("SAR","ر.س"));
                        if(form.PrintedCurrencyText!="ر.ي")throw new Exception("Saved legacy print follows changed system/display currency.");
                        typeof(Billing).GetField("_currentCommercialInvoiceSnapshot",flags).SetValue(form,new CommercialInvoicePrintSnapshot(Guid.NewGuid(),1,DateTime.UtcNow,"USD",1m,"0","عميل","000000000","","cashier","",new InvoiceTotals{GrossTotal=75m,NetTotal=75m},new CommercialInvoicePrintLine[0]));
                        if(form.PrintedCurrencyText!="USD")throw new Exception("Commercial print ignores persisted currency code.");
                        var missingSnapshot=new CommercialInvoicePrintSnapshot(Guid.NewGuid(),1,DateTime.UtcNow," ",1m,"0","عميل","000000000","","cashier","",new InvoiceTotals{GrossTotal=75m,NetTotal=75m},new CommercialInvoicePrintLine[0]);
                        typeof(Billing).GetField("_currentCommercialInvoiceSnapshot",flags).SetValue(form,missingSnapshot);
                        if(missingSnapshot.CurrencyCode.Length!=0 || form.PrintedCurrencyText!=(english?"Currency not recorded":"عملة غير محفوظة"))throw new Exception("Commercial missing currency invented SAR.");
                        typeof(Billing).GetField("_currentCommercialInvoiceSnapshot",flags).SetValue(form,null);
                        typeof(Billing).GetField("savedLegacyCurrencyText",flags).SetValue(form,null);
                        if(form.PrintedCurrencyText!=(english?"Currency not recorded":"عملة غير محفوظة"))throw new Exception("Missing legacy print currency invented historical unit.");
                        grid.Rows.Clear();typeof(Billing).GetMethod("ResetDraftCurrency",flags).Invoke(form,null);
                        if(reader.Pending.Count!=5 || !money().Contains(english?"Currency unavailable":"عملة غير متاحة"))throw new Exception("New draft retains previous currency.");
                        form.Dispose();form.Dispose();if(!reader.Tokens[4].IsCancellationRequested)throw new Exception("Closing does not cancel currency read.");
                        reader.Pending[4].SetResult(PosCurrency("YER","ر.ي"));Application.DoEvents();
                    }
                }
            }
            finally{SessionContext.Clear();Properties.Setings.Default.ThemeMode=theme;}
            Console.WriteLine("PASS POS currency snapshot: no sync reads/fallback, unavailable/error/retry/stale/cancel/UI loop, frozen identity/no repeated query, actual request raw values, English totals, connection/session guard, saved legacy/commercial print identity and new-draft/disposal; both themes/languages; fakes, no financial commit or native printing.");
        }
        private static CurrencyDisplaySnapshot PosCurrency(string code,string symbol)=>new CurrencyDisplaySnapshot(new CurrencyRecord{CurrencyId=7,CurrencyCode=code,CurrencySymbol=symbol,IsSystemCurrency=true});
        private sealed class PendingPosCurrencyService:ICurrencyReadService
        {
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<CurrencyDisplaySnapshot>> Pending=new List<System.Threading.Tasks.TaskCompletionSource<CurrencyDisplaySnapshot>>();
            internal readonly List<System.Threading.CancellationToken> Tokens=new List<System.Threading.CancellationToken>();
            public System.Threading.Tasks.Task<CurrencyDisplaySnapshot> GetSystemCurrencySnapshotAsync(OperationActor actor,System.Threading.CancellationToken token)
            {var t=new System.Threading.Tasks.TaskCompletionSource<CurrencyDisplaySnapshot>();Pending.Add(t);Tokens.Add(token);return t.Task;}
            public IReadOnlyList<CurrencyRecord> GetAll(){throw new Exception("POS synchronous currency list.");}
            public CurrencyRecord GetSystemCurrency(){throw new Exception("POS synchronous currency read.");}
            public string GetSystemCurrencyDisplay(){throw new Exception("POS synchronous currency display/fallback.");}
        }

        public static void VerifyBillingBarcodeAsync()
        {
            string theme = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = mode; SessionContext.Start("barcode-read", "Manager", "POS-E");
                    var medicines = new PendingPosMedicineService(); var search = new PendingPosBarcodeService();
                    using (var form = new Billing(false, english, medicines, () => "ر.ي", search))
                    {
                        Prepare(form,new Size(960,640)); IntPtr handle=form.Handle;
                        typeof(Billing).GetMethod("InitializeBillingGrid",flags).Invoke(form,null);
                        var choices=Require<ComboBox>(form,"MediComboCb"); var barcode=Require<Control>(form,"txtBarcode");
                        var quantity=Require<Control>(form,"txtQuantity"); var add=Require<AntdUI.Button>(form,"btnAddToCart");
                        var cart=Require<DataGridView>(form,"BillingGV"); var status=Require<Label>(form,"lblStockStatus");
                        var names=form.LoadMedicineNamesAsync(); medicines.NameDirectories[0].SetResult(new[]{"ألف 500 mg","باء 250 mg"}); FinishMovementRead(names);
                        quantity.Text="4"; barcode.Text="000001"; var old=form.TrySelectMedicineByBarcodeAsync();
                        if(old.IsCompleted || add.Enabled || choices.SelectedIndex!=-1 || search.Values[0]!="000001" || search.Actors[0].UserName!="barcode-read")
                            throw new Exception("POS async barcode fails leading-zero/actor/action/pending contract.");
                        bool pumped=false; form.BeginInvoke(new Action(()=>pumped=true)); Application.DoEvents();
                        if(!pumped) throw new Exception("POS barcode read blocks UI messages.");
                        barcode.Text="000002"; if(!search.Tokens[0].IsCancellationRequested) throw new Exception("Editing barcode did not cancel read.");
                        var current=form.TrySelectMedicineByBarcodeAsync(); search.Pending[1].SetResult(new MedicineMatch("باء 250 mg","شركة"));
                        PumpBarcodeUntil(()=>medicines.Lookups.Count==1,"Selected barcode stock read did not start.");
                        if(add.Enabled || current.IsCompleted) throw new Exception("Barcode permits add before fresh selected stock is checked.");
                        medicines.Lookups[0].SetResult(PosMedicine("باء 250 mg",16,12)); FinishMovementRead(current);
                        if(!current.GetAwaiter().GetResult() || choices.SelectedItem?.ToString()!="باء 250 mg" || !add.Enabled || quantity.Text!="4")
                            throw new Exception("Valid barcode selection/quantity/stock did not recover.");
                        search.Pending[0].SetResult(new MedicineMatch("ألف 500 mg","OLD")); FinishMovementRead(old);
                        if(old.GetAwaiter().GetResult() || choices.SelectedItem?.ToString()!="باء 250 mg" || medicines.Lookups.Count!=1)
                            throw new Exception("Late barcode changed current selection.");

                        barcode.Text="missing"; var missing=form.TrySelectMedicineByBarcodeAsync(); search.Pending[2].SetResult(null); FinishMovementRead(missing);
                        if(missing.GetAwaiter().GetResult() || add.Enabled || choices.SelectedIndex!=-1 || cart.Rows.Count!=0 ||
                            status.Text!=(english?UiLanguageCatalog.Translate("الباركود غير موجود."):"الباركود غير موجود."))
                            throw new Exception("Missing barcode retained the previous selectable medicine or wrong language.");
                        barcode.Text="duplicate"; var duplicate=form.TrySelectMedicineByBarcodeAsync(); search.Pending[3].SetException(new MedicineBarcodeAmbiguityException()); FinishMovementRead(duplicate);
                        if(duplicate.GetAwaiter().GetResult() || choices.SelectedIndex!=-1 || add.Enabled || status.Text != (english ? UiLanguageCatalog.Translate("الباركود مكرر. اختر الصنف بالاسم أو صححه في إدارة الأدوية.") : "الباركود مكرر. اختر الصنف بالاسم أو صححه في إدارة الأدوية."))
                            throw new Exception("Ambiguous barcode silently selected a medicine.");
                        barcode.Text="not-in-directory"; var unknown=form.TrySelectMedicineByBarcodeAsync(); search.Pending[4].SetResult(new MedicineMatch("غياب","شركة")); FinishMovementRead(unknown);
                        if(unknown.GetAwaiter().GetResult() || choices.SelectedIndex!=-1 || medicines.Lookups.Count!=1)
                            throw new Exception("Barcode absent from current directory selected arbitrary text.");

                        barcode.Text="manual-overrides"; var manual=form.TrySelectMedicineByBarcodeAsync(); choices.SelectedIndex=0;
                        if(!search.Tokens[5].IsCancellationRequested) throw new Exception("Manual medicine selection did not supersede barcode.");
                        medicines.Lookups[1].SetResult(PosMedicine("ألف 500 mg",20,25)); Application.DoEvents();
                        search.Pending[5].SetResult(new MedicineMatch("باء 250 mg","LATE")); FinishMovementRead(manual);
                        if(manual.GetAwaiter().GetResult() || choices.SelectedItem?.ToString()!="ألف 500 mg") throw new Exception("Barcode overwrote manual selection.");

                        barcode.Text="editing-stock"; var editing=form.TrySelectMedicineByBarcodeAsync(); search.Pending[6].SetResult(new MedicineMatch("باء 250 mg","شركة"));
                        PumpBarcodeUntil(()=>medicines.Lookups.Count==3,"Barcode selected stock wait missing.");
                        barcode.Text="edited-stock";
                        if(!search.Tokens[6].IsCancellationRequested || !medicines.LookupTokens[2].IsCancellationRequested)
                            throw new Exception("Barcode edit did not cancel both owned barcode and selected-stock reads.");
                        medicines.Lookups[2].SetResult(PosMedicine("باء 250 mg",16,12)); FinishMovementRead(editing);
                        if(editing.GetAwaiter().GetResult() || add.Enabled) throw new Exception("Edited scan retained valid stale stock.");

                        barcode.Text="refresh-overrides"; var refresh=form.TrySelectMedicineByBarcodeAsync(); var refreshedNames=form.LoadMedicineNamesAsync();
                        if(!search.Tokens[7].IsCancellationRequested) throw new Exception("Directory refresh did not cancel barcode.");
                        medicines.NameDirectories[1].SetResult(new[]{"ألف 500 mg","باء 250 mg"}); FinishMovementRead(refreshedNames);
                        search.Pending[7].SetResult(new MedicineMatch("باء 250 mg","LATE")); FinishMovementRead(refresh);
                        if(refresh.GetAwaiter().GetResult() || choices.SelectedIndex!=-1) throw new Exception("Old barcode crossed directory refresh.");

                        barcode.Text="enter"; var enter=new KeyEventArgs(Keys.Enter);
                        typeof(Billing).GetMethod("txtBarcode_KeyDown",flags).Invoke(form,new object[]{barcode,enter});
                        if(!enter.SuppressKeyPress || !enter.Handled || search.Pending.Count!=9) throw new Exception("Enter barcode event not handled once.");
                        search.Pending[8].SetResult(new MedicineMatch("ألف 500 mg","شركة"));
                        PumpBarcodeUntil(()=>medicines.Lookups.Count==4,"Enter did not request fresh selected stock.");
                        medicines.Lookups[3].SetResult(PosMedicine("ألف 500 mg",20,25));
                        PumpBarcodeUntil(()=>barcode.Text.Length==0,"Successful Enter did not clear barcode.");
                        if(choices.SelectedItem?.ToString()!="ألف 500 mg" || !add.Enabled || quantity.Text!="4" || cart.Rows.Count!=0)
                            throw new Exception("Enter changed quantity or posted/added a medicine automatically.");

                        barcode.Text="saved-overrides"; var saved=form.TrySelectMedicineByBarcodeAsync();
                        typeof(Billing).GetField("_isInvoiceSaved",flags).SetValue(form,true);
                        search.Pending[9].SetResult(new MedicineMatch("باء 250 mg","LATE")); FinishMovementRead(saved);
                        if(saved.GetAwaiter().GetResult() || add.Enabled || choices.SelectedIndex!=-1) throw new Exception("Late scan edited saved invoice.");
                        typeof(Billing).GetField("_isInvoiceSaved",flags).SetValue(form,false);

                        int failedIndex=search.Pending.Count; barcode.Text="network-failure"; var failed=form.TrySelectMedicineByBarcodeAsync();
                        search.Pending[failedIndex].SetException(new Exception("unexpected provider details")); FinishMovementRead(failed);
                        if(failed.GetAwaiter().GetResult() || choices.SelectedIndex!=-1 || add.Enabled || status.Text.Contains("unexpected provider details") || string.IsNullOrWhiteSpace(status.Text))
                            throw new Exception("Unexpected barcode failure leaked details or retained selection.");
                        int longIndex=search.Pending.Count; barcode.Text=new string('0',101); var tooLong=form.TrySelectMedicineByBarcodeAsync();
                        search.Pending[longIndex].SetException(new MedicineBarcodeLengthException()); FinishMovementRead(tooLong);
                        if(tooLong.GetAwaiter().GetResult() || add.Enabled || status.Text!=(english?UiLanguageCatalog.Translate("الباركود يتجاوز 100 حرف. راجع القيمة ثم أعد المسح."):"الباركود يتجاوز 100 حرف. راجع القيمة ثم أعد المسح."))
                            throw new Exception("Invalid barcode length did not explain safe correction.");
                        int changedIndex=search.Pending.Count; barcode.Text="session"; var changed=form.TrySelectMedicineByBarcodeAsync(); SessionContext.Start("other","Manager","OTHER-E");
                        search.Pending[changedIndex].SetResult(new MedicineMatch("ألف 500 mg","PRIVATE")); FinishMovementRead(changed);
                        if(changed.GetAwaiter().GetResult() || choices.SelectedIndex!=-1 || add.Enabled) throw new Exception("Barcode leaked selection across session.");
                        SessionContext.Start("barcode-read","Manager","POS-E");
                        int closingIndex=search.Pending.Count; barcode.Text="close"; var closing=form.TrySelectMedicineByBarcodeAsync(); form.Dispose(); form.Dispose();
                        if(!search.Tokens[closingIndex].IsCancellationRequested) throw new Exception("Closing did not cancel barcode read.");
                        search.Pending[closingIndex].SetResult(new MedicineMatch("ألف 500 mg","LATE")); FinishMovementRead(closing);
                        if(closing.GetAwaiter().GetResult()) throw new Exception("Closed POS accepted barcode result.");
                    }
                }
            }
            finally { SessionContext.Clear(); Properties.Setings.Default.ThemeMode=theme; }
            Console.WriteLine("PASS POS async barcode: UI loop, leading zeros/actor, edit/manual/refresh/session/saved/close cancellation, late/missing/duplicate/length/unexpected-error/stale-directory rejection, fresh selected stock, Enter handler and quantity/no-auto-add; both themes/languages; fakes, no SQL or native keyboard.");
        }

        private static void PumpBarcodeUntil(Func<bool> condition,string message)
        {
            DateTime deadline=DateTime.UtcNow.AddSeconds(10);
            while(!condition()) { if(DateTime.UtcNow>deadline) throw new Exception(message); Application.DoEvents(); System.Threading.Thread.Sleep(1); }
        }
        public static void VerifyQuickSearchAuthorization()
        {
            VerifyQuickSearchSessionInvalidation();
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            string original=Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string mode in new[]{"Light","Dark"}) foreach(bool english in new[]{false,true})
                {
                    Properties.Setings.Default.ThemeMode=mode;
                    bool current=true; var service=new PendingQuickSearchService();
                    var session=new MedicineQuickSearchSession(service,new OperationActor{UserName="qa-search",UserRole="Manager"},()=>current);
                    using(var form=new MedicineQuickSearchForm("",false,english,session))
                    {
                        var first=form.RunSearchAsync(); var second=form.RunSearchAsync();
                        if(!service.Tokens[0].IsCancellationRequested)throw new Exception("Old quick search was not cancelled.");
                        service.Pending[1].SetResult(new List<MedicineSearchItem>{new MedicineSearchItem{MedName="دواء جديد 500 mg"}}.AsReadOnly());
                        PumpBarcodeUntil(()=>second.IsCompleted,"Latest quick search did not finish."); second.GetAwaiter().GetResult();
                        var grid=Require<DataGridView>(form,"quickSearchResults"); var latest=grid.DataSource;
                        if(!Require<AntdUI.Button>(form,"quickSearchSelect").Enabled || latest==null)throw new Exception("Valid quick search did not enable selection.");
                        service.Pending[0].SetResult(new List<MedicineSearchItem>{new MedicineSearchItem{MedName="old"}}.AsReadOnly());
                        PumpBarcodeUntil(()=>first.IsCompleted,"Late quick search did not finish."); first.GetAwaiter().GetResult();
                        if(!ReferenceEquals(latest,grid.DataSource))throw new Exception("Late search replaced current rows.");
                        current=false;
                        typeof(MedicineQuickSearchForm).GetMethod("SelectResult",flags).Invoke(form,null);
                        if(grid.DataSource!=null || Require<AntdUI.Button>(form,"quickSearchSelect").Enabled || form.SelectedMedicine!=null || form.DialogResult==DialogResult.OK)
                            throw new Exception("Invalid session retained selectable search rows.");
                        int count=service.Pending.Count; form.RunSearchAsync().GetAwaiter().GetResult();
                        if(service.Pending.Count!=count)throw new Exception("Invalid context reached search service.");
                        current=true; var revoked=form.RunSearchAsync(); current=false;
                        service.Pending[count].SetResult(new List<MedicineSearchItem>{new MedicineSearchItem{MedName="revoked"}}.AsReadOnly());
                        PumpBarcodeUntil(()=>revoked.IsCompleted,"Revoked search did not finish."); revoked.GetAwaiter().GetResult();
                        if(grid.DataSource!=null)throw new Exception("Revoked in-flight context exposed search rows.");
                        current=true; var closing=form.RunSearchAsync(); var token=service.Tokens[service.Tokens.Count-1]; form.Dispose();
                        if(!token.IsCancellationRequested)throw new Exception("Closing quick search did not cancel read.");
                        service.Pending[service.Pending.Count-1].SetResult(new List<MedicineSearchItem>().AsReadOnly());
                        PumpBarcodeUntil(()=>closing.IsCompleted,"Closed quick search did not finish."); closing.GetAwaiter().GetResult();
                    }
                }
                Console.WriteLine("PASS quick search: cancellation/latest result, session revocation before selection/during read, denied retry and close; both themes/languages; fake services, no native keys or SQL.");
            }
            finally{Properties.Setings.Default.ThemeMode=original;}
        }
        private static void VerifyQuickSearchSessionInvalidation()
        {
            string oldTheme=Properties.Setings.Default.ThemeMode;
            bool authenticated=SessionContext.IsAuthenticated;
            string oldUser=SessionContext.CurrentUser,oldRole=SessionContext.CurrentRole,oldEmployee=SessionContext.CurrentEmployeeId;
            try
            {
                foreach(string theme in new[]{"Light","Dark"}) foreach(bool english in new[]{false,true})
                foreach(string path in new[]{"Loaded","Pending","Background"})
                {
                    Properties.Setings.Default.ThemeMode=theme;
                    SessionContext.Start("quick-search-session-fixture","Manager");
                    long revision=SessionContext.CurrentSessionRevision;
                    var service=new PendingQuickSearchService();
                    var session=new MedicineQuickSearchSession(service,new OperationActor{UserName="quick-search-session-fixture",UserRole="Manager"},
                        ()=>SessionContext.CurrentSessionRevision==revision);
                    using(var form=new MedicineQuickSearchForm("",false,english,session))
                    {
                        IntPtr handle=form.Handle;
                        var read=form.RunSearchAsync();
                        var grid=Require<DataGridView>(form,"quickSearchResults");
                        var select=Require<AntdUI.Button>(form,"quickSearchSelect");
                        if(path!="Pending")
                        {
                            service.Pending[0].SetResult(new List<MedicineSearchItem>{new MedicineSearchItem{MedName="Fixture 500 mg"}}.AsReadOnly());
                            PumpBarcodeUntil(()=>read.IsCompleted,"Quick search fixture did not load.");
                            read.GetAwaiter().GetResult();
                            if(grid.DataSource==null||!select.Enabled)throw new Exception("Quick search session fixture was not selectable.");
                        }
                        if(path=="Background")
                        {
                            System.Threading.Tasks.Task.Run(()=>SessionContext.Start("quick-search-session-fixture","Manager")).GetAwaiter().GetResult();
                            PumpBarcodeUntil(()=>grid.DataSource==null&&!select.Enabled,"Background session notification did not clear displayed quick search.");
                        }
                        else SessionContext.Start("quick-search-session-fixture","Manager");
                        if(grid.DataSource!=null||select.Enabled||form.SelectedMedicine!=null)
                            throw new Exception("Session notification retained quick search results.");
                        if(path=="Pending")
                        {
                            if(!service.Tokens[0].IsCancellationRequested)throw new Exception("Session notification did not cancel pending quick search.");
                            service.Pending[0].SetResult(new List<MedicineSearchItem>{new MedicineSearchItem{MedName="late"}}.AsReadOnly());
                            PumpBarcodeUntil(()=>read.IsCompleted,"Cancelled quick search did not finish.");
                            read.GetAwaiter().GetResult();
                            if(grid.DataSource!=null||select.Enabled)throw new Exception("Late search repopulated invalidated context.");
                        }
                        int calls=service.Pending.Count;
                        form.RunSearchAsync().GetAwaiter().GetResult();
                        if(service.Pending.Count!=calls)throw new Exception("Invalidated search reached service on retry.");
                    }
                    Console.WriteLine("PASS immediate quick search session invalidation: "+theme+"/"+(english?"LTR":"RTL")+"/"+path+"; controlled context/fake service.");
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode=oldTheme;
                if(authenticated)SessionContext.Start(oldUser,oldRole,oldEmployee);else SessionContext.Clear();
            }
        }

        private sealed class PendingQuickSearchService : IMedicineSearchService
        {
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<MedicineSearchItem>>> Pending=new List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<MedicineSearchItem>>>();
            internal readonly List<System.Threading.CancellationToken> Tokens=new List<System.Threading.CancellationToken>();
            public System.Threading.Tasks.Task<IReadOnlyList<MedicineSearchItem>> SearchAsync(string query,OperationActor actor,System.Threading.CancellationToken token)
            {var pending=new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<MedicineSearchItem>>();Pending.Add(pending);Tokens.Add(token);return pending.Task;}
            public MedicineMatch FindByBarcode(string barcode, OperationActor actor){throw new Exception("Unexpected barcode.");}
            public System.Threading.Tasks.Task<MedicineMatch> FindByBarcodeAsync(string barcode,OperationActor actor,System.Threading.CancellationToken token){throw new Exception("Unexpected barcode.");}
        }
        private sealed class PendingPosBarcodeService : IMedicineSearchService
        {
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<MedicineMatch>> Pending=new List<System.Threading.Tasks.TaskCompletionSource<MedicineMatch>>();
            internal readonly List<System.Threading.CancellationToken> Tokens=new List<System.Threading.CancellationToken>();
            internal readonly List<string> Values=new List<string>(); internal readonly List<OperationActor> Actors=new List<OperationActor>();
            public System.Threading.Tasks.Task<MedicineMatch> FindByBarcodeAsync(string value,OperationActor actor,System.Threading.CancellationToken token)
            { var pending=new System.Threading.Tasks.TaskCompletionSource<MedicineMatch>();Pending.Add(pending);Tokens.Add(token);Values.Add(value);Actors.Add(new OperationActor{UserName=actor.UserName,UserRole=actor.UserRole});return pending.Task; }
            public MedicineMatch FindByBarcode(string value, OperationActor actor){throw new Exception("POS synchronous barcode read.");}
