        }


        private static void VerifyBillingSessionRevisions()
        {
            string theme=Properties.Setings.Default.ThemeMode;
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach(string mode in new[]{"Light","Dark"}) foreach(bool english in new[]{false,true})
                foreach(string path in new[]{"Names","Selection","Barcode","Cart","Currency","FrozenCurrency"})
                {
                    Properties.Setings.Default.ThemeMode=mode;SessionContext.Start("pos-revision","Manager","POS-E");
                    var medicines=new PendingPosMedicineService();var barcode=new PendingPosBarcodeService();var currency=new PendingPosCurrencyService();
                    bool currencyPath=path=="Currency"||path=="FrozenCurrency";
                    using(var form=new Billing(false,english,medicines,currencyPath?null:(Func<string>)(()=>"ر.ي"),barcode,currency))
                    {
                        Prepare(form,new Size(960,640));IntPtr handle=form.Handle;
                        typeof(Billing).GetMethod("InitializeBillingGrid",flags).Invoke(form,null);
                        var grid=Require<DataGridView>(form,"BillingGV");grid.Rows.Add("DRAFT-1","مسودة 500 mg",25,3,75);
                        var choices=Require<ComboBox>(form,"MediComboCb");
                        typeof(Billing).GetField("medicineBarcodeApplyingSelection",flags).SetValue(form,true);
                        choices.Items.Add("دواء 500 mg");choices.SelectedIndex=0;
                        typeof(Billing).GetField("medicineBarcodeApplyingSelection",flags).SetValue(form,false);
                        Require<Control>(form,"txtQuantity").Text="2";
                        Require<AntdUI.Input>(form,"txtBarcode").Text="000123";
                        typeof(Billing).GetField("selectedStockPreview",flags).SetValue(form,(int?)20);
                        System.Threading.Tasks.Task<bool> pending;
                        switch(path)
                        {
                            case "Names":pending=form.LoadMedicineNamesAsync();break;
                            case "Selection":pending=form.RefreshSelectedMedicineAsync();break;
                            case "Barcode":pending=form.TrySelectMedicineByBarcodeAsync();break;
                            case "Cart":pending=form.AddMedicineToCartAsync();break;
                            default:pending=form.LoadCurrencySnapshotAsync();break;
                        }
                        if(pending.IsCompleted)throw new Exception(path+" did not reach controlled pending read.");
                        if(path=="FrozenCurrency")
                        {currency.Pending[0].SetResult(PosCurrency("YER","ر.ي"));FinishMovementRead(pending);if(!pending.Result)throw new Exception("Initial currency was not accepted.");}
                        SessionContext.Clear();SessionContext.Start("pos-revision","Manager","POS-E");
                        switch(path)
                        {
                            case "Names":medicines.NameDirectories[0].SetResult(new[]{"OLD SESSION"});break;
                            case "Selection":case "Cart":medicines.Lookups[medicines.Lookups.Count-1].SetResult(PosMedicine("دواء 500 mg",20,25));break;
                            case "Barcode":barcode.Pending[0].SetResult(new MedicineMatch("دواء 500 mg","000123"));break;
                            case "Currency":currency.Pending[0].SetResult(PosCurrency("YER","ر.ي"));break;
                        }
                        FinishMovementRead(pending);
                        if(path!="FrozenCurrency"&&pending.Result)throw new Exception(path+" accepted a result from a previous login of the same user.");
                        if(grid.Rows.Count!=1||Convert.ToInt32(grid.Rows[0].Cells["TotalAmount"].Value)!=75)
                            throw new Exception(path+" changed the existing invoice draft during reauthentication.");
                        if(path=="Cart"&&(!Require<AntdUI.Button>(form,"billingRefreshMedicines").Enabled||!Require<AntdUI.Button>(form,"btnBack").Enabled||!Require<Control>(form,"txtQuantity").Enabled||Require<AntdUI.Button>(form,"btnSaveOnly").Enabled))
                            throw new Exception("Changed cart session leaves no safe navigation/refresh or enables persistence.");
                        if(path=="Names"&&choices.Items.Count!=0)throw new Exception("Old login medicine names remain selectable.");
                        if(path=="Selection"&&typeof(Billing).GetField("selectedStockPreview",flags).GetValue(form)!=null)throw new Exception("Old login stock preview remains available.");
                        if(path=="Barcode"&&(choices.SelectedIndex!=-1||medicines.Lookups.Count!=0))throw new Exception("Old login barcode launched a new stock read or selected a medicine.");
                        if(currencyPath)
                        {
                            string money=Convert.ToString(typeof(Billing).GetMethod("FormatMoney",flags).Invoke(form,new object[]{75m}));
                            if(money.EndsWith("ر.ي"))throw new Exception(path+" currency identity survived the old login.");
                            bool denied=false;try{form.CreateSalesIssueRequest("0","عميل","000000000","",75m,"cashier",DateTime.Today,"");}catch(InvalidOperationException){denied=true;}
                            if(!denied)throw new Exception(path+" can prepare persistence with previous-login currency.");
                            if(path=="Currency")
                            {
                                var retry=form.LoadCurrencySnapshotAsync();currency.Pending[1].SetResult(PosCurrency("YER","ر.ي"));FinishMovementRead(retry);
                                if(!retry.Result)throw new Exception("New login cannot recover a rejected pending currency read.");
                            }
                        }
                    }
                }
            }
            finally{SessionContext.Clear();Properties.Setings.Default.ThemeMode=theme;}
            Console.WriteLine("PASS POS same-user login revision: names, stock selection, barcode, cart, pending/frozen currency; existing draft preserved; both themes/languages; controlled asynchronous providers, no SQL writes/native keys.");
        }

        public static void VerifyBillingMedicineReads()
        {
            VerifyBillingSessionRevisions();
            string theme = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = mode; SessionContext.Start("pos-read", "Manager", "POS-E");
                    var service = new PendingPosMedicineService();
                    using (var form = new Billing(false, english, service, () => "ر.ي"))
                    {
                        Prepare(form, new Size(1024,768)); IntPtr handle = form.Handle;
                        typeof(Billing).GetMethod("InitializeBillingGrid", flags).Invoke(form, null);
                        var choices = Require<ComboBox>(form, "MediComboCb");
                        var cart = Require<DataGridView>(form, "BillingGV");
                        var quantity = Require<Control>(form,"txtQuantity");
                        var add = Require<AntdUI.Button>(form,"btnAddToCart");
                        var first = form.LoadMedicineNamesAsync(); var second = form.LoadMedicineNamesAsync();
                        if (!service.NameTokens[0].IsCancellationRequested || choices.Enabled || add.Enabled) throw new Exception("POS pending names do not cancel/guard actions.");
                        bool pumped = false; form.BeginInvoke(new Action(() => pumped = true)); Application.DoEvents();
                        if (!pumped) throw new Exception("POS directory wait blocks UI messages.");
                        service.NameDirectories[1].SetResult(new[]{"ألف Pharma 500 mg","باء Pharma 250 mg"}); FinishMovementRead(second);
                        service.NameDirectories[0].SetResult(new[]{"OLD"}); FinishMovementRead(first);
                        if (choices.Items.Count!=2 || choices.Items.Contains("OLD") || !choices.Enabled || add.Enabled) throw new Exception("POS old names leaked or selection action enabled without a selected record.");
                        choices.SelectedIndex=0; var selectingA = form.RefreshSelectedMedicineAsync(); int selectedA=service.Lookups.Count-1;
                        choices.SelectedIndex=1; var selectingB = form.RefreshSelectedMedicineAsync(); int selectedB=service.Lookups.Count-1;
                        if (!service.LookupTokens[selectedA].IsCancellationRequested || add.Enabled) throw new Exception("POS selection does not cancel a preceding read.");
                        service.Lookups[selectedB].SetResult(PosMedicine("باء Pharma 250 mg",17,22)); FinishMovementRead(selectingB);
                        for(int i=0;i<service.Lookups.Count;i++) if(i!=selectedB&&!service.Lookups[i].Task.IsCompleted) service.Lookups[i].SetResult(PosMedicine("ألف Pharma 500 mg",11,20));
                        FinishMovementRead(selectingA); Application.DoEvents();
                        if ((int?)typeof(Billing).GetField("selectedStockPreview",flags).GetValue(form)!=17 || !add.Enabled) throw new Exception("POS stale stock response overwrote the current selection.");
                        quantity.Text="3"; int beforeCart=service.Lookups.Count;
                        var adding=form.AddMedicineToCartAsync(); int pendingCart=service.Lookups.Count-1;
                        if(adding.IsCompleted||form.AddMedicineToCartAsync().GetAwaiter().GetResult()||cart.Rows.Count!=0||Require<AntdUI.Button>(form,"btnSaveOnly").Enabled||quantity.Enabled)
                            throw new Exception("POS cart read permits duplicate/add/save/edit while pending.");
                        pumped=false;form.BeginInvoke(new Action(()=>pumped=true));Application.DoEvents();if(!pumped)throw new Exception("POS cart read blocks messages.");
                        service.Lookups[pendingCart].SetResult(PosMedicine("باء Pharma 250 mg",17,25));FinishMovementRead(adding);
                        if(!adding.Result||service.Lookups.Count!=beforeCart+1||cart.Rows.Count!=1||Convert.ToInt32(cart.Rows[0].Cells["Sprice"].Value)!=25||Convert.ToInt32(cart.Rows[0].Cells["Quantity"].Value)!=3||Convert.ToInt32(cart.Rows[0].Cells["TotalAmount"].Value)!=75||!quantity.Enabled)
                            throw new Exception("POS fresh single read changed price/quantity/line totals or control recovery.");
                        choices.SelectedIndex=0; var reselect=form.RefreshSelectedMedicineAsync(); int current=service.Lookups.Count-1;
                        for(int i=0;i<service.Lookups.Count;i++)if(!service.Lookups[i].Task.IsCompleted)service.Lookups[i].SetResult(PosMedicine("ألف Pharma 500 mg",11,20));FinishMovementRead(reselect);
                        quantity.Text="2";var changedDraft=form.AddMedicineToCartAsync();current=service.Lookups.Count-1;quantity.Text="4";
                        service.Lookups[current].SetResult(PosMedicine("ألف Pharma 500 mg",11,20));FinishMovementRead(changedDraft);
                        if(changedDraft.Result||cart.Rows.Count!=1)throw new Exception("POS late item response ignored edited quantity.");
                        var failed=form.LoadMedicineNamesAsync();service.NameDirectories[2].SetException(new InvalidOperationException("offline"));FinishMovementRead(failed);
                        if(failed.Result||choices.Items.Count!=0||cart.Rows.Count!=1||add.Enabled)throw new Exception("POS failed directory exposes stale names or erases the invoice.");
                        if(!Require<AntdUI.Button>(form,"billingRefreshMedicines").Enabled)throw new Exception("POS failed read provides no refresh action.");
                        foreach(var size in new[]{new Size(960,640),new Size(1024,768),new Size(1366,768)})
                        {
                            Prepare(form,size);CommerceWorkspaceTheme.RefreshLayout(form);
                            var footer=Require<FlowLayoutPanel>(form,"flowFooterButtons");var refresh=Require<AntdUI.Button>(form,"billingRefreshMedicines");
                            var save=Require<AntdUI.Button>(form,"btnSaveOnly");var sell=Require<AntdUI.Button>(form,"btnPreviewPrint");
                            if(footer.RightToLeft!=RightToLeft.No || (english?save.Left>=sell.Left:save.Left<=sell.Left))
                                throw new Exception("POS footer physical order contradicts Arabic RTL or English LTR.");
                            if(refresh.Parent!=footer||refresh.Left<0||refresh.Top<0||refresh.Right>footer.ClientSize.Width||refresh.Bottom>footer.ClientSize.Height)
                                throw new Exception("POS outlined refresh clips its responsive footer.");
                            foreach(Control action in footer.Controls)if(action!=refresh&&action.Visible&&refresh.Bounds.IntersectsWith(action.Bounds))throw new Exception("POS refresh overlaps another footer action.");
                        }
                        var empty=form.LoadMedicineNamesAsync();service.NameDirectories[3].SetResult(new string[0]);FinishMovementRead(empty);if(!empty.Result||!choices.Enabled)throw new Exception("POS empty retry cannot recover.");
                        var changedSession=form.LoadMedicineNamesAsync();SessionContext.Start("other-pos","Manager","OTHER");if(!service.NameTokens[4].IsCancellationRequested||choices.Items.Count!=0||add.Enabled)throw new Exception("POS session notification retained pending lookup before completion.");service.NameDirectories[4].SetResult(new[]{"PRIVATE"});FinishMovementRead(changedSession);
                        if(changedSession.Result||choices.Items.Count!=0||add.Enabled)throw new Exception("POS names leaked to another session.");
                        SessionContext.Start("pos-read","Manager","POS-E");var closing=form.LoadMedicineNamesAsync();form.Dispose();
                        if(!service.NameTokens[5].IsCancellationRequested)throw new Exception("POS dispose did not cancel directory SQL.");
                        service.NameDirectories[5].SetResult(new string[0]);FinishMovementRead(closing);
                    }
                }
            }
            finally{Properties.Setings.Default.ThemeMode=theme;SessionContext.Clear();}
            Console.WriteLine("PASS POS async names/targeted selection/fresh cart record, UI message loop, cancellation/stale/session/edit guards, repeated add/save controls, raw price/quantity/totals, failure/empty/close; both themes/languages; fake services, no SQL or invoice commit.");
        }
