                        var old=form.ReloadDirectoryAsync();SessionContext.Start("medicine-test","Manager","MED-E");reply(0);FinishMovementRead(old);
                        if(grid.Rows.Count!=0||company.Items.Count!=0)throw new Exception("Medicine directory accepts previous login generation rows/options.");
                        var fresh=form.ReloadDirectoryAsync();reply(1);FinishMovementRead(fresh);
                        if(grid.Rows.Count!=1||company.Items.Count!=1)throw new Exception("Medicine fresh directory cannot recover.");
                        typeof(Medicine).GetMethod("PopulateFieldsFromRow",flags).Invoke(form,new object[]{0});
