        private sealed class PendingMedicineService : IMedicineService
        {
            internal int Creates, Updates, Deletes;
            internal readonly List<System.Threading.CancellationToken> Tokens = new List<System.Threading.CancellationToken>();
            internal readonly List<System.Threading.CancellationToken> CompanyTokens = new List<System.Threading.CancellationToken>();
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<MedicineRecord>>> Medicines = new List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<MedicineRecord>>>();
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<string>>> Companies = new List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<string>>>();
            public IReadOnlyList<MedicineRecord> GetAll(OperationActor actor) { throw new Exception("Medicine form uses synchronous directory read."); }
            public IReadOnlyList<string> GetCompanyNames(OperationActor actor) { throw new Exception("Medicine form uses synchronous company read."); }
            public System.Threading.Tasks.Task<IReadOnlyList<MedicineRecord>> GetAllAsync(OperationActor actor, System.Threading.CancellationToken token)
            { var pending = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<MedicineRecord>>(); Medicines.Add(pending); Tokens.Add(token); return pending.Task; }
            public async System.Threading.Tasks.Task<IReadOnlyList<string>> GetNamesAsync(OperationActor actor, System.Threading.CancellationToken token)
            { var rows = await GetAllAsync(actor, token); if (rows == null) return null; var names = new List<string>(rows.Count); foreach (var row in rows) names.Add(row.MedName); return names.AsReadOnly(); }
            public System.Threading.Tasks.Task<MedicineRecord> FindByNameAsync(string name, OperationActor actor, System.Threading.CancellationToken token)
            { throw new Exception("Unexpected selected lookup in medicine directory test."); }
            public System.Threading.Tasks.Task<IReadOnlyList<string>> GetCompanyNamesAsync(OperationActor actor, System.Threading.CancellationToken token)
            { var pending = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<string>>(); Companies.Add(pending); CompanyTokens.Add(token); return pending.Task; }
            internal System.Threading.CancellationToken BarcodeToken;
            internal System.Threading.Tasks.TaskCompletionSource<string> PendingBarcode;
            public System.Threading.Tasks.Task<string> GenerateAvailableBarcodeAsync(string excluded, OperationActor actor, System.Threading.CancellationToken token)
            { BarcodeToken = token; PendingBarcode = new System.Threading.Tasks.TaskCompletionSource<string>(); return PendingBarcode.Task; }
            public string GenerateAvailableBarcode(string excluded, OperationActor actor) { throw new Exception("Unexpected barcode request in directory test."); }
            internal System.Threading.Tasks.TaskCompletionSource<MedicineRecord> NextCreate;
            public System.Threading.Tasks.Task<MedicineRecord> CreateAsync(MedicineRecord row, OperationActor actor)
            { Creates++; return NextCreate == null ? System.Threading.Tasks.Task.FromResult(row) : NextCreate.Task; }
            public System.Threading.Tasks.Task<bool> UpdateAsync(MedicineRecord row, OperationActor actor)
            { return System.Threading.Tasks.Task.FromResult(Update(row, actor)); }
            public System.Threading.Tasks.Task<bool> DeleteAsync(string name, OperationActor actor)
            { return System.Threading.Tasks.Task.FromResult(Delete(name, actor)); }
            public MedicineRecord Create(MedicineRecord value, OperationActor actor) { throw new Exception("Medicine screen uses synchronous save."); }
            public bool Update(MedicineRecord value, OperationActor actor) {Updates++;return true;}
            public bool Delete(string value, OperationActor actor) {Deletes++;return true;}
        }

