                    {
                        Prepare(form, new Size(960, 640)); IntPtr handle = form.Handle;
                        var grid = Require<AntdUI.Table>(form, "manufacturerTable");
                        if (form.ActiveCompanyGrid != grid || grid.ClipboardCopy || grid.ClipboardCopyFocusedCell)
