                        bool pumped = false; form.BeginInvoke(new Action(() => pumped = true)); Application.DoEvents();
                        if (!pumped || first.IsCompleted || grid.Enabled) throw new Exception("Modern supplier read blocks or accepts stale selection.");
                        var second = form.ReloadGridAsync();
                        if (!service.Tokens[0].IsCancellationRequested) throw new Exception("Modern supplier read does not cancel obsolete SQL.");
                        var row = new ManufacturerRecord { CompId = "0007", CompName = "مُستَلزمات Pharma 500 mg", CompPhone = "+967 077 012 345", CompAddress = "عدن Main 12" };
                        service.Pending[1].SetResult(new[] { row }); FinishMovementRead(second);
                        service.Pending[0].SetResult(new[] { new ManufacturerRecord { CompId = "OLD" } }); FinishMovementRead(first);
                        var data = grid.DataSource as DataTable;
                        if (data == null || data.Rows.Count != 1 || (string)data.Rows[0]["CompId"] != "0007" ||
                            (string)data.Rows[0]["CompPhone"] != row.CompPhone || (string)data.Rows[0]["CompName"] != row.CompName)
                            throw new Exception("Modern supplier table changes raw Arabic, phone or identity.");
