                            for (int i = 0; i < actions.Length; i++) for (int j = i + 1; j < actions.Length; j++)
                                if (actions[i].Bounds.IntersectsWith(actions[j].Bounds)) throw new Exception("Modern supplier actions overlap.");
                        }
                        var refresh = form.ReloadGridAsync(); copied = null;
                        typeof(AntdUI.Table).GetMethod("OnKeyDown", flags).Invoke(grid, new object[] { new KeyEventArgs(Keys.Control | Keys.C) });
                        if (copied != null || form.SelectedCompanyText() != null) throw new Exception("Modern supplier copies a stale row during refresh.");
                        service.Pending[2].SetException(new InvalidOperationException("read failure")); FinishMovementRead(refresh);
                        if (((DataTable)grid.DataSource).Rows.Count != 0 || !grid.Enabled) throw new Exception("Modern supplier failed read leaves stale rows or blocks recovery.");
                        var retry = form.ReloadGridAsync(); service.Pending[3].SetResult(new ManufacturerRecord[0]); FinishMovementRead(retry);
                        if (((DataTable)grid.DataSource).Rows.Count != 0 || form.SelectedCompanyText() != null) throw new Exception("Modern supplier empty retry has a selection.");
                        Require<TextBox>(form, "tb2").Text = "بيانات المورد السابق";
                        var changed = form.ReloadGridAsync(); SessionContext.Start("another-user", "Manager", "OTHER");
                        if (!service.Tokens[4].IsCancellationRequested || Require<TextBox>(form, "tb2").Text.Length != 0 ||
                            Require<AntdUI.Button>(form, "button4").Enabled)
                            throw new Exception("Supplier session notification retained draft or pending read before completion.");
                        service.Pending[4].SetResult(new[] { row }); FinishMovementRead(changed);
                        if (((DataTable)grid.DataSource).Rows.Count != 0 || Require<TextBox>(form, "tb2").Text.Length != 0)
                            throw new Exception("Modern supplier exposes previous session rows.");
                        SessionContext.Start("supplier-test", "Manager", "SUP-E");
                        var closing = form.ReloadGridAsync(); form.Dispose();
                        if (!service.Tokens[5].IsCancellationRequested) throw new Exception("Modern supplier disposal does not cancel read.");
                        service.Pending[5].SetResult(new ManufacturerRecord[0]); FinishMovementRead(closing);
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = originalTheme; SessionContext.Clear(); }
            Console.WriteLine("PASS AntdUI supplier raw Arabic/phone/identity, selection, injected row copy, RTL/LTR, footer/table geometry, async stale/session/failure/disposal; no clipboard or SQL writes.");
        }

        private static void VerifyManufacturerSessionRevisions()
        {
            string originalTheme = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool modern in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    SessionContext.Start("supplier-test", "Manager", "SUP-E");
                    var service = new PendingManufacturerService();
                    bool reloginOnConfirm = false;
                    int confirmations = 0;
                    string copiedRow = null;
                    using (var form = new Manufacturer(false, english, service, modern, text => copiedRow=text, () => {
                        confirmations++;
                        if (reloginOnConfirm) SessionContext.Start("supplier-test", "Manager", "SUP-E");
                        return true;
                    }))
                    {
                        Prepare(form, new Size(960, 640)); IntPtr handle = form.Handle;
                        var row = new ManufacturerRecord { CompId="0007", CompName="شركة Pharma 500 mg", CompPhone="077012", CompAddress="عدن Main 12" };
                        var pending = form.ReloadGridAsync();
                        SessionContext.Start("supplier-test", "Manager", "SUP-E");
                        service.Pending[0].SetResult(new[] { row }); FinishMovementRead(pending);
                        var rows = (List<ManufacturerRecord>)typeof(Manufacturer).GetField("companyRows", flags).GetValue(form);
                        if (rows.Count != 0) throw new Exception("Supplier accepts pending rows from a prior login generation.");
                        var fresh = form.ReloadGridAsync(); service.Pending[1].SetResult(new[] { row }); FinishMovementRead(fresh);
                        if (rows.Count != 1) throw new Exception("Supplier fresh login read does not recover.");
                        if (modern) Require<AntdUI.Table>(form, "manufacturerTable").SelectedIndex = 1;
                        else typeof(Manufacturer).GetMethod("CompanyGV_CellContentClick", flags).Invoke(form, new object[] { null, new DataGridViewCellEventArgs(0,0) });
                        if (Require<TextBox>(form,"tb2").Text != row.CompName) throw new Exception("Supplier fresh selection changed raw Arabic.");
                        string expectedCopy=string.Join("\t",new[]{row.CompId,row.CompName,row.CompPhone,row.CompAddress});
                        if(form.SelectedCompanyText()!=expectedCopy)throw new Exception("Supplier table variants do not expose the same raw row copy contract.");
                        var copyKey=new KeyEventArgs(Keys.Control|Keys.C);
                        form.ActiveCompanyGrid.GetType().GetMethod("OnKeyDown",flags).Invoke(form.ActiveCompanyGrid,new object[]{copyKey});
                        if(copiedRow!=expectedCopy || !copyKey.Handled)throw new Exception("Supplier table Ctrl+C does not route through guarded injected copy.");
                        Require<TextBox>(form,"tb2").Clear();
                        var enterKey=new KeyEventArgs(Keys.Enter);
                        form.ActiveCompanyGrid.GetType().GetMethod("OnKeyDown",flags).Invoke(form.ActiveCompanyGrid,new object[]{enterKey});
                        if(Require<TextBox>(form,"tb2").Text!=row.CompName || !enterKey.Handled)throw new Exception("Supplier table Enter does not load current selection.");
                        SessionContext.Start("supplier-test", "Manager", "SUP-E");
                        copiedRow=null;
                        var staleCopyKey=new KeyEventArgs(Keys.Control|Keys.C);
                        form.ActiveCompanyGrid.GetType().GetMethod("OnKeyDown",flags).Invoke(form.ActiveCompanyGrid,new object[]{staleCopyKey});
                        if (copiedRow!=null || form.SelectedCompanyText()!=null) throw new Exception("Supplier copies previous login rows.");
                        typeof(Manufacturer).GetMethod("button3_Click", flags).Invoke(form,new object[]{null,EventArgs.Empty});
                        typeof(Manufacturer).GetMethod("button1_Click", flags).Invoke(form,new object[]{null,EventArgs.Empty});
                        if (service.Updates!=0 || service.Deletes!=0 || confirmations!=0 || Require<TextBox>(form,"tb2").Text.Length!=0)
                            throw new Exception("Supplier stale editor reaches mutation/confirmation or remains populated.");
                        var recovery = form.ReloadGridAsync(); service.Pending[2].SetResult(new[] { row }); FinishMovementRead(recovery);
                        if (modern) Require<AntdUI.Table>(form, "manufacturerTable").SelectedIndex = 1;
                        else typeof(Manufacturer).GetMethod("CompanyGV_CellContentClick", flags).Invoke(form,new object[]{null,new DataGridViewCellEventArgs(0,0)});
                        reloginOnConfirm = true;
                        typeof(Manufacturer).GetMethod("button1_Click", flags).Invoke(form,new object[]{null,EventArgs.Empty});
                        if (confirmations!=1 || service.Deletes!=0) throw new Exception("Supplier confirmation relogin reaches deletion.");
                        Require<TextBox>(form,"tb2").Text="old editor draft";
                        var editorRecovery = form.ReloadGridAsync(); service.Pending[3].SetResult(new[] { row }); FinishMovementRead(editorRecovery);
                        if(Require<TextBox>(form,"tb2").Text.Length!=0) throw new Exception("Supplier reload preserves previous login editor draft.");
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode=originalTheme; SessionContext.Clear(); }
            Console.WriteLine("PASS supplier login generation: pending rows, selection/copy/editor, mutation and confirmation guards; 8 theme/language/table variants; no SQL/native input.");
        }

        private sealed class PendingManufacturerService : IManufacturerService
        {
            internal int Creates, Updates, Deletes;
            internal readonly List<System.Threading.CancellationToken> Tokens = new List<System.Threading.CancellationToken>();
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<ManufacturerRecord>>> Pending =
                new List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<ManufacturerRecord>>>();

            public System.Threading.Tasks.Task<IReadOnlyList<ManufacturerRecord>> GetAllAsync(OperationActor actor, System.Threading.CancellationToken token)
            {
                var pending = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<ManufacturerRecord>>();
                Pending.Add(pending); Tokens.Add(token); return pending.Task;
            }
            public void Create(ManufacturerRecord value, OperationActor actor) { Creates++; }
            public bool Update(ManufacturerRecord value, OperationActor actor) { Updates++; return true; }
            public bool Delete(string value, OperationActor actor) { Deletes++; return true; }
        }

        private static void VerifyManufacturerResponsiveLayout()
        {
            string originalTheme = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string mode in new[] { "Light", "Dark" })
                {
                    Properties.Setings.Default.ThemeMode = mode;
                    using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
                    foreach (bool english in new[] { false, true })
                    using (var form = new Manufacturer(true, english, useAntdTable: false))
                    {
                        form.ShowInTaskbar = false;
                        form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000);
                        form.Show();
                        if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox ||
                            Require<Control>(form, "label8").Visible)
                            throw new InvalidOperationException("Manufacturer window must use standard window chrome without a duplicate close button.");
                        foreach (Size size in new[] { new Size(760, 640), new Size(1024, 768), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            Application.DoEvents();
                            var naturalGrid = Require<DataGridView>(form, "CompanyGV");
                            var naturalEditor = Require<AntdUI.Panel>(form, "manufacturerEditorCard");
                            if (size.Width < 1000 && naturalGrid.Bounds.IntersectsWith(naturalEditor.Bounds))
                            {
                                Console.WriteLine("Supplier natural resize overlap: grid=" + naturalGrid.Bounds + "; editor=" + naturalEditor.Bounds + "; size=" + size);
                                throw new InvalidOperationException("Supplier table overlaps editor before manual layout reset.");
                            }
                            typeof(Manufacturer).GetMethod("LayoutResponsiveScreen",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                            Panel header = Require<Panel>(form, "panel1");
                            Label title = Require<Label>(form, "label2");
                            Panel content = Require<Panel>(form, "manufacturerContentHost");
                            Panel footer = Require<Panel>(form, "manufacturerActionBar");
                            Control statusStrip = form.Controls["__UiStatusStrip"];
                            int workspaceBottom = form.ClientSize.Height - (statusStrip != null ? statusStrip.Height : 0);
                            DataGridView grid = Require<DataGridView>(form, "CompanyGV");
                            AntdUI.Input companyId = Require<AntdUI.Input>(form, "tb1");
                            TextBox companyName = Require<TextBox>(form, "tb2");
                            AntdUI.Input companyPhone = Require<AntdUI.Input>(form, "tb3");
                            AntdUI.Input companyAddress = Require<AntdUI.Input>(form, "tb4");
                            AntdUI.Button add = Require<AntdUI.Button>(footer, "button4");
                            AntdUI.Button close = Require<AntdUI.Button>(footer, "button2");
                            foreach (string actionName in new[] { "button4", "button3", "button1", "button5", "refreshManufacturers", "button2" })
                            {
                                var action = Require<AntdUI.Button>(footer, actionName);
                                RequireInside(footer, action, "Supplier footer " + actionName);
                                if (action.Height < 44 || action.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right) ||
                                    action.Radius != DesktopDesignTokens.ActionRadius(action.Height))
                                    throw new InvalidOperationException("Supplier action shape or direction changed: " + actionName);
                            }
                            var arranged = footer.Controls.OfType<AntdUI.Button>().OrderBy(action => action.Left).ToArray();
                            for (int index = 1; index < arranged.Length; index++)
                                if (arranged[index - 1].Right > arranged[index].Left)
                                    throw new InvalidOperationException("Supplier footer actions overlap.");

                            if (form.Text != (english ? "Manufacturers" : "الشركات المصنعة") ||
                                title.Text != (english ? "Manufacturers" : "الشركات المصنعة") ||
                                form.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                header.Width != form.ClientSize.Width || title.Right > header.ClientSize.Width ||
                                header.Controls.OfType<Label>().Count(label => label.Visible) != 1 ||
                                header.BackColor != UiTheme.Background || title.ForeColor != UiTheme.Text ||
                                footer.Bottom != workspaceBottom || content.Bottom != footer.Top || !content.AutoScroll ||
                                footer.BackColor != UiTheme.Background || Require<Panel>(form, "panel2").Visible)
                                throw new InvalidOperationException("Manufacturer bilingual shell failed at " + size + " in " + mode +
                                    ": english=" + english + ", formText=" + form.Text + ", title=" + title.Text +
                                    ", direction=" + form.RightToLeft + ", header=" + header.Bounds + "/" + header.BackColor +
                                    ", titleBounds=" + title.Bounds + "/" + title.ForeColor +
                                    ", visibleLabels=" + header.Controls.OfType<Label>().Count(label => label.Visible) +
                                    ", content=" + content.Bounds + ", footer=" + footer.Bounds +
                                    ", workspaceBottom=" + workspaceBottom + ", autoScroll=" + content.AutoScroll +
                                    ", panel2Visible=" + Require<Panel>(form, "panel2").Visible + ".");

                            RequireHorizontallyInside(content, grid, "manufacturer grid " + size);
                            RequireHorizontallyInside(content, companyId, "manufacturer id " + size);
                            RequireHorizontallyInside(content, companyName, "manufacturer name " + size);
                            RequireHorizontallyInside(content, companyPhone, "manufacturer phone " + size);
                            RequireHorizontallyInside(content, companyAddress, "manufacturer address " + size);
                            if (companyId.RightToLeft != RightToLeft.No ||
                                companyName.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                companyPhone.RightToLeft != RightToLeft.No ||
                                companyAddress.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                companyId.TabIndex != 0 || companyName.TabIndex != 1 ||
                                companyPhone.TabIndex != 2 || companyAddress.TabIndex != 3)
                                throw new InvalidOperationException("Manufacturer field direction or keyboard order failed at " + size + ".");
                            if (grid.Rows.Count < 2 || grid.ScrollBars != ScrollBars.Both ||
                                grid.ColumnHeadersDefaultCellStyle.SelectionForeColor.ToArgb() != Color.White.ToArgb() ||
                                grid.ColumnHeadersDefaultCellStyle.SelectionBackColor.ToArgb() != UiTheme.Primary.ToArgb() ||
                                grid.Columns["CompId"].HeaderText != (english ? "Company ID" : "رقم الشركة") ||
                                grid.Columns["CompAddress"].HeaderText != (english ? "Address" : "العنوان") ||
                                grid.Columns["CompId"].DisplayIndex != 0 ||
                                grid.Columns["CompAddress"].DisplayIndex != grid.Columns.Count - 1 ||
                                grid.Columns["CompName"].DefaultCellStyle.Alignment !=
                                    (english ? DataGridViewContentAlignment.MiddleLeft : DataGridViewContentAlignment.MiddleRight))
                                throw new InvalidOperationException("Manufacturer grid direction or preview data failed at " + size + " in " + mode +
                                    ": english=" + english + ", rows=" + grid.Rows.Count + ", scroll=" + grid.ScrollBars +
                                    ", idHeader=" + grid.Columns["CompId"].HeaderText + ", addressHeader=" + grid.Columns["CompAddress"].HeaderText +
                                    ", idIndex=" + grid.Columns["CompId"].DisplayIndex + "/0" +
                                    ", addressIndex=" + grid.Columns["CompAddress"].DisplayIndex + "/" + (grid.Columns.Count - 1) +
                                    ", nameAlignment=" + grid.Columns["CompName"].DefaultCellStyle.Alignment + ".");
                            if (size.Width >= 1000)
                            {
                                int editorScreenX = companyId.PointToScreen(Point.Empty).X;
                                int gridScreenX = grid.PointToScreen(Point.Empty).X;
                                if (english ? editorScreenX >= gridScreenX : editorScreenX <= gridScreenX)
                                    throw new InvalidOperationException("Manufacturer editor is not on the leading side at " + size + ".");
                            }
                            if (size.Width < 1000 && content.AutoScrollMinSize.Height <= content.ClientSize.Height)
                                throw new InvalidOperationException("Compact manufacturer layout must retain vertical scroll for its editor.");
                            foreach (string actionName in new[] { "button4", "button3", "button1", "button5", "button2" })
                            {
                                AntdUI.Button action = Require<AntdUI.Button>(footer, actionName);
                                RequireInside(footer, action, "manufacturer footer action " + actionName);
                                if (action.Height < 44 || action.BorderWidth != 1 || action.DefaultBorderColor != UiTheme.Primary ||
                                    string.IsNullOrWhiteSpace(action.IconSvg) || string.IsNullOrWhiteSpace(action.AccessibleName))
                                    throw new InvalidOperationException("Manufacturer action lost shared AntdUI treatment at " + size + ": " + actionName);
                            }
                            if (add.Enabled || !close.Enabled || (english ? add.Left >= close.Left : add.Right <= close.Right))
                                throw new InvalidOperationException("Manufacturer preview safety or action reading edge failed at " + size + ".");
                            AntdUI.Panel editorCard = Require<AntdUI.Panel>(form, "manufacturerEditorCard");
                            AntdUI.Panel nameFrame = Require<AntdUI.Panel>(form, "manufacturerNameFrame");
                            if (editorCard.Radius != 12 || editorCard.Shadow != 0 || editorCard.Back != UiTheme.Surface ||
                                nameFrame.Height != 44 || nameFrame.Tag != DesktopComponents.NativeTextFrameMarker ||
                                nameFrame.Radius != DesktopDesignTokens.ActionRadius(nameFrame.Height) ||
                                companyName.BorderStyle != BorderStyle.None || companyName.Region != null ||
                                title.AccessibleName != title.Text || title.Height < TextRenderer.MeasureText(title.Text,
                                    title.Font, new Size(title.Width, 1000), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height)
                                throw new InvalidOperationException("Manufacturer editor lost shared card, field shape or measured header; region=" +
                                    (companyName.Region != null) + "; cardRadius=" + editorCard.Radius + "; frameHeight=" + nameFrame.Height);
                            if (form.MinimumSize != new Size(760, 620) || form.AutoScaleMode != AutoScaleMode.Dpi ||
                                grid.Tag != UiTheme.PreserveLocalizedCustomGridColumns)
                                throw new InvalidOperationException("Manufacturer font scaling or grid ownership regressed.");
                            UiTheme.ApplyDataGridQuality(grid);
                            Application.DoEvents();
                            if (grid.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes) ||
                                grid.Columns["CompId"].DisplayIndex != 0 || grid.ScrollBars != ScrollBars.Both)
                                throw new InvalidOperationException("Manufacturer grid lost its localized layout after shared styling.");
                            if (Convert.ToString(grid.Rows[0].Cells["CompPhone"].Value) != "+967 1 234 567" ||
                                Convert.ToString(grid.Rows[0].Cells["CompPhone"].FormattedValue) != "+967 1 234 567")
                                throw new InvalidOperationException("Manufacturer phone rendering changed its underlying or formatted text.");
                            RequireInside(nameFrame, companyName, "Manufacturer centered name editor");
                            foreach (Control field in new Control[] { companyId, nameFrame, companyPhone, companyAddress })
                                RequireInside(editorCard, field, "Manufacturer field inside shared card");
                            if (CompanyGVBoundsOverlap(editorCard, grid))
                                throw new InvalidOperationException("Manufacturer card overlaps the table.");
                        }
                        TextBox nameInput = Require<TextBox>(form, "tb2");
                        nameInput.Text = "الشركة الطبية — Pharma 500 mg";
                        if (nameInput.Text != "الشركة الطبية — Pharma 500 mg")
                            throw new InvalidOperationException("Manufacturer name input changed mixed Arabic/English text.");
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = originalTheme;
                using (var paletteRefresh = new Form()) UiTheme.Apply(paletteRefresh);
            }
        }

        private static bool CompanyGVBoundsOverlap(Control editor, Control grid)
        {
            return editor.Parent == grid.Parent && editor.Bounds.IntersectsWith(grid.Bounds);
        }

        private static void VerifyCustomerSharedSurfaces()
        {
            string originalTheme = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (bool chooser in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var form = new CustomerSupplierManagementForm(chooser, true, english))
                    {
                        foreach (Size size in new[] { new Size(760, 590), new Size(960, 640), new Size(1366, 768) })
                        {
                            Prepare(form, size);
                            UiTheme.Apply(form);
                            form.ApplyPresentation(english);
                            form.PerformLayout();
                            var actions = Require<FlowLayoutPanel>(form, "customerEditorActions");
                            if (actions.RightToLeft != RightToLeft.No || actions.FlowDirection !=
                                (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft))
                                throw new InvalidOperationException("Customer actions must have one explicit physical reading direction.");
                            foreach (string actionName in chooser ? new[] { "chooseCustomer", "reloadCustomers" } : new[] { "newCustomer", "saveCustomer", "openSupplierManagement", "reloadCustomers" })
                            {
                                var button = Require<AntdUI.Button>(form, actionName);
                                RequireInside(button.Parent, button, "Customer action " + actionName);
                                if (button.Height < 44 || button.BorderWidth != 1 ||
                                    button.Radius != DesktopDesignTokens.ActionRadius(button.Height) ||
                                    button.IconPosition != (english ? AntdUI.TAlignMini.Left : AntdUI.TAlignMini.Right))
                                {
                                    Console.WriteLine("Customer action mismatch: " + actionName + "; english=" + english +
                                        "; height=" + button.Height + "; border=" + button.BorderWidth + "; radius=" + button.Radius +
                                        "; expectedRadius=" + DesktopDesignTokens.ActionRadius(button.Height) + "; icon=" + button.IconPosition);
                                    throw new InvalidOperationException("Customer action lost its shared shape or icon direction: " + actionName);
                                }
                            }
                            foreach (string labelName in new[] { "customerManagementTitle", "customerManagementSubtitle" })
                            {
                                var label = Require<Label>(form, labelName);
                                int needed = TextRenderer.MeasureText(label.Text, label.Font, new Size(label.Width, 1000),
                                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                                if (label.Height < needed || label.AccessibleName != label.Text)
                                    throw new InvalidOperationException("Customer header clips or hides its accessible text: " + labelName);
                            }
                            foreach (string frameName in chooser ? new[] { "customerSearchFrame" } :
                                new[] { "customerSearchFrame", "customerNameFrame", "customerAddressFrame" })
                            {
                                var frame = Require<AntdUI.Panel>(form, frameName);
                                var editor = frame.Controls.OfType<TextBox>().Single();
                                if (frame.Tag != DesktopComponents.NativeTextFrameMarker || frame.Height < 44 ||
                                    frame.Radius != DesktopDesignTokens.ActionRadius(frame.Height) || frame.Shadow != 0 ||
                                    editor.BorderStyle != BorderStyle.None || editor.Region != null)
                                    throw new InvalidOperationException("Customer native text fallback has a second border or inconsistent shared frame.");
                                RequireInside(frame, editor, "Customer text editor");
                                string sample = "مُستَلزمات Pharma 500 mg";
                                editor.Text = sample;
                                editor.Select(2, 3);
                                form.ApplyPresentation(english);
                                if (editor.Text != sample || editor.SelectionStart != 2 || editor.SelectionLength != 3)
                                    throw new InvalidOperationException("Customer presentation changed the editor value or selection.");
                            }
                            if (!chooser)
                            {
                                var phoneInput = Require<AntdUI.Input>(form, "customerPhone");
                                if (phoneInput.Right > phoneInput.Parent.ClientSize.Width || phoneInput.Bottom > phoneInput.Parent.ClientSize.Height)
                                    Console.WriteLine("Customer phone clips: input=" + phoneInput.Bounds + "; field=" + phoneInput.Parent.ClientSize + "; form=" + size);
                                RequireInside(phoneInput.Parent, phoneInput, "Customer phone input");
                            }
                            var table = Require<AntdUI.Table>(form, "customerMasterTable");
                            if (!chooser && table.Columns[english ? 0 : table.Columns.Count - 1].Key != "CustomerName")
                                throw new InvalidOperationException("Customer name column must lead from the language's reading edge.");
                        }
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = originalTheme; }
        }

        private static void VerifyCustomerSupplierManagementLayout()
        {
            var fields = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            using (var chooser = new CustomerSupplierManagementForm(selectionMode: true, previewMode: true))
            {
                foreach (Size size in new[] { new Size(760, 590), new Size(960, 640), new Size(1120, 760), new Size(1366, 768) })
                {
                    Prepare(chooser, size);
                    AntdUI.Table table = Require<AntdUI.Table>(chooser, "customerMasterTable");
                    TextBox search = Require<TextBox>(chooser, "customerSearch");
                    TableLayoutPanel workspace = Require<TableLayoutPanel>(chooser, "customerManagementWorkspace");
                    Control actionSurface = Require<Control>(chooser, "customerEditorSurface");
                    if (table.Columns.Count != 1 || Find<TextBox>(chooser, "customerName") != null ||
                        Find<AntdUI.Input>(chooser, "customerPhone") != null || Find<TextBox>(chooser, "customerAddress") != null ||
                        Find<AntdUI.Button>(chooser, "newCustomer") != null || Find<AntdUI.Button>(chooser, "saveCustomer") != null ||
                        Find<AntdUI.Button>(chooser, "openSupplierManagement") != null)
                        throw new InvalidOperationException("POS customer selector exposes customer details or management actions.");
                    RequireHorizontallyInside(chooser, table, "Customer selection table " + size);
                    RequireHorizontallyInside(chooser, search, "Customer selection search " + size);
                    if (table.Parent != workspace || actionSurface.Parent != workspace || workspace.RowCount != 2 ||
                        actionSurface.Top < table.Bottom ||
                        search.RightToLeft != RightToLeft.Yes || search.TextAlign != HorizontalAlignment.Left)
                        throw new InvalidOperationException("Customer-only selection layout failed at " + size +
                            ": tableParent=" + (table.Parent == workspace) + ", actionParent=" + (actionSurface.Parent == workspace) +
                            ", rows=" + workspace.RowCount + ", actionTop=" + actionSurface.Top + ", tableBottom=" + table.Bottom +
                            ", searchRTL=" + search.RightToLeft + ", searchAlign=" + search.TextAlign + ".");
                }

                var rows = (List<SalesCustomer>)typeof(CustomerSupplierManagementForm).GetField("allCustomers", fields).GetValue(chooser);
                rows.Add(new SalesCustomer { CustomerId = "selection-test", CustomerName = "عميل محدد", PhoneNumber = "777555111", Address = "عنوان خاص" });
                TextBox chooserSearch = Require<TextBox>(chooser, "customerSearch");
                chooserSearch.Text = "777555111";
                AntdUI.Table chooserTable = Require<AntdUI.Table>(chooser, "customerMasterTable");
                DataTable chooserData = chooserTable.DataSource as DataTable;
                if (chooserData == null || chooserData.Rows.Count != 1 || chooserTable.Columns.Count != 1)
                    throw new InvalidOperationException("Customer selector must search by phone while displaying customer name only.");
                chooserTable.SelectedIndex = 1;
                SalesCustomer selectedCustomer = (SalesCustomer)typeof(CustomerSupplierManagementForm).GetProperty("SelectedCustomer", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(chooser);
                if (selectedCustomer == null || selectedCustomer.CustomerId != "selection-test" || !Require<Control>(chooser, "chooseCustomer").Enabled)
                    throw new InvalidOperationException("Customer selector must confirm only the explicitly selected master record.");
                chooser.ApplyPresentation(true);
                Prepare(chooser, new Size(760, 590));
                if (chooser.RightToLeft != RightToLeft.No || chooser.RightToLeftLayout ||
                    chooser.Text != "Select a customer" ||
                    Require<AntdUI.Table>(chooser, "customerMasterTable").RightToLeft != RightToLeft.No ||
                    Require<AntdUI.Button>(chooser, "chooseCustomer").Text != "Select customer")
                    throw new InvalidOperationException("POS customer selector English direction failed.");
                chooser.ApplyPresentation(false);
                if (chooser.RightToLeft != RightToLeft.Yes || !chooser.RightToLeftLayout ||
                    Require<AntdUI.Table>(chooser, "customerMasterTable").RightToLeft != RightToLeft.Yes)
                    throw new InvalidOperationException("POS customer selector did not restore Arabic direction.");
            }

            using (var management = new CustomerSupplierManagementForm(selectionMode: false, previewMode: true))
            {
                foreach (Size size in new[] { new Size(760, 590), new Size(960, 640), new Size(1120, 760), new Size(1366, 768) })
                {
                    Prepare(management, size);
                    AntdUI.Table table = Require<AntdUI.Table>(management, "customerMasterTable");
                    TextBox search = Require<TextBox>(management, "customerSearch");
                    TextBox name = Require<TextBox>(management, "customerName");
                    AntdUI.Input phone = Require<AntdUI.Input>(management, "customerPhone");
                    TextBox address = Require<TextBox>(management, "customerAddress");
                    AntdUI.Panel nameFrame = Require<AntdUI.Panel>(management, "customerNameFrame");
                    AntdUI.Panel addressFrame = Require<AntdUI.Panel>(management, "customerAddressFrame");
                    TableLayoutPanel workspace = Require<TableLayoutPanel>(management, "customerManagementWorkspace");
                    TableLayoutPanel editorFields = Require<TableLayoutPanel>(management, "customerEditorFields");
                    Label editorStatus = Require<Label>(management, "customerManagementStatus");
                    FlowLayoutPanel editorActions = Require<FlowLayoutPanel>(management, "customerEditorActions");
                    Control editor = Require<Control>(management, "customerEditorSurface");
                    RequireHorizontallyInside(management, table, "Customer management table " + size);
                    RequireHorizontallyInside(management, search, "Customer management search " + size);
                    if (table.Columns.Count != 4 || table.AccessibleName != "قائمة العملاء" ||
                        nameFrame.Height < 44 || phone.Height < 44 || addressFrame.Height < 44 ||
                        editorFields.Bottom > editorStatus.Top || editorActions.HorizontalScroll.Visible ||
                        search.RightToLeft != RightToLeft.Yes || name.RightToLeft != RightToLeft.Yes ||
                        phone.RightToLeft != RightToLeft.No || address.RightToLeft != RightToLeft.Yes ||
                        search.TextAlign != HorizontalAlignment.Left || name.TextAlign != HorizontalAlignment.Left ||
                        phone.TextAlign != HorizontalAlignment.Left || address.TextAlign != HorizontalAlignment.Left)
                        throw new InvalidOperationException("Customer management direction check failed at " + size +
                            ": columns=" + table.Columns.Count + ", tableName='" + table.AccessibleName +
                            "', search=" + search.RightToLeft + "/" + search.TextAlign + ", name=" + name.RightToLeft + "/" + name.TextAlign +
                            ", phone=" + phone.RightToLeft + "/" + phone.TextAlign + ", address=" + address.RightToLeft + "/" + address.TextAlign + ".");
                    bool wide = size.Width >= 1220;
                    if (table.Parent != workspace || editor.Parent != workspace ||
                        (wide && (workspace.RowCount != 1 || editor.Bounds.IntersectsWith(table.Bounds) ||
                            (UiDirection.IsLeftToRight ? editor.Right > table.Left : editor.Left < table.Right))) ||
                        (!wide && (workspace.RowCount != 2 || editor.Top < table.Bottom)))
                        throw new InvalidOperationException("Customer management responsive master/detail layout failed at " + size + ".");
                    foreach (string actionName in new[] { "newCustomer", "saveCustomer", "openSupplierManagement" })
                    {
                        Control action = Require<Control>(management, actionName);
                        if (action.Width <= 0 || action.Height <= 0)
                            throw new InvalidOperationException("Customer master action has no layout size: " + actionName + " at " + size + ".");
                    }
                }

                var rows = (List<SalesCustomer>)typeof(CustomerSupplierManagementForm).GetField("allCustomers", fields).GetValue(management);
                rows.Add(new SalesCustomer { CustomerId = "layout-test-customer", CustomerName = "عميل اختبار تخطيط", PhoneNumber = "777123456", Address = "عنوان اختبار", TotalSpent = 100m });
                TextBox searchInput = Require<TextBox>(management, "customerSearch");
                TextBox nameInput = Require<TextBox>(management, "customerName");
                AntdUI.Input phoneInput = Require<AntdUI.Input>(management, "customerPhone");
                TextBox addressInput = Require<TextBox>(management, "customerAddress");
                searchInput.Text = "عميل اختبار تخطيط";
                Require<AntdUI.Table>(management, "customerMasterTable").SelectedIndex = 1;
                if (nameInput.Text != "عميل اختبار تخطيط" || phoneInput.Text != "777123456" || addressInput.Text != "عنوان اختبار")
                    throw new InvalidOperationException("Customer editor did not load the selected master record.");
                searchInput.Text = "777123456";
                if (!string.IsNullOrEmpty(nameInput.Text) ||
                    !string.IsNullOrEmpty((string)typeof(CustomerSupplierManagementForm).GetField("editingCustomerId", fields).GetValue(management)))
                    throw new InvalidOperationException("Customer editor retained a previous record after a nonempty search result change.");
                searchInput.Text = "لا توجد نتيجة";
                string editingId = (string)typeof(CustomerSupplierManagementForm).GetField("editingCustomerId", fields).GetValue(management);
                if (!string.IsNullOrEmpty(editingId) || !string.IsNullOrEmpty(nameInput.Text) ||
                    !string.IsNullOrEmpty(phoneInput.Text) || !string.IsNullOrEmpty(addressInput.Text))
                    throw new InvalidOperationException("Customer editor retained stale personal data after an empty search.");
                management.ApplyPresentation(true);
                Prepare(management, new Size(760, 590));
                if (management.RightToLeft != RightToLeft.No || management.RightToLeftLayout ||
                    management.Text != "Customer management" ||
                    Require<Label>(management, "customerManagementTitle").TextAlign != ContentAlignment.MiddleLeft ||
                    Require<Label>(management, "customerNameFieldLabel").Text != "Customer name" ||
                    Require<AntdUI.Table>(management, "customerMasterTable").RightToLeft != RightToLeft.No ||
                    Require<FlowLayoutPanel>(management, "customerEditorActions").FlowDirection != FlowDirection.LeftToRight ||
                    Require<TextBox>(management, "customerSearch").TextAlign != HorizontalAlignment.Left)
                    throw new InvalidOperationException("Customer management English text or LTR layout failed.");
                management.ApplyPresentation(false);
                Prepare(management, new Size(760, 590));
                if (management.RightToLeft != RightToLeft.Yes || !management.RightToLeftLayout ||
                    Require<Label>(management, "customerNameFieldLabel").Text != "اسم العميل" ||
                    Require<AntdUI.Table>(management, "customerMasterTable").RightToLeft != RightToLeft.Yes)
                    throw new InvalidOperationException("Customer management did not restore Arabic RTL layout.");
            }
        }

        private static void VerifyActiveIngredientManagementLayout()
        {
            using (var form = new ActiveIngredientManagementForm(true))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(760, 640), new Size(960, 640), new Size(1240, 860) })
                {
                    Prepare(form, size);
                    Panel header = Require<Panel>(form, "activeIngredientHeader");
                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "activeIngredientFooter");
                    TableLayoutPanel body = Require<TableLayoutPanel>(form, "activeIngredientSections");
                    Label status = Require<Label>(form, "activeIngredientStatus");
                    foreach (string cardName in new[] { "ingredientDefinitionGroup", "ingredientEvidenceGroup", "ingredientMappingGroup" })
                    {
                        AntdUI.Panel card = Require<AntdUI.Panel>(form, cardName);
                        Label heading = Require<Label>(form, cardName + "Title");
                        if (card.Radius < 8 || heading.Parent != card || heading.Height < 28 ||
                            heading.ForeColor != UiTheme.Text)
                            throw new InvalidOperationException("Active ingredient AntdUI card title is inconsistent: " + cardName);
                    }
                    if (header.Top != 0 || header.Bottom != body.Top || body.Bottom != status.Top ||
                        status.Bottom != footer.Top || footer.Bottom > form.ClientSize.Height ||
                        footer.HorizontalScroll.Visible || body.HorizontalScroll.Visible ||
                        !status.Text.Contains("معاينة"))
                        throw new InvalidOperationException("Active ingredient shell clips or reaches data in preview at " + size + ".");
                    foreach (AntdUI.Button action in footer.Controls.OfType<AntdUI.Button>())
                        if (action.Height < 44 || action.DefaultBorderColor != UiTheme.Primary ||
                            action.Left < 0 || action.Right > footer.ClientSize.Width ||
                            action.Top < 0 || action.Bottom > footer.ClientSize.Height)
                            throw new InvalidOperationException("Active ingredient action is clipped: " + action.Name +
                                " at " + size + ": action=" + action.Bounds + ", footer=" + footer.Bounds + ".");
                    RequireHorizontallyInside(form, Require<Control>(form, "ingredientDefinitionGroup"), "المواد الفعالة/التعريف " + size);
                    RequireHorizontallyInside(form, Require<DataGridView>(form, "activeIngredientsGrid"), "المواد الفعالة/الجدول " + size);
                    RequireHorizontallyInside(form, Require<DataGridView>(form, "activeIngredientEvidenceGrid"), "المواد الفعالة/المصادر " + size);
                    RequireHorizontallyInside(form, Require<DataGridView>(form, "activeIngredientMappingsGrid"), "المواد الفعالة/الربط " + size);
                }
                form.ApplyPresentation(true);
                Prepare(form, new Size(760, 640));
                if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                    form.Text != "Active ingredients and evidence" ||
                    Require<Label>(form, "activeIngredientTitle").TextAlign != ContentAlignment.MiddleLeft ||
                    Require<Label>(form, "ingredientDefinitionGroupTitle").Text != "1. Ingredient" ||
                    Require<Label>(form, "activeIngredientArabicNameLabel").Text != "Arabic name" ||
                    Require<AntdUI.Button>(form, "activeIngredientAdd").Text != "Add ingredient" ||
                    Require<AntdUI.Button>(form, "activeIngredientAdd").AccessibleName != "Add ingredient and source" ||
                     Require<TextBox>(form, "activeIngredientArabicName").AccessibleName != "Arabic name of active ingredient" ||
                     Require<TextBox>(form, "activeIngredientLatinName").AccessibleName != "Latin name of active ingredient" ||
                     Require<TextBox>(form, "activeIngredientSourceTitle").AccessibleName != "Scientific reference title" ||
                     Require<TextBox>(form, "activeIngredientPublisher").AccessibleName != "Publisher" ||
                     Require<AntdUI.DatePicker>(form, "activeIngredientRetrievedOn").AccessibleName != "Optional access date" ||
                    Require<FlowLayoutPanel>(form, "activeIngredientFooter").FlowDirection != FlowDirection.LeftToRight ||
                    Require<DataGridView>(form, "activeIngredientsGrid").RightToLeft != RightToLeft.No ||
                    Require<DataGridView>(form, "activeIngredientsGrid").Columns[0].HeaderText != "Arabic name" ||
                    Require<ComboBox>(form, "activeIngredientMedicine").Items[0].ToString() != "Sample medicine" ||
                    Require<TextBox>(form, "activeIngredientLatinName").RightToLeft != RightToLeft.No ||
                    Require<AntdUI.DatePicker>(form, "activeIngredientRetrievedOn").RightToLeft != RightToLeft.No)
                    throw new InvalidOperationException("Active ingredient English text or physical LTR layout is incomplete.");
                var englishDate = Require<AntdUI.DatePicker>(form, "activeIngredientRetrievedOn");
                var buildEvidence = typeof(ActiveIngredientManagementForm).GetMethod("TryBuildEvidenceInput",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                englishDate.Text = "2026/02/30";
                if ((bool)buildEvidence.Invoke(form, new object[] { null }) ||
                    Require<Label>(form, "activeIngredientStatus").Text != "Invalid access date; correct or clear this optional field.")
                    throw new InvalidOperationException("Active ingredient invalid date was not explained in English.");
                englishDate.Text = string.Empty;
                form.ApplyPresentation(false);
                Prepare(form, new Size(760, 640));
                if (form.RightToLeft != RightToLeft.Yes || !form.RightToLeftLayout ||
                    Require<Label>(form, "activeIngredientTitle").TextAlign != ContentAlignment.MiddleRight ||
                    Require<Label>(form, "activeIngredientArabicNameLabel").Text != "الاسم العربي" ||
                    Require<FlowLayoutPanel>(form, "activeIngredientFooter").FlowDirection != FlowDirection.RightToLeft ||
                    Require<DataGridView>(form, "activeIngredientsGrid").RightToLeft != RightToLeft.Yes ||
                    Require<DataGridView>(form, "activeIngredientsGrid").Columns[0].HeaderText != "الاسم العربي")
                    throw new InvalidOperationException("Active ingredient Arabic RTL layout did not restore after LTR simulation.");
                if (form.FormBorderStyle != FormBorderStyle.Sizable || !form.MaximizeBox || !form.MinimizeBox)
                    throw new InvalidOperationException("شاشة المواد الفعالة يجب أن تدعم التكبير والتصغير.");
                TextBox arabic = FindControlByAccessibleName<TextBox>(form, "الاسم العربي للمادة الفعالة");
                TextBox strength = FindControlByAccessibleName<TextBox>(form, "تركيز المادة الفعالة");
                AntdUI.DatePicker retrievedOn = Require<AntdUI.DatePicker>(form, "activeIngredientRetrievedOn");
                if (arabic == null || strength == null || retrievedOn.Value.HasValue || !retrievedOn.AllowClear)
                    throw new InvalidOperationException("شاشة المواد الفعالة تفتقد أسماء الوصول للحقول الحرجة.");
                object[] evidenceArgs = { null };
                if (!(bool)buildEvidence.Invoke(form, evidenceArgs) ||
                    ((PharmacyManagement.Application.ActiveIngredientEvidenceInput)evidenceArgs[0]).RetrievedOn.HasValue)
                    throw new InvalidOperationException("Optional ingredient evidence date was not left empty.");
                retrievedOn.Text = "2026/02/30";
                if ((bool)buildEvidence.Invoke(form, new object[] { null }))
                    throw new InvalidOperationException("Invalid ingredient evidence date reached the save service.");
                retrievedOn.Text = "2026/09/23";
                evidenceArgs[0] = null;
                if (!(bool)buildEvidence.Invoke(form, evidenceArgs) ||
                    ((PharmacyManagement.Application.ActiveIngredientEvidenceInput)evidenceArgs[0]).RetrievedOn != new DateTime(2026, 9, 23))
                    throw new InvalidOperationException("Visible ingredient evidence date was not preserved.");
                retrievedOn.Text = string.Empty;
                Label previewStatus = Require<Label>(form, "activeIngredientStatus");
                string statusBeforeGuard = previewStatus.Text;
                typeof(ActiveIngredientManagementForm).GetMethod("AddIngredient", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (previewStatus.Text != statusBeforeGuard)
                    throw new InvalidOperationException("Active ingredient preview reached a write operation.");
            }
        }

        public static void VerifyCustomerRecoveryOnly()
        {
            VerifyCustomerSupplierManagementLayout();
