        private static void VerifyCustomerSaveRecovery()
        {
            string originalTheme = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    SessionContext.Start("customer-recovery-test", "Manager");
                    var service = new CustomerRecoveryService();
                    using (var form = new CustomerSupplierManagementForm(false, false, english, service))
                    {
                        Prepare(form, new Size(960, 640));
                        Require<TextBox>(form, "customerName").Text = "مُستَلزمات Pharma 500 mg";
                        Require<AntdUI.Input>(form, "customerPhone").Text = "077123";
                        Require<TextBox>(form, "customerAddress").Text = "صنعاء - Main 12";
                        service.FailRead = true;
                        ((System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("SaveCustomer", flags).Invoke(form, null)).GetAwaiter().GetResult();
                        var status = Require<Label>(form, "customerManagementStatus");
                        string expected = english ? "Customer saved, but the list could not be refreshed. Retry loading the list." :
                            "تم حفظ العميل، لكن تعذر تحديث القائمة. أعد تحميل القائمة.";
                        if (status.Text != expected || service.Creates != 1 || service.Updates != 0 ||
                            Require<TextBox>(form, "customerName").Text != "مُستَلزمات Pharma 500 mg" ||
                            Require<AntdUI.Input>(form, "customerPhone").Text != "077123")
                            throw new InvalidOperationException("Customer save/read failure lost the committed identity, input or truthful status.");
                        ((System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("SaveCustomer", flags).Invoke(form, null)).GetAwaiter().GetResult();
                        if (service.Creates != 1 || service.Updates != 1 || service.Last.CustomerId != "C-RECOVERY")
                            throw new InvalidOperationException("Customer retry created another record after a committed save.");
                        service.FailRead = false;
                        Require<TextBox>(form, "customerAddress").Text = "مسودة عنوان Draft 12";
                        ((System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("ReloadCustomerList", flags).Invoke(form, null)).GetAwaiter().GetResult();
                        if (Require<TextBox>(form, "customerAddress").Text != "مسودة عنوان Draft 12")
                            throw new InvalidOperationException("Customer list refresh erased an unsaved editor draft.");
                        ((System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("SaveCustomer", flags).Invoke(form, null)).GetAwaiter().GetResult();
                        if (service.Creates != 1 || service.Updates != 2 || service.Last.Address != "مسودة عنوان Draft 12")
                            throw new InvalidOperationException("Customer recovered save lost its original identity or edited address.");
                        var rows = (List<SalesCustomer>)typeof(CustomerSupplierManagementForm).GetField("visibleCustomers", flags).GetValue(form);
                        if (rows.Count != 1 || rows[0].CustomerName != "مُستَلزمات Pharma 500 mg")
                            throw new InvalidOperationException("Customer refresh did not recover the saved Arabic record.");
                    }
                    service.FailRead = false;
                    using (var chooser = new CustomerSupplierManagementForm(true, false, english, service))
                    {
                        Prepare(chooser, new Size(960, 640));
                        ((System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("LoadCustomers", flags).Invoke(chooser, new object[] { "C-RECOVERY" })).GetAwaiter().GetResult();
                        Require<AntdUI.Table>(chooser, "customerMasterTable").SelectedIndex = 1;
                        typeof(CustomerSupplierManagementForm).GetMethod("LoadSelectedCustomer", flags).Invoke(chooser, null);
                        service.FailRead = true;
                        ((System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("LoadCustomers", flags).Invoke(chooser, new object[] { null })).GetAwaiter().GetResult();
                        Require<TextBox>(chooser, "customerSearch").Text = "Pharma";
                        var rows = (List<SalesCustomer>)typeof(CustomerSupplierManagementForm).GetField("visibleCustomers", flags).GetValue(chooser);
                        if (chooser.SelectedCustomer != null || Require<AntdUI.Button>(chooser, "chooseCustomer").Enabled || rows.Count != 0)
                            throw new InvalidOperationException("Failed customer read revived a stale selectable customer.");
                    }
                }
            }
            finally { SessionContext.Clear(); Properties.Setings.Default.ThemeMode = originalTheme; }
        }


        private static void VerifyCustomerSessionRevisions()
        {
            string theme=Properties.Setings.Default.ThemeMode;
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach(string mode in new[]{"Light","Dark"}) foreach(bool english in new[]{false,true}) foreach(bool selection in new[]{false,true})
                {
                    Properties.Setings.Default.ThemeMode=mode;SessionContext.Start("customer-revision","Manager","CUSTOMER-E");
                    var service=new PendingCustomerService();
                    using(var form=new CustomerSupplierManagementForm(selection,false,english,service))
                    {
                        Prepare(form,new Size(960,640));IntPtr handle=form.Handle;
                        Func<System.Threading.Tasks.Task> load=()=>(System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("LoadCustomers",flags).Invoke(form,new object[]{null});
                        var visible=(List<SalesCustomer>)typeof(CustomerSupplierManagementForm).GetField("visibleCustomers",flags).GetValue(form);
                        var table=Require<AntdUI.Table>(form,"customerMasterTable");
                        var pending=load();SessionContext.Clear();SessionContext.Start("customer-revision","Manager","CUSTOMER-E");
                        service.Pending[0].SetResult(new[]{new SalesCustomer{CustomerId="OLD",CustomerName="جلسة قديمة Pharma 500 mg"}});FinishMovementRead(pending);
                        if(visible.Count!=0||form.SelectedCustomer!=null)throw new Exception("Customer directory accepted a prior login of the same user.");
                        var fresh=load();service.Pending[1].SetResult(new[]{new SalesCustomer{CustomerId="NEW",CustomerName="جديد Pharma 500 mg",PhoneNumber="000777"}});FinishMovementRead(fresh);
                        if(visible.Count!=1||visible[0].CustomerId!="NEW")throw new Exception("Customer directory failed to recover in the new login.");
                        table.SelectedIndex=1;
                        SessionContext.Clear();SessionContext.Start("customer-revision","Manager","CUSTOMER-E");
                        typeof(CustomerSupplierManagementForm).GetMethod(selection?"ChooseSelectedCustomer":"LoadSelectedCustomer",flags).Invoke(form,null);
                        if(form.DialogResult==DialogResult.OK||form.SelectedCustomer!=null||visible.Count!=0||((TextBox)typeof(CustomerSupplierManagementForm).GetField("name",flags).GetValue(form)).Text.Length!=0)
                            throw new Exception("Loaded customer selection or editor survived an old login.");
                        var retry=load();service.Pending[2].SetResult(new[]{new SalesCustomer{CustomerId="RECOVERED",CustomerName="استعادة Pharma 500 mg"}});FinishMovementRead(retry);
                        if(visible.Count!=1||visible[0].CustomerId!="RECOVERED"||!Require<TextBox>(form,"customerSearch").Enabled)
                            throw new Exception("Customer selection rejection blocked explicit reload.");

                        if(!selection)
                        {
                            table.SelectedIndex=1;
                            Require<TextBox>(form,"customerName").Text="مسودة جلسة سابقة Pharma 500 mg";
                            SessionContext.Clear();SessionContext.Start("customer-revision","Manager","CUSTOMER-E");
                            var reload=(System.Threading.Tasks.Task)typeof(CustomerSupplierManagementForm).GetMethod("ReloadCustomerList",flags).Invoke(form,null);
                            service.Pending[3].SetResult(new[]{new SalesCustomer{CustomerId="CURRENT",CustomerName="بيانات الجلسة الجديدة"}});FinishMovementRead(reload);
                            if(Require<TextBox>(form,"customerName").Text.Length!=0||visible.Count!=1||visible[0].CustomerId!="CURRENT"||
                                Convert.ToString(typeof(CustomerSupplierManagementForm).GetField("editingCustomerId",flags).GetValue(form)).Length!=0)
                                throw new Exception("Customer reload restored an editor draft from a previous login.");
                        }

                    }
                }
            }
            finally{SessionContext.Clear();Properties.Setings.Default.ThemeMode=theme;}
            Console.WriteLine("PASS customer same-user login revision: pending and loaded selection/editor rejected; explicit reload recovers; management/selection, both themes/languages; controlled providers, no SQL/native keys.");
        }

        private static void VerifyCustomerAsyncReads()
        {
            VerifyCustomerSessionRevisions();
            string originalTheme = Properties.Setings.Default.ThemeMode;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    SessionContext.Start("customer-async", "Manager", "E-ASYNC");
                    var service = new PendingCustomerService();
                    using (var form = new CustomerSupplierManagementForm(false, false, english, service))
                    {
                        Prepare(form, new Size(960, 640));
                        IntPtr windowHandle = form.Handle;
                        Func<System.Threading.Tasks.Task> load = () => (System.Threading.Tasks.Task)
                            typeof(CustomerSupplierManagementForm).GetMethod("LoadCustomers", flags).Invoke(form, new object[] { null });
                        var first = load();
                        if (first.IsCompleted || Require<AntdUI.Button>(form, "saveCustomer").Enabled ||
                            Require<AntdUI.Button>(form, "chooseCustomer").Enabled)
                            throw new Exception("Pending customer read blocks UI or allows stale actions.");
                        bool pumped = false; form.BeginInvoke(new Action(() => pumped = true)); Application.DoEvents();
                        if (!pumped) throw new Exception("Pending customer read blocks the message loop.");
                        var second = load();
                        if (!service.Tokens[0].IsCancellationRequested) throw new Exception("New customer read did not cancel the old request.");
                        service.Pending[1].SetResult(new[] { new SalesCustomer { CustomerId = "C-NEW", CustomerName = "حديث Pharma 500 mg" } });
                        FinishMovementRead(second);
                        service.Pending[0].SetResult(new[] { new SalesCustomer { CustomerId = "C-OLD", CustomerName = "قديم" } });
                        FinishMovementRead(first);
                        var rows = (List<SalesCustomer>)typeof(CustomerSupplierManagementForm).GetField("visibleCustomers", flags).GetValue(form);
                        if (rows.Count != 1 || rows[0].CustomerId != "C-NEW") throw new Exception("Late customer response replaced the current list.");
                        var failure = load(); service.Pending[2].SetException(new InvalidOperationException("Read failure")); FinishMovementRead(failure);
                        Require<TextBox>(form, "customerSearch").Text = "Pharma";
                        if (rows.Count != 0 || form.SelectedCustomer != null) throw new Exception("Failed read revived stale customer data.");
                        var retry = load(); service.Pending[3].SetResult(new SalesCustomer[0]); FinishMovementRead(retry);
                        if (rows.Count != 0 || !Require<AntdUI.Button>(form, "saveCustomer").Enabled) throw new Exception("Empty customer retry did not recover editor access.");
                        Require<TextBox>(form, "customerSearch").Text = string.Empty;
                        Require<TextBox>(form, "customerName").Text = "بيانات الجلسة السابقة";
                        Require<TextBox>(form, "customerAddress").Text = "عنوان حساس";
                        var contextRead = load(); SessionContext.Start("another-user", "Manager", "E-OTHER");
                        if (!service.Tokens[4].IsCancellationRequested ||
                            Require<TextBox>(form, "customerName").Text.Length != 0 ||
                            Require<TextBox>(form, "customerAddress").Text.Length != 0 ||
                            Require<AntdUI.Button>(form, "saveCustomer").Enabled)
                            throw new Exception("Session notification retained customer draft or pending read before completion.");
                        service.Pending[4].SetResult(new[] { new SalesCustomer { CustomerId = "PRIVATE", CustomerName = "Previous session" } });
                        FinishMovementRead(contextRead);
                        if (rows.Count != 0 || Require<TextBox>(form, "customerName").Text.Length != 0) throw new Exception("User change exposed previous-session customer data.");
                        SessionContext.Start("customer-async", "Manager", "E-ASYNC");
                        var closing = load(); form.Dispose();
                        if (!service.Tokens[5].IsCancellationRequested) throw new Exception("Disposing customer form did not cancel SQL read.");
                        service.Pending[5].SetResult(new SalesCustomer[0]); FinishMovementRead(closing);
                    }
                }
            }
            finally { SessionContext.Clear(); Properties.Setings.Default.ThemeMode = originalTheme; }
            Console.WriteLine("PASS customer async message loop, cancellation, late response, failure/retry, session change and disposal; no SQL.");
        }

        private sealed class PendingCustomerService : CustomerRecoveryService
        {
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<SalesCustomer>>> Pending =
                new List<System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<SalesCustomer>>>();
            internal readonly List<System.Threading.CancellationToken> Tokens = new List<System.Threading.CancellationToken>();
            public override System.Threading.Tasks.Task<IReadOnlyList<SalesCustomer>> GetAllAsync(OperationActor actor, System.Threading.CancellationToken token)
            {
                var completion = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<SalesCustomer>>();
                Pending.Add(completion); Tokens.Add(token); return completion.Task;
            }
        }

        private class CustomerRecoveryService : ISalesCustomerService
        {
            internal bool FailRead;
            internal int Creates, Updates;
            internal SalesCustomer Last;
            public virtual System.Threading.Tasks.Task<IReadOnlyList<SalesCustomer>> GetAllAsync(OperationActor actor, System.Threading.CancellationToken token)
            {
                token.ThrowIfCancellationRequested();
                return System.Threading.Tasks.Task.FromResult(GetAll());
            }
            public IReadOnlyList<SalesCustomer> GetAll()
            {
                if (FailRead) throw new InvalidOperationException("Simulated read failure");
                return Last == null ? new SalesCustomer[0] : new[] { Last };
            }
            public string Create(SalesCustomer customer, OperationActor actor)
            {
                Creates++; customer.CustomerId = "C-RECOVERY"; Last = customer; return customer.CustomerId;
            }
            public bool Update(SalesCustomer customer, OperationActor actor) { Updates++; Last = customer; return true; }
            public IReadOnlyList<string> GetCustomerNames() => new string[0];
            public IReadOnlyList<string> GetPhoneNumbers() => new string[0];
            public SalesCustomer FindById(string value) => Last;
            public SalesCustomer FindByName(string value) => Last;
            public SalesCustomer FindByPhone(string value) => Last;
        }

        public static void SaveCustomerPreviews(string directory)
        {
