        private static void VerifyPharmacyCompanyInputDirection()
        {
            using (var form = new PharmacyCompanyPreview())
            {
                foreach (Size size in new[] { new Size(760, 600), new Size(1000, 700), new Size(1366, 768) })
                {
                    if (size.Width == 760)
                    {
                        form.Show();
                        Application.DoEvents();
                    }
                    Prepare(form, size);
                    Application.DoEvents();
                    if (size.Width == 760)
                        using (var bitmap = new Bitmap(form.Width, form.Height))
                            form.DrawToBitmap(bitmap, new Rectangle(Point.Empty, bitmap.Size));
                    Panel surface = Require<Panel>(form, "profileSurface");
                    AntdUI.Panel identity = Require<AntdUI.Panel>(surface, "profileIdentityCard");
                    AntdUI.Panel contact = Require<AntdUI.Panel>(surface, "profileContactCard");
                    Panel toolbar = Require<Panel>(form, "panelToolbar");
                    Panel content = Require<Panel>(form, "panelContent");
                    if (form.Text != "بيانات الصيدلية" || Require<Label>(form, "lblTitle").Text != "بيانات الصيدلية")
                        throw new InvalidOperationException("Pharmacy profile title includes an obsolete system/company suffix.");
                    if (toolbar.BackColor != UiTheme.Surface || content.HorizontalScroll.Visible)
                        throw new InvalidOperationException("Pharmacy profile has a colored action strip or unnecessary horizontal scrolling at " + size +
                            "; viewport=" + content.ClientSize + ", display=" + content.DisplayRectangle + ", surface=" + surface.Bounds + ".");
                    if (toolbar.Bottom != form.ClientSize.Height || identity.Bounds.IntersectsWith(contact.Bounds))
                        throw new InvalidOperationException("Pharmacy profile cards or fixed actions overlap at " + size + ".");
                    foreach (string actionName in new[] { "btnToolAdd", "btnToolSave", "btnToolPrint", "btnToolHelp", "btnToolExit" })
                    {
                        AntdUI.Button action = Require<AntdUI.Button>(toolbar, actionName);
                        if (action.BorderWidth != 1 || action.DefaultBorderColor != UiTheme.Primary ||
                            action.IconPosition != AntdUI.TAlignMini.Right ||
                            action.IconSize.Width != 18 || action.Font.SizeInPoints < 9F)
                            throw new InvalidOperationException("Pharmacy profile footer action has lost its readable outlined style: " + actionName);
                    }
                    AntdUI.Button firstFooterAction = Require<AntdUI.Button>(toolbar, "btnToolAdd");
                    AntdUI.Button lastFooterAction = Require<AntdUI.Button>(toolbar, "btnToolExit");
                    if (firstFooterAction.Left <= lastFooterAction.Left)
                        throw new InvalidOperationException("Pharmacy profile footer does not begin at the language leading edge at " + size + ".");
                    if (size.Width < 1180 && (identity.Bottom >= contact.Top || !Require<Panel>(form, "panelContent").AutoScroll))
                        throw new InvalidOperationException("Pharmacy profile must stack and scroll at " + size + ".");
                    if (size.Width >= 1180 && identity.Left <= contact.Left)
                        throw new InvalidOperationException("Pharmacy profile identity card is on the wrong leading side at " + size + ".");
                    RequireInside(identity, Require<TextBox>(form, "txtNameAr"), "pharmacy Arabic name " + size);
                    RequireInside(contact, Require<AntdUI.Input>(form, "txtEmail"), "pharmacy email " + size);
                }
                TextBox arabic = Require<TextBox>(form, "txtNameAr");
                AntdUI.Input english = Require<AntdUI.Input>(form, "txtNameEn");
                AntdUI.Input email = Require<AntdUI.Input>(form, "txtEmail");
                if (arabic.Parent.Left <= english.Left)
                    throw new InvalidOperationException("Pharmacy profile language fields are not ordered from the leading edge.");
                if (arabic.RightToLeft != RightToLeft.Yes || arabic.TextAlign != HorizontalAlignment.Right ||
                    english.RightToLeft != RightToLeft.No || english.TextAlign != HorizontalAlignment.Left ||
                    email.RightToLeft != RightToLeft.No || email.TextAlign != HorizontalAlignment.Left)
                    throw new InvalidOperationException("Pharmacy company text fields do not preserve Arabic and LTR input direction.");
                arabic.Text = "صيدلية المهندس — Pharma 500 mg";
                english.Text = "Engineer Pharmacy";
                Require<TextBox>(form, "txtInvoiceNotes").Text = "سطر أول\nSecond line";
                PharmacyProfile profile = (PharmacyProfile)typeof(PharmacyCompanyForm)
                    .GetMethod("ReadFromForm", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    .Invoke(form, null);
                if (profile.NameAr != arabic.Text || profile.NameEn != english.Text ||
                    profile.InvoiceNotes != "سطر أول\nSecond line")
                    throw new InvalidOperationException("Pharmacy profile AntdUI fields changed saved Arabic or multiline text.");
            }

            using (var form = new PharmacyCompanyForm(true, true))
            {
                form.Show();
                Prepare(form, new Size(1366, 768));
                Application.DoEvents();
                AntdUI.Panel identity = Require<AntdUI.Panel>(form, "profileIdentityCard");
                AntdUI.Panel contact = Require<AntdUI.Panel>(form, "profileContactCard");
                AntdUI.Button save = Require<AntdUI.Button>(form, "btnToolSave");
                AntdUI.Button add = Require<AntdUI.Button>(form, "btnToolAdd");
                AntdUI.Button exit = Require<AntdUI.Button>(form, "btnToolExit");
                if (form.Text != "Pharmacy profile" || Require<Label>(form, "lblTitle").Text != "Pharmacy profile" ||
                    Require<Label>(form, "profileIdentityHeading").Text != "Identity and registration" ||
                    Require<Label>(form, "lblNameEn").Text != "English name" ||
                    save.Text != "Save" || save.Enabled || save.AccessibleName != "Save pharmacy profile")
                    throw new InvalidOperationException("Pharmacy profile English preview is incomplete or permits persistence.");
                if (identity.Left >= contact.Left || add.Left >= exit.Left || save.IconPosition != AntdUI.TAlignMini.Left)
                    throw new InvalidOperationException("Pharmacy profile English layout does not start at the left leading edge.");
                TextBox arabic = Require<TextBox>(form, "txtNameAr");
                AntdUI.Input english = Require<AntdUI.Input>(form, "txtNameEn");
                if (arabic.RightToLeft != RightToLeft.Yes || arabic.TextAlign != HorizontalAlignment.Right ||
                    english.RightToLeft != RightToLeft.No || english.TextAlign != HorizontalAlignment.Left ||
                    arabic.Text != "صيدلية المهندس" || english.Text != "Engineer Pharmacy")
                    throw new InvalidOperationException("Pharmacy profile preview changed field direction or fixture values.");
            }
        }

        private static void VerifyOperationalReportDateValidation()
        {
            DateTime today = DateTime.Today;
            if (!OperationalReportCatalog.IsValidDateRange(today, today) ||
                !OperationalReportCatalog.IsValidDateRange(today, today.AddDays(1)) ||
                OperationalReportCatalog.IsValidDateRange(today, today.AddDays(-1)))
                throw new InvalidOperationException("Operational report date validation accepts an invalid period.");
        }

        private static void VerifyInventoryReportInputValidation()
        {
            using (var form = new InventoryDataFormProbe())
            using (var value = new TextBox { Text = "0" })
            {
                if (!form.IsDateRangeAccepted(DateTime.Today, DateTime.Today) ||
                    form.IsDateRangeAccepted(DateTime.Today, DateTime.Today.AddDays(-1)))
                    throw new InvalidOperationException("Inventory report date-range validation accepts an invalid interval.");

                if (form.ParseNonNegative(value, "حد الاختبار") != 0)
                    throw new InvalidOperationException("Inventory report non-negative parser changed a valid zero value.");

                value.Text = "-1";
                bool rejected = false;
                try
                {
                    form.ParseNonNegative(value, "حد الاختبار");
                }
                catch (InvalidOperationException)
                {
                    rejected = true;
                }

                if (!rejected)
                    throw new InvalidOperationException("Inventory report non-negative parser accepted a negative value.");

                using (var antInput = new AntdUI.Input { Text = "30" })
                {
                    if (form.ParseNonNegative(antInput, "أيام الركود") != 30)
                        throw new InvalidOperationException("Inventory report parser changed an AntdUI numeric input.");
                    antInput.Text = "-1";
                    bool antRejected = false;
                    try { form.ParseNonNegative(antInput, "أيام الركود"); }
                    catch (InvalidOperationException) { antRejected = true; }
                    if (!antRejected)
                        throw new InvalidOperationException("Inventory report parser accepted a negative AntdUI input.");
                }

                if (!InventoryOperationForm.IsLocallyValidQuantity(InventoryOperationMode.OpeningStock, 0) ||
                    InventoryOperationForm.IsLocallyValidQuantity(InventoryOperationMode.Adjustment, -1) ||
                    !InventoryOperationForm.IsLocallyValidQuantity(InventoryOperationMode.Receipt, 1) ||
                    InventoryOperationForm.IsLocallyValidQuantity(InventoryOperationMode.Receipt, 0) ||
                    InventoryOperationForm.IsLocallyValidQuantity(InventoryOperationMode.Issue, -1))
                    throw new InvalidOperationException("Inventory operation input validation does not preserve the operation quantity rules.");
            }
        }

