        private sealed class InventoryContextProbe : PharmacyManagement.Application.IInventoryPostService
        {
            internal int Calls;
            internal Action OnPost;
            public PharmacyManagement.Application.InventoryPostResult Post(PharmacyManagement.Application.InventoryPostRequest request, PharmacyManagement.Application.OperationActor actor)
            {
                if(actor.UserName != "original-user" || actor.UserRole != "original-role")
                    throw new Exception("Inventory context lost its captured actor.");
                Calls++;
                actor.UserName="mutated-collaborator";
                OnPost?.Invoke();
                return new PharmacyManagement.Application.InventoryPostResult(request.SourceId, 2, 5, 3, Calls > 1);
            }
        }

