                table.Rows.Add(2000000000m,0m,2000000000m,1.25m,2.50m);table.Rows.Add(2000000000m,0m,2000000000m,1.25m,2.50m);form.PresentMovementTable(table);
                values=summary.Controls.Cast<Control>().SelectMany(card=>card.Controls.Cast<Control>()).OfType<Label>().Where(label=>label.Name=="inventoryMetricValue").Select(label=>label.Text).ToArray();
                if(values[1]!=(4000000002.25m).ToString("#,##0.###")||values[3]!=(4000000000.5m).ToString("#,##0.###"))throw new Exception("Movement totals retain Int32 overflow limit.");
            }
            }
