        private static void VerifyInventoryAsyncScreen()
        {
            using(var form=new InventoryOperationForm(InventoryOperationMode.Receipt,false))
            {
                form.Show();Application.DoEvents();
                var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
                var type=typeof(InventoryOperationForm);var reader=new InventoryScreenReadProbe();bool context=true;
                var session=new InventoryPostingSession(new InventoryContextProbe(),new OperationActor {UserName="original-user",UserRole="original-role"},()=>context,null,reader);
                type.GetField("pendingInventorySession",flags).SetValue(form,session);
                type.GetField("inventoryAsyncReads",flags).SetValue(form,true);
                var medicines=new DataTable();medicines.Columns.Add("MedName");medicines.Columns.Add("DisplayName");medicines.Columns.Add("MedQty",typeof(int));
                medicines.Rows.Add("A","الصنف الأول",10);medicines.Rows.Add("B","باراسيتامول 500 mg",20);
                type.GetMethod("SetMedicineOptions",flags).Invoke(form,new object[]{medicines});
                var selector=Require<ComboBox>(form,"inventoryOperationMedicine");selector.SelectedValue="A";
                var first=form.RefreshInventorySnapshotAsync(false);
                if(first.IsCompleted||Require<AntdUI.Button>(form,"inventoryOperationCommit").Enabled)throw new Exception("Read blocks UI or allows commit before balance.");
                bool processed=false;form.BeginInvoke(new Action(()=>processed=true));Application.DoEvents();if(!processed)throw new Exception("Pending read blocks message loop.");
                selector.SelectedValue="B";var second=form.RefreshInventorySnapshotAsync(false);
                if(!reader.Tokens["A"].IsCancellationRequested)throw new Exception("Previous read is not cancelled.");
                reader.Pending["B"].SetResult(new InventoryOperationReadSnapshot("B",20,new List<InventoryMovementReadRow>()));
                while(!second.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(1);}second.GetAwaiter().GetResult();
                reader.Pending["A"].SetResult(new InventoryOperationReadSnapshot("A",99,new List<InventoryMovementReadRow>()));
                while(!first.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(1);}first.GetAwaiter().GetResult();
                if((int)type.GetField("currentValue",flags).GetValue(form)!=20)throw new Exception("Obsolete response replaced current medicine balance.");
                var failed=form.RefreshInventorySnapshotAsync(false);
                var summary=Require<FlowLayoutPanel>(form,"inventoryDataSummary");
                if((int)type.GetField("currentValue",flags).GetValue(form)!=0||
                    summary.Controls.Cast<Control>().SelectMany(card=>card.Controls.Cast<Control>()).Any(control=>control.Text=="20"))
                    throw new Exception("Pending read exposes the previous stock summary.");
                reader.Pending["B"].SetException(new InvalidOperationException("Simulated read failure"));
                while(!failed.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(1);}failed.GetAwaiter().GetResult();
                if(Require<AntdUI.Button>(form,"inventoryOperationCommit").Enabled||(bool)type.GetField("inventoryReadReady",flags).GetValue(form))
                    throw new Exception("Failed balance read enables commit.");
                var retried=form.RefreshInventorySnapshotAsync(false);
                reader.Pending["B"].SetResult(new InventoryOperationReadSnapshot("B",20,new List<InventoryMovementReadRow>()));
                while(!retried.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(1);}retried.GetAwaiter().GetResult();
                if(!Require<AntdUI.Button>(form,"inventoryOperationCommit").Enabled||(int)type.GetField("currentValue",flags).GetValue(form)!=20)
                    throw new Exception("Successful balance retry does not restore availability.");
                if(Require<Label>(form,"inventoryDataStatus").Text.Contains("تعذر")||!string.IsNullOrEmpty(Require<Label>(form,"inventoryDataStatus").AccessibleDescription))throw new Exception("Successful read retry leaves a stale failure message.");
                var changed=form.RefreshInventorySnapshotAsync(false);context=false;
                reader.Pending["B"].SetResult(new InventoryOperationReadSnapshot("B",88,new List<InventoryMovementReadRow>()));
                while(!changed.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(1);}changed.GetAwaiter().GetResult();
                if(Require<AntdUI.Button>(form,"inventoryOperationCommit").Enabled||(bool)type.GetField("inventoryReadReady",flags).GetValue(form))throw new Exception("Changed context allowed commit.");
                context=true;var closing=form.RefreshInventorySnapshotAsync(false);form.Dispose();
                if(!reader.Tokens["B"].IsCancellationRequested)throw new Exception("Disposed screen kept read active.");
                reader.Pending["B"].SetResult(new InventoryOperationReadSnapshot("B",77,new List<InventoryMovementReadRow>()));
                while(!closing.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(1);}closing.GetAwaiter().GetResult();
            }
            var row=new InventoryMovementReadRow(DateTime.Today,"باراسيتامول 500 mg",null,null,-2,null,8,1.25m,null,null,"ملاحظة عربية");
            var table=InventoryOperationForm.InventoryMovementTable(new InventoryOperationReadSnapshot("باراسيتامول 500 mg",8,new List<InventoryMovementReadRow>{row}));
            if(table.Columns.Count!=13||(decimal)table.Rows[0][5]!=2||table.Rows[0][2]!=DBNull.Value||table.Rows[0][7]!=DBNull.Value||(string)table.Rows[0][12]!="ملاحظة عربية")throw new Exception("Typed movement display lost quantity/null/Arabic.");
            Console.WriteLine("PASS async inventory screen: message loop, cancellation, out-of-order result, changed context, dispose and Arabic/null projection; no SQL.");
        }

        private sealed class InventorySessionReadProbe : IInventoryOperationReadService
        {
            internal int Calls;
            internal System.Threading.CancellationToken Token;
            internal Func<System.Threading.Tasks.Task<System.Collections.Generic.IReadOnlyList<InventoryMedicineLookupRow>>> Lookup;
            public System.Threading.Tasks.Task<System.Collections.Generic.IReadOnlyList<InventoryMedicineLookupRow>> LoadMedicinesAsync(OperationActor actor,System.Threading.CancellationToken cancellation)
            {
                if(actor.UserName!="original-user")throw new Exception("Read session lost its captured actor.");
                Calls++;Token=cancellation;actor.UserName="mutated-reader";return Lookup();
            }
            public System.Threading.Tasks.Task<InventoryOperationReadSnapshot> LoadSnapshotAsync(InventoryOperationReadRequest request,OperationActor actor,System.Threading.CancellationToken cancellation)
            {
                if(actor.UserName!="original-user")throw new Exception("Snapshot session lost its captured actor.");
                Calls++;Token=cancellation;return System.Threading.Tasks.Task.FromResult(new InventoryOperationReadSnapshot(request.MedicineName,3,new List<InventoryMovementReadRow>()));
            }
        }
        private static void VerifyInventoryReadSession()
        {
            bool matches=true;var reader=new InventorySessionReadProbe();
            reader.Lookup=()=>System.Threading.Tasks.Task.FromResult((System.Collections.Generic.IReadOnlyList<InventoryMedicineLookupRow>)new List<InventoryMedicineLookupRow>());
            var actor=new OperationActor {UserName="original-user",UserRole="original-role"};
            var session=new InventoryPostingSession(new InventoryContextProbe(),actor,()=>matches,null,reader);
            actor.UserName="changed-caller";
            session.LoadMedicinesAsync(System.Threading.CancellationToken.None).GetAwaiter().GetResult();
