            reader.Lookup=()=>completion.Task;
            var task=session.LoadMedicinesAsync(System.Threading.CancellationToken.None);matches=false;
            completion.SetResult(new List<InventoryMedicineLookupRow>());denied=false;
            try{task.GetAwaiter().GetResult();}catch(InvalidOperationException){denied=true;}
            if(!denied||reader.Calls!=3)throw new Exception("Changed context published completed read results.");
            using(var cancellation=new System.Threading.CancellationTokenSource())
            {
                cancellation.Cancel();bool cancelled=false;
                try{session.LoadMedicinesAsync(cancellation.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}
