                using(var prior=new InventoryPendingStore(directory,key,request.Kind))prior.Save(request);
                string path=System.IO.Path.Combine(directory,key+"-2.xml");bool contextMatches=true;
                var probe=new InventoryContextProbe();
                using(var form=new InventoryOperationForm(InventoryOperationMode.Receipt,false))
