                    if(scenario!=3)medicines.Rows.Add(request.MedicineName,request.MedicineName);
                    var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
                    typeof(InventoryOperationForm).GetMethod("SetMedicineOptions",flags).Invoke(form,new object[]{medicines});
                    form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();UiTheme.Apply(form);
                    var store=new InventoryPendingStore(directory,key,request.Kind);
                    form.AttachInventoryRecovery(store,new InventoryPostingSession(probe,new OperationActor {UserName="original-user",UserRole="original-role"},()=>contextMatches,key));
                    if(scenario==3)
