                        if(Require<AntdUI.Button>(form,"inventoryOperationCommit").Enabled||probe.Calls!=0||!Require<Label>(form,"inventoryDataStatus").AccessibleDescription.Contains(request.MedicineName))
                            throw new Exception("Unavailable recovered medicine allowed posting or lost its diagnostic identity.");
                        continue;
                    }
                    if(scenario<2)
                    {
                        if(scenario==0)contextMatches=false;else System.IO.File.WriteAllText(path,"<broken>");
                        bool rejected=false;
                        try{form.PostInventorySubmissionAsync(request).GetAwaiter().GetResult();}
                        catch(Exception error)
                        {
                            if(!(error is InvalidOperationException)&&!(error is System.Xml.XmlException)&&!(error is System.IO.InvalidDataException))throw;
                            rejected=true;form.HandleInventoryWriteIssue(error);
                        }
                        if(!rejected||probe.Calls!=0||typeof(InventoryOperationForm).GetField("pendingInventoryRequest",flags).GetValue(form)==null)
                            throw new Exception("Recovery/context failure submitted or discarded its pending request.");
                        if(scenario==1)
                        {
                            form.HandleInventoryWriteIssue(new InventoryPostNotCommittedException(request.SourceId,"known rejection",new Exception()));
                            if(!Require<Label>(form,"inventoryDataStatus").Text.Contains("رفض الحفظ مؤكد")||typeof(InventoryOperationForm).GetField("pendingInventoryRequest",flags).GetValue(form)==null)
                                throw new Exception("Failed rejection cleanup discarded pending recovery state.");
                        }
                        continue;
                    }
                    probe.OnPost=()=>System.IO.File.WriteAllText(path,"<broken>");
                    var cleanup=typeof(InventoryOperationForm).GetMethod("PrepareNextInventoryDraft",flags);
                    var task=form.RunInventoryWriteAsync(()=>form.PostInventorySubmissionAsync(request),()=>cleanup.Invoke(form,new object[]{request}),()=>{});
                    while(!task.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(1);}
                    if(!task.GetAwaiter().GetResult()||probe.Calls!=1||!Require<Label>(form,"inventoryDataStatus").Text.Contains("تم حفظ حركة المخزون")||
                        form.RunInventoryWrite(()=>probe.Calls++,()=>{},()=>{})||probe.Calls!=1)
                        throw new Exception("Known accepted movement with failed file cleanup was reported as failed or allowed reposting.");
                }
            }
            Console.WriteLine("PASS inventory recovery failures: changed context, corrupt pre-send file, known rejection cleanup, accepted cleanup and unavailable medicine; no SQL.");
        }

        private static void VerifyInventoryRecovery()
        {
            string previous=Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})
                foreach(InventoryOperationMode mode in new[]{InventoryOperationMode.OpeningStock,InventoryOperationMode.Adjustment,InventoryOperationMode.Receipt,InventoryOperationMode.Issue})
                {
                    Properties.Setings.Default.ThemeMode=theme;
                    var kind=mode==InventoryOperationMode.OpeningStock?InventoryPostKind.OpeningStock:mode==InventoryOperationMode.Adjustment?InventoryPostKind.Adjustment:mode==InventoryOperationMode.Receipt?InventoryPostKind.Receipt:InventoryPostKind.Issue;
                    string directory=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"PharmacyInventoryRecovery-"+Guid.NewGuid().ToString("N"));
                    string key=InventoryPendingStore.CreateContextKey("test-target","test-user","test-role","test-employee");
                    var request=new InventoryPostRequest(kind,"recovered-source","باراسيتامول 500 mg",3,kind==InventoryPostKind.Receipt||kind==InventoryPostKind.Issue?(decimal?)12.345m:null,"سطر عربي\r\nMixed 500 mg");
                    using(var prior=new InventoryPendingStore(directory,key,kind))prior.Save(request);
                    var probe=new InventoryContextProbe();
                    using(var form=new InventoryOperationForm(mode,false))
                    {
                        form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);
                        form.ApplyPresentation(mode==InventoryOperationMode.Issue||mode==InventoryOperationMode.Receipt);
                        var medicines=new DataTable();medicines.Columns.Add("MedName");medicines.Columns.Add("DisplayName");medicines.Rows.Add(request.MedicineName,request.MedicineName);
                        typeof(InventoryOperationForm).GetMethod("SetMedicineOptions",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(form,new object[]{medicines});
                        form.Show();UiTheme.Apply(form);
                        var store=new InventoryPendingStore(directory,key,kind);
                        var session=new InventoryPostingSession(probe,new OperationActor {UserName="original-user",UserRole="original-role"},()=>true,key);
                        form.AttachInventoryRecovery(store,session);
                        var pendingField=typeof(InventoryOperationForm).GetField("pendingInventoryRequest",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);
                        var restored=(InventoryPostRequest)pendingField.GetValue(form);
                        if(!request.HasSameContent(restored)||restored.SourceId!=request.SourceId||probe.Calls!=0||Require<TextBox>(form,"inventoryOperationNotes").Text!=request.Notes)
                            throw new Exception("Restoring a movement changed its payload or posted automatically.");
                        probe.OnPost=()=>{if(store.Load().SourceId!=request.SourceId)throw new Exception("Inventory posting preceded persistent pending request.");};
                        var cleanup=typeof(InventoryOperationForm).GetMethod("PrepareNextInventoryDraft",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);
                        var task=form.RunInventoryWriteAsync(()=>form.PostInventorySubmissionAsync(restored),()=>cleanup.Invoke(form,new object[]{restored}),()=>{});
                        // DoEvents may wait in GetMessage on an idle private desktop after
                        // native input-method filtering. Keep a local UI message available;
                        // this timer performs no input, clicks, consent or application work.
                        using(var pumpWake = new System.Windows.Forms.Timer { Interval = 25 })
                        {
                            pumpWake.Tick += (sender, args) => { };
                            pumpWake.Start();
                            var completion = System.Diagnostics.Stopwatch.StartNew();
                            while(!task.IsCompleted)
                            {
                                Application.DoEvents();
                                if(completion.ElapsedMilliseconds > 30000 && !task.IsCompleted)
                                    throw new TimeoutException("SQL-free inventory recovery did not complete within 30 seconds.");
                                System.Threading.Thread.Sleep(1);
                            }
                        }
                        if(!task.GetAwaiter().GetResult()||probe.Calls!=1||store.Load()!=null||pendingField.GetValue(form)!=null)
                            throw new Exception("Accepted restored movement lost source or failed to resolve its pending file.");
                    }
                    // Dispose must release the process lease; the next form can own the same slot.
                    using(var next=new InventoryPendingStore(directory,key,kind))if(next.Load()!=null)throw new Exception("Resolved pending request survived form disposal.");
                    Console.WriteLine("PASS inventory recovery; Theme="+theme+"; Kind="+kind+"; no SQL, temporary store.");
                }
            }
            finally{Properties.Setings.Default.ThemeMode=previous;}
        }

        private static void VerifyInventoryCompositionContext()
        {
            string previousUser=SessionContext.CurrentUser, previousRole=SessionContext.CurrentRole, previousEmployee=SessionContext.CurrentEmployeeId;
            bool authenticated=SessionContext.IsAuthenticated;
            try
            {
                SessionContext.Start("context-user", "context-role", "employee-A");
                var session=ApplicationServices.CreateInventoryPostingSession();
                var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
                var service=typeof(InventoryPostingSession).GetField("service",flags).GetValue(session);
                var repository=service.GetType().GetField("repository",flags).GetValue(service);
                var factory=(Func<System.Data.SqlClient.SqlConnection>)repository.GetType().GetField("connectionFactory",flags).GetValue(repository);
                var readService=typeof(InventoryPostingSession).GetField("reads",flags).GetValue(session);
                var readRepository=readService.GetType().GetField("repository",flags).GetValue(readService);
                var readFactory=(Func<System.Data.SqlClient.SqlConnection>)readRepository.GetType().GetField("connectionFactory",flags).GetValue(readRepository);
                string expected=Database.ConnectionString;
                using(var unopened=readFactory())
                    if(unopened.State!=ConnectionState.Closed||unopened.ConnectionString!=expected)
                        throw new Exception("Inventory read/write composition targets differ.");
                using(var unopened=factory())
                    if(unopened.State!=ConnectionState.Closed||unopened.ConnectionString!=expected)
                        throw new Exception("Inventory composition did not capture an unopened target connection.");
                var request=new InventoryPostRequest(InventoryPostKind.Receipt,"context-root","drug",1,null,"reason");
                foreach(int change in new[]{0,1,2,3})
                {
                    if(change==0)SessionContext.Start("context-user","context-role","employee-B");
                    if(change==1)SessionContext.Start("other-user","context-role","employee-A");
                    if(change==2)SessionContext.Start("context-user","other-role","employee-A");
                    if(change==3)SessionContext.Clear();
                    bool rejected=false;
                    try{session.PostAsync(request).GetAwaiter().GetResult();}catch(InvalidOperationException){rejected=true;}
                    if(!rejected)throw new Exception("Composition allowed inventory retry under a changed login identity.");
                    bool readRejected=false;
                    try{session.LoadSnapshotAsync(new InventoryOperationReadRequest("drug",DateTime.Today,DateTime.Today),System.Threading.CancellationToken.None).GetAwaiter().GetResult();}
                    catch(InvalidOperationException){readRejected=true;}
                    if(!readRejected)throw new Exception("Changed login dispatched inventory reads.");
                    using(var unopened=readFactory())
                        if(unopened.State!=ConnectionState.Closed||unopened.ConnectionString!=expected)
                            throw new Exception("Read factory changed its captured target.");
                    using(var unopened=factory())
                        if(unopened.State!=ConnectionState.Closed||unopened.ConnectionString!=expected)
                            throw new Exception("Captured target connection changed with the login context.");
                }
                Console.WriteLine("PASS: real composition captures unopened connection and rejects changed employee/user/role/logout before SQL.");
            }
            finally
            {
                if(authenticated)SessionContext.Start(previousUser,previousRole,previousEmployee);else SessionContext.Clear();
            }
        }

        private static void VerifyInventoryPostingContext()
        {
            string target="database-A", user="user-A";
            var actor=new PharmacyManagement.Application.OperationActor {UserName="original-user",UserRole="original-role"};
            var probe=new InventoryContextProbe();
            var session=new InventoryPostingSession(probe,actor,()=>target=="database-A"&&user=="user-A");
            actor.UserName="changed-after-capture";
            var request=new PharmacyManagement.Application.InventoryPostRequest(PharmacyManagement.Application.InventoryPostKind.Receipt,"context-source","drug",3,null,"reason");
            var first=session.PostAsync(request).GetAwaiter().GetResult();
            if(first.SourceId!=request.SourceId||probe.Calls!=1)throw new Exception("Captured inventory submission failed.");
            foreach(bool changeTarget in new[]{true,false})
            {
                target=changeTarget?"database-B":"database-A";user=changeTarget?"user-A":"user-B";
                bool rejected=false;
                try{session.PostAsync(request).GetAwaiter().GetResult();}
                catch(InvalidOperationException error){rejected=error.Message.Contains("تغير المستخدم");}
                if(!rejected||probe.Calls!=1)throw new Exception("Unresolved inventory request was sent in a changed context.");
            }
            target="database-A";user="user-A";
            var retry=session.PostAsync(request).GetAwaiter().GetResult();
            if(!retry.AlreadyPosted||probe.Calls!=2)throw new Exception("Original inventory context could not confirm its retained request.");
            probe.OnPost=()=>target="database-B";
            // A known result stays accepted even if the displayed context changes after the call starts.
            var accepted=session.PostAsync(request).GetAwaiter().GetResult();
            if(accepted.SourceId!=request.SourceId||probe.Calls!=3)throw new Exception("Context change after acceptance caused a false failure.");
            bool blocked=false;
            try{session.PostAsync(request).GetAwaiter().GetResult();}catch(InvalidOperationException){blocked=true;}
            if(!blocked||probe.Calls!=3)throw new Exception("Subsequent retry ignored changed context.");
            Console.WriteLine("PASS: retained inventory context rejects changed target/user, preserves actor, resumes original target and keeps accepted results; mock service, no SQL.");
        }

        private static object InventoryPreparationField(object owner,string name)
        {
            var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.DeclaredOnly;
            for(Type type=owner.GetType();type!=null;type=type.BaseType){var field=type.GetField(name,flags);if(field!=null)return field.GetValue(owner);}
            throw new InvalidOperationException("Missing inventory preparation fixture field: "+name);
        }
