   foreach(InventoryOperationMode mode in baseline?new[]{InventoryOperationMode.Receipt}:new[]{InventoryOperationMode.OpeningStock,InventoryOperationMode.Adjustment,InventoryOperationMode.Receipt,InventoryOperationMode.Issue})
   foreach(string theme in baseline?new[]{"Light"}:new[]{"Light","Dark"})
   foreach(bool ltr in baseline?new[]{false}:new[]{false,true})
   foreach(string boundary in new[]{"FilterPanel","Grid","inventoryOperationCommit"})
   foreach(string action in new[]{"relogin","dispose","throw"}){
    project_fo_3.Properties.Setings.Default.ThemeMode=theme;
    SessionContext.Start("inventory-preparation","Manager","QA-INVENTORY");
    using(var form=new InventoryOperationForm(mode,true)){
     int loads=0;form.Load+=(s,e)=>loads++;
     form.ApplyPresentation(ltr);
     Control target=boundary=="inventoryOperationCommit"?form.Controls.Find(boundary,true).Single():(Control)InventoryPreparationField(form,boundary);
     var filter=(Control)InventoryPreparationField(form,"FilterPanel");var grid=(Control)InventoryPreparationField(form,"Grid");var commit=form.Controls.Find("inventoryOperationCommit",true).Single();
     var kind=(InventoryPostKind)Enum.Parse(typeof(InventoryPostKind),mode.ToString());
