     var request=form.BindInventorySubmission(new InventoryPostRequest(kind,"PREP-"+Guid.NewGuid().ToString("N"),"QA medicine",2,unitAmount,"QA preparation"));
     bool fired=false;int writes=0,clears=0,reads=0;var injected=new InvalidOperationException("owned-inventory-preparation-event");
     EventHandler handler=(s,e)=>{if(fired||target.Enabled)return;fired=true;if(action=="relogin")SessionContext.Start("inventory-preparation","Manager","QA-INVENTORY");else if(action=="dispose")form.Dispose();else throw injected;};
     target.EnabledChanged+=handler;
     Func<Task<bool>> invoke=()=>form.RunInventoryWriteAsync(()=>{writes++;return Task.CompletedTask;},()=>clears++,()=>reads++);
     bool result=false;Exception error=null;
     try{result=invoke().GetAwaiter().GetResult();}catch(Exception ex){error=ex;}finally{target.EnabledChanged-=handler;}
     bool busy=(bool)InventoryPreparationField(form,"inventoryWriteBusy");
     bool ok=fired&&writes==0&&clears==0&&reads==0&&!busy&&loads==0&&ReferenceEquals(request,InventoryPreparationField(form,"pendingInventoryRequest"));
     if(action=="throw")ok&=ReferenceEquals(error,injected)&&filter.Enabled&&grid.Enabled&&commit.Enabled;
     else ok&=!result&&error==null;
     if(action=="relogin")ok&=(bool)InventoryPreparationField(form,"inventorySessionInvalidated")&&!filter.Enabled&&!grid.Enabled&&!commit.Enabled;
     if(ok&&action=="throw"){ok=invoke().GetAwaiter().GetResult()&&writes==1&&clears==1&&reads==1&&!(bool)InventoryPreparationField(form,"inventoryWriteBusy")&&loads==0;}
     Console.WriteLine("CASE mode="+mode+" theme="+theme+" ltr="+ltr+" boundary="+boundary+" action="+action+" fired="+fired+" writes="+writes+" clears="+clears+" reads="+reads+" busy="+busy+" loads="+loads+" error="+(error==null?"none":error.Message)+" accepted="+ok);
     cases++;if(!ok)failures++;
    }
   }

                if(failures!=0)throw new InvalidOperationException("Inventory preparation failures: "+failures);
                Console.WriteLine("PASS inventory write preparation cases="+cases+"; no stale writer, event exception cleanup/recovery; no Show/SQL/native input.");
            }
            finally { SessionContext.Clear();Properties.Setings.Default.ThemeMode=oldTheme; }
        }

        private static void VerifyInventoryAcceptedWrite()
        {
            string previous=Properties.Setings.Default.ThemeMode;
            try
            {
                foreach(string theme in new[]{"Light","Dark"})
                foreach(var mode in new[]{InventoryOperationMode.OpeningStock,InventoryOperationMode.Adjustment,InventoryOperationMode.Receipt,InventoryOperationMode.Issue})
                using(var form=new InventoryOperationForm(mode,false))
                {
                    Properties.Setings.Default.ThemeMode=theme;
                    form.ShowInTaskbar=false; form.StartPosition=FormStartPosition.Manual; form.Location=new Point(-20000,-20000);
                    form.Show(); UiTheme.Apply(form);
                    var commit=Require<AntdUI.Button>(form,"inventoryOperationCommit");
                    var filters=Require<FlowLayoutPanel>(form,"inventoryDataFilters");
                    var grid=Require<DataGridView>(form,"inventoryDataGrid");
                    var status=Require<Label>(form,"inventoryDataStatus");
                    bool invalidRejected=false;
                    try{form.BindInventorySubmission(new PharmacyManagement.Application.InventoryPostRequest(PharmacyManagement.Application.InventoryPostKind.Receipt,"INV-invalid","drug",0,null,"reason"));}
                    catch(InvalidOperationException){invalidRejected=true;}
                    if(!invalidRejected)throw new Exception("Invalid inventory draft was reserved for retry.");
                    var originalRequest=new PharmacyManagement.Application.InventoryPostRequest(PharmacyManagement.Application.InventoryPostKind.Receipt,"INV-original","دواء 500 mg",3,10m,"reason");
                    var retained=form.BindInventorySubmission(originalRequest);
                    var sessionField=typeof(InventoryOperationForm).GetField("pendingInventorySession",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);
                    var retainedSession=new InventoryPostingSession(new InventoryContextProbe(),new OperationActor {UserName="original-user",UserRole="original-role"},()=>true);
                    sessionField.SetValue(form,retainedSession);
                    form.HandleInventoryWriteIssue(new InvalidOperationException("unknown outcome"));
                    if(!ReferenceEquals(retainedSession,sessionField.GetValue(form)))throw new Exception("Unknown inventory outcome discarded its captured context.");
                    var retryCandidate=new PharmacyManagement.Application.InventoryPostRequest(originalRequest.Kind,"INV-other",originalRequest.MedicineName,3,10m,"reason");
                    if(!ReferenceEquals(retained,form.BindInventorySubmission(retryCandidate)))throw new Exception("Inventory retry lost the original request identity.");
                    bool changedRejected=false;
                    try{form.BindInventorySubmission(new PharmacyManagement.Application.InventoryPostRequest(originalRequest.Kind,"INV-other",originalRequest.MedicineName,4,10m,"reason"));}
                    catch(InvalidOperationException){changedRejected=true;}
                    if(!changedRejected||!ReferenceEquals(retained,form.BindInventorySubmission(retryCandidate)))throw new Exception("A changed inventory retry replaced the pending source.");
                    form.HandleInventoryWriteIssue(new PharmacyManagement.Application.InventoryPostNotCommittedException("other-source","رفض معروف",new Exception()));
                    if(!ReferenceEquals(retained,form.BindInventorySubmission(retryCandidate)))throw new Exception("An unrelated rejected source discarded the pending inventory request.");
                    if(!ReferenceEquals(retainedSession,sessionField.GetValue(form)))throw new Exception("Another rejected source discarded the original context.");
                    form.HandleInventoryWriteIssue(new PharmacyManagement.Application.InventoryPostNotCommittedException(retained.SourceId,"الفترة مقفلة",new Exception()));
                    if(sessionField.GetValue(form)!=null)throw new Exception("Confirmed inventory rejection retained the previous context.");
                    if(!status.Text.Contains("لم يتم الحفظ"))throw new Exception("Confirmed inventory rejection is still reported as an unknown acceptance.");
                    var changedAfterRejection=form.BindInventorySubmission(new PharmacyManagement.Application.InventoryPostRequest(originalRequest.Kind,"INV-new",originalRequest.MedicineName,4,10m,"reason"));
                    if(changedAfterRejection.SourceId!="INV-new"||changedAfterRejection.Quantity!=4)throw new Exception("Confirmed inventory rollback prevents correcting a new draft.");
                    form.HandleInventoryWriteIssue(new InvalidOperationException("unknown commit outcome"));
                    if(status.Text.Contains("لم يتم الحفظ")||!status.Text.Contains("تعذر تأكيد"))throw new Exception("Unknown inventory outcome is reported as a confirmed failed write.");
                    if(!ReferenceEquals(changedAfterRejection,form.BindInventorySubmission(new PharmacyManagement.Application.InventoryPostRequest(originalRequest.Kind,"INV-another",originalRequest.MedicineName,4,10m,"reason"))))
                        throw new Exception("An unknown inventory outcome discarded its retry identity.");
                    grid.Enabled=false;
                    var pending=new System.Threading.Tasks.TaskCompletionSource<bool>();
                    bool clearedAsync=false,refreshedAsync=false,uiProcessed=false;
                    var asyncWrite=form.RunInventoryWriteAsync(()=>pending.Task,()=>clearedAsync=true,()=>refreshedAsync=true);
                    if(asyncWrite.IsCompleted||filters.Enabled||grid.Enabled||commit.Enabled||
                        form.RunInventoryWriteAsync(()=>System.Threading.Tasks.Task.CompletedTask,()=>{},()=>{}).GetAwaiter().GetResult())
                        throw new Exception("Pending inventory write allows editing, reentry or completes too soon.");
                    form.BeginInvoke(new Action(()=>uiProcessed=true));Application.DoEvents();
                    form.Close();if(form.IsDisposed||!uiProcessed)throw new Exception("Pending write blocks the message loop or allows user close.");
                    pending.SetResult(true);
                    var deadline=DateTime.UtcNow.AddSeconds(10);
                    while(!asyncWrite.IsCompleted&&DateTime.UtcNow<deadline){Application.DoEvents();System.Threading.Thread.Sleep(1);}
                    if(!asyncWrite.IsCompleted||!asyncWrite.GetAwaiter().GetResult()||!clearedAsync||!refreshedAsync||!filters.Enabled||grid.Enabled||!commit.Enabled)
                        throw new Exception("Async inventory acceptance lost cleanup, refresh or prior enabled states.");
                    int writes=0; bool failed=false;
                    try {form.RunInventoryWrite(()=>{throw new InvalidOperationException("before acceptance");},()=>{},()=>{});}
                    catch(InvalidOperationException){failed=true;}
                    if(!failed||!filters.Enabled||grid.Enabled||!commit.Enabled)throw new Exception("Inventory write failure lost previous enabled states.");
                    if(!form.RunInventoryWrite(()=> {
                        writes++;
                        if(filters.Enabled||grid.Enabled||commit.Enabled||form.RunInventoryWrite(()=>writes++,()=>{},()=>{}))
                            throw new Exception("Inventory write allowed reentry or editing.");
                        form.Close(); if(form.IsDisposed)throw new Exception("Inventory closed during writing.");
                    },()=>{},()=>{throw new InvalidOperationException("refresh failure");})||writes!=1||
                        !status.Text.Contains("تم حفظ حركة المخزون")||status.Text.Contains("لم يتم الحفظ"))
                        throw new Exception("Accepted inventory movement was reported as an unsuccessful write.");
                    foreach(var size in new[]{new Size(860,560),new Size(1120,700)})
                    {
                        OwnedTestWindowViewport.Resize(form, size); form.PerformLayout();
                        int width=Math.Max(1,status.ClientSize.Width-status.Padding.Horizontal);
                        if(TextRenderer.MeasureText(status.Text,status.Font,new Size(width,int.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height>
                            status.ClientSize.Height-status.Padding.Vertical||status.AccessibleDescription.Contains("refresh failure")||
                            !System.Text.RegularExpressions.Regex.IsMatch(status.AccessibleDescription,"[0-9]{8}-[0-9]{6}-[A-F0-9]{8}"))
                            throw new Exception("The known-acceptance warning is clipped, exposes technical detail or loses its support identifier.");
                    }
                    if(!form.RunInventoryWrite(()=>writes++,()=>{},()=>{})||writes!=2)
                        throw new Exception("A new cleared inventory draft cannot be saved.");
                    if(!form.RunInventoryWrite(()=>writes++,()=>{throw new InvalidOperationException("clear failure");},()=>{})||writes!=3||
                        form.RunInventoryWrite(()=>writes++,()=>{},()=>{})||writes!=3)
                        throw new Exception("An accepted inventory draft was replayed after clear failure.");
                    if(!filters.Enabled||grid.Enabled||!commit.Enabled||!status.Text.Contains("محفوظة بالفعل"))
                        throw new Exception("Accepted inventory recovery or enabled states are invalid.");
                }
            }
            finally {Properties.Setings.Default.ThemeMode=previous;using(var palette=new Form())UiTheme.Apply(palette);}
        }
        public static void VerifyInventoryOperationFramesOnly()
        {
            string theme = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string modeTheme in new[] { "Light", "Dark" })
                {
                Properties.Setings.Default.ThemeMode = modeTheme;
                foreach (bool english in new[] { false, true })
                foreach (InventoryOperationMode mode in Enum.GetValues(typeof(InventoryOperationMode)))
                using (var form = new InventoryOperationForm(mode, false))
                {
                    form.ApplyPresentation(english);
                    form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual; form.Location = new Point(-20000, -20000);
                    form.Show();
                    var notes = Require<TextBox>(form, "inventoryOperationNotes");
                    string text = "صيدلية المهندس\r\nباراسيتامول 500 mg\r\nالإجمالي 1,250.50 ر.ي";
                    notes.Text = text;
                    foreach (Size size in new[] { new Size(960, 640), new Size(1024, 768), new Size(1366, 768), new Size(1920, 1080) })
                    {
                        Prepare(form, size);
                        var frame = Require<AntdUI.Panel>(form, "inventoryOperationNotesFrame");
                        if (notes.Parent != frame || notes.BorderStyle != BorderStyle.None || !notes.Multiline || notes.Height < 40 || notes.Left < 8 || notes.Right > frame.ClientSize.Width - 8 || notes.Bottom > frame.ClientSize.Height - 8 || notes.Text != text || frame.Shadow != 0 || frame.Radius <= 0)
                            throw new Exception("Inventory multiline frame clipped or changed stored text at " + size);
                        foreach (string name in new[] { "inventoryOperationBalanceFrame", "inventoryOperationPreviewFrame" })
                        {
                            var display = Require<AntdUI.Panel>(form, name);
                            var label = display.Controls.OfType<Label>().Single();
                            if (label.BackColor != Color.Transparent || display.Shadow != 0 || display.Radius <= 0 || display.BorderWidth != 1 || label.TextAlign != ContentAlignment.MiddleCenter || label.BorderStyle != BorderStyle.None || label.Left < 1 || label.Top < 1 || label.Right >= display.Width || label.Bottom >= display.Height)
                                throw new Exception("Inventory display frame is not centered/rounded at " + size);
                        }
                        if (Require<FlowLayoutPanel>(form, "inventoryOperationFooter").Bottom != form.ClientSize.Height)
                            throw new Exception("Inventory action footer moved out of view.");
                    }
                }
            }
            }
            finally { Properties.Setings.Default.ThemeMode = theme; }
            Console.WriteLine("PASS inventory frames: 64 mode/theme/direction/size cases, rounded centered displays, multiline text retained, no shadows and fixed footer; software layout only, no SQL/native keys/DPI.");
        }
        public static void VerifyInventoryOperationNotificationOnly()
        {
            string originalTheme = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool english in new[] { false, true })
                foreach (InventoryOperationMode mode in Enum.GetValues(typeof(InventoryOperationMode)))
                foreach (bool pendingWrite in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    SessionContext.Start("inventory-notification", "Manager", "fixture");
                    using (var form = new InventoryOperationForm(mode, false))
                    {
                        var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                        var type = typeof(InventoryOperationForm);
                        type.GetField("loadData", flags).SetValue(form, true);
                        form.ApplyPresentation(english);
                        var handle = form.Handle;
                        var selector = Require<ComboBox>(form, "inventoryOperationMedicine");
                        if (selector.RightToLeft != (english ? RightToLeft.No : RightToLeft.Yes)) throw new Exception("Inventory operation direction differs from interface.");
                        selector.Items.Add("Previous medicine"); selector.SelectedIndex = 0;
                        Require<AntdUI.Input>(form, "inventoryOperationQuantity").Text = "2";
                        Require<TextBox>(form, "inventoryOperationNotes").Text = "Old draft";
                        var request = new PharmacyManagement.Application.InventoryPostRequest(PharmacyManagement.Application.InventoryPostKind.Receipt, "INV-notification", "A", 2, null, "Old draft");
                        type.GetField("pendingInventoryRequest", flags).SetValue(form, request);
                        var cancellation = new System.Threading.CancellationTokenSource(); var token = cancellation.Token;
                        type.GetField("inventoryReadCancellation", flags).SetValue(form, cancellation);
                        var completion = new System.Threading.Tasks.TaskCompletionSource<bool>();
                        int prepared = 0, refreshed = 0;
                        var write = pendingWrite ? form.RunInventoryWriteWithRefreshAsync(() => completion.Task, () => prepared++, () => { refreshed++; return System.Threading.Tasks.Task.CompletedTask; }) : null;
                        SessionContext.Start("inventory-notification", "Manager", "fixture");
                        if (!token.IsCancellationRequested || selector.Items.Count != 0 || Require<AntdUI.Input>(form, "inventoryOperationQuantity").Text.Length != 0 || Require<TextBox>(form, "inventoryOperationNotes").Text.Length != 0 || Require<AntdUI.Button>(form, "inventoryOperationCommit").Enabled)
                            throw new Exception("Inventory session retained editable old draft.");
                        if (!ReferenceEquals(type.GetField("pendingInventoryRequest", flags).GetValue(form), request)) throw new Exception("Session notification destroyed uncertain request identity.");
                        if (pendingWrite)
                        {
                            completion.SetResult(true);
                            DateTime deadline = DateTime.UtcNow.AddSeconds(10);
                            while (!write.IsCompleted) { if (DateTime.UtcNow > deadline) throw new Exception("Inventory write fixture stalled."); Application.DoEvents(); System.Threading.Thread.Sleep(1); }
                            if (!write.GetAwaiter().GetResult() || prepared != 0 || refreshed != 0 || Require<AntdUI.Button>(form, "inventoryOperationCommit").Enabled || !ReferenceEquals(type.GetField("pendingInventoryRequest", flags).GetValue(form), request))
                                throw new Exception("Old write response changed new-session UI or uncertain request.");
                        }
                        bool invoked = false;
                        if (form.RunInventoryWriteWithRefreshAsync(() => { invoked = true; return System.Threading.Tasks.Task.CompletedTask; }, () => { }, () => System.Threading.Tasks.Task.CompletedTask).GetAwaiter().GetResult() || invoked)
                            throw new Exception("Invalidated inventory window accepted another write.");
                    }
                }
            }
            finally { SessionContext.Clear(); Properties.Setings.Default.ThemeMode = originalTheme; }
            Console.WriteLine("PASS inventory operation notification: four modes/themes/directions, draft cleared, read cancelled, uncertain request retained, old write response suppressed and repeat blocked; no SQL/native input.");
        }
        private static void VerifyInventoryOperationInputs()
        {
            foreach (InventoryOperationMode mode in new[]
            {
                InventoryOperationMode.OpeningStock, InventoryOperationMode.Adjustment, InventoryOperationMode.Issue
            })
            {
                using (var modeForm = new InventoryOperationForm(mode, false))
                {
                    modeForm.ShowInTaskbar = false;
                    modeForm.StartPosition = FormStartPosition.Manual;
                    modeForm.Location = new Point(-20000, -20000);
                    modeForm.Show();
                    Prepare(modeForm, new Size(860, 560));
                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(modeForm, "inventoryOperationFooter");
                    TextBox reason = Require<TextBox>(modeForm, "inventoryOperationNotes");
                    if (footer.Bottom != modeForm.ClientSize.Height || reason.Parent == null || !reason.Visible)
                        throw new InvalidOperationException("Inventory " + mode + " hides its reason or fixed approval action.");
                }
            }
            using (var form = new InventoryOperationForm(InventoryOperationMode.Receipt, false))
            using (var parser = new InventoryDataFormProbe())
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(860, 560), new Size(1120, 700) })
                {
                    Prepare(form, size);
                    FlowLayoutPanel filters = Require<FlowLayoutPanel>(form, "inventoryDataFilters");
                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "inventoryOperationFooter");
                    AntdUI.Button commit = Require<AntdUI.Button>(footer, "inventoryOperationCommit");
                    ComboBox medicine = Require<ComboBox>(form, "inventoryOperationMedicine");
                    AntdUI.Button medicineDropdown = Require<AntdUI.Button>(form, "inventoryOperationMedicineDropdown");
                    AntdUI.Input quantityField = Require<AntdUI.Input>(form, "inventoryOperationQuantity");
                    if (filters.Right > form.ClientSize.Width || filters.Height < 100)
                        throw new InvalidOperationException("Inventory receipt filters are clipped at " + size + ".");
                    if (footer.Bottom != form.ClientSize.Height || commit.BorderWidth != 1 ||
                        commit.DefaultBorderColor != UiTheme.Primary ||
                        medicineDropdown.Parent != medicine.Parent ||
                        medicineDropdown.Top < medicine.Top || medicineDropdown.Bottom > medicine.Bottom ||
                        medicineDropdown.Left < medicine.Left || medicineDropdown.Right > medicine.Right ||
                        (UiDirection.IsLeftToRight
                            ? medicine.PointToScreen(Point.Empty).X >= quantityField.PointToScreen(Point.Empty).X
                            : medicine.PointToScreen(Point.Empty).X <= quantityField.PointToScreen(Point.Empty).X))
                        throw new InvalidOperationException("Inventory receipt action bar or leading field order is invalid at " + size + ".");
                }

                AntdUI.Input quantity = Require<AntdUI.Input>(form, "inventoryOperationQuantity");
                AntdUI.Input money = Require<AntdUI.Input>(form, "inventoryOperationUnitAmount");
                TextBox notes = Require<TextBox>(form, "inventoryOperationNotes");
                ComboBox medicineSelect = Require<ComboBox>(form, "inventoryOperationMedicine");
                if (quantity.RightToLeft != RightToLeft.No || money.RightToLeft != RightToLeft.No ||
                    notes.RightToLeft != RightToLeft.Yes || !notes.Multiline || notes.MaxLength != 500 ||
                    notes.ScrollBars != ScrollBars.None ||
                    string.IsNullOrWhiteSpace(quantity.AccessibleName) || string.IsNullOrWhiteSpace(notes.AccessibleName))
                    throw new InvalidOperationException("Inventory operation input direction, note limit or accessibility changed.");

                var lookup = new DataTable();
                lookup.Columns.Add("DisplayName", typeof(string));
                lookup.Columns.Add("MedName", typeof(string));
                lookup.Rows.Add("باراسيتامول 500 mg — شركة أ", "باراسيتامول 500 mg");
                lookup.Rows.Add("أموكسيسيلين 250 mg — شركة ب", "أموكسيسيلين 250 mg");
                typeof(InventoryOperationForm).GetMethod("SetMedicineOptions", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { lookup });
                AntdUI.Button medicineDropdownAction = Require<AntdUI.Button>(form, "inventoryOperationMedicineDropdown");
                medicineDropdownAction.PerformClick();
                if (!medicineSelect.DroppedDown)
                    throw new InvalidOperationException("Inventory medicine dropdown action did not open the selector.");
                medicineSelect.DroppedDown = false;
                medicineSelect.SelectedIndex = 1;
                string selectedMedicine = (string)typeof(InventoryOperationForm).GetMethod("SelectedMedicine",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (selectedMedicine != "أموكسيسيلين 250 mg")
                    throw new InvalidOperationException("Inventory selector changed the saved medicine identity.");
                lookup.Clear();
                typeof(InventoryOperationForm).GetMethod("SetMedicineOptions", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { lookup });
                if (medicineSelect.SelectedIndex != -1 || medicineSelect.Text.Length != 0)
                    throw new InvalidOperationException("Inventory selector kept a stale medicine after an empty lookup.");

                quantity.Text = "12";
                money.Text = "1.25";
                notes.Text = "توريد تجريبي — Batch 500 mg";
                if (parser.ParseQuantity(quantity) != 12 || parser.ParseMoney(money) != 1.25m ||
                    notes.Text != "توريد تجريبي — Batch 500 mg")
                    throw new InvalidOperationException("Inventory AntdUI inputs changed quantity, money or mixed Arabic notes.");

                form.ApplyPresentation(true);
                Prepare(form, new Size(860, 560));
                AntdUI.Button englishCommit = Require<AntdUI.Button>(form, "inventoryOperationCommit");
                if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                    form.Text != "Stock receipt" || quantity.AccessibleName != "Receipt quantity" ||
                    notes.AccessibleName != "Movement reason or reference" || englishCommit.Text != "Post movement" ||
                    medicineSelect.PointToScreen(Point.Empty).X >= quantity.PointToScreen(Point.Empty).X)
                    throw new InvalidOperationException("Inventory operation English presentation failed.");
                typeof(InventoryOperationForm).GetMethod("SaveOperation", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("no data was saved"))
                    throw new InvalidOperationException("Inventory operation preview could reach persistence.");
                form.ApplyPresentation(false);
            }
        }

