                            grid.Columns["Operation"].MinimumWidth != 190 || grid.Columns["Override"].MinimumWidth != 165 ||
                            grid.Columns["Effective"].MinimumWidth != 100 ||
                            grid.Columns["Effective"].HeaderText != (english ? "Effective access" : "النتيجة الفعلية"))
                            throw new InvalidOperationException("Permission presentation must retain its language and custom column widths after styling.");
                        Size minimumClient = new Size(form.MinimumSize.Width - (form.Width - form.ClientSize.Width),
                            form.MinimumSize.Height - (form.Height - form.ClientSize.Height));
                        foreach (Size size in new[] { minimumClient, new Size(620, 500), new Size(960, 640) })
                        {
                            Prepare(form, size);
                            Label title = Require<Label>(form, "permissionsTitle");
                            Label subtitle = Require<Label>(form, "permissionsSubtitle");
                            foreach (Label caption in new[] { title, subtitle })
                            {
                                int needed = TextRenderer.MeasureText(caption.Text, caption.Font,
                                    new Size(caption.ClientSize.Width, int.MaxValue), TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                                if (needed > caption.ClientSize.Height || caption.AutoEllipsis || caption.AccessibleName != caption.Text)
                                    throw new InvalidOperationException("Permission employee identity or policy explanation is clipped: " + caption.Name);
                            }
                            AntdUI.Panel card = Require<AntdUI.Panel>(form, "permissionsCard");
                            if (card.Radius != DesktopDesignTokens.CardRadius || card.Shadow != 0 || grid.Height < 60 ||
                                Require<AntdUI.Button>(form, "saveEmployeeOperationPermissions").Enabled)
                                throw new InvalidOperationException("Permission card crowds the editor or permits a preview save.");
                            var snapshot = (Dictionary<string, bool>)typeof(EmployeeOperationPermissionsForm)
                                .GetMethod("ReadOverrides", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                                .Invoke(form, null);
                            if (snapshot.Count != 2 || !snapshot[firstKey] || snapshot[secondKey] ||
                                grid.Columns["Override"].HeaderText != (english ? UiLanguageCatalog.Translate("تجاوز للموظف") : "تجاوز للموظف"))
                                throw new InvalidOperationException("Permission presentation changed a grant, denial or translated heading.");
                            if (!grid.Columns["Effective"].Visible ||
                                grid.Columns["RoleDefault"].Visible != (grid.ClientSize.Width >= 690) ||
                                Convert.ToString(grid.Rows[0].Cells["Effective"].Value) != (english ? "Allowed" : "مسموح") ||
                                Convert.ToString(grid.Rows[1].Cells["Effective"].Value) != (english ? "Denied" : "غير مسموح") ||
                                !grid.Rows[0].Cells["Effective"].ToolTipText.Contains(english ? "Role:" : "الدور:"))
                                throw new InvalidOperationException("Permission effective access is hidden, stale or untranslated.");
                        }
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = originalMode; }
        }

        private static void VerifyPermissionSearch()
        {
            bool originalOpeningPreference = Properties.Setings.Default.OpenScreensMaximized;
            Properties.Setings.Default.OpenScreensMaximized = false;
            try
            {
            VerifyPermissionEditState();
            VerifyPermissionPresentation();
            using (var form = new EmployeeOperationPermissionsForm("preview", "موظف تجريبي", true))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                TextBox search = Require<TextBox>(form, "permissionsSearch");
                AntdUI.Panel frame = Require<AntdUI.Panel>(form, "permissionsSearchFrame");
                DataGridView grid = Require<DataGridView>(form, "employeeOperationPermissionsGrid");
                int total = grid.Rows.Count;
                if (total < 2) throw new InvalidOperationException("Permission search fixture is incomplete.");
                string firstKey = (string)grid.Rows[0].Tag;
                string secondKey = (string)grid.Rows[1].Tag;
                grid.Rows[0].Cells["Override"].Value = "سماح";
                grid.Rows[1].Cells["Override"].Value = "منع";
                foreach (bool english in new[] { false, true })
                {
                    form.ApplyPresentation(english);
                    foreach (Size size in new[] { new Size(620, 500), new Size(960, 640) })
                    {
                        Prepare(form, size);
                        if (Require<Panel>(form, "permissionsSearchBar").BackColor != UiTheme.Surface ||
                            Require<Label>(form, "permissionsSearchCaption").BackColor != UiTheme.Surface)
                            throw new InvalidOperationException("Permission search surface does not match the field theme.");
                        if (frame.Height < 44 || search.BorderStyle != BorderStyle.None || grid.Height < 60)
                            throw new InvalidOperationException("Permission search crowds the permission editor.");
                        RequireInside(frame.Parent, frame, "permission search frame");
                        RequireInside(frame, search, "permission search editor");
                    }
                    grid.CurrentCell = grid.Rows[0].Cells["Override"];
                    search.Text = "NO_MATCH_PERMISSION_TEST";
                    if (grid.Rows.Count != total || grid.Rows.Cast<DataGridViewRow>().Any(row => row.Visible))
                        throw new InvalidOperationException("Permission search removed rows or did not filter them.");
                    var snapshot = (Dictionary<string, bool>)typeof(EmployeeOperationPermissionsForm)
                        .GetMethod("ReadOverrides", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                        .Invoke(form, null);
                    if (!snapshot.ContainsKey(firstKey) || !snapshot[firstKey] || !snapshot.ContainsKey(secondKey) || snapshot[secondKey])
                        throw new InvalidOperationException("Hidden permission edits were omitted from the save snapshot.");
                    search.Text = firstKey;
                    if (!grid.Rows[0].Visible) throw new InvalidOperationException("Permission identifier search failed.");
                    search.Text = "";
                    if (grid.Rows.Cast<DataGridViewRow>().Any(row => !row.Visible))
                        throw new InvalidOperationException("Clearing permission search did not restore every row.");
                }
            }
            }
            finally
            {
                Properties.Setings.Default.OpenScreensMaximized = originalOpeningPreference;
            }
        }
        private static void VerifyPermissionEditState()
        {
            using (var form = new EmployeeOperationPermissionsForm("preview", "موظف تجريبي", true))
            {
                DataGridView grid = Require<DataGridView>(form, "employeeOperationPermissionsGrid");
                TextBox search = Require<TextBox>(form, "permissionsSearch");
                if (form.HasPendingChanges || !form.ConfirmPendingChanges(() =>
                    { throw new InvalidOperationException("An unchanged editor must not ask to discard."); }))
                    throw new InvalidOperationException("Permission editor starts with pending changes.");
                grid.Rows[0].Cells["Override"].Value = "سماح";
                if (!form.HasPendingChanges) throw new InvalidOperationException("Permission edit was not tracked.");
                if (Convert.ToString(grid.Rows[0].Cells["Effective"].Value) != "مسموح")
                    throw new InvalidOperationException("Permission allow override did not update effective access.");
                search.Text = "NO_MATCH_PERMISSION_TEST";
                form.ApplyPresentation(true);
                if (Convert.ToString(grid.Rows[0].Cells["Effective"].Value) != "Allowed")
                    throw new InvalidOperationException("Permission effective access did not translate with the form.");
                if (!form.HasPendingChanges || form.ConfirmPendingChanges(() => false))
                    throw new InvalidOperationException("Filtering/localization lost edits or close cancellation failed.");
                if (!form.ConfirmPendingChanges(() => true) || !form.HasPendingChanges)
                    throw new InvalidOperationException("Discard decision must not mutate data before actual closing.");
                grid.Rows[0].Cells["Override"].Value = "افتراضي حسب الدور";
                if (form.HasPendingChanges) throw new InvalidOperationException("Reverting a permission leaves a false dirty state.");
                grid.Rows[1].Cells["Override"].Value = "منع";
                typeof(EmployeeOperationPermissionsForm).GetMethod("CaptureSavedOverrides",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (form.HasPendingChanges) throw new InvalidOperationException("Acknowledged baseline remains dirty.");
                grid.Rows[1].Cells["Override"].Value = "سماح";
                if (Convert.ToString(grid.Rows[1].Cells["Effective"].Value) != "Allowed")
                    throw new InvalidOperationException("Permission deny-to-allow edit did not update effective access.");
                if (!form.HasPendingChanges || Require<AntdUI.Button>(form, "saveEmployeeOperationPermissions").Enabled)
                    throw new InvalidOperationException("Deny-to-allow edit was missed or preview saving became enabled.");
            }
            foreach (bool english in new[] { false, true })
            using (var dialog = new UnsavedChangesDialog(english))
            {
                var keep = Require<AntdUI.Button>(dialog, "keepEditing");
                var discard = Require<AntdUI.Button>(dialog, "discardChanges");
                if (!ReferenceEquals(dialog.AcceptButton, keep) || !ReferenceEquals(dialog.CancelButton, keep) ||
                    keep.DialogResult != DialogResult.Cancel || discard.DialogResult != DialogResult.OK ||
                    dialog.ShowInTaskbar || dialog.StartPosition != FormStartPosition.CenterParent)
                    throw new InvalidOperationException("Unsaved-changes dialog has an unsafe default or broken ownership policy.");
                foreach (Size size in new[] { new Size(430, 280), new Size(640, 360) })
                {
                    Prepare(dialog, size);
                    var actions = Require<FlowLayoutPanel>(dialog, "unsavedChangesActions");
                    if (actions.BackColor != UiTheme.Background || actions.HorizontalScroll.Visible ||
                        keep.Bounds.IntersectsWith(discard.Bounds))
                        throw new InvalidOperationException("Unsaved-changes actions overlap or overflow.");
                    RequireInside(actions, keep, "keep editing action");
                    RequireInside(actions, discard, "discard action");
                }
            }
        }
        private static void VerifyCompactInventoryReports()
        {
            foreach (InventoryDataForm form in new InventoryDataForm[] {
                new InventoryStockReportForm(false, false), new InventoryStockReportForm(true, false),
                new InventoryMovementSummaryForm(false), new InventoryMovementForm(false),
                new InventoryTurnoverForm(false), new InventoryAlertsForm(false) })
            using (form)
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (bool english in new[] { false, true })
                {
                    form.GetType().GetMethod("ApplyPresentation", System.Reflection.BindingFlags.Instance |
                        System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { english });
                    foreach (Size size in new[] { new Size(640, 480), new Size(720, 480), new Size(960, 640) })
                    {
                        Prepare(form, size);
                        FlowLayoutPanel filters = Require<FlowLayoutPanel>(form, "inventoryDataFilters");
                        FlowLayoutPanel summary = Require<FlowLayoutPanel>(form, "inventoryDataSummary");
                        DataGridView grid = Require<DataGridView>(form, "inventoryDataGrid");
                        FlowLayoutPanel footer = form.Controls.OfType<FlowLayoutPanel>()
                            .Single(panel => panel.Name.EndsWith("Footer", StringComparison.Ordinal));
                        if (form.ClientSize != size || summary.Visible || grid.Height < 80 ||
                            filters.HorizontalScroll.Visible || footer.Bottom != form.ClientSize.Height)
                            throw new InvalidOperationException("Compact inventory viewport failed: " + form.GetType().Name + "; size=" + size);
                        foreach (Control item in filters.Controls) RequireInside(filters, item, "compact inventory filter");
                        foreach (Control action in footer.Controls) RequireInside(footer, action, "compact inventory action");
                        var compactMetrics = Enumerable.Range(1, 4).Select(index =>
                            new InventorySummaryItem("مؤشر " + index, "1,250.50")).ToArray();
                        typeof(InventoryDataForm).GetMethod("SetSummary", System.Reflection.BindingFlags.Instance |
                            System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { compactMetrics });
                        foreach (Control card in summary.Controls) RequireInside(summary, card, "compact loaded metric");
                        if (summary.VerticalScroll.Visible)
                            throw new InvalidOperationException("Four short summary metrics should fit the compact viewport: " + form.GetType().Name + "/" + english + "/" + size + "; host=" + summary.ClientSize + "; min=" + summary.AutoScrollMinSize + "; display=" + summary.DisplayRectangle);
                        var metrics = Enumerable.Range(1, 8).Select(index =>
                            new InventorySummaryItem("مؤشر " + index, index.ToString())).ToArray();
                        typeof(InventoryDataForm).GetMethod("SetSummary", System.Reflection.BindingFlags.Instance |
                            System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { metrics });
                        if (form is InventoryMovementSummaryForm && filters.VerticalScroll.Visible)
                            throw new InvalidOperationException("The compact summary date fields require unnecessary vertical scrolling.");
                        Panel header = Require<Panel>(form, "inventoryDataHeader");
                        if (filters.Top < header.Bottom || summary.Top < filters.Bottom || grid.Top < summary.Bottom)
                            throw new InvalidOperationException("Loaded inventory order is invalid: header=" + header.Bounds +
                                "; filters=" + filters.Bounds + "; summary=" + summary.Bounds + "; grid=" + grid.Bounds);
                        if (!summary.Visible || grid.Height < 80 || !summary.AutoScroll || summary.HorizontalScroll.Visible)
                            throw new InvalidOperationException("Compact inventory populated metrics are clipped or hide the table.");
                        typeof(InventoryDataForm).GetMethod("SetSummary", System.Reflection.BindingFlags.Instance |
                            System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { new InventorySummaryItem[0] });
                    }
                }
            }
        }
