        private static void VerifyInventoryTurnoverLayout()
        {
            using (var form = new InventoryTurnoverForm(false))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(860, 560), new Size(1120, 700) })
                {
                    Prepare(form, size);
                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "inventoryTurnoverFooter");
                    AntdUI.Input days = Require<AntdUI.Input>(form, "inventoryTurnoverIdleDays");
                    Label emptyHint = Require<Label>(form, "inventoryDataEmptyHint");
                    AntdUI.DatePicker from = Require<AntdUI.DatePicker>(form, "inventoryTurnoverFromDate");
                    AntdUI.DatePicker to = Require<AntdUI.DatePicker>(form, "inventoryTurnoverToDate");
                    if (footer.Bottom != form.ClientSize.Height || footer.Controls.Count != 4 ||
                        days.Text != "60" || days.RightToLeft != RightToLeft.No || !emptyHint.Visible ||
                        days.Height < 44 || from.Height < 44 || to.Height < 44 ||
                        from.Value?.Date != DateTime.Today.AddMonths(-3) || to.Value?.Date != DateTime.Today ||
                        from.RightToLeft != RightToLeft.No || to.RightToLeft != RightToLeft.No)
                        throw new InvalidOperationException("Inventory turnover defaults or fixed footer are invalid at " + size + ".");
                    foreach (string name in new[] { "inventoryTurnoverRefresh", "inventoryTurnoverPrint", "inventoryTurnoverExport" })
                    {
                        AntdUI.Button action = Require<AntdUI.Button>(footer, name);
                        RequireInside(footer, action, "inventory turnover action " + name);
                        if (action.Height < 44 || action.DefaultBorderColor != UiTheme.Primary)
                            throw new InvalidOperationException("Inventory turnover action lost its green 44px target: " + name + ".");
                    }
                }
                AntdUI.Input threshold = Require<AntdUI.Input>(form, "inventoryTurnoverIdleDays");
                var refresh = typeof(InventoryTurnoverForm).GetMethod("RefreshData",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (refresh == null) throw new InvalidOperationException("Turnover refresh cannot be verified.");
                foreach (string invalid in new[] { "0", "3651" })
                {
                    threshold.Text = invalid;
                    refresh.Invoke(form, null);
                    if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("بين 1 و3650"))
                        throw new InvalidOperationException("Turnover threshold " + invalid + " reached SQL or was silently changed.");
                }
                threshold.Text = "60";
                refresh.Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("لم تُقرأ قاعدة البيانات"))
                    throw new InvalidOperationException("Inventory turnover preview reached SQL for a valid threshold.");
                form.ApplyPresentation(true);
                Prepare(form, new Size(860, 560));
                FlowLayoutPanel englishFooter = Require<FlowLayoutPanel>(form, "inventoryTurnoverFooter");
                AntdUI.Button englishRefresh = Require<AntdUI.Button>(englishFooter, "inventoryTurnoverRefresh");
                AntdUI.Button englishPrint = Require<AntdUI.Button>(englishFooter, "inventoryTurnoverPrint");
                Label englishTitle = Require<Label>(form, "inventoryDataTitle");
                if (form.RightToLeft != RightToLeft.No || form.RightToLeftLayout ||
                    form.Text != "Item turnover and inactivity" || threshold.AccessibleName != "Inactive days" ||
                    englishTitle.TextAlign != ContentAlignment.MiddleLeft || englishTitle.Text != form.Text ||
                    englishRefresh.Left >= englishPrint.Left)
                    throw new InvalidOperationException("Inventory turnover English presentation failed.");
                refresh.Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("no database data was read"))
                    throw new InvalidOperationException("Inventory turnover English preview reached SQL.");
                form.ApplyPresentation(false);
            }
            foreach (int invalid in new[] { 0, 3651 })
            {
                bool rejected = false;
                try { InventoryService.GetTurnoverReport(DateTime.Today, DateTime.Today, invalid); }
                catch (InvalidOperationException) { rejected = true; }
                if (!rejected) throw new InvalidOperationException("Inventory turnover service accepts invalid idle days: " + invalid + ".");
            }
            bool reversedRejected = false;
            try { InventoryService.GetTurnoverReport(DateTime.Today, DateTime.Today.AddDays(-1), 60); }
            catch (InvalidOperationException) { reversedRejected = true; }
            if (!reversedRejected) throw new InvalidOperationException("Inventory turnover service silently changes a reversed date range.");
        }

