        private sealed class MovementReportReadProbe : IInventoryOperationReadService
        {
            internal Func<System.Threading.Tasks.Task<IReadOnlyList<InventoryMedicineLookupRow>>> Lookup;
            internal System.Threading.CancellationToken LookupToken;
            internal readonly List<InventoryOperationReadRequest> Requests = new List<InventoryOperationReadRequest>();
            internal readonly List<System.Threading.CancellationToken> Tokens = new List<System.Threading.CancellationToken>();
            internal readonly List<System.Threading.Tasks.TaskCompletionSource<InventoryOperationReadSnapshot>> Pending = new List<System.Threading.Tasks.TaskCompletionSource<InventoryOperationReadSnapshot>>();
            public System.Threading.Tasks.Task<IReadOnlyList<InventoryMedicineLookupRow>> LoadMedicinesAsync(OperationActor actor, System.Threading.CancellationToken cancellation)
            { LookupToken = cancellation; return Lookup == null ? System.Threading.Tasks.Task.FromResult((IReadOnlyList<InventoryMedicineLookupRow>)new List<InventoryMedicineLookupRow>()) : Lookup(); }
            public System.Threading.Tasks.Task<InventoryOperationReadSnapshot> LoadSnapshotAsync(InventoryOperationReadRequest request, OperationActor actor, System.Threading.CancellationToken cancellation)
            {
                Requests.Add(request); Tokens.Add(cancellation);
                var result = new System.Threading.Tasks.TaskCompletionSource<InventoryOperationReadSnapshot>();
                Pending.Add(result); return result.Task;
            }
        }

        private static void FinishMovementRead(System.Threading.Tasks.Task task)
        {
            var deadline = DateTime.UtcNow.AddSeconds(10);
            while (!task.IsCompleted)
            {
                if (DateTime.UtcNow > deadline) throw new Exception("Movement read continuation did not complete.");
                Application.DoEvents(); System.Threading.Thread.Sleep(1);
            }
            task.GetAwaiter().GetResult();
        }

        private static void VerifyInventoryMovementLookupAsync()
        {
            using (var form = new InventoryMovementForm(false))
            {
                form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000); form.Show(); Application.DoEvents();
                var reader = new MovementReportReadProbe(); bool context = true;
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                typeof(InventoryMovementForm).GetField("movementSession", flags).SetValue(form,
                    new InventoryPostingSession(new InventoryContextProbe(), new OperationActor { UserName = "original-user", UserRole = "original-role" }, () => context, null, reader));
                var load = typeof(InventoryMovementForm).GetMethod("LoadMovementAsync", flags);
                var lookup = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<InventoryMedicineLookupRow>>();
                reader.Lookup = () => lookup.Task;
                var task = (System.Threading.Tasks.Task)load.Invoke(form, null);
                var selector = Require<ComboBox>(form, "inventoryMovementMedicine");
                var refresh = Require<AntdUI.Button>(form, "inventoryMovementRefresh");
                var print = Require<AntdUI.Button>(form, "inventoryMovementPrint");
                if (task.IsCompleted || selector.Enabled || refresh.Enabled || print.Enabled)
                    throw new Exception("Movement lookup allows reading/output before medicine options load.");
                lookup.SetException(new InvalidOperationException("Lookup fixture failure")); FinishMovementRead(task);
                if (!refresh.Enabled || print.Enabled || !Require<Label>(form, "inventoryDataStatus").Text.Contains("Lookup fixture failure"))
                    throw new Exception("Movement lookup failure has no retry path or preserves output.");
                lookup = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<InventoryMedicineLookupRow>>();
                task = (System.Threading.Tasks.Task)load.Invoke(form, null);
                lookup.SetResult(new List<InventoryMedicineLookupRow> { new InventoryMedicineLookupRow("A", "دواء تجريبي 500 mg", 10) });
                var deadline = DateTime.UtcNow.AddSeconds(10);
                while (reader.Pending.Count == 0)
                {
                    if (DateTime.UtcNow > deadline) throw new Exception("Movement lookup did not dispatch initial movement read.");
                    Application.DoEvents(); System.Threading.Thread.Sleep(1);
                }
                reader.Pending[0].SetResult(new InventoryOperationReadSnapshot("A", 10, new List<InventoryMovementReadRow>()));
                FinishMovementRead(task);
                if (!selector.Enabled || !refresh.Enabled || InventoryMedicineSelection.SelectedName(selector) != "A" || print.Enabled)
                    throw new Exception("Movement lookup retry lost options/key or enables empty output.");
                lookup = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<InventoryMedicineLookupRow>>();
                task = (System.Threading.Tasks.Task)load.Invoke(form, null); context = false;
                lookup.SetResult(new List<InventoryMedicineLookupRow> { new InventoryMedicineLookupRow("B", "خيار متأخر", 20) });
                FinishMovementRead(task);
                if (InventoryMedicineSelection.SelectedName(selector) != "A" || print.Enabled)
                    throw new Exception("Changed context replaced movement lookup options.");
                context = true;
                lookup = new System.Threading.Tasks.TaskCompletionSource<IReadOnlyList<InventoryMedicineLookupRow>>();
                task = (System.Threading.Tasks.Task)load.Invoke(form, null); var token = reader.LookupToken; form.Dispose();
                if (!token.IsCancellationRequested) throw new Exception("Closing movement report did not cancel medicine lookup.");
                lookup.SetResult(new List<InventoryMedicineLookupRow>()); FinishMovementRead(task);
            }
            Console.WriteLine("PASS movement medicine lookup: pending state, failure/retry, selected key, context change, close cancellation; no SQL.");
        }


