        private static void VerifyInventoryAlertSessionReads()
        {
            bool allowed = true, context = true;
            var repository = new InventoryAlertAsyncReadProbe();
            var service = new PharmacyManagement.Application.InventoryAlertReadService(repository, actor => allowed);
            var session = new InventoryAlertReadSession(service,
                new PharmacyManagement.Application.OperationActor { UserName = "alert-user", UserRole = "Manager" }, () => context);

            var success = session.LoadAsync(10, 30, new[] { "دواء الاختبار", "دواء الاختبار" }, System.Threading.CancellationToken.None);
            repository.Pending[0].SetResult(AlertFixture("مخزون منخفض"));
            var result = success.GetAwaiter().GetResult();
            if (result.Rows.Count != 1 || result.Columns.Count != 6 || repository.Requests[0].AffectedMedicines.Count != 1 ||
                repository.Requests[0].AffectedMedicines[0] != "دواء الاختبار")
                throw new Exception("Async alert service did not preserve the result schema.");

            var cancellation = new System.Threading.CancellationTokenSource();
            var cancelled = session.LoadAsync(10, 30, cancellation.Token);
            cancellation.Cancel();
            repository.Pending[1].SetResult(AlertFixture("منتهي"));
            try { cancelled.GetAwaiter().GetResult(); throw new Exception("Cancelled alert read returned a result."); }
            catch (OperationCanceledException) { }

            var staleContext = session.LoadAsync(10, 30, System.Threading.CancellationToken.None);
            context = false;
            repository.Pending[2].SetResult(AlertFixture("منتهي"));
            try { staleContext.GetAwaiter().GetResult(); throw new Exception("Alert read accepted a changed session context."); }
            catch (InvalidOperationException) { }

            context = true;
            allowed = false;
            try
            {
                session.LoadAsync(10, 30, System.Threading.CancellationToken.None).GetAwaiter().GetResult();
                throw new Exception("Unauthorized alert read was accepted.");
            }
            catch (UnauthorizedAccessException) { }
        }

        private static void VerifyInventoryOperationalReportReads()
        {
            bool allowed = true, context = true;
            var repository = new InventoryOperationalReportReadProbe();
            var service = new PharmacyManagement.Application.InventoryOperationalReportReadService(repository, actor => allowed);
            var session = new InventoryOperationalReportReadSession(service,
                new PharmacyManagement.Application.OperationActor { UserName = "inventory-report-user", UserRole = "Manager" }, () => context);
            var from = DateTime.Today.AddDays(-30);
            var to = DateTime.Today;

            var summary = session.LoadMovementSummaryAsync(
                new PharmacyManagement.Application.InventoryMovementSummaryRequest(from, to, "باراسيتامول"),
                System.Threading.CancellationToken.None);
            repository.SummaryPending[0].SetResult(OperationalReportFixture("إجمالي الوارد"));
            if (summary.GetAwaiter().GetResult().Rows.Count != 1 || repository.SummaryRequests[0].SearchText != "باراسيتامول")
                throw new Exception("Movement summary async request or typed result changed.");

            var cancel = new System.Threading.CancellationTokenSource();
            var turnover = session.LoadTurnoverAsync(new PharmacyManagement.Application.InventoryTurnoverRequest(from, to, 60), cancel.Token);
            cancel.Cancel();
            repository.TurnoverPending[0].SetResult(OperationalReportFixture("التصنيف"));
            try { turnover.GetAwaiter().GetResult(); throw new Exception("Cancelled turnover request returned a result."); }
            catch (OperationCanceledException) { }

            var changed = session.LoadMovementSummaryAsync(
                new PharmacyManagement.Application.InventoryMovementSummaryRequest(from, to, string.Empty),
                System.Threading.CancellationToken.None);
            context = false;
            repository.SummaryPending[1].SetResult(OperationalReportFixture("إجمالي الوارد"));
            try { changed.GetAwaiter().GetResult(); throw new Exception("Operational report accepted a changed database/user context."); }
            catch (InvalidOperationException) { }

            context = true;
            allowed = false;
            try
            {
                session.LoadTurnoverAsync(new PharmacyManagement.Application.InventoryTurnoverRequest(from, to, 60),
                    System.Threading.CancellationToken.None).GetAwaiter().GetResult();
                throw new Exception("Unauthorized operational report read was accepted.");
            }
            catch (UnauthorizedAccessException) { }

            ExpectReportValidationFailure(() => new PharmacyManagement.Application.InventoryMovementSummaryRequest(to, from, string.Empty), "Reversed movement summary period accepted.");
            ExpectReportValidationFailure(() => new PharmacyManagement.Application.InventoryTurnoverRequest(from, to, 0), "Invalid turnover threshold accepted.");
            ExpectReportValidationFailure(() => new PharmacyManagement.Application.InventoryMovementSummaryRequest(from, to, new string('x', 201)), "Oversized inventory search accepted.");
        }

