        private sealed class InventoryOperationalReportReadProbe : PharmacyManagement.Application.IInventoryOperationalReportRepository
        {
            internal readonly System.Collections.Generic.List<PharmacyManagement.Application.InventoryMovementSummaryRequest> SummaryRequests = new System.Collections.Generic.List<PharmacyManagement.Application.InventoryMovementSummaryRequest>();
            internal readonly System.Collections.Generic.List<System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>> SummaryPending = new System.Collections.Generic.List<System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>>();
            internal readonly System.Collections.Generic.List<System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>> TurnoverPending = new System.Collections.Generic.List<System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>>();
            public System.Threading.Tasks.Task<PharmacyManagement.Application.OperationalReportResult> LoadMovementSummaryAsync(
                PharmacyManagement.Application.InventoryMovementSummaryRequest request, System.Threading.CancellationToken cancellation)
            {
                SummaryRequests.Add(request);
                var pending = new System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);
                SummaryPending.Add(pending); return pending.Task;
            }
            public System.Threading.Tasks.Task<PharmacyManagement.Application.OperationalReportResult> LoadTurnoverAsync(
                PharmacyManagement.Application.InventoryTurnoverRequest request, System.Threading.CancellationToken cancellation)
            {
                var pending = new System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);
                TurnoverPending.Add(pending); return pending.Task;
            }
        }

