            public System.Threading.Tasks.Task<PharmacyManagement.Application.OperationalReportResult> LoadAsync(System.Threading.CancellationToken cancellation)
            {
                var pending = new System.Threading.Tasks.TaskCompletionSource<PharmacyManagement.Application.OperationalReportResult>(
                    System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);
                Pending.Add(pending);
                return pending.Task;
            }
        }

