        private static void VerifyOutputState(InventoryDataForm form, Action<InventoryDataForm> apply,
            string printName, string exportName)
        {
            using (form)
            {
                apply(form);
                var print = Require<AntdUI.Button>(form, printName);
                var export = Require<AntdUI.Button>(form, exportName);
                if (print.Enabled || export.Enabled) throw new Exception("Empty inventory report enabled print/export: " + printName);
                var table = new DataTable(); table.Columns.Add("الصنف", typeof(string)); table.Rows.Add("دواء تجريبي 500 mg");
                typeof(InventoryDataForm).GetMethod("BindGrid", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { table, null });
                if (!print.Enabled || !export.Enabled) throw new Exception("Inventory report did not enable outputs for populated rows: " + printName);
                typeof(InventoryDataForm).GetMethod("BindGrid", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(form, new object[] { new DataTable(), null });
                if (print.Enabled || export.Enabled) throw new Exception("Cleared inventory report retained print/export: " + printName);
            }
        }
        private static void VerifyInventoryMovementAsyncReads()
        {
            DateTime testToday = DateTime.Today;
            string originalTheme = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                foreach (bool ltr in new[] { false, true })
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    using (var form = new InventoryMovementForm(false))
                    {
                        form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual;
                        form.Location = new Point(-20000, -20000); form.Show(); Application.DoEvents();
                        form.ApplyPresentation(ltr);
                        var reader = new MovementReportReadProbe(); bool context = true;
                        var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                        typeof(InventoryMovementForm).GetField("movementSession", flags).SetValue(form,
                            new InventoryPostingSession(new InventoryContextProbe(), new OperationActor { UserName = "original-user", UserRole = "original-role" }, () => context, null, reader));
                        var selector = Require<ComboBox>(form, "inventoryMovementMedicine");
                        var lookup = new DataTable(); lookup.Columns.Add("MedName"); lookup.Columns.Add("DisplayName"); lookup.Columns.Add("MedQty", typeof(int));
                        lookup.Rows.Add("A", "الصنف الأول", 10); lookup.Rows.Add("B", "باراسيتامول 500 mg", 20);
                        InventoryMedicineSelection.Bind(selector, lookup); selector.SelectedValue = "A";
                        var print = Require<AntdUI.Button>(form, "inventoryMovementPrint");
                        var export = Require<AntdUI.Button>(form, "inventoryMovementExport");
                        var grid = Require<DataGridView>(form, "inventoryDataGrid");
                        var first = form.RefreshMovementAsync();
                        if (first.IsCompleted || print.Enabled || export.Enabled || grid.Rows.Count != 0)
                            throw new Exception("Movement pending read blocks UI or exposes stale output.");
                        bool pumped = false; form.BeginInvoke(new Action(() => pumped = true)); Application.DoEvents();
                        if (!pumped) throw new Exception("Movement pending read blocks message processing.");
                        selector.SelectedValue = "B";
                        if (!reader.Tokens[0].IsCancellationRequested) throw new Exception("Medicine change did not cancel movement read.");
                        var second = form.RefreshMovementAsync();
                        var rows = new List<InventoryMovementReadRow> { new InventoryMovementReadRow(testToday, "B", "SalesInvoice", "fixture", -0.25m, null, 20, 1.25m, null, null, "ملاحظة عربية") };
                        reader.Pending[1].SetResult(new InventoryOperationReadSnapshot("B", 20, rows)); FinishMovementRead(second);
                        reader.Pending[0].SetResult(new InventoryOperationReadSnapshot("A", 99, new List<InventoryMovementReadRow>())); FinishMovementRead(first);
                        if (grid.Rows.Count != 1 || Convert.ToString(grid.Rows[0].Cells["الصنف"].Value) != "B" ||
                            (decimal)grid.Rows[0].Cells["الصادر"].Value != 0.25m || grid.Rows[0].Cells["الرصيد قبل"].Value != DBNull.Value || !print.Enabled || !export.Enabled)
                            throw new Exception("Late movement response changed selected result or lost Arabic/null/quantity projection.");
                        var dateRead = form.RefreshMovementAsync();
                        var from = Require<AntdUI.DatePicker>(form, "inventoryMovementFromDate");
                        from.Text = testToday.AddDays(-2).ToString("yyyy/MM/dd", System.Globalization.CultureInfo.InvariantCulture);
                        if (!reader.Tokens[2].IsCancellationRequested || print.Enabled || export.Enabled || grid.Rows.Count != 0)
                            throw new Exception("Date change leaves stale movement outputs available.");
                        reader.Pending[2].SetResult(new InventoryOperationReadSnapshot("B", 20, rows)); FinishMovementRead(dateRead);
                        if (grid.Rows.Count != 0) throw new Exception("Obsolete date response repopulated movement grid.");
                        var failed = form.RefreshMovementAsync();
                        if (reader.Requests[3].From != testToday.AddDays(-2)) throw new Exception("Async movement request ignored visible date.");
                        reader.Pending[3].SetException(new InvalidOperationException("Simulated read failure")); FinishMovementRead(failed);
                        if (print.Enabled || export.Enabled || grid.Rows.Count != 0 || !Require<Label>(form, "inventoryDataStatus").Text.Contains("Simulated read failure"))
                            throw new Exception("Movement failure preserved data or obscured retry status.");
                        var retry = form.RefreshMovementAsync(); reader.Pending[4].SetResult(new InventoryOperationReadSnapshot("B", 20, rows)); FinishMovementRead(retry);
                        if (!print.Enabled || Require<Label>(form, "inventoryDataStatus").Text.Contains("Simulated read failure")) throw new Exception("Movement retry did not recover output/status.");
                        var changed = form.RefreshMovementAsync(); context = false;
                        reader.Pending[5].SetResult(new InventoryOperationReadSnapshot("B", 20, rows)); FinishMovementRead(changed);
                        if (grid.Rows.Count != 0 || print.Enabled || export.Enabled) throw new Exception("Changed context accepted movement data.");
                        context = true;
                        var empty = form.RefreshMovementAsync(); reader.Pending[6].SetResult(new InventoryOperationReadSnapshot("B", 20, new List<InventoryMovementReadRow>())); FinishMovementRead(empty);
                        if (grid.Rows.Count != 0 || print.Enabled || export.Enabled) throw new Exception("Empty movement result enables output.");
                        var closing = form.RefreshMovementAsync(); var closingToken = reader.Tokens[7]; form.Dispose();
                        if (!closingToken.IsCancellationRequested) throw new Exception("Closing movement form did not cancel read.");
                        reader.Pending[7].SetResult(new InventoryOperationReadSnapshot("B", 20, rows)); FinishMovementRead(closing);
                    }
                }
            }
            finally { Properties.Setings.Default.ThemeMode = originalTheme; }
            Console.WriteLine("PASS movement report async reads: message loop, medicine/date cancellation, late results, retry, context, empty output, disposal, both themes/directions; no SQL.");
        }


        private static void VerifyInventoryMovementInputs()
        {
            using (var form = new InventoryMovementForm(false))
            {
                form.ShowInTaskbar = false;
                form.StartPosition = FormStartPosition.Manual;
                form.Location = new Point(-20000, -20000);
                form.Show();
                foreach (Size size in new[] { new Size(860, 560), new Size(1120, 700) })
                {
                    Prepare(form, size);
                    Label emptyHint = Require<Label>(form, "inventoryDataEmptyHint");
                    if (!emptyHint.Visible || string.IsNullOrWhiteSpace(emptyHint.Text) ||
                        emptyHint.Right > emptyHint.Parent.ClientSize.Width)
                        throw new InvalidOperationException("Inventory movement guidance is missing or clipped at " + size + ".");
                    FlowLayoutPanel footer = Require<FlowLayoutPanel>(form, "inventoryMovementFooter");
                    ComboBox medicine = Require<ComboBox>(form, "inventoryMovementMedicine");
                    AntdUI.DatePicker from = Require<AntdUI.DatePicker>(form, "inventoryMovementFromDate");
                    AntdUI.DatePicker to = Require<AntdUI.DatePicker>(form, "inventoryMovementToDate");
                    if (footer.Bottom != form.ClientSize.Height || footer.HorizontalScroll.Visible ||
                        footer.Controls.Count != 4 || from.RightToLeft != RightToLeft.No || to.RightToLeft != RightToLeft.No ||
                        (UiDirection.IsLeftToRight
                            ? medicine.PointToScreen(Point.Empty).X >= from.PointToScreen(Point.Empty).X
                            : medicine.PointToScreen(Point.Empty).X <= from.PointToScreen(Point.Empty).X))
                        throw new InvalidOperationException("Inventory movement filters or footer are invalid at " + size + ".");
                    foreach (string name in new[] { "inventoryMovementRefresh", "inventoryMovementPrint", "inventoryMovementExport" })
                    {
                        AntdUI.Button action = Require<AntdUI.Button>(footer, name);
                        if (action.BorderWidth != 1 || action.DefaultBorderColor != UiTheme.Primary ||
                            action.Right > footer.ClientSize.Width)
                            throw new InvalidOperationException("Inventory movement footer action is clipped: " + name + ".");
                    }
                }

                ComboBox selector = Require<ComboBox>(form, "inventoryMovementMedicine");
                var lookup = new DataTable();
                lookup.Columns.Add("DisplayName", typeof(string));
                lookup.Columns.Add("MedName", typeof(string));
                lookup.Rows.Add("دواء تجريبي 500 mg — شركة أ", "دواء تجريبي 500 mg");
                InventoryMedicineSelection.Bind(selector, lookup);
                if (InventoryMedicineSelection.SelectedName(selector) != "دواء تجريبي 500 mg")
                    throw new InvalidOperationException("Movement lookup changed the medicine key sent to the report.");

                AntdUI.DatePicker fromDate = Require<AntdUI.DatePicker>(form, "inventoryMovementFromDate");
                AntdUI.DatePicker toDate = Require<AntdUI.DatePicker>(form, "inventoryMovementToDate");
                fromDate.Value = null;
                typeof(InventoryMovementForm).GetMethod("RefreshData", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("اختر تاريخ"))
                    throw new InvalidOperationException("Movement report did not reject an empty AntdUI date before SQL.");
                fromDate.Value = DateTime.Today;
                toDate.Value = DateTime.Today.AddDays(-1);
                typeof(InventoryMovementForm).GetMethod("RefreshData", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("تاريخ البداية"))
                    throw new InvalidOperationException("Movement report did not reject a reversed date range before SQL.");
                fromDate.Value = DateTime.Today.AddMonths(-1);
                toDate.Value = DateTime.Today;
                typeof(InventoryMovementForm).GetMethod("RefreshData", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("لم تُقرأ قاعدة البيانات"))
                    throw new InvalidOperationException("Movement preview reached SQL for a valid medicine and date range.");
                fromDate.Text = "invalid-date";
                typeof(InventoryMovementForm).GetMethod("RefreshData", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("اختر تاريخ"))
                    throw new InvalidOperationException("Movement report used an old internal date for invalid visible text.");
                fromDate.Text = DateTime.Today.AddDays(1).ToString("yyyy/MM/dd", System.Globalization.CultureInfo.InvariantCulture);
                typeof(InventoryMovementForm).GetMethod("RefreshData", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("تاريخ البداية"))
                    throw new InvalidOperationException("Movement report ignored the visible uncommitted date range.");
                AntdDateInput.SetDate(fromDate, DateTime.Today.AddMonths(-1));
                AntdDateInput.SetDate(toDate, DateTime.Today);
                form.ApplyPresentation(true);
                Prepare(form, new Size(860, 560));
                FlowLayoutPanel englishFooter = Require<FlowLayoutPanel>(form, "inventoryMovementFooter");
                if (form.Text != "Item movements" || selector.AccessibleName != "Medicine" ||
                    fromDate.AccessibleName != "From date" || toDate.AccessibleName != "To date" ||
                    Require<AntdUI.Button>(englishFooter, "inventoryMovementRefresh").Left >=
                        Require<AntdUI.Button>(englishFooter, "inventoryMovementPrint").Left)
                    throw new InvalidOperationException("Movement report English presentation failed.");
                typeof(InventoryMovementForm).GetMethod("RefreshData", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).Invoke(form, null);
                if (!Require<Label>(form, "inventoryDataStatus").Text.Contains("no database data was read"))
                    throw new InvalidOperationException("Movement English preview reached SQL.");
                form.ApplyPresentation(false);
            }
            using (var probe = new InventoryDataFormProbe())
            {
                probe.ShowInTaskbar = false;
                probe.StartPosition = FormStartPosition.Manual;
                probe.Location = new Point(-20000, -20000);
                probe.Show();
                probe.ShowEmptyHint("اختر الصنف");
                if (!Require<Label>(probe, "inventoryDataEmptyHint").Visible)
                    throw new InvalidOperationException("Inventory guidance did not appear for an empty grid.");
                var rows = new DataTable();
                rows.Columns.Add("الصنف", typeof(string));
                rows.Rows.Add("باراسيتامول 500 mg");
                probe.ShowRows(rows);
                if (Require<Label>(probe, "inventoryDataEmptyHint").Visible)
                    throw new InvalidOperationException("Inventory guidance obscures loaded rows.");
                probe.ApplyDirection(true);
                if (Require<DataGridView>(probe, "inventoryDataGrid").Columns[0].HeaderText != "Medicine")
                    throw new InvalidOperationException("Inventory grid headers were not translated for English presentation.");
                probe.ApplyDirection(false);
                if (Require<DataGridView>(probe, "inventoryDataGrid").Columns[0].HeaderText != "الصنف")
                    throw new InvalidOperationException("Inventory grid headers did not restore Arabic presentation.");
            }
        }

        private sealed class InventoryDataFormProbe : InventoryDataForm
        {
            internal InventoryDataFormProbe()
                : base("فحص معزول لفلاتر المخزون")
            {
            }

            internal bool IsDateRangeAccepted(DateTime from, DateTime to)
            {
                return TryValidateDateRange(from, to);
            }

            internal int ParseNonNegative(Control textBox, string fieldName)
            {
                return ParseNonNegativeInt(textBox, fieldName);
            }

            internal int ParseQuantity(Control input) => ParseInt(input, "الكمية");
            internal decimal? ParseMoney(Control input) => ParseOptionalMoney(input, "تكلفة الوحدة");
            internal void ShowEmptyHint(string message) => SetEmptyGridHint(message);
            internal void ShowRows(DataTable rows) => BindGrid(rows);
            internal void ApplyDirection(bool useLeftToRight) => ApplyInventoryPresentation(useLeftToRight);
        }

        private static void VerifyCashBoxLayout()
        {
            VerifyCashBoxRecoveryPresentation();
            VerifyCashBoxSaveCompletion();
            foreach (bool english in new[] { false, true })
            foreach (Size size in new[] { new Size(560, 500), new Size(760, 560), new Size(1024, 700) })
            using (var form = new CashBoxManagementForm(true))
            {
                form.ApplyPresentation(english);
                Prepare(form, size);
                form.Location = new Point(-20000, -20000);
                form.Show();
                Application.DoEvents();
                Panel header = Require<Panel>(form, "cashBoxHeader");
                Panel editor = Require<Panel>(form, "cashBoxEditor");
                Panel body = Require<Panel>(form, "cashBoxBody");
                Panel footer = Require<Panel>(form, "cashBoxFooter");
                FlowLayoutPanel fields = Require<FlowLayoutPanel>(form, "cashBoxFields");
                FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "cashBoxActions");
                AntdUI.Input code = Require<AntdUI.Input>(form, "cashBoxCode");
                TextBox name = Require<TextBox>(form, "cashBoxName");
                AntdUI.Panel activePanel = Require<AntdUI.Panel>(form, "cashBoxActivePanel");
                Label subtitle = Require<Label>(form, "cashBoxSubtitle");
                int subtitleHeight = TextRenderer.MeasureText(subtitle.Text, subtitle.Font,
                    new Size(Math.Max(1, subtitle.ClientSize.Width), int.MaxValue),
                    TextFormatFlags.WordBreak | TextFormatFlags.NoPadding).Height;
                if (subtitle.Height < subtitleHeight)
                    throw new InvalidOperationException("Cashbox subtitle is clipped at " + size + " English=" + english);
                if (fields.VerticalScroll.Visible && (size.Width >= 810 || editor.Height >= 172))
                    throw new InvalidOperationException("Cashbox fields unnecessarily scroll at " + size + " English=" + english +
                        "; editor=" + editor.Bounds + "; fields=" + fields.ClientSize + "; blocks=" +
                        string.Join("/", fields.Controls.Cast<Control>().Select(control => control.Bounds.ToString())));
                AntdUI.Panel nameFrame = Require<AntdUI.Panel>(form, "cashBoxFrame_name");
                form.ApplyPresentation(english);
        name.Text = "الصندوق الرئيسي Main 01";
        UiTheme.Apply(form);
        form.ApplyPresentation(english);
        // Let deferred theme/layout messages settle so the native frame assertion
        // judges the final state instead of a mid-pump transient under load.
        Application.DoEvents();
        form.PerformLayout();
                if (form.Controls["__UiStatusStrip"] != null ||
                    string.IsNullOrWhiteSpace(Require<Label>(form, "cashBoxStatus").Text))
                    throw new InvalidOperationException("Cashbox operation status was replaced by a duplicate global strip.");
                if (name.Text != "الصندوق الرئيسي Main 01" || name.RightToLeft != RightToLeft.Yes ||
                    name.TextAlign != HorizontalAlignment.Left || name.BorderStyle != BorderStyle.None ||
                    nameFrame.Shadow != 0 || nameFrame.Radius != DesktopDesignTokens.ActionRadius(nameFrame.Height))
                    throw new InvalidOperationException("Cashbox mixed Arabic name or native frame changed after theme application at " + size + " English=" + english + " text=" + name.Text + " rtl=" + name.RightToLeft + " align=" + name.TextAlign + " border=" + name.BorderStyle + " radius=" + nameFrame.Radius + " height=" + nameFrame.Height);
                if (name.Top != Math.Max(0, (nameFrame.ClientSize.Height - name.PreferredHeight) / 2) ||
                    name.Left < 8 || name.Right > nameFrame.ClientSize.Width - 8)
                    throw new InvalidOperationException("Cashbox name is not vertically centered inside its AntdUI frame.");
                if (code.Height < 44 || Require<AntdUI.Panel>(form, "cashBoxFrame_name").Height < 44 ||
                    string.IsNullOrWhiteSpace(code.AccessibleName) ||
                    string.IsNullOrWhiteSpace(name.AccessibleName) ||
                    activePanel.Radius != DesktopDesignTokens.FieldRadius)
                    throw new InvalidOperationException("Cashbox inputs or active card lost the shared AntdUI design at " + size);
                if (header.Bottom > editor.Top || editor.Bottom > body.Top ||
                    body.Bottom > footer.Top || body.Height < 45 ||
                    fields.HorizontalScroll.Visible || actions.HorizontalScroll.Visible)
                    throw new InvalidOperationException("Cashbox shell overlaps or scrolls horizontally at " + size +
                        " English=" + english + ": header=" + header.Bounds + " editor=" + editor.Bounds +
                        " body=" + body.Bounds + " footer=" + footer.Bounds);
                if (fields.FlowDirection != (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft) ||
                    actions.FlowDirection != (english ? FlowDirection.LeftToRight : FlowDirection.RightToLeft) ||
                    Require<DataGridView>(form, "cashBoxGrid").RightToLeft !=
                        (english ? RightToLeft.No : RightToLeft.Yes))
                    throw new InvalidOperationException("Cashbox reading direction is incorrect at " + size +
                        " English=" + english + " fields=" + fields.FlowDirection +
                        " actions=" + actions.FlowDirection + " grid=" +
                        Require<DataGridView>(form, "cashBoxGrid").RightToLeft);
                DataGridView cashGrid = Require<DataGridView>(form, "cashBoxGrid");
                if (cashGrid.ClientSize.Height < cashGrid.ColumnHeadersHeight + cashGrid.RowTemplate.Height + SystemInformation.HorizontalScrollBarHeight)
                    throw new InvalidOperationException("Cashbox compact layout must show its header and a complete data row at " + size + " English=" + english + " grid=" + cashGrid.ClientSize.Height);
                if (cashGrid.ColumnHeadersHeight < 48)
                    throw new InvalidOperationException("Cashbox two-line column headers may clip at " + size);
                int firstX = cashGrid.GetColumnDisplayRectangle(1, false).Left;
                int lastX = cashGrid.GetColumnDisplayRectangle(5, false).Left;
                if (english ? firstX >= lastX : firstX <= lastX)
                    throw new InvalidOperationException("Cashbox visible column order is incorrect at " + size +
                        " English=" + english + " RTL=" + cashGrid.RightToLeft +
                        " first=" + firstX + " last=" + lastX);
                foreach (Control block in fields.Controls)
                    if (block.Left < 0 || block.Right > fields.ClientSize.Width)
                        throw new InvalidOperationException("Cashbox field overflows at " + size + ": " + block.Bounds);
                foreach (AntdUI.Button action in actions.Controls.OfType<AntdUI.Button>())
                    if (action.Height < 44 || action.Right > actions.ClientSize.Width ||
                        action.Bottom > actions.ClientSize.Height || string.IsNullOrWhiteSpace(action.AccessibleName))
                        throw new InvalidOperationException("Cashbox action overflows or lacks access at " + size +
                            ": " + action.Name + " " + action.Bounds);
            }
        }

        private static void VerifyCashBoxRecoveryPresentation()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                using (var form = new CashBoxManagementForm(false))
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    UiTheme.Apply(form);
                    Prepare(form, new Size(560, 500));
                    var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                    typeof(CashBoxManagementForm).GetMethod("ApplyConfirmedReloadFailure", flags)
                        .Invoke(form, new object[] { new System.IO.IOException("simulated refresh failure") });
                    foreach (bool english in new[] { false, true, false })
                    foreach (Size size in new[] { new Size(560, 480), new Size(760, 560), new Size(1024, 700) })
                    {
                        form.ApplyPresentation(english);
                        if (size.Width == 560) { Prepare(form, size); form.Size = form.MinimumSize; }
                        else Prepare(form, size);
                        Label status = Require<Label>(form, "cashBoxStatus");
                        DataGridView grid = Require<DataGridView>(form, "cashBoxGrid");
                        FlowLayoutPanel actions = Require<FlowLayoutPanel>(form, "cashBoxActions");
                        int needed = TextRenderer.MeasureText(status.Text, status.Font,
                            new Size(Math.Max(1, status.ClientSize.Width - status.Padding.Horizontal), int.MaxValue),
                            TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix).Height;
                        if (needed > status.ClientSize.Height - status.Padding.Vertical ||
                            !status.Text.Contains(english ? "were saved" : "حُفظت تعريفات") ||
                            status.AccessibleName != status.Text || status.AccessibleRole != AccessibleRole.StatusBar ||
                            Require<AntdUI.Button>(form, "cashBoxSave").Enabled ||
                            Require<AntdUI.Button>(form, "cashBoxImport").Enabled ||
                            Require<AntdUI.Button>(form, "cashBoxNew").Enabled ||
                            !Require<AntdUI.Button>(form, "cashBoxClose").Enabled ||
                            grid.ClientSize.Height < grid.ColumnHeadersHeight + grid.RowTemplate.Height)
                            throw new InvalidOperationException("Cashbox recovery state is clipped or allows repeated writes at " + form.Size + "/" + english +
                                "; status=" + status.Bounds + "; grid=" + grid.ClientSize);
                        foreach (AntdUI.Button action in actions.Controls.OfType<AntdUI.Button>())
                            if (!actions.ClientRectangle.Contains(action.Bounds) ||
                                action.Width < TextRenderer.MeasureText(action.Text, action.Font).Width + 36 || action.Height < 44)
                                throw new InvalidOperationException("Cashbox recovery action is clipped: " + action.Name);
                    }
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = original;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        private static void VerifyExcelTransferOperationPresentation()
        {
            string original = Properties.Setings.Default.ThemeMode;
            try
            {
                foreach (string theme in new[] { "Light", "Dark" })
                using (var form = new ExcelDataTransferForm(true))
                {
                    Properties.Setings.Default.ThemeMode = theme;
                    UiTheme.Apply(form);
                    Prepare(form, new Size(720, 520));
                    var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                    AntdUI.Select selector = Require<AntdUI.Select>(form, "excelTransferSource");
                    var sources = (IReadOnlyList<OperationalReportSource>)typeof(ExcelDataTransferForm).GetField("exportSources", flags).GetValue(form);
                    selector.SelectedIndex = sources.ToList().FindIndex(item => item.UsesDateRange);
                    int selected = selector.SelectedIndex;
                    TextBox search = Require<TextBox>(form, "excelTransferSearch");
                    search.Text = "باراسيتامول 500 mg";
                    typeof(ExcelDataTransferForm).GetMethod("SetStatusMessageWithValues", flags).Invoke(form,
                        new object[] { "تم تصدير {0} صفًا إلى Excel.", (bool?)true, new object[] { 777 } });
                    foreach (bool english in new[] { false, true, false })
                    {
                        form.ApplyPresentation(english);
                        form.Size = form.MinimumSize;
                        Label status = Require<Label>(form, "excelTransferStatus");
                        if (status.Text != (english ? "Exported 777 rows to Excel." : "تم تصدير 777 صفًا إلى Excel.") ||
                            status.AccessibleName != status.Text || status.AccessibleRole != AccessibleRole.StatusBar ||
                            selector.SelectedIndex != selected || search.Text != "باراسيتامول 500 mg")
                            throw new InvalidOperationException("Excel export result or selected source/search was lost when changing presentation.");
                    }
                    typeof(ExcelDataTransferForm).GetField("exportInProgress", flags).SetValue(form, true);
                    typeof(ExcelDataTransferForm).GetMethod("SetExportBusy", flags).Invoke(form, new object[] { true });
                    foreach (bool english in new[] { true, false })
                    {
                        form.ApplyPresentation(english);
                        if (selector.Enabled || search.Enabled || Require<AntdUI.DatePicker>(form, "excelTransferFrom").Enabled ||
                            Require<AntdUI.DatePicker>(form, "excelTransferTo").Enabled || Require<AntdUI.Button>(form, "excelTransferClose").Enabled ||
                            !Require<Label>(form, "excelTransferStatus").Text.Contains(english ? "Preparing data" : "جارٍ تجهيز"))
                            throw new InvalidOperationException("Changing Excel presentation enabled a busy input or replaced its progress status.");
                    }
                    typeof(ExcelDataTransferForm).GetField("exportInProgress", flags).SetValue(form, false);
                    typeof(ExcelDataTransferForm).GetMethod("SetExportBusy", flags).Invoke(form, new object[] { false });
                    if (Require<AntdUI.Button>(form, "excelTransferExport").Enabled || Require<AntdUI.Button>(form, "excelTransferImport").Enabled)
                        throw new InvalidOperationException("Excel preview became writable after leaving busy state.");
                    typeof(ExcelDataTransferForm).GetMethod("SetStatusMessage", flags).Invoke(form,
                        new object[] { "تعذر تأكيد تصدير الملف؛ راجع الملف والمسار قبل إعادة المحاولة.", (bool?)false });
                    form.ApplyPresentation(true);
                    if (!Require<Label>(form, "excelTransferStatus").Text.Contains("Export could not be confirmed"))
                        throw new InvalidOperationException("Excel failure message was lost during translation.");
                }
            }
            finally
            {
                Properties.Setings.Default.ThemeMode = original;
                using (var refresh = new Form()) UiTheme.Apply(refresh);
            }
        }

        private static void VerifyCashBoxSaveCompletion()
        {
            int reloadCalls = 0;
            var expected = new[] { new CashBoxRecord { Code = "MAIN-1", Name = "الصندوق الرئيسي" } };
            CashBoxSaveCompletion success = CashBoxSaveWorkflow.ExecuteAsync(
                () => System.Threading.Tasks.Task.CompletedTask,
                () => System.Threading.Tasks.Task.FromResult<IReadOnlyList<CashBoxRecord>>(expected))
                .GetAwaiter().GetResult();
            if (success.ReloadError != null || !ReferenceEquals(success.Boxes, expected))
                throw new InvalidOperationException("Cashbox save completion lost the refreshed definitions.");

            CashBoxSaveCompletion reloadFailure = CashBoxSaveWorkflow.ExecuteAsync(
                () => System.Threading.Tasks.Task.CompletedTask,
                () => System.Threading.Tasks.Task.FromException<IReadOnlyList<CashBoxRecord>>(
                    new System.IO.IOException("simulated refresh failure")))
                .GetAwaiter().GetResult();
            if (!(reloadFailure.ReloadError is System.IO.IOException) || reloadFailure.Boxes != null)
                throw new InvalidOperationException("Cashbox post-save refresh failure was confused with a failed save.");

            bool saveFailurePropagated = false;
            try
            {
                CashBoxSaveWorkflow.ExecuteAsync(
                    () => System.Threading.Tasks.Task.FromException(new InvalidOperationException("simulated save failure")),
                    () => { reloadCalls++; return System.Threading.Tasks.Task.FromResult<IReadOnlyList<CashBoxRecord>>(expected); })
                    .GetAwaiter().GetResult();
            }
            catch (InvalidOperationException) { saveFailurePropagated = true; }
            if (!saveFailurePropagated || reloadCalls != 0)
                throw new InvalidOperationException("Cashbox save failure must not trigger a list refresh or success message.");
        }

        private static void Prepare(Form form, Size size)
        {
            if (form.Visible && form.IsHandleCreated && !form.ShowInTaskbar)
            {
                OwnedTestWindowViewport.Resize(form, size);
                return;
            }
            // Unshown fixtures still verify logical layout; they do not prove a native viewport.
            form.ClientSize = size;
            form.CreateControl();
            form.PerformLayout();
        }

        private static T Require<T>(Control root, string name) where T : Control
        {
            T control = Find<T>(root, name);
            if (control == null)
            {
                throw new InvalidOperationException("لم يُعثر على عنصر التخطيط: " + name);
            }

            return control;
        }

        private static T Find<T>(Control root, string name) where T : Control
        {
            if (root == null)
            {
                return null;
            }

            if (root.Name == name && root is T)
            {
                return (T)root;
            }

            foreach (Control child in root.Controls)
            {
                T result = Find<T>(child, name);
                if (result != null)
                {
                    return result;
                }
            }

            return null;
        }

        private static T FindControlByAccessibleName<T>(Control root, string accessibleName) where T : Control
        {
            if (root == null) return null;
            if (root is T && string.Equals(root.AccessibleName, accessibleName, StringComparison.Ordinal)) return (T)root;
            foreach (Control child in root.Controls)
            {
                T result = FindControlByAccessibleName<T>(child, accessibleName);
                if (result != null) return result;
            }
            return null;
        }
        private static void RequireInside(Control parent, Control child, string description)
        {
            RequireHorizontallyInside(parent, child, description);
            if (child.Top < 0 || child.Bottom > parent.ClientSize.Height)
            {
                throw new InvalidOperationException("CONTROL_OUTSIDE_HEIGHT name=" + child.Name + " type=" + child.GetType().Name + " bounds=" + child.Bounds + " parent=" + parent.Name + " parentSize=" + parent.ClientSize + " details=" + description);
            }
        }

        private static void RequireHorizontallyInside(Control parent, Control child, string description)
        {
            if (child.Left < 0 || child.Right > parent.ClientSize.Width)
            {
                throw new InvalidOperationException("CONTROL_OUTSIDE_WIDTH name=" + child.Name + " type=" + child.GetType().Name + " bounds=" + child.Bounds + " parent=" + parent.Name + " parentSize=" + parent.ClientSize + " details=" + description);
            }
        }

        // Focused contract for the commercial return recovery and for the owned viewport measurement.
        // It runs in seconds so the gate can prove these two rules without the full layout sweep.
        public static void VerifyCommercialReturnContract()
        {
            VerifyReturnWorkflowLanguage();
            VerifyReturnEditorSharedComponents();
            VerifyOwnedViewportAgainstOpeningPreference();
            Console.WriteLine("PASS commercial return contract: pending request stays reviewable and read-only with its language, accessible status and original request; owned viewport measurement survives the maximized opening preference.");
        }

        private static void VerifyOwnedViewportAgainstOpeningPreference()
        {
            bool previousPreference;
            try { previousPreference = Properties.Setings.Default.OpenScreensMaximized; }
            catch { previousPreference = true; }
            try
            {
                // The user's opening preference maximizes business windows on Shown. The owned
                // measurement must still reach the requested client size instead of the screen size.
                Properties.Setings.Default.OpenScreensMaximized = true;
                foreach (Size requested in new[] { new Size(760, 640), new Size(1024, 768) })
                {
                    using (var form = new Form())
                    {
                        form.FormBorderStyle = FormBorderStyle.Sizable;
                        form.MaximizeBox = true;
                        form.MinimizeBox = true;
                        form.MinimumSize = new Size(400, 300);
                        form.StartPosition = FormStartPosition.Manual;
                        form.ShowInTaskbar = false;
                        form.Location = new Point(-20000, -20000);
                        ScreenModeSettings.InstallOpeningPreference(form);
                        form.Show();
                        Application.DoEvents();
                        OwnedTestWindowViewport.Resize(form, requested);
                        if (form.ClientSize != requested || form.WindowState != FormWindowState.Normal)
                            throw new InvalidOperationException("Owned viewport did not keep the requested client size against the maximized opening preference.");
                    }
                }
            }
            finally
            {
                try { Properties.Setings.Default.OpenScreensMaximized = previousPreference; } catch { }
            }
        }
    }
